Normal_String:
//0x704
Text_6E4:
.stringn "\x05FL|CHAP|BOLE||\x0C01\x0C13\x0701어이쿠야……\n"
.stringn "졌다 졌어, 항복이여.\n"
.stringn "후우, 역시\n"
.stringn "보레한테는 못 이기겠구마.\n"
.stringn "\x0713그래도 지금은 아까웠어.\n"
.stringn "아저씨도 강해졌고.\n"
.stringn "슬슬 특훈도 끝나가네.\n"
.stringn "\x0701그려?\n"
.stringn "나도 조금은 나아진 건가?\n"
.stringn "\x0713어디에 내놓아도 부끄럽지 않은\n"
.stringn "어엿한 병사라는 느낌이야.\n"
.stringn "\x0701그것참 다행이구먼.\n"
.stringn "모두의 짐이 되지 않으면\n"
.stringn "그걸로 충분하데이.\n"
.stringn "\x0713무슨 소리야.\n"
.stringn "이 정도면 종전 후에\n"
.stringn "왕궁 병사로 들어갈 수도 있을걸?\n"
.stringn "\x0701…나는 싸움이 지긋지긋혀.\n"
.stringn "이 전쟁이 끝나면\n"
.stringn "바로 제대해서 농민으로 돌아갈 거여.\n"
.stringn "\x0713…………\n"
.stringn "저기 아저씨.\n"
.stringn "솔직히 아저씨가 보기에\n"
.stringn "우리 용병은 어떻게 보여?\n"
.stringn "\x0701응?\n"
.stringn "\x0713이 세상에 용병은 널려 있지만,\n"
.stringn "대부분은 먹고 살기도 힘든 불량배들이야.\n"
.stringn "게다가 용병은 전쟁이 끝나면\n"
.stringn "변변한 일거리가 없어져서 몰락하지.\n"
.stringn "그 대부분의 말로는 마을 사람들로부터\n"
.stringn "돈을 빼앗는 도적들과 다를 바가 없어.\n"
.stringn "\x0701……보레.\n"
.stringn "\x0713우리는 그런 놈들과 달라.\n"
.stringn "하지만… 그건\n"
.stringn "겉으로만 봐서는 모르지.\n"
.stringn "가끔 거리를 돌아다니다 보면 자주 들어.\n"
.stringn "또 용병 놈들이 등쳐 먹으러 왔다…고.\n"
.stringn "나에 대해선 어떻게 말하든지 상관없지만,\n"
.stringn "동료들에게 그러는 건…… 조금 그래서.\n"
.stringn "\x0701……저기, 보레.\n"
.stringn "아무리 깨끗한 삶을 살려고 해도\n"
.stringn "누군가에게는 원망을 사 버린다.\n"
.stringn "그런 악의는 피할 수 없다고 생각혀.\n"
.stringn "하지만 나는 보레나 모두를\n"
.stringn "좋아하고, 존경도 하고, 감사하고 있데이.\n"
.stringn "그걸로 충분하지 않나.\n"
.stringn "\x0713…………\n"
.stringn "미안, 아저씨. ……고마워.\n"
.stringn "그걸로…… 충분하지.\n"
.stringn "영차, 그럼 다시 한번 힘내 볼까!\n"
.stringn "가자고!\n"
.stringn "\x0701엥!? 또, 또 하는 겨?\n"
.stringn "자, 잠깐만 기다리라, 보레!\n"
.stringn "후우 후우 후우"
db 0
.align 4
//MYELL_8_BOLE_CHAP_A

//0x2FC
Text_2DC:
.stringn "\x05FL|BOLE|CHAP||\x0C03\x0711후우 후우 후우\n"
.stringn "후우우……\n"
.stringn "미안하구먼, 보레.\n"
.stringn "늦어 버려서.\n"
.stringn "\x0703뭐, 발이 느린 건 어쩔 수 없으니까.\n"
.stringn "처음이라 어떨까 싶었는데,\n"
.stringn "아저씨, 의외로 잘 따라오네.\n"
.stringn "\x0711그려?\n"
.stringn "확실히 끈기만큼은\n"
.stringn "다른 사람보다 강할지도 모르겠구먼.\n"
.stringn "안 그래도 농사는 1년이 걸리니께.\n"
.stringn "끈기가 없다고 하면 섭섭혀.\n"
.stringn "\x0703흐~음……\n"
.stringn "저기, 밭일은 재밌어?\n"
.stringn "\x0711그야 재미있제.\n"
.stringn "날씨라든가 해충이라든가 여러 고충이 있지만,\n"
.stringn "수확할 때의 기쁨은 이루 말할 수가 없어.\n"
.stringn "\x0703그렇구나……\n"
.stringn "\x0711? 왜 그러는 겨?\n"
.stringn "\x0703아니,\n"
.stringn "용병 일과는\n"
.stringn "정반대구나 싶어서.\n"
.stringn "농민이 하는 일은 뭔가를 만드는 거잖아?\n"
.stringn "하지만 우리가 하는 일은 적을 쓰러뜨리는……\n"
.stringn "파괴적인 일들뿐이지. 그 뒤엔 남는 게 없어.\n"
.stringn "\x0711그런 식으로 말하지 말어……\n"
.stringn "사람들을 지키려고 싸우는 일이잖어.\n"
.stringn "나는 훌륭한 일이라고 생각하는디.\n"
.stringn "\x0703아, 착각하지 마.\n"
.stringn "난 이 일이 좋아서 하는 거니까.\n"
.stringn "그레일 용병단 말고 있을 곳이 없기도 하고.\n"
.stringn "그런데…… 말야.\n"
.stringn "\x0711응?\n"
.stringn "\x0703……너무 많이 쉬었는걸.\n"
.stringn "특훈 재개야. 다음으로 가자!\n"
.stringn "\x0711그, 그렇게 갑자기…\n"
.stringn "잠깐만 기다리래이~ 후우 후우"
db 0
.align 4
//MYELL_8_BOLE_CHAP_B

//0x20
Text_0:
.stringn "\x05FL|CHAP|BOLE||\x070-\x0C01\x0C13\x0701이야, 반갑구먼.\n"
.stringn "난 채프라고 혀.\n"
.stringn "너, 용병단 사람인 겨?\n"
.stringn "\x0713응? 당신은 분명\n"
.stringn "포로였던 아저씨 맞지?\n"
.stringn "난 보레야.\n"
.stringn "그레일 용병단 최고의 전사지.\n"
.stringn "\x0701호오~ 그려?\n"
.stringn "젊은 데도 대단하구먼.\n"
.stringn "\x0713뭐, 진짜 그 정도로 대단하진 않아.\n"
.stringn "근데 아저씨.\n"
.stringn "당신… 포로였던 것치고는\n"
.stringn "왠지 뚱뚱한걸.\n"
.stringn "그런 몸으로 제대로 싸울 수는 있어?\n"
.stringn "\x0701아니, 잘 싸우지도\n"
.stringn "못하제.\n"
.stringn "밭을 가는 건\n"
.stringn "문제 없었지마는.\n"
.stringn "\x0713아저씨, 농민이었어?\n"
.stringn "\x0701그려.\n"
.stringn "그나저나 이 상태로는…\n"
.stringn "모두에게 짐이 될 것 같아서\n"
.stringn "미안하구먼.\n"
.stringn "\x0713그럼 특훈하면 되지.\n"
.stringn "내가 같이 해 줄게.\n"
.stringn "\x0701차, 참말로?\n"
.stringn "그럼 미안하지만\n"
.stringn "잘 부탁혀."
db 0
.align 4
//MYELL_8_BOLE_CHAP_C

//0x1484
Text_1464:
.stringn "\x05FL|BOLE|MIST||\x0703お、ミスト。\n"
.stringn "\x0711…ボーレ。\n"
.stringn "\x0703お、おい。\n"
.stringn "どうしたんだよ、えらく元気ねえなあ？\n"
.stringn "最近、おまえらしくねえぞ。\n"
.stringn "なんかあったのか？\n"
.stringn "\x0711ボーレぇ…\n"
.stringn "…っ　………\n"
.stringn "\x0703わっ！　どうしたっ！？\n"
.stringn "\x0711………いっぱい…あった…の…\n"
.stringn "いろんなこと…　いっぱい…\n"
.stringn "……わたし……　わたし……\n"
.stringn "\x0703あー…　……うん。\n"
.stringn "…なんかわかんねえけど……\n"
.stringn "泣きたいときは、泣いとけ。\n"
.stringn "\x0711……ぇっ　………っ\n"
.stringn "……………\n"
.stringn "\x0703落ち着いたら、\n"
.stringn "おれが話、聞いてやるから。\n"
.stringn "思いっきり泣いて。\n"
.stringn "思いっきりぶちまけて。\n"
.stringn "んで、楽になっちまえ。　な？\n"
.stringn "\x0711………ん……　……\n"
.stringn "………り…がと……\n"
.stringn "\x0703だいじょうぶだって。\n"
.stringn "おれ…と、みんなもいるから。\n"
.stringn "…だいじょうぶだ。\n"
.stringn "\x0711………ん……"
db 0
.align 4
//MYELL_8_BOLE_MIST_A

//0x10A0
Text_1080:
.stringn "\x05FL|MIST|BOLE||\x0701あれ？\n"
.stringn "どこいったのかな？\n"
.stringn "\x0713ったく、どこにいんだか……\n"
.stringn "\x0701あ、ボーレ。\n"
.stringn "\x0713お、ミスト。\n"
.stringn "アイクどこいったか知らねえか？\n"
.stringn "\x0701ううん、わたしも捜してたとこ。\n"
.stringn "\x0713そっか。\n"
.stringn "ここんとこ、あいつ\n"
.stringn "すげえ忙しそうだもんな。\n"
.stringn "じゃあ、あきらめて\n"
.stringn "別のやつをつかまえるか。\n"
.stringn "\x0701訓練の相手？\n"
.stringn "\x0713そう。やっぱおれ、\n"
.stringn "相手がいねえと調子でねえんだよな。\n"
.stringn "\x0701わたしじゃ…ダメかな？\n"
.stringn "\x0713へ？\n"
.stringn "\x0701その、相手にならないのは\n"
.stringn "わかってるの！\n"
.stringn "でもね…わたしも\n"
.stringn "強くならないといけないと思って。\n"
.stringn "戦場で生き残るために…　だから…\n"
.stringn "\x0713んじゃ、頼もうかな。\n"
.stringn "\x0701ほんと？\n"
.stringn "\x0713棒持たせた\n"
.stringn "かかしよりはましだろうし。\n"
.stringn "\x0701ひっどい！\n"
.stringn "あのね、わたしだってね…\n"
.stringn "\x0713お父さんの娘なんだから、か？\n"
.stringn "\x0701……う……\n"
.stringn "\x0713この間は悪かった。\n"
.stringn "きつい言い方しちまったよな。\n"
.stringn "\x0701ううん…　わたしが\n"
.stringn "甘すぎたのは事実だもん。\n"
.stringn "あれでちょっと目が覚めたし。\n"
.stringn "ボーレには感謝してるよ。\n"
.stringn "\x0713………ばっ\n"
.stringn "ばか野郎…っ！\n"
.stringn "急になに言って……\n"
.stringn "\x0701なにってお礼…\n"
.stringn "あ、やだ。\n"
.stringn "ボーレ、なに赤くなってんのよ？\n"
.stringn "\x0713るせえっ！\n"
.stringn "\x0701あ、ちょっと！\n"
.stringn "どこ行くのよ？\n"
.stringn "訓練するんでしょー！？"
db 0
.align 4
//MYELL_8_BOLE_MIST_B

//0xD44
Text_D24:
.stringn "\x05FL|BOLE|?|MIST||\x0706よっ！\n"
.stringn "せっ！\n"
.stringn "おらっ！　……っと。\n"
.stringn "ふう……今日はこんなもんでいいだろ。\n"
.stringn "イマイチ気がのらねえし、\n"
.stringn "素振りはこれくらいにして……\n"
.stringn "\x0717ボーレ！\n"
.stringn "いいかげんにしなさいっ！\n"
.stringn "\x0C06\x0703げぇっ！？\n"
.stringn "ちゃ、ちゃんとやってるって\n"
.stringn "ティアマトさ……　あれ？\n"
.stringn "\x072-\x0721くす　くす\n"
.stringn "\x0703てめぇ！\n"
.stringn "こら、待てミスト！\n"
.stringn "\x0C21\x0720訓練をさぼろうとする\n"
.stringn "ボーレが悪いんじゃない。\n"
.stringn "そうやってさぼってると、\n"
.stringn "そのうちわたしの方が\n"
.stringn "強くなっちゃったりして。\n"
.stringn "\x0703んなわけねーだろ。\n"
.stringn "図々しいにもほどがあるぜ。\n"
.stringn "\x0720だって、わたし\n"
.stringn "あのお父さんの娘なんだよ？\n"
.stringn "戦いのセンスあると思うけどな。\n"
.stringn "\x0703……ふざけんなよ。\n"
.stringn "戦場で生き残れるかどうかは\n"
.stringn "実戦経験の多さにかかってんだ。\n"
.stringn "センスがあるからって\n"
.stringn "変なうぬぼれもってると死ぬぞ。\n"
.stringn "\x0720やだ…　いつもの冗談じゃない。\n"
.stringn "本気で怖い顔しないでよ。\n"
.stringn "\x0703おれたちは冗談で戦ってんじゃねえっ！\n"
.stringn "わかったら、あっち行ってろ。\n"
.stringn "訓練の邪魔だ。\n"
.stringn "\x0720………ごめん。\n"
.stringn "\x0703………………"
db 0
.align 4
//MYELL_8_BOLE_MIST_C

//0x1E44
Text_1E24:
.stringn "\x05FL|BOLE|TIAMAT||\x070-\x0703ティアマトさん！\n"
.stringn "やっと見つけたぜ……\n"
.stringn "最近ティアマトさん、軍議とかばっかで\n"
.stringn "なかなか１人で居ないから……\n"
.stringn "\x071-\x0711なあに、ボーレ。\n"
.stringn "今日は別に怒ることもないわよ。\n"
.stringn "\x0703いや、別に怒られたいわけじゃなくって。\n"
.stringn "……\n"
.stringn "ティアマトさんさ、今なんか\n"
.stringn "欲しいものとかないか？\n"
.stringn "\x0711特に思い浮かばないけど…\n"
.stringn "どうして？\n"
.stringn "\x0703この間もらった報酬、結構あったからな。\n"
.stringn "いつもお世話になってるティアマトさんに\n"
.stringn "なにか買ってやろうかと思って。\n"
.stringn "\x0711ふふ　一人前だと認めた途端、\n"
.stringn "考えることも大人になったじゃない。\n"
.stringn "\x0703へへ　だからさ、なんでも言ってくれよ。\n"
.stringn "新しい肩当てとか、膝当てとか、\n"
.stringn "すげえ斧とか…？\n"
.stringn "\x0711気持ちだけいただいておくわ。\n"
.stringn "自分で稼いだお金だもの。\n"
.stringn "自分のためだけに使えばいいのよ。\n"
.stringn "\x0703だから！　おれ、\n"
.stringn "ティアマトさんに物をあげたいんじゃねえか。\n"
.stringn "\x0711ボーレ…　あなた、まさか……\n"
.stringn "\x0703おれ…\n"
.stringn "ティアマトさんを見てて\n"
.stringn "いっつも思ってた。\n"
.stringn "こんなキレイな人、見たことないって。\n"
.stringn "\x0711ボーレ、気持ちは嬉しいけど…\n"
.stringn "わたしは……\n"
.stringn "\x0703かあちゃんって、\n"
.stringn "こんな感じなんだろうなって。\n"
.stringn "\x0711………\n"
.stringn "\x0703うっわー！　照れくせぇっ！！\n"
.stringn "いやもう、おれ、恥ずかしすぎ。\n"
.stringn "\x0711……ボーレ。\n"
.stringn "\x0703ん？\n"
.stringn "\x0711あなた、いったい…\n"
.stringn "私をいくつだと思ってるの？\n"
.stringn "\x0703…………………\n"
.stringn "………えーっと……\n"
.stringn "おれの、死んだかあちゃんよりは…下？\n"
.stringn "\x0711…………\n"
.stringn "\x0703……\n"
.stringn "さてと、訓練訓練！\n"
.stringn "\x0711ボーレっ！\n"
.stringn "待ちなさいっ！！"
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_A

//0x1AC0
Text_1AA0:
.stringn "\x05FL|TIAMAT|BOLE||\x0701ボーレ。\n"
.stringn "\x0713テ、ティアマトさん！？\n"
.stringn "いや、さぼってねえって！\n"
.stringn "今日もちゃんと基礎訓練やったから！\n"
.stringn "\x0701まだ何も言ってないわよ。\n"
.stringn "\x0713あ、そっか。\n"
.stringn "もうすっかりそういう流れが\n"
.stringn "身についちまって……\n"
.stringn "\x0701今日は怒りに来たんじゃないわ。\n"
.stringn "もう、ちゃんとわかってるはずだもの。\n"
.stringn "どんどん激しくなる戦いに、\n"
.stringn "気の緩む隙なんかないって。\n"
.stringn "\x0713……ああ。\n"
.stringn "\x0701どれだけ技を身につけたのか……\n"
.stringn "どれだけ肉体を鍛えたのか……\n"
.stringn "それが戦場で生き残る全て……\n"
.stringn "……あなたはもう大丈夫ね、ボーレ。\n"
.stringn "その重みがちゃんとわかってるんだもの。\n"
.stringn "\x0713うええ！？\n"
.stringn "\x0701な、何？\n"
.stringn "何か変なこと言ったかしら？\n"
.stringn "\x0713だってティアマトさん、おかしいぜ。\n"
.stringn "それじゃまるで…おれのこと\n"
.stringn "ほめてるみたいに聞こえるぜ？\n"
.stringn "\x0701褒めてるのよ。\n"
.stringn "もう一人前ねって。\n"
.stringn "\x0713うっわ～…\n"
.stringn "なんか不吉ってゆーか…\n"
.stringn "怒られるより、すげえ怖えかも。\n"
.stringn "\x0701……そう。そんなに叱られるのが\n"
.stringn "お望みなのね……\n"
.stringn "じゃ、今後も遠慮なく叱るようにするわ。\n"
.stringn "\x0713げ……！\n"
.stringn "ち、違うって、ティアマトさん！"
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_B

//0x1700
Text_16E0:
.stringn "\x05FL|BOLE|TIAMAT||\x0703５３、５４、５５……と。\n"
.stringn "ふー…　こんな素振り、\n"
.stringn "１人でやっててもなあ…\n"
.stringn "相手がいなきゃ意味がねえよな。\n"
.stringn "そうだ、アイクの奴でも誘って……\n"
.stringn "\x0711ボーレ！\n"
.stringn "\x0703げっ、ティアマトさん！\n"
.stringn "\x0711また基礎訓練をさぼって\n"
.stringn "どこへ行くつもり？\n"
.stringn "\x0703いや、サボリじゃなくて。\n"
.stringn "アイクと手合わせでも\n"
.stringn "しようかなって思ったんだよ。\n"
.stringn "実戦で鍛えてこそって思うしさ。\n"
.stringn "\x0711確かに、私たちの剣技は\n"
.stringn "習い事でも何でもないわ。\n"
.stringn "でも、基礎をおろそかにすると、死に近づく。\n"
.stringn "疲弊し、判断がつかなくなった時、\n"
.stringn "身に馴染んだとっさの体の動きが\n"
.stringn "明暗を分けることだってあるもの。\n"
.stringn "\x0703けど、相手がいないと\n"
.stringn "イマイチ気が乗らないっていうか……\n"
.stringn "\x0711困ったわね……\n"
.stringn "また昔みたいに本気で\n"
.stringn "怒らないといけないのかしら。\n"
.stringn "\x0703い、いや冗談！\n"
.stringn "今までの全部冗談だって！\n"
.stringn "ああ、なんかもうめちゃくちゃ\n"
.stringn "素振りやりてえ！\n"
.stringn "基礎訓練は楽しいなあもう！\n"
.stringn "ね、ティアマトさん！\n"
.stringn "\x0711そう、それでいいの。\n"
.stringn "ボーレ、あなたは体格的にも\n"
.stringn "恵まれているんだから、\n"
.stringn "その気になればいつでも\n"
.stringn "私以上に優秀な戦士になれるのよ。\n"
.stringn "とにかく、がんばりなさい。"
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_C

//0x29CC
Text_29AC:
.stringn "\x05FL|VULCI|BOLE||\x0C05\x0713居た！\n"
.stringn "待ってくれよ、ウルキ！\n"
.stringn "\x0705………\n"
.stringn "\x0713なんで、おれを避けてんだよ？\n"
.stringn "なんか気に入らないことしたんなら\n"
.stringn "はっきり言ってくれねえと…\n"
.stringn "おれ、わかんねえよ。\n"
.stringn "\x0C05\x0701…ボーレ……\n"
.stringn "\x0713せっかく、ラグズのあんたと\n"
.stringn "ダチになれたって思ってたのに…\n"
.stringn "やっぱり、おれがベオクだから\n"
.stringn "親しくなれねえって…そういうことか？\n"
.stringn "\x0701……ちがう…\n"
.stringn "…おまえはいい奴だ。\n"
.stringn "私が…最低なだけだ……\n"
.stringn "\x0713その『最低』って、\n"
.stringn "この間も言ってたよな？\n"
.stringn "なんだよ、どういう意味だよ？\n"
.stringn "\x0701………………\n"
.stringn "…おまえが初めて…\n"
.stringn "私に声をかけてきた時、\n"
.stringn "私は…おまえを疑っていた。\n"
.stringn "ベオクが、ラグズの私に\n"
.stringn "親しげに話しかけ、近寄ってくる…\n"
.stringn "なにか企んでいるに違いないと……\n"
.stringn "\x0713え…　でも、ウルキは\n"
.stringn "最初おれのことほめたよな？\n"
.stringn "あれ…ウソだったのか？\n"
.stringn "\x0701相手を褒めるのが、\n"
.stringn "ベオクの挨拶なのかと思った…\n"
.stringn "ボーレも、私にはそぐわないような\n"
.stringn "美辞麗句を並べたてていたからな。\n"
.stringn "\x0713あ……\n"
.stringn "あれは……\n"
.stringn "\x0701私は、おまえと別れてすぐ…\n"
.stringn "おまえのことを調べた。\n"
.stringn "なんという名で、どんな素性であるか。\n"
.stringn "ぬかりなく全てを。\n"
.stringn "\x0713…………\n"
.stringn "で、なんか見つかったか？\n"
.stringn "\x0701グレイル傭兵団のボーレ。\n"
.stringn "見ためのとおり…裏表のない\n"
.stringn "快活な戦士だった。\n"
.stringn "\x0713………………\n"
.stringn "\x0701…おまえは、最初から\n"
.stringn "好意を示してくれたというのに…\n"
.stringn "私は、はなから信じていなかった。\n"
.stringn "疑ってかかった。\n"
.stringn "だから『最低』だと言ったのだ。\n"
.stringn "おまえが友好を結ぶには値しない。\n"
.stringn "\x0713……ベオクとラグズか。\n"
.stringn "\x0701？\n"
.stringn "\x0713おれさ、最初は…\n"
.stringn "ウルキと上手くやれるかどうか\n"
.stringn "すげえ自信なかったんだ。\n"
.stringn "アイクみたいに自然に…\n"
.stringn "ラグズと付き合えるのかってな。\n"
.stringn "でも…たまたまウルキと話せて、\n"
.stringn "やってみたら\n"
.stringn "なんだ簡単じゃねえかって。\n"
.stringn "そしたら、うれしくってな。\n"
.stringn "戦場でも、あんたの姿見つけては\n"
.stringn "寄ってって近くで戦ってた。\n"
.stringn "\x0701…ボーレ。\n"
.stringn "\x0713ベオクはずっとラグズと敵対してきた。\n"
.stringn "だから、ウルキがおれを警戒して…\n"
.stringn "素性を調べたってのは仕方ねえよ。\n"
.stringn "けどな、おれがシロだってわかった後でも\n"
.stringn "こうやって壁作られんのは納得いかねえ。\n"
.stringn "そんなんじゃ、いつまでたっても\n"
.stringn "ベオクとラグズは分かり合えねえ。\n"
.stringn "おれは、そんな風に思うけど…\n"
.stringn "ウルキはそれでも、まだ\n"
.stringn "おれを避けるつもりか？\n"
.stringn "\x0701………いや。\n"
.stringn "ボーレ、本当にすまなかった。\n"
.stringn "おまえがそれを許してくれるというなら、\n"
.stringn "私はおまえの友になりたい。\n"
.stringn "\x0713許すも許さないも…\n"
.stringn "おれは最初の時から\n"
.stringn "そのつもりだったってんだよ！"
db 0
.align 4
//MYELL_8_BOLE_VULCI_A

//0x2614
Text_25F4:
.stringn "\x05FL|BOLE|VULCI||\x070-\x0703おーい！\n"
.stringn "タカのにいちゃん。\n"
.stringn "\x0711…おまえか。\n"
.stringn "戦場以外で会うのは久しぶりだな。\n"
.stringn "\x0703おう。\n"
.stringn "あ、おれなボーレってんだ。\n"
.stringn "仲間なんだし、『おまえ』じゃなくて\n"
.stringn "名前で呼んでくれるか？\n"
.stringn "\x0711わかった。…私はウルキだ。\n"
.stringn "私も『タカのにいちゃん』ではなく、\n"
.stringn "名前で呼ばれることを希望する。\n"
.stringn "\x0703了解っと。\n"
.stringn "で、ウルキ。\n"
.stringn "こんなところでなにやってたんだ？\n"
.stringn "\x0711……小鳥の声に耳を傾けていた。\n"
.stringn "彼らの声は心を和ませてくれる。\n"
.stringn "\x0703ほんとか？\n"
.stringn "………………\n"
.stringn "ダメだ。おれじゃなんにも聞こえねえや。\n"
.stringn "あんた、ほんとに耳がいいよな。\n"
.stringn "\x0711………\n"
.stringn "\x0703しっかしさ、鳥翼族っていいよなあ～。\n"
.stringn "空が飛べるって最強じゃねえか！\n"
.stringn "ウルキの戦いを近くで見てるとさ、\n"
.stringn "とにかくすげえんだ。\n"
.stringn "ラグズの強さってもんを感じたぜ。\n"
.stringn "なんでベオクには翼がねえんだろうな？\n"
.stringn "化身してなきゃ、似たような見た目だってのに。\n"
.stringn "\x0711………\n"
.stringn "\x0703あ、悪ぃ。なんか\n"
.stringn "おればっかしゃべってるな。\n"
.stringn "邪魔だったらそう言ってくれていい…\n"
.stringn "\x0711……すまん…\n"
.stringn "\x0703どうしたんだ、いきなり？\n"
.stringn "\x0711私は…最低だ。\n"
.stringn "\x0703あ、おい！\n"
.stringn "………なんだよ急に…"
db 0
.align 4
//MYELL_8_BOLE_VULCI_B

//0x2320
Text_2300:
.stringn "\x05FL|BOLE|VULCI||\x0703お…？\n"
.stringn "あいつって、うちの軍にいる\n"
.stringn "タカのラグズ……\n"
.stringn "\x0711…………\n"
.stringn "\x0703うおっ！？\n"
.stringn "\x0711……何か用だろうか。\n"
.stringn "\x0703へ？\n"
.stringn "\x0711呼ばれたように思った。\n"
.stringn "違うのか？\n"
.stringn "\x0703え、あ、\n"
.stringn "もしかして…さっきのつぶやきのことか？\n"
.stringn "あんだけ離れてても聞こえたのか？\n"
.stringn "\x0711鮮明に。\n"
.stringn "\x0703す、すげえな。\n"
.stringn "\x0711それで…\n"
.stringn "私に何の用だ？\n"
.stringn "\x0703いや……なんだ、\n"
.stringn "えーっと……その…\n"
.stringn "……えらく気合の入った顔だなーって……\n"
.stringn "\x0711？\n"
.stringn "……この顔に問題があるのか？\n"
.stringn "いたって普通にしているつもりだが。\n"
.stringn "\x0703ないない。全っ然、問題ないぜ！\n"
.stringn "すっげえ強そう。男らしい。最高！\n"
.stringn "\x0711………\n"
.stringn "\x0703…………\n"
.stringn "\x0711………おまえのほうこそ、\n"
.stringn "健康そうで、いい色艶の頭髪だ。\n"
.stringn "腕も太くて中々に力強そうでいい。\n"
.stringn "\x0703へ？\n"
.stringn "\x0711では、今日は用があるから…またな。\n"
.stringn "\x0703………………\n"
.stringn "おれって、意外に\n"
.stringn "ラグズとうまくやってけそうだな。うん。"
db 0
.align 4
//MYELL_8_BOLE_VULCI_C

//0x3B00
Text_3AE0:
.stringn "\x05FL|CALILL|GEOFFRAY||\x0C01\x0C13\x0701ふんふん、それで？\n"
.stringn "\x0713……そういった経緯から、\n"
.stringn "姫の存在は公表されることはなく…\n"
.stringn "王宮の奥にある離宮で、密かに育てられたのだ。\n"
.stringn "\x0701あたしたち平民からすると、\n"
.stringn "なんだかややこしい話だねえ。\n"
.stringn "せっかく生まれた娘を\n"
.stringn "世間から隠して育てないといけないなんて…\n"
.stringn "\x0713だが、姫は決して不幸ではなかった。\n"
.stringn "国王陛下ご夫妻、レニング様の\n"
.stringn "愛情を一身に受けられ…\n"
.stringn "王位を継ぐ必要がないからと、\n"
.stringn "気負うことなく、地方貴族の息女のように\n"
.stringn "のびやかに暮らしておられた。\n"
.stringn "\x0701あの日、デインが攻めてこなければ、\n"
.stringn "今でもその幸せは続いてたんだろうね。\n"
.stringn "\x0713…………\n"
.stringn "\x0701あ、ごめん。迂闊なことを言ったね。\n"
.stringn "\x0713いや、構わない。\n"
.stringn "\x0701ええっと、さっきまでの話で、\n"
.stringn "姫の生い立ちはよくわかったよ。\n"
.stringn "ジョフレが姫の乳母の子で、\n"
.stringn "幼い頃からの遊び友達だったってのもね。\n"
.stringn "\x0713…今にして思えば、我が人生において\n"
.stringn "最良の日々だったな。\n"
.stringn "クリミアは平和で、\n"
.stringn "明るい光に満ち溢れていた。\n"
.stringn "姫がいて、姉のルキノがいて\n"
.stringn "私が２人の後ろを追いかけて…\n"
.stringn "\x0701ダメだよ。そんな風に\n"
.stringn "過去の思い出にすがってちゃさ。\n"
.stringn "あたしたちは生きてるんだよ？\n"
.stringn "こうやって戦争してて、\n"
.stringn "血と汗にまみれる日々だけど…\n"
.stringn "希望や、生活を楽しむ心は…\n"
.stringn "どんな時だって忘れちゃいけないんだ。\n"
.stringn "\x0713…カリル殿。\n"
.stringn "すまない、弱音を吐いたようだ。\n"
.stringn "\x0701別にいいけどさ。\n"
.stringn "あたしは完璧な人間より\n"
.stringn "どっか抜けてるほうが\n"
.stringn "人間味があって好きだからね。\n"
.stringn "\x0713ありがとう。\n"
.stringn "とにかく、今はただ…\n"
.stringn "クリミア再興に全力を注ぐ。\n"
.stringn "姫のことは…どんなに深く想ったところで\n"
.stringn "身分の差は越えられぬ。\n"
.stringn "ならばせめて…生涯お仕えし、\n"
.stringn "お近くで姫の幸せを見守りたい。\n"
.stringn "それだけが…私の願いだ。\n"
.stringn "\x0701いっそのこと、\n"
.stringn "さらって逃げちゃえばいいのに。\n"
.stringn "……なーんてね、\n"
.stringn "ジョフレみたいな堅物には無理だよね。\n"
.stringn "わかってるんだ。\n"
.stringn "けど…なんだか切なくてねえ。\n"
.stringn "他人事だってのに。まったく…\n"
.stringn "\x0713…………\n"
.stringn "カリル殿、君はいい人だな。\n"
.stringn "\x0701なんだい、今頃気づいたのかい。\n"
.stringn "あたしみたいないい女、\n"
.stringn "そこら辺じゃちょっと見かけないよ？\n"
.stringn "\x0713認めよう。\n"
.stringn "君は素晴らしい女性だ。\n"
.stringn "\x0701そ、そんなこと言っても\n"
.stringn "もう遅いんだからね。\n"
.stringn "あたしは、あたしだけを見つめて…\n"
.stringn "愛してくれる男にしか興味ないんだから。\n"
.stringn "\x0713そうか…　それは残念なことをした。\n"
.stringn "\x0701あはは　あたしたち、\n"
.stringn "いい友達にはなれたよね？\n"
.stringn "なんでも相談してよ、力になるからさ。"
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_A

//0x345C
Text_343C:
.stringn "\x05FL|CALILL|GEOFFRAY||\x070-\x0703あ、いたいた！\n"
.stringn "ジョフレさま～！\n"
.stringn "\x071-\x0711ん？　ああ…カリル殿。\n"
.stringn "どうかされたか？\n"
.stringn "\x0703うふふ　ちゃあんと\n"
.stringn "あたしのこと、覚えてくれてるじゃないか……\n"
.stringn "これは脈あり、だよねえ？\n"
.stringn "\x0711なんの話だ？\n"
.stringn "\x0703い～え、こっちの話ですわ。\n"
.stringn "ねえ、ジョフレさまって\n"
.stringn "クリミアの王女様の騎士なんでしょう？\n"
.stringn "そんな方とお近づきになれるなんて、\n"
.stringn "あたくし、すごく光栄ですわ！\n"
.stringn "\x0711そんなに大したものではない。\n"
.stringn "カリル殿も私も同じ仲間なのだ、\n"
.stringn "身分などで分け隔てることなく\n"
.stringn "普通に付き合っていただきたいと願う。\n"
.stringn "\x0703え！　そりゃあ願ってもな…いえ。\n"
.stringn "こほん　こちらこそ\n"
.stringn "よろしくお願いしますわぁ。　うふふふ\n"
.stringn "\x0711うむ。\n"
.stringn "\x0703ところで、ジョフレ様？\n"
.stringn "あたくしは、エリンシア姫のこと…\n"
.stringn "よく存じ上げないんですけど……\n"
.stringn "いったいどんなお方なんですか？\n"
.stringn "\x0711姫に、興味がおありか？\n"
.stringn "\x0703ええ。\n"
.stringn "…だって、恋敵かもしれないからねえ。\n"
.stringn "\x0711今、なんと…\n"
.stringn "\x0703い～え、こっちの話ですってば。\n"
.stringn "あたくしたちが守るべき大切な方ですもの、\n"
.stringn "知っておきたくて当然ですわ。\n"
.stringn "お話、聞かせてもらえませんこと？\n"
.stringn "\x0711それは、もちろんだ。…だが\n"
.stringn "どんなお方かと聞かれて、\n"
.stringn "言葉にするのは難しいな……\n"
.stringn "\x0703どうしてですか？\n"
.stringn "\x0711…どんな言葉をもってしても、\n"
.stringn "姫を正確に表現することは難しい。\n"
.stringn "……とにかく…\n"
.stringn "\x0703とにかく？\n"
.stringn "\x0711すべてが素晴らしいお方なのだ。\n"
.stringn "家臣の欲目だと言われそうだが、\n"
.stringn "そんなことは断じてない。\n"
.stringn "何物にも代えがたい…\n"
.stringn "クリミアの宝そのもので……\n"
.stringn "\x0703…………なぁんだ……\n"
.stringn "ジョフレ様って、姫にぞっこん？\n"
.stringn "あ～もう！　どうしてこう\n"
.stringn "いい男には縁がないんだろうね！！\n"
.stringn "\x0711な……なっ！！？\n"
.stringn "待ってくれ、カリル殿！\n"
.stringn "誤解だ！　私はその…………\n"
.stringn "\x0703あ～あ…\n"
.stringn "お強い騎士様がうろたえちゃって…\n"
.stringn "まったく可愛いったら、ありゃしないねえ。\n"
.stringn "いいよいいよ。\n"
.stringn "あたしのもんにならないのは残念だけど、\n"
.stringn "恋話なら、カリルさんのお得意分野さ。\n"
.stringn "うぶな騎士様と姫君の恋愛成就に\n"
.stringn "一肌脱いでやろうじゃないか。"
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_B

//0x31EC
Text_31CC:
.stringn "\x05FL|CALILL|GEOFFRAY||\x0701うーん…　どうしようかねぇ……\n"
.stringn "…………きゃっ！？\n"
.stringn "\x0712！　あぶない！\n"
.stringn "\x0701！　！　！\n"
.stringn "\x0C12\x0C12\x0713平気か、お嬢さん？\n"
.stringn "\x0701ま、まあ……\n"
.stringn "お嬢さんだなんて……\n"
.stringn "そ、そうですわね。\n"
.stringn "聖騎士さまのおかげで\n"
.stringn "どうやら無傷で済んだようですわ。\n"
.stringn "\x0713そうか。よかった。\n"
.stringn "考え事もいいが、足元には\n"
.stringn "くれぐれも気をつけてな。\n"
.stringn "\x0701ちょ、ちょっと！　待って！\n"
.stringn "\x0C13\x0714何か？\n"
.stringn "\x0701あたし…　いえ、あたくしは\n"
.stringn "カリルっていうんですけど……\n"
.stringn "聖騎士様のお名前は？\n"
.stringn "\x0714ジョフレだ。\n"
.stringn "それでは、また。\n"
.stringn "\x0701ジョフレ様……\n"
.stringn "いいじゃないかぁ。\n"
.stringn "ああいう上等な男こそ、\n"
.stringn "このカリルさんにはお似合いなんだよ。\n"
.stringn "あぁ…　恋ってほんと\n"
.stringn "突然やってきちゃうんだよねえ。"
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_C

//0x4998
Text_4978:
.stringn "\x05FL|CALILL|NEPHENEE||\x0C03\x0C11\x0703ん？　ネフェニー、袋なんて下げて\n"
.stringn "どこか出かけてきたのかい？\n"
.stringn "\x0711近くに、ロシュの木の実が……\n"
.stringn "なっとったから……\n"
.stringn "\x0703へえ……で、\n"
.stringn "そのロシュってのは…なんなんだい？\n"
.stringn "\x0711虫さされの……薬です。\n"
.stringn "\x0703ふーん、そんなもんがあるんだねえ。\n"
.stringn "田舎の知恵ってやつかい？\n"
.stringn "あたしは王都育ちだからよく知らないんだけど。\n"
.stringn "ま、いいや、１つおくれよ。\n"
.stringn "\x0711ええんですけど……\n"
.stringn "生の実を手でさわると……\n"
.stringn "肌がかぶれますけえ。\n"
.stringn "\x0703ああ、わかってるよ。\n"
.stringn "こうやって持てばいいんだろう？\n"
.stringn "\x0711……なんで知っとるんですか？\n"
.stringn "\x0703…………\n"
.stringn "\x0711王都育ちじゃって…ずっとそう言うて……\n"
.stringn "\x0703う、うるさいね！\n"
.stringn "ネフェニー、今のは内緒だよ？\n"
.stringn "あたしは洗練された都会の女なんだから！\n"
.stringn "いいね！\n"
.stringn "\x0711…………\n"
.stringn "\x0703な、なんだい。\n"
.stringn "田舎者だって思われたくないのは……\n"
.stringn "あたしだって一緒ってことさ。\n"
.stringn "だからあんたの気持ちは…よくわかるんだよ…\n"
.stringn "\x0711…………わかった……\n"
.stringn "……でも……そっかあ。\n"
.stringn "努力すりゃあ……カリルさんみたいに\n"
.stringn "なれるんじゃな……よかった。\n"
.stringn "あたし……がんばるよ。\n"
.stringn "\x0703そう、その意気だよ。\n"
.stringn "いい男見つけて、村へ帰るんだよ！\n"
.stringn "がんばんな！"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_A

//0x4610
Text_45F0:
.stringn "\x05FL|CALILL|NEPHENEE||\x070-\x0C03\x0C11\x0703おや、ネフェニー。\n"
.stringn "どうだい、調子は？\n"
.stringn "\x0711……カリルさん。\n"
.stringn "\x0703ほら、ちょっと顔上げてみなよ。\n"
.stringn "…うーん、やっぱその兜がいけてないよ。\n"
.stringn "せっかく化粧してるのに。薄いけど。\n"
.stringn "\x0711いいんです……\n"
.stringn "取ったら……じろじろ見られるし……\n"
.stringn "\x0703…それは暗に自分が可愛いってことを\n"
.stringn "主張してるのかね？\n"
.stringn "\x0711え？\n"
.stringn "\x0703……自覚なし、かい。\n"
.stringn "いいねえ……あんたは。\n"
.stringn "胸だってあるのに……\n"
.stringn "全部隠しちまってさ……\n"
.stringn "なんかちょっと、ムカついてくるねえ……\n"
.stringn "\x0711で、でも……あたし……\n"
.stringn "カリルさんみたいに、堂々と……生きれん。\n"
.stringn "田舎もん……だから……\n"
.stringn "\x0703そうなんだよねえ～。\n"
.stringn "人の目が気になるからさ、なかなか\n"
.stringn "自分を着飾ったりできないんだけど…\n"
.stringn "でも、都会の人は冷たいからねぇ。\n"
.stringn "他人のことなんか気にしちゃいないんだよ。\n"
.stringn "\x0711……でも……\n"
.stringn "カリルさん、親切だよ……？\n"
.stringn "\x0703！\n"
.stringn "あ、ああ、そう？\n"
.stringn "私は都会生まれだけど、常識人だからね！\n"
.stringn "とにかく、諦めるんじゃないよ、ネフェニー！\n"
.stringn "あんたはかわいいんだから、ね？\n"
.stringn "\x0711…………うん……"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_B

//0x42F8
Text_42D8:
.stringn "\x05FL|CALILL|NEPHENEE||\x0703ん？　そこのあんた、\n"
.stringn "ちょいとおまちよ。\n"
.stringn "\x0711……？\n"
.stringn "\x0703なんだいなんだい、\n"
.stringn "若い娘がそんな兜で顔かくしちまって。\n"
.stringn "化粧の１つでもしたらどうだい？\n"
.stringn "\x0711……別に、そんなの……\n"
.stringn "どうでもいい……\n"
.stringn "\x0703…………\n"
.stringn "あんた、生まれはどこだい？\n"
.stringn "\x0711……どこでもいい…です。\n"
.stringn "\x0703愛想のない娘だねえ。\n"
.stringn "まあ、あんまり\n"
.stringn "喋りたくない気持ちはわかるよ。\n"
.stringn "田舎なまりが出ると\n"
.stringn "恥ずかしいっていうんだろ？\n"
.stringn "\x0711！　な、なんで……\n"
.stringn "\x0703なんでわかるかって？\n"
.stringn "あたしの昔なじみが…\n"
.stringn "あんたと同じ悩みを抱えてたからねえ。\n"
.stringn "\x0711…………\n"
.stringn "\x0703そうだ、\n"
.stringn "あたしが一肌脱いでやるよ。\n"
.stringn "あんたみたいな田舎くさいのがいると\n"
.stringn "こっちまで滅入っちまうからね。\n"
.stringn "気晴らしに化粧の仕方を教えてやるよ。\n"
.stringn "\x0711……い、いら…りません。\n"
.stringn "\x0703ほらほら、変な言葉使ってないで。\n"
.stringn "このカリルさんに、ぜ～んぶまかせときな。\n"
.stringn "悪いようにはしないからさ。\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_C

//0x5424
Text_5404:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x0713なぁ、カリル先生…\n"
.stringn "おいらの魔道、どう？\n"
.stringn "\x0701…そうだねぇ。\n"
.stringn "\x0713……\n"
.stringn "\x0701よく頑張ったね。\n"
.stringn "もう、あたしが教えることはないよ。\n"
.stringn "\x0713ぃやった！\n"
.stringn "これでおいらも一人前だ！\n"
.stringn "\x0701ふふ　あんたのおかげで\n"
.stringn "あたしも刺激されたよ。\n"
.stringn "もう１度、魔道を学ぼうって\n"
.stringn "気になっちまったじゃないか。\n"
.stringn "\x0713え…　先生でも\n"
.stringn "まだ覚えることあんのか？\n"
.stringn "\x0701何言ってんの。\n"
.stringn "あたしが教えたのは、\n"
.stringn "魔道のほんの一部分さ。\n"
.stringn "ここまでは、修行を積めば\n"
.stringn "誰にだって習得できる。\n"
.stringn "これから先に進めるかどうかは…\n"
.stringn "自分の資質との戦いだよ。\n"
.stringn "\x0713資質って…？\n"
.stringn "\x0701生まれ持った才能、ってやつだね。\n"
.stringn "魔道を極めるには\n"
.stringn "これがあるかどうかが鍵だ。\n"
.stringn "\x0713お、おいらは！？\n"
.stringn "おいらの魔道の資質は…？\n"
.stringn "\x0701……残念だけど、\n"
.stringn "あんたは私と同じ凡人。\n"
.stringn "大した資質は持ってないね。\n"
.stringn "\x0713…じゃあ、\n"
.stringn "おいらは、ここまでなのか？\n"
.stringn "どんなに努力しても、\n"
.stringn "最強の魔道士にはなれないのか？\n"
.stringn "\x0701……ある方法を使って\n"
.stringn "魔力を高めることはできるが、\n"
.stringn "それにも限界があるしね。\n"
.stringn "\x0713ど、どんな方法なんだ！？\n"
.stringn "\x0701自分の体に精霊を宿すのさ。\n"
.stringn "いわゆる【精霊の護符】ってやつさ。\n"
.stringn "\x0713精霊の…ごふ？\n"
.stringn "\x0701そう。\n"
.stringn "魔道の源は\n"
.stringn "大自然を司る精霊の力。\n"
.stringn "それを体内に取り込んで、\n"
.stringn "手っ取り早く、自分の魔力を上げる手段だ。\n"
.stringn "簡単に言えば、自分自身を餌にして\n"
.stringn "精霊を飼うってことになるかねぇ。\n"
.stringn "\x0713く、食われるのか？\n"
.stringn "\x0701魂を削られるらしいよ…\n"
.stringn "魔力の代償としてね。\n"
.stringn "だから、よっぽどの覚悟がなきゃ\n"
.stringn "やらないほうがいい。\n"
.stringn "\x0713…そんな危ないこと\n"
.stringn "やる奴いるのか？\n"
.stringn "\x0701それが、結構いるんだよね。\n"
.stringn "この軍の参謀殿とかも、多分そうさ。\n"
.stringn "\x0713セネリオってやつ？\n"
.stringn "\x0701額に浮き出てる模様があるだろ。\n"
.stringn "精霊と契約すると\n"
.stringn "ああいった印が現れるんだ。\n"
.stringn "\x0713あ、あれか…！\n"
.stringn "あれがそうなら、おいらも見たことある。\n"
.stringn "おいらに魔道を教えてくれた\n"
.stringn "砂漠のじいちゃんの手のひらにもあった。\n"
.stringn "\x0701…ベグニオンやデインでは、\n"
.stringn "【印つき】と間違われるからって理由で\n"
.stringn "避ける人も多いみたいだけどね。\n"
.stringn "\x0713え？\n"
.stringn "なんだって？\n"
.stringn "\x0701まぁ、とにかく\n"
.stringn "精霊との契約はやめときなって話だ。\n"
.stringn "\x0713でもなぁ…\n"
.stringn "おいら、強くなりたいし…\n"
.stringn "\x0701契約しなくたって、\n"
.stringn "まだ努力する余地はあるさ。\n"
.stringn "凡人同士、\n"
.stringn "助け合っていこうじゃないか。\n"
.stringn "\x0713そ、そうだな。\n"
.stringn "よし！\n"
.stringn "おいら、最強の凡魔道士を目指すぜ！！\n"
.stringn "\x0701あはは　その調子だ。"
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_A

//0x5000
Text_4FE0:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x0C13\x0701トパック！\n"
.stringn "いいかげんにおしってば！！\n"
.stringn "\x0713いいじゃんか。\n"
.stringn "早く次の魔法、教えてくれよ。\n"
.stringn "\x0701ダメだよ。\n"
.stringn "\x0713おいら、ちゃんとできてるじゃねえか！\n"
.stringn "炎も、雷も、風も！\n"
.stringn "\x0701あんたの覚えの早さは認める。\n"
.stringn "正直、たいしたもんだよ。\n"
.stringn "\x0713だろ？\n"
.stringn "\x0701けどね、中身がなっちゃいない。\n"
.stringn "いっぺんにつめこんだって\n"
.stringn "1つ１つがちゃんと使えなきゃ\n"
.stringn "習得したって言えないんだから。\n"
.stringn "\x0713そんなこと言って\n"
.stringn "カリルは、おいらのほうが\n"
.stringn "才能あるのが悔しいんだろ！\n"
.stringn "追い抜かれるのがやなんだろ！\n"
.stringn "\x0701…ふぅ\n"
.stringn "いいかい？　よく聞きな。\n"
.stringn "中途半端な呪文詠唱じゃ、\n"
.stringn "いつか事故を起こすよ？\n"
.stringn "\x0713事故？\n"
.stringn "\x0701魔道の暴発だよ。\n"
.stringn "指がふっとんだり…\n"
.stringn "ああ、指だけならたいしたことないね。\n"
.stringn "腕をもってかれることもあるし、\n"
.stringn "悪くすれば、命がなくなることもある。\n"
.stringn "\x0713か、覚悟の上さ…\n"
.stringn "\x0701自分の、とは言ってないよ。\n"
.stringn "\x0713え？\n"
.stringn "\x0701敵に放ったつもりが、\n"
.stringn "味方に直撃…\n"
.stringn "そして、大事な者を失う……\n"
.stringn "\x0713……\n"
.stringn "\x0701魔道ってのはね、\n"
.stringn "他の武器とは違うんだ。\n"
.stringn "使い手の能力が低いと\n"
.stringn "大事故になりかねない。\n"
.stringn "これは、脅しでもなんでもないよ。\n"
.stringn "\x0713……うん。\n"
.stringn "\x0701じゃあ、ちゃんと基礎をやりな。\n"
.stringn "戦場で味方の足、\n"
.stringn "ひっぱりたくないだろ？\n"
.stringn "\x0713うん…！"
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_B

//0x4D80
Text_4D60:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x071-\x0713なぁなぁ、\n"
.stringn "キレイなオバさん！\n"
.stringn "\x0701……\n"
.stringn "\x0713あれ？\n"
.stringn "派手なおねえさんだっけ？\n"
.stringn "\x0701キレイな！\n"
.stringn "おねえさん！！\n"
.stringn "…じゃないと返事しないよ。\n"
.stringn "\x0713ちぇっ\n"
.stringn "めんどくせえの。\n"
.stringn "\x0701じゃあ、やめたっていいんだよ？\n"
.stringn "あたしだって\n"
.stringn "あんたみたいなガキに\n"
.stringn "魔道を教えるのなんてゴメン…\n"
.stringn "\x0713キレイなおねえさん！\n"
.stringn "カリルさん！\n"
.stringn "お願いだから\n"
.stringn "おいらに魔道、教えてください！\n"
.stringn "\x0701…ったく。\n"
.stringn "現金なガキだねえ。\n"
.stringn "で、この間教えたとこまでは\n"
.stringn "どうなんだい？\n"
.stringn "ちゃんと習得できてなきゃ\n"
.stringn "新しいのは教えないよ。\n"
.stringn "\x0713ばっちり！\n"
.stringn "つーか、おいら、\n"
.stringn "この本のやつは全部マスターしたぜ。\n"
.stringn "\x0701本当かい？\n"
.stringn "\x0713今から見せるからさ。\n"
.stringn "ちゃんとできてるか確認してくれよ？\n"
.stringn "\x0701はいはい。"
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_C

//0x63D0
Text_63B0:
.stringn "\x05FL|CHAP|NEPHENEE||\x0701おおい、ネフェニー。\n"
.stringn "\x071-\x0713あ、チャップさん。\n"
.stringn "\x0701さっき、若いもんらから聞いたぞ。\n"
.stringn "おまえさん、あんまり\n"
.stringn "ほかのみんなと口をきかんそうじゃないか。\n"
.stringn "\x0713だ、だってなあ……\n"
.stringn "あたし田舎者じゃけぇ、\n"
.stringn "恥ずかしいんじゃあ……\n"
.stringn "\x0701なにが恥ずかしいもんかい、\n"
.stringn "田舎でよかろうに。\n"
.stringn "\x0713あたしの喋り、\n"
.stringn "すげえなまっとるけえ。\n"
.stringn "馬鹿にされるじゃろう……\n"
.stringn "チャップさんみたいに\n"
.stringn "うまく普通に喋れんもん……\n"
.stringn "\x0701何言うとるかね、この団に\n"
.stringn "そんな悪い人はおりゃあせんよ。\n"
.stringn "そんなかちこちしとらんと、\n"
.stringn "村におる頃みたいに\n"
.stringn "ふつうにできんのんかね？\n"
.stringn "\x0713…………\n"
.stringn "\x0701あんたはわしと話すときは\n"
.stringn "明るい笑顔しとるじゃないか。\n"
.stringn "あんな綺麗な笑顔なのに、\n"
.stringn "隠しとるなんてもったいない。\n"
.stringn "ほれ、ためしにここで笑ってみんかね。\n"
.stringn "\x0713え、ええ……？\n"
.stringn "\x0701ほれ、笑って笑って。\n"
.stringn "\x0713は、恥ずかしいなぁ……もう。\n"
.stringn "こ、こう？\n"
.stringn "\x0701そうそう、それじゃ。\n"
.stringn "その笑顔さあ。\n"
.stringn "あんたもとが器量良しなんじゃから\n"
.stringn "そうしてりゃ、\n"
.stringn "団の若い男どもがほっとかんよ。\n"
.stringn "ここでいい人を見つけて、\n"
.stringn "村に一緒に帰ったらどうかねえ？\n"
.stringn "\x0713も、もう……\n"
.stringn "何言うんよ、チャップさん！"
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_A

//0x5EB8
Text_5E98:
.stringn "\x05FL|NEPHENEE|CHAP||\x0C03\x0711兵舎っちゅうのは、\n"
.stringn "いったいどこかねえ？\n"
.stringn "\x0703さあ……？\n"
.stringn "\x0711よくみんな迷わずに\n"
.stringn "ちゃんとわかるもんじゃなあ。\n"
.stringn "毎日毎日宿が変わるもんじゃから\n"
.stringn "わしゃあなんだか落ち着かんよ。\n"
.stringn "\x0703しょうがねえよ、戦じゃけぇ。\n"
.stringn "あたしらぁも\n"
.stringn "はよぉ慣れんといけんね。\n"
.stringn "\x0711そうじゃなあ……\n"
.stringn "わしもおまえさんも\n"
.stringn "今まで戦なんかとは\n"
.stringn "縁がなかったもんなあ。\n"
.stringn "\x0703そうじゃなあ。\n"
.stringn "だから軍の当たり前が\n"
.stringn "よぉわからんのんじゃ。\n"
.stringn "\x0711そういえば、志願したときは\n"
.stringn "大変じゃったなあ。\n"
.stringn "なにしろわしら民兵ゆうたら\n"
.stringn "ほとんどそこらの村人の集まりじゃあ。\n"
.stringn "理想はあっても力と技がついてこんわ。\n"
.stringn "\x0703そうそう。\n"
.stringn "装備も数が足りんからゆうて\n"
.stringn "あたしとチャップさん、\n"
.stringn "２人分で弓１つ渡されて。\n"
.stringn "しかもどっちも使えりゃあせんのに、もう。\n"
.stringn "\x0711今回の戦は、\n"
.stringn "ほんまに突然じゃったからなあ。\n"
.stringn "わしらがまともにやった訓練といえば\n"
.stringn "点呼だけで…\n"
.stringn "行軍するたびにみんな逃げたりはぐれたりで、\n"
.stringn "いざ戦う前からどんどん\n"
.stringn "人が減っていったっけなあ。\n"
.stringn "そりゃあ負けて捕まるのも無理ないなあ。\n"
.stringn "それに比べれば、この軍は\n"
.stringn "えらく優秀なもんじゃ。\n"
.stringn "\x0703そりゃ、王女さまの軍じゃけぇ。\n"
.stringn "でも、ほんまに場所わからんなあ。\n"
.stringn "\x0711まあいいさ、とにかくそのへんの\n"
.stringn "誰かに聞いてみようかね。\n"
.stringn "\x0703う、うん……\n"
.stringn "\x0711ん？　どうしたね？\n"
.stringn "\x0703あたし……あんまり\n"
.stringn "都会の人と話すの慣れとらんのじゃ。\n"
.stringn "\x0711なに言ってるかね、そんな。\n"
.stringn "いつもどおり、\n"
.stringn "普通にしてたらいいじゃないか。\n"
.stringn "\x0703だ、だってなあ……\n"
.stringn "あたし田舎者じゃけえ……"
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_B

//0x5BF8
Text_5BD8:
.stringn "\x05FL|NEPHENEE|CHAP||\x070-\x0C03\x071-\x0711今日はいい天気じゃなあ、\n"
.stringn "ネフェニー。\n"
.stringn "\x0703うんうん、ほんまに。\n"
.stringn "\x0711ネフェニー、\n"
.stringn "おまえさんとこはどうだい？\n"
.stringn "今頃は畑の収穫に精が出るころかあ。\n"
.stringn "\x0703ああ、そうじゃなあ。\n"
.stringn "妹と弟らぁが、母さんの手伝いに借り出されて\n"
.stringn "文句言よぉるよ、きっと。\n"
.stringn "\x0711ははは　そりゃ遊びたい盛りじゃもんなあ。\n"
.stringn "ネフェニーんとこは、何人家族だったかねえ？\n"
.stringn "\x0703妹が２人に弟が３人。\n"
.stringn "弟は３人じゃけど３つ子でな、\n"
.stringn "まだ６歳なんじゃ。\n"
.stringn "\x0711そりゃあヤンチャな盛りじゃなあ。\n"
.stringn "さぞ家ん中もにぎやかなことじゃろう。\n"
.stringn "\x0703うん、毎日母さんに\n"
.stringn "怒鳴られとるじゃろうなあ。\n"
.stringn "チャップさんとこは？\n"
.stringn "\x0711うちのはもうちょっと大きいなあ。\n"
.stringn "ちゃんと母ちゃんの手伝い\n"
.stringn "やってくれとるといいんじゃけど……\n"
.stringn "\x0703大丈夫、\n"
.stringn "ちゃんとやりょおるよ、きっと。"
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_C

//0x7210
Text_71F0:
.stringn "\x05FL|ZIHARK|CHAP||\x0C01\x071-\x0713…でなあ。\n"
.stringn "１番上の娘は、わしみたいにこう…\n"
.stringn "恰幅が良くてねえ。\n"
.stringn "野良仕事も男並にできるいい娘なんじゃ。\n"
.stringn "おまえさんも、きっと気に入ると思うよ。\n"
.stringn "\x0701ああ…うん。\n"
.stringn "\x0713そんな生返事しとらんで、\n"
.stringn "ちゃあんと聞かんといかんよ。\n"
.stringn "嫁さんになるかもしれん\n"
.stringn "娘のことなんだからねえ。\n"
.stringn "\x0701チャップさん……\n"
.stringn "この間は言いそびれたけど、\n"
.stringn "俺はまだ所帯を持つ気はないんだ。\n"
.stringn "\x0713おや…どうしてだい？\n"
.stringn "\x0701……昔…大切な恋人がいたんだ。\n"
.stringn "事情があって一緒には\n"
.stringn "なれなかったんだけど……\n"
.stringn "俺はいまだに、その子に未練があってさ。\n"
.stringn "忘れられない。\n"
.stringn "だから、チャップさんの気持ちは\n"
.stringn "嬉しいけど…ごめん。\n"
.stringn "\x0713そうだったのかい。\n"
.stringn "残念だねえ…\n"
.stringn "\x0701チャップさんの家族に\n"
.stringn "なれるっていうのは…\n"
.stringn "かなり魅力的だったんだけどね。\n"
.stringn "\x0713……\n"
.stringn "じゃあ２番目の娘はどうかね？\n"
.stringn "年が少しばかり離れちまうが、\n"
.stringn "まあ、そんなに気にせんでええ。\n"
.stringn "これがまた気立てのいい子でねえ。\n"
.stringn "笑うとこう、ふっくらホッペにえくぼが……\n"
.stringn "\x0701いや、\n"
.stringn "そういうことじゃないんだ。\n"
.stringn "困ったな……"
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_A

//0x6C5C
Text_6C3C:
.stringn "\x05FL|ZIHARK|CHAP||\x070-\x0C01\x071-\x0713やあ、ツイハーク。\n"
.stringn "こないだは楽しかったねえ。\n"
.stringn "\x0701そうだな。\n"
.stringn "チャップさんは話し上手だから\n"
.stringn "食事の間中、笑わされっぱなしだったよ。\n"
.stringn "あんな楽しい食事は久しぶりだ。\n"
.stringn "\x0713そう言うてもらえると\n"
.stringn "誘ったかいがあったねえ。\n"
.stringn "\x0701あ、そうだこれ。\n"
.stringn "俺の分なんだけど。\n"
.stringn "\x0713ああ、かまわんよ。\n"
.stringn "わしから誘ったんじゃ。\n"
.stringn "おごらせてもらうよ。\n"
.stringn "\x0701そうはいかない。\n"
.stringn "急な誘いで持ち合わせがなかったが\n"
.stringn "今日はちゃんと持っている。\n"
.stringn "きっちり半分、払わせてもらうから。\n"
.stringn "\x0713そんなこと言われてもなあ…\n"
.stringn "いくら払ったかなんて、もう覚えとらんよ。\n"
.stringn "\x0701全部で４と半ゴールドだった。\n"
.stringn "だから２と４分の１ゴールドを\n"
.stringn "返して貸し借りなしだ。\n"
.stringn "\x0713はぁ～　若いのに\n"
.stringn "しっかりしとるねえ。\n"
.stringn "記憶力はいいし、計算も速い。\n"
.stringn "\x0701きっちりしたいのは性分なんだ。\n"
.stringn "大らかでずさんな傭兵仲間達には\n"
.stringn "結構、けむたがられるんだけどね。\n"
.stringn "\x0713いやあ。それだけ\n"
.stringn "いい男ぶりで真面目なんじゃ。\n"
.stringn "若い娘さんには\n"
.stringn "さぞやもてるんじゃないかい？\n"
.stringn "\x0701そうでもないさ。\n"
.stringn "俺みたいな奴を好いてくれる\n"
.stringn "もの好きな女の子には…\n"
.stringn "なかなか出会えない。\n"
.stringn "\x0713ほえぇ　世の中わからんもんじゃなあ。\n"
.stringn "わしみたいに、ぼんやりした男でも\n"
.stringn "所帯をもっとるっていうのになあ。\n"
.stringn "\x0701ははは　チャップさんは\n"
.stringn "いい男だって。俺が保証する。\n"
.stringn "\x0713そうだ！　うちの娘をもらえばええ。\n"
.stringn "\x0701え？\n"
.stringn "急に何を言い出すんだい？\n"
.stringn "\x0713自慢じゃないが、\n"
.stringn "いい子たちばかりじゃ。\n"
.stringn "わしはツイハークを気にいっとるし、\n"
.stringn "娘たちじゃってきっと気にいる。\n"
.stringn "\x0701チャップさん、冗談はそれくらいに…\n"
.stringn "\x0713どうだい、\n"
.stringn "１番上の娘なら、年もちょうど\n"
.stringn "釣り合うと思うんだがねえ。\n"
.stringn "\x0701いや…　弱ったな。\n"
.stringn "俺はそんなつもりは……"
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_B

//0x67B0
Text_6790:
.stringn "\x05FL|ZIHARK|CHAP||\x0C03\x0711おんや……\n"
.stringn "おまえさん、そんなところで\n"
.stringn "何をしとるんかね？\n"
.stringn "\x0703やあ、チャップさん。\n"
.stringn "ちょっと肩当ての補修をね。\n"
.stringn "ほら、ここが裂けてたから。\n"
.stringn "\x0711本当じゃ。このまんま\n"
.stringn "戦ったりしたら危ないねえ……\n"
.stringn "って…　んん？\n"
.stringn "なんで、わしの名前を知っとるのかね？\n"
.stringn "\x0703ああ…　俺は職業柄から、\n"
.stringn "人の顔と名前を覚えるのは得意なんだ。\n"
.stringn "挨拶がまだなのに、馴れ馴れしくして\n"
.stringn "驚かせてしまって申し訳ない。\n"
.stringn "俺はツイハーク。\n"
.stringn "これからよろしく頼むよ、チャップさん。\n"
.stringn "\x0711やあ、こりゃあどうも……\n"
.stringn "ご丁寧に。\n"
.stringn "肩当てを修理しとって、職業柄ってことは…\n"
.stringn "おまえさんは皮職人かなにかかい？\n"
.stringn "\x0703違うよ。俺は剣士だ。\n"
.stringn "傭兵としてアイクに雇われている。\n"
.stringn "\x0711はあ…剣士さんがこんなものを\n"
.stringn "修理もできるのかい。えらい器用なもんじゃ。\n"
.stringn "\x0703これくらい自分でできないと。\n"
.stringn "傭兵なんて貧乏だからね。\n"
.stringn "よし、これでいい。\n"
.stringn "\x0711ほう…見事なもんだねえ。\n"
.stringn "うちの２番目の息子にも\n"
.stringn "見習わせんといけんなあ。\n"
.stringn "\x0703チャップさんとこは、\n"
.stringn "子供は何人だい？\n"
.stringn "\x0711息子が５人で娘が３人じゃ。\n"
.stringn "１番上の子がちょうど\n"
.stringn "おまえさんと同じくらいじゃな。\n"
.stringn "\x0703やっぱり子だくさんなんだな。\n"
.stringn "そんな感じがしたんだ。\n"
.stringn "\x0711そりゃあ、いったいどんな感じだい？\n"
.stringn "\x0703気のいいおとっつあん。\n"
.stringn "チャップさんにはぴったりだろ。\n"
.stringn "\x0711そ、そうかねえ？\n"
.stringn "そんな風に言われると\n"
.stringn "こそばゆい感じがして落ち着かんよ。"
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_C

//0x7F48
Text_7F28:
.stringn "\x05FL|GATRIE|CHINON||\x0705…………\n"
.stringn "\x0713ん？\n"
.stringn "\x0705…………\n"
.stringn "\x0713おい、何ぼけっと\n"
.stringn "突っ立ってんだガトリー？\n"
.stringn "\x0C05\x0C05\x0701あ、シノンさん\n"
.stringn "おれ、彼女を待ってるんす。\n"
.stringn "\x0713ああ、例の女か。\n"
.stringn "じゃあ、うまくいったんだな？\n"
.stringn "\x0701そりゃあもう！\n"
.stringn "シノンさんに選んでもらった\n"
.stringn "贈り物もって会いに行ったら\n"
.stringn "彼女、そりゃあ喜んじゃって…\n"
.stringn "実はですね、\n"
.stringn "すぐ結婚しようってことになったんです。\n"
.stringn "\x0713そいつはまた…\n"
.stringn "いきなりな展開だな。\n"
.stringn "\x0701ところがその子、なんでも\n"
.stringn "不治の病にかかってるらしくて\n"
.stringn "治療代のゴールド払えないと、\n"
.stringn "余命数日の命らしいんです。\n"
.stringn "で、おれ今が\n"
.stringn "金の使い時だと思って……\n"
.stringn "\x0713渡したのか？\n"
.stringn "\x0701ええ、有り金全部。\n"
.stringn "そしたらその額がちょうど\n"
.stringn "治療代とぴったり同じっていうじゃないですか！\n"
.stringn "これってやっぱ運命ですよね？\n"
.stringn "女神さまがおれと彼女をめぐり合わせるために\n"
.stringn "用意しといてくれたんですよ！\n"
.stringn "\x0713……で？\n"
.stringn "\x0701こんな時だけど…\n"
.stringn "いや、こんな時だからこそ\n"
.stringn "すぐ式を挙げようってことになって。\n"
.stringn "本当はあの子が来てから、\n"
.stringn "みんなに盛大に発表しようと\n"
.stringn "思ったんすけど……\n"
.stringn "まだ、来ないんすよね。\n"
.stringn "……心配だなぁ。\n"
.stringn "家には行ってみたんすけど、\n"
.stringn "おれ、場所を聞きまちがえてたみたいで\n"
.stringn "空き家しかなかったんですよね。\n"
.stringn "でも、大丈夫。\n"
.stringn "彼女はおれがこの軍にいるって\n"
.stringn "知ってるし。\n"
.stringn "\x0713…ガトリー……\n"
.stringn "おまえ、だまされてるぞ。\n"
.stringn "\x0701えええ！\n"
.stringn "そんなわけないじゃないすか！？\n"
.stringn "あんな清らかな子が！\n"
.stringn "\x0713なんで余命数日が\n"
.stringn "街角うろうろしてんだよ。\n"
.stringn "\x0701そ、それは……\n"
.stringn "おれと出会うためですよ！\n"
.stringn "\x0713じゃあ、なんで現れないんだよ。\n"
.stringn "\x0701それは……それはですね……\n"
.stringn "\x0713ガトリー…\n"
.stringn "\x0701……あははは…\n"
.stringn "…やっぱ、おれ…\n"
.stringn "まただまされたんすかね…\n"
.stringn "\x0713…女の人相とか、教えろよ。\n"
.stringn "\x0701え？　けど…\n"
.stringn "\x0713有り金全部ってのは\n"
.stringn "タチ悪すぎだ。\n"
.stringn "オレがひっつかまえて、\n"
.stringn "金を取り戻して来てやるぜ。\n"
.stringn "\x0701……\n"
.stringn "うーん、やっぱいいっす。\n"
.stringn "おれが渡した金っすから……\n"
.stringn "\x0713いいのかよ？\n"
.stringn "その女、今ごろおまえのこと笑ってんだぜ。\n"
.stringn "\x0701まあ、あの子の笑顔可愛かったし。\n"
.stringn "\x0713はぁ…　どこまで\n"
.stringn "おめでたくできてんだ、おまえは？\n"
.stringn "\x0701いいんす…\n"
.stringn "おれ、それだけが取り柄みたいっスから。\n"
.stringn "\x0713…ま、これで\n"
.stringn "金の使い道を悩まなくてすんだな。\n"
.stringn "\x0701そうっすね、そう考えたら\n"
.stringn "逆に良かったっすね！\n"
.stringn "\x0713…ったく。\n"
.stringn "酒でも飲まねえと\n"
.stringn "やってらんねぇな。\n"
.stringn "\x0701あ、じゃあ！　おれもおれも！\n"
.stringn "あ…しまった金がないや……\n"
.stringn "やっぱおれいいっす。\n"
.stringn "\x0713来いよ。\n"
.stringn "オレが１杯おごってやる。\n"
.stringn "\x0701え、いいんすか？\n"
.stringn "\x0713ああ。\n"
.stringn "\x0701…へへへ\n"
.stringn "\x0713なに笑ってやがる？\n"
.stringn "\x0701シノンさんのおごり酒飲めるなんて\n"
.stringn "今日はおれ、ついてるかなって。\n"
.stringn "\x0713……ったく。\n"
.stringn "おめでたい奴だ。"
db 0
.align 4
//MYELL_8_CHINON_GATRIE_A

//0x7B20
Text_7B00:
.stringn "\x05FL|GATRIE|CHINON||\x0C03\x0C15\x0703なぁ、シノンさ～ん！\n"
.stringn "\x0715今は取り込み中だ。\n"
.stringn "後にしろって言ってんだろ。\n"
.stringn "\x0703どうしても\n"
.stringn "すぐに聞いてほしいことが、あるんすよ。\n"
.stringn "\x0715だめだ。\n"
.stringn "\x0703今日も、酒代はおれ持ちでいいすから。\n"
.stringn "\x0715うるせぇ。\n"
.stringn "\x0703いつもより高い酒、飲んでいいすから。\n"
.stringn "\x0715…つまみは？\n"
.stringn "\x0703秘蔵の燻製肉！\n"
.stringn "あれ、だします！\n"
.stringn "\x0C15\x0C15\x0711仕方ねえなぁ。\n"
.stringn "可愛い弟分のためだ。\n"
.stringn "ちょっとだけ時間を割いてやるか。\n"
.stringn "\x0703恩にきるっす！\n"
.stringn "\x0711で、なんだ？\n"
.stringn "\x0703なにって、いやぁ～\n"
.stringn "まいったなぁ。\n"
.stringn "\x0711なんだよ？\n"
.stringn "\x0703まいったなぁ～\n"
.stringn "どうしようかなぁ～…\n"
.stringn "そんなに聞きたいんすか？\n"
.stringn "\x0711ケッ　死ぬまでやってろ。\n"
.stringn "\x0703ま、待って！\n"
.stringn "待ってくださいって！\n"
.stringn "今から話しますって！！\n"
.stringn "\x0711ったく。\n"
.stringn "さっさとしろよ。\n"
.stringn "\x0703おれ…\n"
.stringn "か、か、彼女ができたんすっ！\n"
.stringn "\x0711へぇ？　そいつは\n"
.stringn "物好きな女もいたもんだ。\n"
.stringn "\x0703この間、町に出た時、出会ったんす！\n"
.stringn "ものすっっっごくカワイイ子なんす！\n"
.stringn "今度こそ本当に運命の赤い糸なんす！\n"
.stringn "\x0711よかったじゃねえか。\n"
.stringn "そうか、わかったぞ。\n"
.stringn "その女に渡すプレゼントをオレに\n"
.stringn "相談したいってんだろ？\n"
.stringn "\x0703へへへへ\n"
.stringn "何がいいっすかね？\n"
.stringn "\x0711そういうことなら、まかせな。\n"
.stringn "酒飲みながら\n"
.stringn "じーっくり教えてやるぜ。\n"
.stringn "\x0703はい！　師匠！"
db 0
.align 4
//MYELL_8_CHINON_GATRIE_B

//0x75A0
Text_7580:
.stringn "\x05FL|GATRIE|CHINON||\x070-\x0705…はぁ\n"
.stringn "……ふぅ…\n"
.stringn "いや、でも…\n"
.stringn "～～～　やっぱりダメだ！！\n"
.stringn "\x0714おい！\n"
.stringn "\x0C05\x0C05\x0701あ？\n"
.stringn "…あ、シノンさん。\n"
.stringn "\x0714『…あ、シノンさん』じゃねえよ。\n"
.stringn "なんだ、さっきから\n"
.stringn "うっとうしい。\n"
.stringn "\x0701……なんでもないっす。\n"
.stringn "\x0714あ、そ。\n"
.stringn "んじゃあな。\n"
.stringn "\x0701ま、待って！　ウソですって！\n"
.stringn "意地悪しないで相談に\n"
.stringn "のって下さいよぉ～！！\n"
.stringn "\x0713今日の酒代、おまえ持ちだな？\n"
.stringn "\x0701うぅ…わかりました。\n"
.stringn "\x0713よーし。\n"
.stringn "じゃあ話してみろ。\n"
.stringn "\x0701今度の報酬の使い道、なんすけどね…\n"
.stringn "どうしようか迷ってて。\n"
.stringn "\x0713そんなもん人それぞれだ。\n"
.stringn "好きに使えばいいだろうが。\n"
.stringn "\x0701好きに使ったら使ったで\n"
.stringn "シノンさんが\n"
.stringn "いちいちケチつけるじゃないっすか！\n"
.stringn "\x0713オレが？\n"
.stringn "どうだっけな？\n"
.stringn "\x0701この間買った『究極の盾』の時も…\n"
.stringn "\x0713あぁ、あの砦の門扉な。\n"
.stringn "衛兵がおまえを盗人呼ばわりしてたぞ。\n"
.stringn "ちゃんと返しといたか？\n"
.stringn "\x0701身体にふりかけるだけで\n"
.stringn "動きが素早くなる秘薬\n"
.stringn "『ダッシュ一発！』の時も…\n"
.stringn "\x0713腐った肉汁のことか？\n"
.stringn "おまえ、匂いを確かめもしないで\n"
.stringn "一瓶自分にぶっかけてたっけな？\n"
.stringn "\x0701おれ、あれでちょっとは\n"
.stringn "動きが素早くなったんすよ！\n"
.stringn "\x0713３０匹の野犬に\n"
.stringn "追いかけられりゃあな。\n"
.stringn "\x0701ほら！　ケチばっかりつけて！！\n"
.stringn "\x0713あ、なんか傷ついちゃったね、オレは。\n"
.stringn "本当のこと教えてやって\n"
.stringn "文句言われちゃあ、割りにあわねえなぁ。\n"
.stringn "\x0701！！　お、おれ\n"
.stringn "そんなつもりじゃあ…\n"
.stringn "あの…　すいません…\n"
.stringn "\x0713おめえのその素直なとこ、\n"
.stringn "オレは結構、気に入ってるぜ。\n"
.stringn "\x0701へへへ　照れるじゃないすか。\n"
.stringn "\x0713よし、飲みにいくか！\n"
.stringn "おまえの金を有効に使わねぇとな。\n"
.stringn "\x0701え、いや、ちょっと\n"
.stringn "シノンさん！\n"
.stringn "それ、なんか違うっす！！"
db 0
.align 4
//MYELL_8_CHINON_GATRIE_C

//0x8E34
Text_8E14:
.stringn "\x05FL|CHINON|JANAFF||\x0C00\x071-\x0713お、いたな。\n"
.stringn "\x0700………\n"
.stringn "\x0713おまえ、\n"
.stringn "シノンってんだろ？\n"
.stringn "ちょっと話さねえか？\n"
.stringn "\x0700…へぇ？\n"
.stringn "半獣のお偉いさんに\n"
.stringn "わざわざご指名いただけるたぁ、\n"
.stringn "人生、いろんなことがあるもんだ。\n"
.stringn "\x0713つっかかんなよ。\n"
.stringn "この間は、悪かったな。\n"
.stringn "\x0700………\n"
.stringn "\x0713おれは、ベオクってやつを\n"
.stringn "誤解してたみたいだ。\n"
.stringn "殺しを好む野蛮な種族で、\n"
.stringn "おれ達ラグズとは\n"
.stringn "相容れない存在だってな。\n"
.stringn "\x0700…それでよく、\n"
.stringn "アイクたちとつるむ気になったな？\n"
.stringn "主の命令だからか？\n"
.stringn "\x0713違う。おれたちと王の関係は\n"
.stringn "そんな一方的なもんじゃない。\n"
.stringn "おれたちが王の意見を是としなければ\n"
.stringn "絶対に命令なんか聞かねえさ。\n"
.stringn "\x0700じゃあ、なんでだ？\n"
.stringn "\x0713あいつは、セリノスの仲間を救った。\n"
.stringn "恩には恩を…\n"
.stringn "リュシオン王子の護衛として\n"
.stringn "この軍に加わったが、\n"
.stringn "おれ自身も、あいつを信頼している。\n"
.stringn "\x0700……気にいらねえな。\n"
.stringn "\x0713ん？\n"
.stringn "\x0700オレは、昔っからアイクの野郎が嫌いでね。\n"
.stringn "あいつは、なんでも持っていやがる。\n"
.stringn "…それが当然だと思ってやがるんだ。\n"
.stringn "\x0713だが、それは\n"
.stringn "あいつのせいじゃねえだろ？\n"
.stringn "\x0700ああ。\n"
.stringn "けどな、ムカつくのは\n"
.stringn "オレの勝手ってやつだ。\n"
.stringn "\x0713そりゃそうだ。\n"
.stringn "\x0700……って、\n"
.stringn "なんだって\n"
.stringn "おまえとこんな話してんだよ。\n"
.stringn "\x0713…なんとなくな。\n"
.stringn "おまえ、若い頃のおれに\n"
.stringn "似てる気がするっつーか。\n"
.stringn "\x0700はぁ？\n"
.stringn "\x0713おれも羽根が生え揃うまでは\n"
.stringn "ムチャやったもんだ。\n"
.stringn "なんでもかんでも気に食わなかったしな。\n"
.stringn "\x0700……おまえ、いくつだよ？\n"
.stringn "\x0713１１０とちょい。\n"
.stringn "\x0700…オレたちと年の数え方、\n"
.stringn "違うんじゃねえか？\n"
.stringn "\x0713春、夏、秋、冬で１年ってのは\n"
.stringn "ラグズもベオクも共通だろ？\n"
.stringn "\x0700……オレが２７だから…\n"
.stringn "少なく見積もっても\n"
.stringn "オレより８５…ぐらいは、年上か？\n"
.stringn "\x0713ちったぁ、敬えよ。\n"
.stringn "若造が。\n"
.stringn "これからなんかあったら、\n"
.stringn "おれを頼ってこい。\n"
.stringn "年上ならではの助言してやっからよ。\n"
.stringn "\x0700…なぁ、おい！\n"
.stringn "ちょっと待てよ！\n"
.stringn "おまえらの寿命って…"
db 0
.align 4
//MYELL_8_CHINON_JANAFF_A

//0x8A64
Text_8A44:
.stringn "\x05FL|JANAFF|CHINON||\x0C04\x0710よぉ、また会ったな。\n"
.stringn "半獣のガキ。\n"
.stringn "\x0704気安く声かけてんじゃねえよ。\n"
.stringn "ニンゲンの若造が。\n"
.stringn "\x0710おまえ、フェニキス王の側近だってな？\n"
.stringn "小せぇ体格して、結構なご身分じゃねえか？\n"
.stringn "\x0704そっちはベオクの大将の古馴染みだってな？\n"
.stringn "傭兵団の仲間を裏切ってデインにつき、\n"
.stringn "それをまた裏切ってクリミアについたって話だ。\n"
.stringn "\x0710それがどうした？\n"
.stringn "卑怯者だと言いてえのか？\n"
.stringn "生憎、俺は生粋の傭兵でね。\n"
.stringn "仲間なんかに縛られる気はねえ。\n"
.stringn "\x0704仲間を持たず、主も持たず…\n"
.stringn "おまえは、いったい\n"
.stringn "なんのために戦ってるんだ？\n"
.stringn "\x0710……生きるためだ。\n"
.stringn "誰だって、そうじゃねえか。\n"
.stringn "そうでもなきゃ、\n"
.stringn "誰が好き好んで殺し合いなんざ…\n"
.stringn "\x0704おまえ…\n"
.stringn "\x0710なんだ？\n"
.stringn "\x0704おまえ、殺しが嫌いなのか？\n"
.stringn "\x0710好きな奴、いんのか？\n"
.stringn "\x0704…ニンゲンは、殺しを好む種族なんだろ？\n"
.stringn "だから武器を作る。\n"
.stringn "だから食いもしない動物を狩る。\n"
.stringn "\x0710ふざけんな！\n"
.stringn "武器を作るのは、てめえら\n"
.stringn "半獣から身を守るためだ！\n"
.stringn "狩りを道楽にしてんのは、\n"
.stringn "暇を持て余してる貴族どもだけだ！！\n"
.stringn "\x0704………\n"
.stringn "\x0710ケッ\n"
.stringn "胸糞悪ぃぜ。\n"
.stringn "\x0704おい！\n"
.stringn "まだ話は……\n"
.stringn "チッ　　どういうことなんだよ。"
db 0
.align 4
//MYELL_8_CHINON_JANAFF_B

//0x881C
Text_87FC:
.stringn "\x05FL|JANAFF|CHINON||\x0700おい！\n"
.stringn "そこの奴、止まれ！\n"
.stringn "\x0716……\n"
.stringn "\x0700おい、聞いてんのか？\n"
.stringn "\x0714あぁ？\n"
.stringn "なんだ、てめえは？\n"
.stringn "\x0700それはこっちの台詞だ。\n"
.stringn "おまえ、この軍じゃ見ない面だな。\n"
.stringn "…新入りか？　名前は？\n"
.stringn "どこの部隊に所属してる？\n"
.stringn "\x0714……半獣のガキに\n"
.stringn "答える義理はねえな。\n"
.stringn "\x0700なんだと、こら！？\n"
.stringn "\x0714おおっと。\n"
.stringn "オレにそういう態度をとってると\n"
.stringn "後で困ったことになるぜ？\n"
.stringn "\x0700おまえのほうこそ、\n"
.stringn "おれが誰だかわかってから\n"
.stringn "後悔したって遅いんだがなぁ？\n"
.stringn "\x0714………\n"
.stringn "\x0700………\n"
.stringn "\x0714…ケッ\n"
.stringn "今日は見逃してやるぜ。\n"
.stringn "\x0700ふざけるな、ニンゲン！\n"
.stringn "いいか、おれが\n"
.stringn "おまえを見逃してやるんだ。\n"
.stringn "そこんとこ勘違いするんじゃねえぞ！！"
db 0
.align 4
//MYELL_8_CHINON_JANAFF_C

//0x9A0C
Text_99EC:
.stringn "\x05FL|CHINON|LOFA||\x0C01\x0C16\x0701お～い、いいかげん\n"
.stringn "機嫌直せよ。　ったく。\n"
.stringn "\x0716……\n"
.stringn "\x0701だから、オレは\n"
.stringn "おまえのためを思ってだなぁ。\n"
.stringn "わかるだろ、それぐらい。\n"
.stringn "\x0716……\n"
.stringn "\x0701チッ\n"
.stringn "強情なガキだぜ。\n"
.stringn "いつまでもそうやってんなら、\n"
.stringn "オレぁもう行くぜ？\n"
.stringn "いいんだなぁ？\n"
.stringn "\x0716……だって…\n"
.stringn "シノンさん、ぼくの作った弓…\n"
.stringn "………………捨てたんだもん。\n"
.stringn "\x0701あのな、あんなもんで\n"
.stringn "戦場に出てみろ。\n"
.stringn "いっぱつでやられるぞ。\n"
.stringn "それを事前に止めてやったんじゃねえか。\n"
.stringn "いわば命の恩人なんだ、\n"
.stringn "むしろ感謝しろってんだよ。\n"
.stringn "\x0C16\x0713………そうだけど。\n"
.stringn "だけど…シノンさんに\n"
.stringn "喜んでもらおうと思って…\n"
.stringn "心をこめて作った物だもん。\n"
.stringn "ぼく…はじめて戦う時、\n"
.stringn "すごく怖くて足が…震えたけど……\n"
.stringn "シノンさんがくれた弓を\n"
.stringn "ぎゅってしたら…勇気がでた。\n"
.stringn "ぼくはやれる、失敗しないって。\n"
.stringn "だってシノンさんが\n"
.stringn "教えてくれたんだもんって。\n"
.stringn "だから今まで生き残って\n"
.stringn "これたんだって…思ってたから……\n"
.stringn "\x0701……\n"
.stringn "なんだってそんなに…\n"
.stringn "オレなんかに期待してんだよ。\n"
.stringn "おまえに弓を教えたのも、\n"
.stringn "弓を作ってやったのも\n"
.stringn "ただの気まぐれだったってのによ。\n"
.stringn "\x0713それでも、うれしかった。\n"
.stringn "おにいちゃんたちは…\n"
.stringn "ぼくがまだ子供だからって\n"
.stringn "なにもさせてくれなかったから。\n"
.stringn "シノンさんが弓を教えてくれなかったら…\n"
.stringn "今でもずっと留守番してなきゃいけなかったもん。\n"
.stringn "みんなが命がけで戦ってるのに…\n"
.stringn "それをじっと…待ってる。\n"
.stringn "昨日は帰ってきた。\n"
.stringn "でも…今日は？　明日は？\n"
.stringn "不安に押しつぶされそうになりながら\n"
.stringn "ただ待ってるしかできなかったんだ。\n"
.stringn "\x0701……どう思おうと\n"
.stringn "おまえの勝手だがよ。\n"
.stringn "大人は…できれば\n"
.stringn "ガキを戦場に送りたくねえんだ。\n"
.stringn "よほどいかれた奴でもねえかぎり、\n"
.stringn "他人の死には関わりたくねえ。\n"
.stringn "それが、ガキだとすれば…\n"
.stringn "なおさらな。\n"
.stringn "これはガキのためっていうより、\n"
.stringn "大人側のエゴだな。\n"
.stringn "自分たちの罪悪感を少しでも\n"
.stringn "緩和させられるよう、\n"
.stringn "頭の端っこでつねに考えている。\n"
.stringn "人は…他人の痛みがわかる生き物だ。\n"
.stringn "それに無意識にふたをするのは…\n"
.stringn "気づいちまうと…生き辛えからかな。\n"
.stringn "\x0713……むずかしいね。\n"
.stringn "\x0701…ああ。\n"
.stringn "ま、とにかく。\n"
.stringn "オレは大人のエゴってのが\n"
.stringn "反吐が出そうなくらい嫌いだからな。\n"
.stringn "ガキだって立派に生きてるんだ。\n"
.stringn "生き残っていく術を覚えんのは\n"
.stringn "早えにこしたことねえぜ。\n"
.stringn "\x0713だから、ぼくに\n"
.stringn "弓を教えてくれたんだね？\n"
.stringn "気まぐれだけじゃなく…\n"
.stringn "\x0701……　チッ\n"
.stringn "好きなように思ってろよ。\n"
.stringn "でもま、それで機嫌が直んなら…\n"
.stringn "まあいいか。"
db 0
.align 4
//MYELL_8_CHINON_LOFA_A

//0x9810
Text_97F0:
.stringn "\x05FL|LOFA|CHINON||\x070-\x0C01\x0C13\x0701見て見て、シノンさん！\n"
.stringn "これならちゃんと弓だよね？\n"
.stringn "\x0713分類『弓』にはなったかもな。\n"
.stringn "\x0701じゃあ、シノンさん使って…\n"
.stringn "\x0713断る！\n"
.stringn "オレぁまだ死にたくねえからよ。\n"
.stringn "\x0701ぶー\n"
.stringn "…いいもん。\n"
.stringn "ぼく、自分用にするもん。\n"
.stringn "\x0713……待て！\n"
.stringn "\x0701なに？\n"
.stringn "\x0713…その弓、よこせよ。\n"
.stringn "\x0701やっぱり欲しくなった？\n"
.stringn "\x0713ああ。\n"
.stringn "いきなり猛烈に欲しいぜ。\n"
.stringn "\x0701わーい。\n"
.stringn "じゃあ、はい！\n"
.stringn "\x0713ありがとよ。\n"
.stringn "じゃあな。\n"
.stringn "\x0701……ぼくの作った弓を\n"
.stringn "シノンさんが使うと\n"
.stringn "どんな風になるのかな～\n"
.stringn "気になるな～………\n"
.stringn "………ついてってみよ。\n"
.stringn "えへへ"
db 0
.align 4
//MYELL_8_CHINON_LOFA_B

//0x9474
Text_9454:
.stringn "\x05FL|LOFA|CHINON||\x070-\x0701シノンさん！　待って待って！\n"
.stringn "\x0713あぁ？\n"
.stringn "なんだ、ヨファ。\n"
.stringn "\x0701えへへ…　ほら！\n"
.stringn "\x0713なんだ、こりゃ？\n"
.stringn "えらくささくれ立ってひん曲がった棒切れ……\n"
.stringn "\x0701弓だよ！\n"
.stringn "いつかシノンさんに会えたら\n"
.stringn "ぜったいお返し、しようと思ってて。\n"
.stringn "ちょっとずつ作ってたんだ。\n"
.stringn "形はいまいちだけど、\n"
.stringn "一生懸命作ったから使ってね！\n"
.stringn "\x0713……百歩譲って、これが\n"
.stringn "弓と呼べる代物だとして、だ。\n"
.stringn "こんなやわなもん１回使ったら\n"
.stringn "ぶっ壊れちまうに決まってんだろ？\n"
.stringn "オレに戦場で丸腰になれってのか？\n"
.stringn "\x0701ち、ちがうよ！\n"
.stringn "\x0713だいたい、\n"
.stringn "木の選び方からして間違ってる。\n"
.stringn "こんな硬い木じゃ話にならねえ。\n"
.stringn "オレが作ってやったおまえ用の弓、\n"
.stringn "こんなんじゃなかっただろうが？\n"
.stringn "\x0701ちゃんと研究したもん。\n"
.stringn "そっくりにできてるはずだよ！\n"
.stringn "\x0713似ても似つかねえな。\n"
.stringn "\x0701うっ…\n"
.stringn "\x0713チッ　仕方ねえな。\n"
.stringn "今度、ちょっとだけ手ほどきしてやるか。\n"
.stringn "\x0701ほんと！？\n"
.stringn "ぼく、すごくうれしい！\n"
.stringn "約束したからね。ぜったいだよ？\n"
.stringn "\x0713ああ、わかったからよ。\n"
.stringn "そんなに犬ころみてえに\n"
.stringn "まとわりつくんじゃねえ。ったく。"
db 0
.align 4
//MYELL_8_CHINON_LOFA_C

//0xA7D4
Text_A7B4:
.stringn "\x05FL|LARGO|DALAHOWE|?||\x0703ダラハウ、ちょっといいか？\n"
.stringn "\x071-\x0711もちろん全然かまわないのよ～。\n"
.stringn "\x0703あの時ぁ怖くなっちまって\n"
.stringn "逃げちまったんだが……\n"
.stringn "ほんとに悪かった、ダラハウ。\n"
.stringn "なんてことをしちまったんだ、\n"
.stringn "どうしたら償えるかとずっと悩んでたが…\n"
.stringn "謝ることしか思いつかねえ。\n"
.stringn "ごめんな、ダラハウ……ウハラダも。\n"
.stringn "\x0711ああ～そんなに気にしてくれてたのね～？\n"
.stringn "ごめんよラルゴ、ウハラダは大丈夫なのよ！\n"
.stringn "\x0703ほ、ほんとか！？\n"
.stringn "\x0711ウハラダはいつだってダラハウの友達！\n"
.stringn "友達はいつでもそばにいてくれるのよ～！\n"
.stringn "だからこうやって紙に描いて～…\n"
.stringn "むにゃむにゃむにゃむにゃ～\n"
.stringn "ほ～ら、ウハラダよ！\n"
.stringn "\x0727久しぶりね、ラルゴ。\n"
.stringn "\x0703おお！　ほんとだ！\n"
.stringn "すまなかったウハラダ～！！\n"
.stringn "おれがつまんねえ腹立てちまったばっかりに\n"
.stringn "痛い思いを……\n"
.stringn "\x0727いいのよラルゴ。\n"
.stringn "\x0711そうそう、いいのよラルゴ～！\n"
.stringn "ラルゴはダラハウの友達だから\n"
.stringn "ウハラダとも友達なのよね～！\n"
.stringn "友達はそんなこと気にしないのよ～！\n"
.stringn "\x0703よかった……ありがとうな、２人とも！\n"
.stringn "おまえらいい奴らだよな！　わはははは！\n"
.stringn "\x0711いえいえ～、ラルゴが一番いい人なのね～。\n"
.stringn "やさしいラルゴを、ダラハウ大好きよ～。\n"
.stringn "これからもよろしくね、ラルゴ～！\n"
.stringn "\x0703ああ、もちろんだぜ！"
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_A

//0xA4EC
Text_A4CC:
.stringn "\x05FL|LARGO|?|DALAHOWE||\x070-\x0701よっしゃ、今日もがんばるか！\n"
.stringn "ん？　こりゃあ……\n"
.stringn "ダラハウのダチのウハラダじゃねえか。\n"
.stringn "こんなとこに落ちてて大丈夫なのかよ。\n"
.stringn "おい、平気か？\n"
.stringn "\x0717…………\n"
.stringn "\x0701……やっぱりなあ。\n"
.stringn "こんな紙っきれが話すわけねえじゃねえか。\n"
.stringn "…………ちょっとハラ立つな……\n"
.stringn "丸めて捨てちまうか！\n"
.stringn "\x0717い、いた……い……\n"
.stringn "\x0701！！？\n"
.stringn "お、おい！　マジかよ！？\n"
.stringn "今確かに声が…………\n"
.stringn "すまん、大丈夫か、ウハラダ！？\n"
.stringn "\x0717……………………\n"
.stringn "\x0701なんてこった……\n"
.stringn "おれぁ、とんでもねえことを……\n"
.stringn "\x072-\x0723ラルゴ～！\n"
.stringn "そこでなにしてるのね～？\n"
.stringn "\x0701うわあ！！\n"
.stringn "ゆ、許してくれ～！！\n"
.stringn "\x0723……逃げていっちゃったのよ～。\n"
.stringn "ごめんよラルゴ～、悪いのは\n"
.stringn "うっかりネタを落としちゃったダラハウなのね～。\n"
.stringn "でも一族の秘技だから\n"
.stringn "決してバレるわけにはいかないのね～…\n"
.stringn "罪の意識なのね～……はぁ。"
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_B

//0xA224
Text_A204:
.stringn "\x05FL|DALAHOWE|LARGO|?||\x070-\x0701今からとっておきの芸をするのね～！\n"
.stringn "みんな見るのよ～、寄ってくのよ～！\n"
.stringn "\x071-\x0713お、大道芸かい。面白そうだ。\n"
.stringn "お客はおれしかいねえみてえだが、\n"
.stringn "１つ頼めるか？\n"
.stringn "\x0701もちろんなのよ～！\n"
.stringn "羊皮紙にこうして絵を描いて～…\n"
.stringn "むにゃむにゃむにゃむにゃ～\n"
.stringn "ほ～ら、できた！\n"
.stringn "この子はダラハウの友達、\n"
.stringn "ウハラダよ～。\n"
.stringn "\x0713ウハラダ？\n"
.stringn "こいつはただの落書きだろう。\n"
.stringn "\x0701違うのよ～。\n"
.stringn "ほら、耳をすませてみるのよ～\n"
.stringn "\x0713耳？\n"
.stringn "\x0727こんにちは。\n"
.stringn "\x0713おお！？　な、なんだ？\n"
.stringn "あんたは喋ってねえのに、\n"
.stringn "今どっかから声がしたぞ。\n"
.stringn "どういうことだ、いったい？\n"
.stringn "\x0701このウハラダが喋ってるのよ～\n"
.stringn "ウハラダ、挨拶～！\n"
.stringn "\x0727こんにちはラルゴ。\n"
.stringn "\x0713わはははは！　すげえじゃねえか！\n"
.stringn "他にもなんかできるのか？\n"
.stringn "\x0701もちろんなのよ～！\n"
.stringn "さ～てお次は…………"
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_C

//0xB1A4
Text_B184:
.stringn "\x05FL|NEPHENEE|DALAHOWE||\x0703ダラハウさん。\n"
.stringn "\x071-\x0711あらら、ネフェニーから\n"
.stringn "声かけてくるなんてめずらしいのね～。\n"
.stringn "ダラハウ嬉しいのよ～。\n"
.stringn "\x0703……ダラハウさんは、いつも笑顔じゃなあ…\n"
.stringn "戦いとか……辛くないん？\n"
.stringn "あたし、時々……\n"
.stringn "泣きとぉなったり…するよ……\n"
.stringn "\x0711………………\n"
.stringn "う～ん……そうね～…\n"
.stringn "確かに戦うのは辛いけど～…\n"
.stringn "そう言ってるネフェニーを見るほうが\n"
.stringn "ダラハウは辛いのね～…\n"
.stringn "\x0703ダラハウさん……\n"
.stringn "\x0711ダラハウ、人の笑顔が大好きなのね～。\n"
.stringn "だから、ダラハウも笑うのね～。\n"
.stringn "でも、辛いのに笑う笑顔は哀しいのよ～。\n"
.stringn "ダラハウが言ったから、\n"
.stringn "ネフェニー、一生懸命笑ってくれてるけど\n"
.stringn "辛そうなのよね～。\n"
.stringn "この前言った、死んじゃった子のこと\n"
.stringn "思い出しちゃうのね～…\n"
.stringn "ごめんね、ネフェニー。無理させることを\n"
.stringn "言ってたみたいなのね～。\n"
.stringn "\x0703ごめんなさい、あたし……\n"
.stringn "田舎もんじゃけえ、都会の人と話すの苦手で…\n"
.stringn "仲のいい人もあんまりおらんで……\n"
.stringn "\x0711そうだったの～…\n"
.stringn "\x0703じゃけえ、ちょっと……悪いことばっかり\n"
.stringn "考えとったみたい……\n"
.stringn "ダラハウさんみたいに、たくさん笑ったら…\n"
.stringn "ええこと考えるように、なるんかな……？\n"
.stringn "\x0711それはそうなのよ～！\n"
.stringn "笑顔はその人も、その相手の人も救うのよ～！\n"
.stringn "\x0703……うん、そうじゃな……\n"
.stringn "ダラハウさんの笑顔って、すごくええよな……\n"
.stringn "ありがとう、ダラハウさん……"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_A

//0xAE00
Text_ADE0:
.stringn "\x05FL|DALAHOWE|NEPHENEE||\x070-\x0C01\x0C13\x0701ネフェニー、\n"
.stringn "話があるのね～\n"
.stringn "\x0713ダラハウさん……\n"
.stringn "なん、ですか……？\n"
.stringn "\x0701やっぱり顔がこわいのね～、\n"
.stringn "もっと笑った方がいいのよ～？\n"
.stringn "意味なく笑ってもいいって\n"
.stringn "ダラハウこの間教えたのよ～？\n"
.stringn "\x0713でも……\n"
.stringn "難しい…から…\n"
.stringn "\x0701難しい？　どうして～？\n"
.stringn "ダラハウみたいに\n"
.stringn "こうやって笑うだけでいいのよ～。\n"
.stringn "\x0713楽しくない…のに……\n"
.stringn "笑っても……\n"
.stringn "\x0701…ネフェニー\n"
.stringn "すぐそう言うのね～\n"
.stringn "声も小さいし、おしゃべりもしないし～。\n"
.stringn "\x0713…………\n"
.stringn "\x0701ダラハウが立ち寄った村にね～、\n"
.stringn "ネフェニーみたいな子がいたのよ～\n"
.stringn "その子、ダラハウに\n"
.stringn "とってもよくしてくれたのね～\n"
.stringn "でも、その子、村をおそった\n"
.stringn "山賊たちに殺されたのね～…\n"
.stringn "\x0713！\n"
.stringn "\x0701その子、１人で思い詰めるというか\n"
.stringn "そういう感じの子だったのよ～。\n"
.stringn "みんなと一緒にじっと隠れていれば\n"
.stringn "よかったのに～、\n"
.stringn "ダラハウが他の山賊と戦ってるすきに\n"
.stringn "出て行っちゃったみたいでね～。\n"
.stringn "自分が何とかしないと、って\n"
.stringn "思ったのかもね～…\n"
.stringn "だからネフェニーには\n"
.stringn "もっとみんなとおしゃべりして、\n"
.stringn "笑っててほしいのよ～。\n"
.stringn "\x0713…………"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_B

//0xABF4
Text_ABD4:
.stringn "\x05FL|DALAHOWE|NEPHENEE||\x070-\x0701ちょっとちょっと、そこの人～。\n"
.stringn "ダラハウ話があるのね～\n"
.stringn "\x0713……なん、ですか？\n"
.stringn "\x0701ダラハウいつも思ってたのよ～\n"
.stringn "あなた、お顔がこわいのね～。\n"
.stringn "\x0713………そう、ですか？\n"
.stringn "\x0701見ていてこわいのよ～。\n"
.stringn "いっぱい、いっぱい\n"
.stringn "笑ったほうがいいのね～。\n"
.stringn "真面目すぎるの、よくないのね～。\n"
.stringn "命をちぢめてしまうのよ～。\n"
.stringn "\x0713真面目……\n"
.stringn "というわけじゃ、ない…けど。\n"
.stringn "\x0701そうなのね～？\n"
.stringn "ところであなた、お名前は～？\n"
.stringn "\x0713ネフェニー……\n"
.stringn "\x0701ダラハウこれから\n"
.stringn "ネフェニーに笑いかたを教えるのよ～。\n"
.stringn "遠慮はしなくていいのよ～。\n"
.stringn "\x0713はあ……"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_C

//0xBBD4
Text_BBB4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x070-\x0703……ふぅ\n"
.stringn "\x071-\x0711トパックだめよ～。\n"
.stringn "ため息はしあわせ逃がすのよ～。\n"
.stringn "\x0703……ダラハウか。\n"
.stringn "\x0711あらら\n"
.stringn "今日は驚かないのね～。少し残念～。\n"
.stringn "\x0703ダラハウはいいよなあ……\n"
.stringn "槍使いになるために生まれてきたって感じ。\n"
.stringn "すっごく強いもんな～…　はあぁ…\n"
.stringn "\x0711トパックだって強いのね～。\n"
.stringn "\x0703……お世辞はいいよ。\n"
.stringn "おいら自分でわかってるんだ。\n"
.stringn "魔道、向いてないのかもって……\n"
.stringn "\x0711誰にでも、伸び悩みの時期はあるものよ～。\n"
.stringn "\x0703……おいらのは、\n"
.stringn "それとは違う気がする。\n"
.stringn "\x0711１つのものを習得するには～\n"
.stringn "いつでも根気が必要なのよ～。\n"
.stringn "先ばっかりみて急いでるとね～\n"
.stringn "大切なことが見えなくなるのよ～。\n"
.stringn "\x0703大切なことって？\n"
.stringn "\x0711たとえば、最初に魔法を\n"
.stringn "使えたときの気持ちとかよ～。\n"
.stringn "どんな気がしたか覚えてる～？\n"
.stringn "\x0703どんなって……\n"
.stringn "そりゃ、うれしかったよ。\n"
.stringn "\x0711ちょっとずつ上達していく時は、\n"
.stringn "どうだったのよ～？\n"
.stringn "\x0703うれしかったし……楽しかった。\n"
.stringn "\x0711……どうして魔法が使えて\n"
.stringn "嬉しかったのかも思い出すのよ～。\n"
.stringn "\x0703………だって、強くなれたと思ったから。\n"
.stringn "…みんなを守れる力を持てたのが\n"
.stringn "すごくうれしかったんだ……\n"
.stringn "\x0711その気持ちを見失っちゃダメなのよ～。\n"
.stringn "それさえしっかり持ってれば～\n"
.stringn "トパックはもっと伸びるのよ～。\n"
.stringn "\x0703…………\n"
.stringn "ありがとな、ダラハウ！\n"
.stringn "なんか…あんたにはいっつも\n"
.stringn "大事なことを教えてもらってる気がする。\n"
.stringn "\x0711気にしなくていいのよ～。\n"
.stringn "子供を導くのは大人の義務なのよ～。\n"
.stringn "それにね～ダラハウも\n"
.stringn "お返しをもらってるから～\n"
.stringn "\x0703お返し？\n"
.stringn "\x0711トパックの明るい笑顔よ～。\n"
.stringn "ダラハウはいつでも～\n"
.stringn "子供の笑顔のために戦っているのよ～。"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_A

//0xB914
Text_B8F4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x0703あー、もうやめ！\n"
.stringn "こんなのできねえよ……\n"
.stringn "\x0714途中で投げ出すのは、よくないのね～？\n"
.stringn "\x0C03\x0701わああ！\n"
.stringn "ど、どっから……！\n"
.stringn "\x0C14\x0713さっきから見てたのよ～。\n"
.stringn "トパック怪我の手当てが\n"
.stringn "いい加減すぎるのよ～。\n"
.stringn "\x0701しかたねえじゃん。\n"
.stringn "傷薬ぬって布で押さえようとしても\n"
.stringn "ずりさがってくるばっかだし。\n"
.stringn "誰かつかまえて、杖振ってもらうほうが\n"
.stringn "早くて確実に治っていいや。\n"
.stringn "\x0713おばかっ！\n"
.stringn "\x0701え……\n"
.stringn "\x0713すぐに他人に頼っちゃだめよ～。\n"
.stringn "自分でできることは\n"
.stringn "自分でやれるようになっとかないと～\n"
.stringn "戦場では生き残れないのね～。\n"
.stringn "困った時に、いつでも\n"
.stringn "誰かが助けてくれるとは限らないのよ～。\n"
.stringn "\x0701…そっか。\n"
.stringn "あんたやっぱり、いいこと言うよな。\n"
.stringn "\x0713基本中の基本なのよ～。\n"
.stringn "さあ、布を貸してみて～\n"
.stringn "上手な巻きかた伝授するのよ～。\n"
.stringn "\x0701おう！"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_B

//0xB614
Text_B5F4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x0701っかしーな、ここで集合だって\n"
.stringn "言われたのに……まだ来てないのか？\n"
.stringn "\x071-\x0713待たせて申し訳ないのね～！\n"
.stringn "\x0701うわああっ！！\n"
.stringn "\x0713うわああっ！\n"
.stringn "って、なにをそんなに驚いてるの～？\n"
.stringn "\x0701あんただよ、あんた！\n"
.stringn "急に出て来たら心臓に悪いって。\n"
.stringn "あ～　おいら寿命が縮まったかも…\n"
.stringn "\x0713トパックちょっとおおげさね～。\n"
.stringn "そんなことで寿命が縮まるのなら～\n"
.stringn "みんなとっくにお亡くなりなのよ～。\n"
.stringn "それより、仕事よ～！\n"
.stringn "参謀さんから頼まれた、武器の手入れを\n"
.stringn "さっさと済ませちゃうのよ～！\n"
.stringn "\x0701はあぁ　なんで、こんな雑用…\n"
.stringn "おいらたちのやる仕事じゃねえよな。\n"
.stringn "\x0713いい経験だと思うわよ～\n"
.stringn "自分の使う武器だけじゃなく～\n"
.stringn "色んな武器を知っておけば～\n"
.stringn "戦う時に役立つはずなのよ～。\n"
.stringn "\x0701そっか。\n"
.stringn "なんだ、いいこと言うじゃん。\n"
.stringn "\x0713お褒めにあずかり光栄なのね～。\n"
.stringn "\x0701じゃあ、とにかく\n"
.stringn "剣から始めてみるかなっと！"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_C

//0xC750
Text_C730:
.stringn "\x05FL|ELAICE|GATRIE||\x0C01\x071-\x0713よ、イレースちゃん！\n"
.stringn "この前、いいものを手に入れたんだ。\n"
.stringn "ほら、この貝がら！\n"
.stringn "どう？　きれいだろ？\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713……興味、ない？\n"
.stringn "\x0701そういうわけでは……\n"
.stringn "\x0713じゃあ、興味ある？\n"
.stringn "\x0701そういうわけでも……\n"
.stringn "\x0713ふう、やっぱりダメかあ。\n"
.stringn "何か気に入ってくれたら\n"
.stringn "それをきっかけに\n"
.stringn "食事にでもって思ったんだけど…\n"
.stringn "\x0701！！\n"
.stringn "あ、ご一緒してもいいです……\n"
.stringn "\x0713え？\n"
.stringn "\x0701お食事……\n"
.stringn "\x0713ホ、ホントか！\n"
.stringn "よしっ！　おれに任せてくれよ！\n"
.stringn "このガトリー、イレースちゃんのために\n"
.stringn "おいし～～いモン食わせてくれるとこ、\n"
.stringn "見つけてくるからよ！\n"
.stringn "\x0701……そうでした。\n"
.stringn "ガトリーさんでした…\n"
.stringn "\x0713へ？　おれがどうかしたの？\n"
.stringn "\x0701いえ、なにも…\n"
.stringn "\x0713？？？\n"
.stringn "まあ、いいや。\n"
.stringn "じゃあ、また今度な！\n"
.stringn "\x0701ガトリーさん、ガトリーさん…\n"
.stringn "お食事をごちそうしてくれる人だもの。\n"
.stringn "覚えておかないと……\n"
.stringn "おいしい食事……ああ、楽しみ……"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_A

//0xC498
Text_C478:
.stringn "\x05FL|ELAICE|GATRIE||\x0C01\x071-\x0713よ、イレースちゃん！\n"
.stringn "\x0701……こんにちは。\n"
.stringn "\x0713へへへ…\n"
.stringn "どう、この花、きれいだろ？\n"
.stringn "このはかなげできれいなところなんかは\n"
.stringn "イレースちゃんにピッタリだと思ってさ。\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713あれ……　えっと、\n"
.stringn "ひょっとして、気に入らなかった？\n"
.stringn "\x0701そういうわけでは…\n"
.stringn "\x0713じゃあ、気に入った？\n"
.stringn "\x0701そういうわけでも……\n"
.stringn "\x0713…………\n"
.stringn "じゃ、じゃあ、これなんかどう？\n"
.stringn "このブローチ、きれいだろ？\n"
.stringn "この前寄った町で売っててさ。\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713えーっと、これもだめ、かなあ？\n"
.stringn "\x0701そういうわけでは……\n"
.stringn "\x0713…………\n"
.stringn "と、とりあえず、また出直してくるよ。\n"
.stringn "ハハ　ハハハ…\n"
.stringn "\x0701はい……失礼します……\n"
.stringn "\x0713うーん、なかなか手ごわいなあ…\n"
.stringn "でも、おれはあきらめないぜ！\n"
.stringn "あんな可愛い子、見逃したら\n"
.stringn "バチが当たるってもんだ！"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_B

//0xC140
Text_C120:
.stringn "\x05FL|ELAICE|GATRIE||\x0C05\x071-\x0713コホン　そこのお嬢さん。\n"
.stringn "\x0705……\n"
.stringn "\x0713えー、そこの可愛いお嬢さん。\n"
.stringn "\x0705……\n"
.stringn "\x0713あー、\n"
.stringn "そこの薄紫色の髪をした、おさげを\n"
.stringn "２つしている愛らしいお嬢さん。\n"
.stringn "\x0C05\x0701あ…私のこと…なんですか？\n"
.stringn "ひょっとして……\n"
.stringn "\x0713ふう、やっと気づいてくれたかぁ。\n"
.stringn "自覚がないなんて、なんて奥ゆかしいんだ…！\n"
.stringn "いやあ～！　お嬢さんのような\n"
.stringn "可愛く素敵な女性と同じ軍にいられるなんて\n"
.stringn "しあわせだなあ～！\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713で、その、\n"
.stringn "お嬢さんの名前は？\n"
.stringn "\x0701名前……ですか？\n"
.stringn "イレースです……\n"
.stringn "\x0713イレースちゃんかあ。\n"
.stringn "いっやあ～、見た目どおりの\n"
.stringn "可愛い名前だなあ！　もっ最高！\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713おれの名前は、ガトリー。\n"
.stringn "ガトちゃんって呼んでくれてもいいぜ！\n"
.stringn "いや、むしろ歓迎？\n"
.stringn "\x0701はあ……\n"
.stringn "\x0713じゃ、そういうことだから\n"
.stringn "広く深～くよろしくな！\n"
.stringn "\x0701はあ……\n"
.stringn "……失礼します……\n"
.stringn "\x0713へへへ　これでおれの印象もバッチリ！\n"
.stringn "そっかあ、イレースちゃんかあ…\n"
.stringn "これから楽しい毎日になりそうだぜ！！"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_C

//0xD290
Text_D270:
.stringn "\x05FL|LUCHINO|ELAICE||\x0703イレース？　おかしいわね。\n"
.stringn "ここで待ってるように言ったのに。\n"
.stringn "いったいどこへ……\n"
.stringn "\x0717ルキノ……さん……\n"
.stringn "\x0703！　イレース……！？\n"
.stringn "イレース、しっかりして！\n"
.stringn "どうしたの、何があったの？\n"
.stringn "\x0711いえ……何も……\n"
.stringn "ただ……お腹が、すいて……\n"
.stringn "\x0703お、お腹がって……\n"
.stringn "あなた、ちゃんと\n"
.stringn "食事はとってるわよね？\n"
.stringn "\x0711いえ……今日はまだ……\n"
.stringn "たった３人分しか……\n"
.stringn "\x0703え？\n"
.stringn "３人……分？\n"
.stringn "\x0711はい……\n"
.stringn "\x0703……あなた、ふだんは\n"
.stringn "どのくらい食べているの？\n"
.stringn "\x0711最近は、ほとんど食べていません……\n"
.stringn "ふつうに５人分……くらいしか……\n"
.stringn "\x0703…………ええと……\n"
.stringn "あなた、ラグズじゃないわよね？\n"
.stringn "\x0711はい……\n"
.stringn "\x0703……ねえ、イレース。\n"
.stringn "ここ数日、私は色々な訓練を\n"
.stringn "あなたにさせてみたわ。\n"
.stringn "それで思ったんだけど……\n"
.stringn "あなたは身体が弱いとかいうより……\n"
.stringn "もっと根本的な何かが問題だと思うの。\n"
.stringn "でも、このまま放ってはおけないわ。\n"
.stringn "乗りかかった船だから……\n"
.stringn "一緒になんとかしましょう。\n"
.stringn "\x0711はい……嬉しいです。\n"
.stringn "ルキノさんは美味しいお料理を\n"
.stringn "つくってくれます……\n"
.stringn "ルキノさんはきれいで、強くて、\n"
.stringn "いい匂いがします……\n"
.stringn "ルキノさんと一緒にいたいです……\n"
.stringn "\x0703そ、そう。\n"
.stringn "じゃあ、とにかく食べ物を……\n"
.stringn "\x0711ルキノさんのお料理……\n"
.stringn "……うっとり\n"
.stringn "\x0703…ふぅ　仕方のない子ね。\n"
.stringn "なんでも好きなものを作ってあげるから、\n"
.stringn "訓練もちゃんとがんばるのよ？\n"
.stringn "\x0711はい！　嬉しいです…！"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_A

//0xCEA0
Text_CE80:
.stringn "\x05FL|ELAICE|LUCHINO||\x0C01\x0713じゃあイレース、始めてみて。\n"
.stringn "\x0701はい……\n"
.stringn "では……やってみます……\n"
.stringn "\x0713………………\n"
.stringn "ま、待ってイレース。\n"
.stringn "ちょっと、こっちへ戻って来てくれるかしら。\n"
.stringn "\x0701はい……\n"
.stringn "なんでしょう……？\n"
.stringn "\x0713イレース、あなたが\n"
.stringn "身体が弱いのはよくわかるわ。\n"
.stringn "でも、少しだけでも走ってみましょう。\n"
.stringn "ゆっくりでいいから。\n"
.stringn "\x0701はい……\n"
.stringn "私、いっしょうけんめい\n"
.stringn "走りました……\n"
.stringn "\x0713え……？\n"
.stringn "さっきのあれは……走ってたの？\n"
.stringn "\x0701はい……\n"
.stringn "\x0713………………\n"
.stringn "……よく聞いて、イレース。\n"
.stringn "誰にだって不得手はあるもの。\n"
.stringn "それを克服するためには\n"
.stringn "たくさんの時間と努力が必要よ。\n"
.stringn "だから…すぐに結果が出なくても、\n"
.stringn "決してあせらないで。わかった？\n"
.stringn "\x0701はい……\n"
.stringn "\x0713私も付き合うから。\n"
.stringn "いっしょに頑張りましょう？\n"
.stringn "\x0701はい…がんばります……\n"
.stringn "\x0713じゃあ、休憩にしましょうか。\n"
.stringn "なにか飲み物でも…\n"
.stringn "\x0701食べ物がいいです。\n"
.stringn "\x0713そ、そう。\n"
.stringn "じゃあ、食べ物として…\n"
.stringn "なにが食べたい？\n"
.stringn "\x0701この間、ルキノさんが\n"
.stringn "作って持ってきてくれたもの…\n"
.stringn "全部、また食べたいです。\n"
.stringn "\x0713そんなに気に入ってくれたの？\n"
.stringn "嬉しいわ。\n"
.stringn "だったら、また\n"
.stringn "腕によりをかけないとね。\n"
.stringn "\x0701はい、嬉しいです…！"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_B

//0xCA64
Text_CA44:
.stringn "\x05FL|ELAICE|LUCHINO||\x0C01\x071-\x0713こんにちは。\n"
.stringn "ずいぶん可愛らしい子がいるかと思えば…\n"
.stringn "あなた魔道士なのね。\n"
.stringn "私はルキノ。\n"
.stringn "クリミア王国軍の１人として\n"
.stringn "あなたが、この戦いに\n"
.stringn "参加してくれたことに感謝するわ。\n"
.stringn "\x0701はい……\n"
.stringn "私はイレースといいます……\n"
.stringn "グレイル傭兵団の……\n"
.stringn "…　…　…\n"
.stringn "\x0713ど、どうしたの？\n"
.stringn "しっかりして、大丈夫？\n"
.stringn "\x0701はい……\n"
.stringn "\x0713それにしても……\n"
.stringn "イレースって、とても華奢なのね。\n"
.stringn "その様子では行軍も辛いでしょう？\n"
.stringn "\x0701はい……　よく行軍中に……\n"
.stringn "倒れてしまいます……\n"
.stringn "\x0713それはいけないわ。\n"
.stringn "もし、戦場でそんなことがあれば\n"
.stringn "すぐに命を落としてしまう。\n"
.stringn "気をつけて。戦う上では、\n"
.stringn "体力などの自己管理も重要なことよ。\n"
.stringn "\x0701は、はい…\n"
.stringn "\x0713消え入りそうな返事ね。\n"
.stringn "しっかりして、今にも倒れそうよ？\n"
.stringn "とりあえず、手を貸すから\n"
.stringn "あなたの天幕まで戻りましょう。\n"
.stringn "\x0701…だめです。おなかがすいて……\n"
.stringn "動けない…です……\n"
.stringn "\x0713そんなに空腹なの？\n"
.stringn "待ってて。私が今から\n"
.stringn "何か食料を持ってくるわ。\n"
.stringn "\x0701本当ですか……？\n"
.stringn "\x0713ええ。どんなものなら\n"
.stringn "食べられそう？\n"
.stringn "\x0701…好き嫌いはありません。\n"
.stringn "口に入るものなら、なんでもいいです。\n"
.stringn "\x0713そ、そう。\n"
.stringn "そこまで切羽詰っているのね。\n"
.stringn "わかったわ。\n"
.stringn "私が戻るまでじっとしていてね？\n"
.stringn "\x0701はい、嬉しいです……"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_C

//0xDDD0
Text_DDB0:
.stringn "\x05FL|MORDY|ELAICE||\x0C03\x071-\x0711モゥディさん……　この間は\n"
.stringn "ありがとうございました……\n"
.stringn "とっても、助かりました……\n"
.stringn "\x0703ア、アあ……気にスるな。\n"
.stringn "シかしオまえ、よく食べた。\n"
.stringn "モゥディが１２人イるクらい食べた。\n"
.stringn "\x0711ごちそうしていただいた\n"
.stringn "お料理は美味しかったですけど……\n"
.stringn "量が控えめなのは残念でした……\n"
.stringn "\x0703モゥディはモう金がナい。\n"
.stringn "スまないがアきらめて欲しい。\n"
.stringn "シかし、イレースは本当にヨく食べる。\n"
.stringn "アれダけの食べ物を、ドこに入れたのだ？\n"
.stringn "\x0711お腹です……\n"
.stringn "\x0703ウゥむ……\n"
.stringn "ソういえば、思い出した。\n"
.stringn "モゥディたちと森で暮らすリスは、\n"
.stringn "身体が小さいノにイつも何か頬張っていた。\n"
.stringn "イレースはベオクだが、\n"
.stringn "キっとリスと同じナのダろうな。\n"
.stringn "\x0711そうかも……しれません……\n"
.stringn "リスですか…可愛らしいたとえですね……\n"
.stringn "\x0703それで…\n"
.stringn "イレースは、イつ冬眠スるのだ？\n"
.stringn "\x0711冬眠は、しません。"
db 0
.align 4
//MYELL_8_ELAICE_MORDY_A

//0xDA50
Text_DA30:
.stringn "\x05FL|MORDY|ELAICE||\x0701ムぅん！\n"
.stringn "\x071-\x0713こんにちは、モゥディさん……\n"
.stringn "荷物運びのお仕事を\n"
.stringn "なさっているのですか……？\n"
.stringn "\x0701ソうだ。モゥディたちは力が強いカら\n"
.stringn "コういう時は、役に立つぞ。\n"
.stringn "後はコれを運べば終わりだ。\n"
.stringn "\x0713そんなにたくさんの荷物を\n"
.stringn "いっぺんに……すごいです。\n"
.stringn "\x0701オまえもモっとたくさん食べて\n"
.stringn "肉をツけたホうがイい。\n"
.stringn "太くナれば、殴られても耐えられる。\n"
.stringn "\x0713私も本当は、そうしたいんです……\n"
.stringn "でも私にはお金がなくて……\n"
.stringn "満足に食べることができないのです……\n"
.stringn "だから、すぐ倒れそうになってしまって……\n"
.stringn "\x0701ムゥ、ソうダったのか……\n"
.stringn "イレースは、食べたいモのも食べれナいのか…\n"
.stringn "ソれは可哀想だ。\n"
.stringn "ワかった。モゥディがゴちそうスる。\n"
.stringn "ナんでも好きなモのを好きなダけ食べろ。\n"
.stringn "\x0713え……\n"
.stringn "それは本当……ですか？\n"
.stringn "\x0701アあ、本当だ。\n"
.stringn "\x0713本当に……本当ですね？\n"
.stringn "\x0701？\n"
.stringn "アあ、モゥディは嘘をツかないぞ。\n"
.stringn "\x0713ありがとうございます……\n"
.stringn "あなたはまるで…女神さまのように\n"
.stringn "素晴らしい方です……\n"
.stringn "\x0701ソうか？\n"
.stringn "ソんなにホめられると、照れるぞ。"
db 0
.align 4
//MYELL_8_ELAICE_MORDY_B

//0xD73C
Text_D71C:
.stringn "\x05FL|ELAICE|MORDY||\x0701あ…\n"
.stringn "\x0713タ、大変だ…！\n"
.stringn "大丈夫か？　シっかりシろ！\n"
.stringn "\x0701……あ…\n"
.stringn "あなたは…たしか……\n"
.stringn "\x0713モゥディだ。\n"
.stringn "オまえはタしか…イレース？\n"
.stringn "話すノは、初めてだな。\n"
.stringn "\x0701そうですね…\n"
.stringn "同じ仲間なのに……\n"
.stringn "私…影が薄いから……\n"
.stringn "……よく忘れられていて……\n"
.stringn "あ……っ……\n"
.stringn "\x0713ドうした？\n"
.stringn "\x0701すみません、ちょっと\n"
.stringn "足もとがふらついてしまって……\n"
.stringn "よくあることなので……\n"
.stringn "気にしないでください……\n"
.stringn "\x0713ムゥ…………\n"
.stringn "ベオクの中でも、\n"
.stringn "オまえはトても細く見える。\n"
.stringn "ソんな細い体で戦えるノか？\n"
.stringn "\x0701はい……なんとか。\n"
.stringn "\x0713ダが、ソの様子デは…\n"
.stringn "敵が当たったダけで\n"
.stringn "倒れてシまうのではナいか？\n"
.stringn "\x0701その時は、仕方ありません……\n"
.stringn "そうなる覚悟はできてますから……\n"
.stringn "\x0713ムウゥ……心配だ……\n"
.stringn "ワかった。モゥディがオまえの側にイる。\n"
.stringn "モゥディが壁になって敵をフさぐカら、\n"
.stringn "イレースは無理をスるな。\n"
.stringn "\x0701あ……\n"
.stringn "ありがとうございます……"
db 0
.align 4
//MYELL_8_ELAICE_MORDY_C

//0xE538
Text_E518:
.stringn "\x05FL|WAYU|ELAICE||\x0706うーん、今日のキレはイマイチ。\n"
.stringn "これじゃまだ見ぬ強敵に笑われちゃうなあ。\n"
.stringn "もっと集中しないと！\n"
.stringn "……そういえばイレース、最近見ないな。\n"
.stringn "元気だといいけど、なんか心配だよ。\n"
.stringn "ま、考えててもしょうがない！\n"
.stringn "それより修行修行っと……\n"
.stringn "あれ？\n"
.stringn "\x0701な、なんかふんづけた？\n"
.stringn "\x071-\x0713……\n"
.stringn "\x0701うわっ！？\n"
.stringn "なんでこんなとこで倒れてんのよ！\n"
.stringn "大丈夫！？\n"
.stringn "\x0713お腹が……\n"
.stringn "\x0701な、何？\n"
.stringn "お腹が？　痛いの？\n"
.stringn "\x0713……すきました。\n"
.stringn "\x0701へ……？\n"
.stringn "\x0713何か……食べるもの、を……\n"
.stringn "\x0701ねえ……\n"
.stringn "あんたがずっとふらふらしてたのって\n"
.stringn "まさか、お腹が減ってただけ？\n"
.stringn "\x0713はい……\n"
.stringn "私、食べてもすぐにお腹がすいて……\n"
.stringn "倒れてしまっ……　……\n"
.stringn "\x0701え、ちょ、待ってよ！\n"
.stringn "あたし、食べるものなんて今持ってないし！\n"
.stringn "と、とにかく誰か呼んでくるから――\n"
.stringn "ってひええ！？\n"
.stringn "\x0718い……行かない……で……\n"
.stringn "\x0701あ、足！\n"
.stringn "足つかむの待った！\n"
.stringn "めっちゃ力強いし！\n"
.stringn "\x0C18\x0712何か、食べ物、を……\n"
.stringn "\x0701わ、わかった！　わかったからー！\n"
.stringn "誰かー！　なんでもいいから\n"
.stringn "食べ物もってきてー！\n"
.stringn "でないとこの子とあたしがあぶないからー！！"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_A

//0xE2C8
Text_E2A8:
.stringn "\x05FL|WAYU|ELAICE||\x0C01\x0C13\x0701あ、あんたこないだの……\n"
.stringn "\x0713こんにちは……\n"
.stringn "\x0701なんか今日も\n"
.stringn "ふらふらしてるけど、具合悪いの？\n"
.stringn "\x0713いえ……どこも悪くないです。\n"
.stringn "\x0701でも顔色、よくないみたいだよ。\n"
.stringn "いっぺん医者に見てもらったら？\n"
.stringn "\x0713本当に、大丈夫です……\n"
.stringn "以前、見ていただいたときも、\n"
.stringn "病ではないと言われましたから……\n"
.stringn "\x0701そうなの？\n"
.stringn "うーん、それってヤブじゃないの？\n"
.stringn "なんか今にも倒れそうに見えるんだけど。\n"
.stringn "\x0713すみません……\n"
.stringn "\x0701ま、いいや。\n"
.stringn "病気じゃないなら良かったけど。\n"
.stringn "ちゃんと歩ける？\n"
.stringn "\x0713はい……ではまた……\n"
.stringn "\x0701いやそっち行き止まりだから！\n"
.stringn "\x0C13\x0C01もう、あたしがついてってあげるよ！\n"
.stringn "行き先言って！\n"
.stringn "\x0713はい……\n"
.stringn "あなたは優しい方ですね……"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_B

//0xE0B4
Text_E094:
.stringn "\x05FL|WAYU|ELAICE||\x070-\x0706よし、今日の太刀筋絶好調！\n"
.stringn "今日はなんだかいいことありそう！\n"
.stringn "宿命のライバルにめぐり合えるかも！\n"
.stringn "\x0711…………\n"
.stringn "\x0C06\x0703うわあ！　びっくりしたっ！\n"
.stringn "な、何？\n"
.stringn "あっさりあたしの背後をとるなんて\n"
.stringn "なかなかやるじゃん！\n"
.stringn "\x0711あの……\n"
.stringn "ちょっと、そこを通ります……\n"
.stringn "\x0703え？　ああ、ごめん。\n"
.stringn "\x0711失礼します……\n"
.stringn "\x0703勝負の相手……\n"
.stringn "さすがに無理っぽいかな。\n"
.stringn "っていうよりちゃんと歩ける？\n"
.stringn "\x0711はい、お気遣い\n"
.stringn "ありがとうございます……\n"
.stringn "\x0703すっごい儚げな女の子……\n"
.stringn "あたしと正反対だなぁ。\n"
.stringn "なんだか守ってあげたくなる感じで……\n"
.stringn "おっと、修行修行！"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_C

//0xEE88
Text_EE68:
.stringn "\x05FL|ZIHARK|ELAICE||\x0C01\x0713あ……\n"
.stringn "\x0701やあ、イレース。\n"
.stringn "最近よく会うな？\n"
.stringn "\x0713…………は、はい……\n"
.stringn "……………………\n"
.stringn "\x0701どうかしたのか？\n"
.stringn "いつもと少し…様子が違うな。\n"
.stringn "\x0713わ、わかりますか……？\n"
.stringn "\x0701ああ。\n"
.stringn "今日は、なんだか\n"
.stringn "いつも以上に可愛い感じだ。\n"
.stringn "\x0713！\n"
.stringn "そ、そう…ですか？\n"
.stringn "\x0701…もしかして……\n"
.stringn "\x0713………\n"
.stringn "\x0701いつもにもまして、\n"
.stringn "腹を空かせてるのか？\n"
.stringn "\x0713………え…？\n"
.stringn "\x0701君は、軍の男連中の間では\n"
.stringn "ちょっとした有名人だからな。\n"
.stringn "可愛い顔につられて近寄ると\n"
.stringn "痛い目にあうって。\n"
.stringn "\x0713そ……\n"
.stringn "そうなんですか……？\n"
.stringn "\x0701誘ったほうにも責任はあるが、\n"
.stringn "高い食事代を払わされたのに\n"
.stringn "次の日会ったら、\n"
.stringn "顔も名前も覚えてないんだって？\n"
.stringn "ひどいことをする。\n"
.stringn "\x0713………私……\n"
.stringn "その……お腹が減りすぎると……\n"
.stringn "倒れてしまうんです……\n"
.stringn "だから…みなさんのご厚意に…すぐ…\n"
.stringn "甘えて…しまって……………\n"
.stringn "\x0701…だったら、名前ぐらい覚えてやらないと。\n"
.stringn "下心があったにせよ、\n"
.stringn "みんな君に厚意…というか、\n"
.stringn "好意をよせているんだし。\n"
.stringn "\x0713……す…すみません……\n"
.stringn "\x0701謝る相手は、俺じゃないって。\n"
.stringn "\x0713……はい………\n"
.stringn "\x0701…さて、じゃあ行こうか。\n"
.stringn "\x0713え…？\n"
.stringn "\x0701また倒れそうなぐらい、空腹なんだろ？\n"
.stringn "説教を聞かせたお詫びに食事をおごるよ。\n"
.stringn "\x0713いいんですか…？\n"
.stringn "\x0701君とは、仲間になってから\n"
.stringn "わりと長い付き合いだしね。\n"
.stringn "ただし…\n"
.stringn "俺は金持ちじゃないから、せいぜい\n"
.stringn "２人前が限度だからな。\n"
.stringn "\x0713そ、そんな…\n"
.stringn "私…それで十分です…\n"
.stringn "すごくうれしいです…！\n"
.stringn "ありがとうございます……\n"
.stringn "…………えーっと……\n"
.stringn "\x0701…ツイハーク。\n"
.stringn "\x0713…す…すみません……\n"
.stringn "ツイハークさん…"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_A

//0xEBB8
Text_EB98:
.stringn "\x05FL|ELAICE|ZIHARK||\x0C01\x0C13\x0701……あ、あの……\n"
.stringn "\x0713どうしたんだ、イレース？\n"
.stringn "また空腹なのか？\n"
.stringn "\x0701は、はい……\n"
.stringn "\x0713君は、見かけによらず\n"
.stringn "大食漢だからな。\n"
.stringn "魔法の詠唱は、そんなに\n"
.stringn "体力を消耗するものなのか？\n"
.stringn "\x0701どうなんでしょうか……\n"
.stringn "なぜかはわからないんですけど……\n"
.stringn "すぐにおなかが減るんです……\n"
.stringn "今日は幸い、４人分いただけたんですけど……\n"
.stringn "いつもは３人分だけなのが……辛くて……\n"
.stringn "\x0713はは　そりゃすごいな。\n"
.stringn "じゃあ、食べた分は\n"
.stringn "しっかり働いて返さないと。\n"
.stringn "がんばれよ。\n"
.stringn "\x0701あ…　あの…\n"
.stringn "ちょっと待って…ください……！\n"
.stringn "\x0C13\x0714何だ？\n"
.stringn "\x0701あの……\n"
.stringn "なにか…お忘れじゃないですか…？\n"
.stringn "\x0714俺が？　……いや、\n"
.stringn "特になにも忘れていないと思うが？\n"
.stringn "\x0701……そう…ですか…\n"
.stringn "\x0714じゃあ、また後でな。\n"
.stringn "\x0701………………\n"
.stringn "なにも、くれない人は……\n"
.stringn "はじめて……　……"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_B

//0xE8E8
Text_E8C8:
.stringn "\x05FL|ZIHARK|ELAICE||\x0C01\x0C13\x0701……イレース？\n"
.stringn "さっきから何を見てるんだ？\n"
.stringn "\x0713え？　あ……\n"
.stringn "その……腰につけた、袋ですけど……\n"
.stringn "\x0701別に珍しいものでも\n"
.stringn "なんでもないと思うが……\n"
.stringn "薬や保存食を入れて携帯している。\n"
.stringn "……これがどうかしたのか？\n"
.stringn "\x0713え、ええと……\n"
.stringn "おいしそうな匂いが……するので……\n"
.stringn "\x0701…そんなに匂うか？\n"
.stringn "乾燥させた物しか入れてないんだが。\n"
.stringn "\x0713ご……ごめんなさい……\n"
.stringn "私……その、お腹が空いてるもので……\n"
.stringn "\x0701さっき、君が元気に\n"
.stringn "食事をしていたのを見かけたぞ？\n"
.stringn "あれから、そう時間は経ってない。\n"
.stringn "そんな消化がいいんなら、\n"
.stringn "見た目に反してよほど健康なんだろうな。\n"
.stringn "さて、俺はもう行くよ。\n"
.stringn "\x0713あ……\n"
.stringn "\x0C01\x0C13………………\n"
.stringn "どうしよう…………\n"
.stringn "なにか、食べなきゃ……動けなくなるかも…\n"
.stringn "………………\n"
.stringn "くださいって、言えばよかったの…かな……"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_C

//0xF87C
Text_F85C:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x0C01\x071-\x0C13\x0701……この間とは、逆ですね。\n"
.stringn "ジョフレ…？　私の話を聞いて下さい。\n"
.stringn "\x0713……聞いております。\n"
.stringn "\x0701……ジョフレ…戦場でのあなたは、\n"
.stringn "私を庇おうとするあまり……\n"
.stringn "とても無理な戦い方をしています。\n"
.stringn "\x0713主君を護り、庇うのが騎士の役目です。\n"
.stringn "\x0701だけどそれのために…\n"
.stringn "あなた自身が何度も危険な目にあいました。\n"
.stringn "\x0713確かに、何度か…\n"
.stringn "浅からぬ傷を負いました。\n"
.stringn "\x0701あなたは…以前、\n"
.stringn "私のために命を捨てるような\n"
.stringn "真似はしないと約束してくれたはず。\n"
.stringn "なのに……やっぱり\n"
.stringn "自分の命を大切にはしてくれない。\n"
.stringn "\x0713姫…　ですが…！\n"
.stringn "\x0701私が、戦場に出たりせず…\n"
.stringn "本営でじっとしていれば\n"
.stringn "いいのだということは……\n"
.stringn "わかっています。\n"
.stringn "でも……\n"
.stringn "私の手の届かないところで…\n"
.stringn "大切な人の命が奪われることが……\n"
.stringn "もう…耐えられなくて……\n"
.stringn "そのために……\n"
.stringn "ジョフレに負担を………\n"
.stringn "\x0713姫…　姫はお気づきではないのですね。\n"
.stringn "あなたが戦場に出られるようになって、\n"
.stringn "クリミア兵の士気が…\n"
.stringn "どれほど上がったと思われますか？\n"
.stringn "主君たるあなたが、戦場におられる。\n"
.stringn "それは確かに…大いなる不安との\n"
.stringn "背中合わせには違いありません。\n"
.stringn "ですが、だからこそ\n"
.stringn "我々は敗れるわけにはいかない。\n"
.stringn "必ず勝たねばならぬのだと…\n"
.stringn "本来備えている以上の力を\n"
.stringn "発揮することができるのです。\n"
.stringn "\x0701………\n"
.stringn "\x0713確かに、私は…\n"
.stringn "最近無謀な戦い方をしてました。\n"
.stringn "それは…姫がお近くにいて下さると\n"
.stringn "思えばこそでした。\n"
.stringn "私が少々無茶なことをしても…\n"
.stringn "姫がすぐ横で傷を癒して下さるので……\n"
.stringn "それに甘えすぎていたようです。\n"
.stringn "\x0701……私は…\n"
.stringn "迷惑なだけでは……ない…？\n"
.stringn "\x0713姫を抜きにした戦い方など…\n"
.stringn "もう思い出すこともできません。\n"
.stringn "この私の命を惜しんで下さるのなら、\n"
.stringn "どうかこれからも\n"
.stringn "戦場でお力をお貸し下さい。\n"
.stringn "\x0701ジョフレ…ごめんなさい。\n"
.stringn "勝手に誤解して\n"
.stringn "腹を立てて…あなたを苦しめました。\n"
.stringn "私は…未熟な主です。\n"
.stringn "\x0713命令違反する私も、あまり\n"
.stringn "褒められた臣下ではありませんよ。\n"
.stringn "\x0701これからもきっと…\n"
.stringn "たくさん迷惑をかけると思いますが……\n"
.stringn "ずっと傍に居て下さいね、ジョフレ。\n"
.stringn "\x0713エリンシア姫…\n"
.stringn "我が剣は、生涯あなただけのものです。"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_A

//0xF5A0
Text_F580:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x070-\x0C01\x0713……姫？\n"
.stringn "姫…　どうか、機嫌を直して下さい。\n"
.stringn "\x0701………\n"
.stringn "\x0713私が…　姫の命令を\n"
.stringn "守らなかったことに対し、\n"
.stringn "ご立腹であるのは承知しております。\n"
.stringn "しかし…！\n"
.stringn "姫の騎士たる、この私に…\n"
.stringn "戦場で構うなとは…\n"
.stringn "あまりにも無体なご命令ではないかと……\n"
.stringn "もし、私に至らない点があり、\n"
.stringn "それを不服とされているのであれば…\n"
.stringn "いっそ、騎士の称号を剥奪して下さい。\n"
.stringn "\x0701………\n"
.stringn "\x0713姫…っ！\n"
.stringn "\x0701……騎士の称号を奪えば…\n"
.stringn "ジョフレは、私を護ることを\n"
.stringn "やめてくれるのですか？\n"
.stringn "\x0713！！\n"
.stringn "\x0701………\n"
.stringn "\x0713…姫は…そこまで私を\n"
.stringn "疎ましくお思いでしたか……\n"
.stringn "\x0701！　ちがいます…！\n"
.stringn "\x0713迂闊なことを口走りましたが…\n"
.stringn "祖国再興の日までは…\n"
.stringn "……どうか、このまま……\n"
.stringn "姫を護る騎士でいさせて下さい。\n"
.stringn "………申し訳ありません……\n"
.stringn "\x0701待って、ジョフレ…！\n"
.stringn "ジョフレ……！！"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_B

//0xF3D8
Text_F3B8:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x0701……\n"
.stringn "\x0713姫？\n"
.stringn "誰かをお捜しですか？\n"
.stringn "\x0701ジョフレ。\n"
.stringn "よかった、そこに居たんですね。\n"
.stringn "\x0713私にご用ですか？\n"
.stringn "\x0701はい。私…\n"
.stringn "ジョフレにお願いがあります。\n"
.stringn "\x0713姫が私にお願いごとだなどと…\n"
.stringn "どんなことでも構いません。\n"
.stringn "お命じ下さればいいのです。\n"
.stringn "\x0701…本当に？\n"
.stringn "\x0713はい。\n"
.stringn "\x0701では、言いますね。\n"
.stringn "ジョフレ…今後一切、\n"
.stringn "戦場では私に構わないで下さい。\n"
.stringn "\x0713な！？\n"
.stringn "姫、そんな…\n"
.stringn "\x0701反論は聞きません。\n"
.stringn "これは…命令ですから。\n"
.stringn "必ず、守って下さいね。\n"
.stringn "\x0713…姫……"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_C

//0x107C4
Text_107A4:
.stringn "\x05FL|ERINCIA|IKE||\x0701…………\n"
.stringn "\x0713いよいよ、明日は王都だな。\n"
.stringn "\x0701……はい。\n"
.stringn "\x0713心境は？\n"
.stringn "\x0701…とても不安です。でも……\n"
.stringn "やっとたどり着いた。\n"
.stringn "やっと帰って来られた。\n"
.stringn "その２つの喜びの方が強いです。\n"
.stringn "\x0713強くなったな。\n"
.stringn "\x0701すぐ傍に…\n"
.stringn "良いお手本がありましたから。\n"
.stringn "\x0713悪いの間違いだろう。\n"
.stringn "あんた南の海で\n"
.stringn "自分がなんて言ったか覚えてるか？\n"
.stringn "\x0701な、なんですか…？\n"
.stringn "私なにか変なことを言いましたか？\n"
.stringn "\x0713『ぶっとばしてさしあげましょう！』\n"
.stringn "だったか？\n"
.stringn "\x0701あ…　あれは…\n"
.stringn "少しアイク様たちの真似を\n"
.stringn "してみたかったんです。\n"
.stringn "私も、みなさんのように\n"
.stringn "たくましくなりたくって……\n"
.stringn "\x0713あれには、さすがに面食らった。\n"
.stringn "\x0701フフ　……なんだか\n"
.stringn "とても、なつかしいですね。\n"
.stringn "\x0C13\x0C01王都を逃れた時…\n"
.stringn "ガリアで…クリミアの敗戦を\n"
.stringn "聞かされた時…\n"
.stringn "これから先、自分を待つものは\n"
.stringn "絶望だけだと思い覚悟していました…\n"
.stringn "…だけど、こうして振り返ってみると\n"
.stringn "希望がいくつもありました……\n"
.stringn "とても暖かな希望の光が……\n"
.stringn "\x0713そうだな……\n"
.stringn "\x0701私は…この希望を胸に……\n"
.stringn "明日の戦いに臨みます。\n"
.stringn "デイン王を倒し、\n"
.stringn "クリミアを取り戻すために。\n"
.stringn "\x0713俺は、あんたに雇われた傭兵だ。\n"
.stringn "あんたの望みを叶えるために\n"
.stringn "全力を尽くすと約束する。\n"
.stringn "\x0701アイク様……"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_A

//0x10384
Text_10364:
.stringn "\x05FL|IKE|ERINCIA||\x0701…まだ、ここにいたんだな。\n"
.stringn "\x0713あ……アイク様。\n"
.stringn "その…自主訓練をしていました…\n"
.stringn "少しでも足手まといにならないようにと\n"
.stringn "思いまして……\n"
.stringn "\x0701……そうか。\n"
.stringn "だが、訓練なら誰か相手がいた方が\n"
.stringn "いいんじゃないのか？\n"
.stringn "\x0713……この張りつめた状態で…\n"
.stringn "あきらかに実力の劣る者の\n"
.stringn "相手をさせるのは…とても心苦しくて……\n"
.stringn "\x0701…さっきは、他人に頼ることに\n"
.stringn "躊躇するなと言ったつもりだったが…\n"
.stringn "上手く伝わらなかったようだな。\n"
.stringn "\x0713いえ、その…\n"
.stringn "ご忠告は身にしみています。\n"
.stringn "ですが…その……\n"
.stringn "\x0701……自分の力の無さを感じ、\n"
.stringn "焦る気持ちはよく分かるつもりだ。\n"
.stringn "俺も親父の遺したグレイル傭兵団を\n"
.stringn "継ぐと決めた時……\n"
.stringn "居てもたってもいられなかった。\n"
.stringn "\x0713…………\n"
.stringn "\x0701まあ、国と傭兵団じゃ重みがまったく違うか。\n"
.stringn "すまん、偉そうなことを言ったな。\n"
.stringn "\x0713いいえ……\n"
.stringn "おっしゃるとおりです。\n"
.stringn "これから自分が背負うものの大きさを思うと\n"
.stringn "自分の至らなさが……辛くて……\n"
.stringn "\x0701俺がこの１年…\n"
.stringn "戦いを通して学んだのは…\n"
.stringn "１人だけでやれることなんて、\n"
.stringn "実はそんなにないってことだ。\n"
.stringn "仲間が俺を支えてくれて、\n"
.stringn "俺がそれを頼りにできたからこそ…\n"
.stringn "成し得たことばかりじゃないかと\n"
.stringn "そう思っている。\n"
.stringn "あんたも同じだ。\n"
.stringn "あんたは１人じゃない。\n"
.stringn "\x0713…………はい……！"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_B

//0xFF88
Text_FF68:
.stringn "\x05FL|IKE|ERINCIA||\x0703エリンシア姫。\n"
.stringn "どうかしたのか？\n"
.stringn "\x0711あ……アイク様。\n"
.stringn "その、戦う支度をしていたのですが\n"
.stringn "剣がうまく腰におさまらなくて……\n"
.stringn "\x0703ちょっと見せてみろ。\n"
.stringn "…ああ、鞘を結ぶ\n"
.stringn "腰の止め金がきちんと留まってないな。\n"
.stringn "これをはめるのには少しコツがいる。\n"
.stringn "少し動かないでくれ。\n"
.stringn "…………\n"
.stringn "よし、これで大丈夫だ\n"
.stringn "\x0711ありがとうございます、アイク様。\n"
.stringn "……私、だめですね。\n"
.stringn "１人で戦支度もできないなんて……\n"
.stringn "他の方はもうすっかり済ませているというのに…\n"
.stringn "\x0703最初は誰だってそんなものだ。\n"
.stringn "俺も、少し前までは\n"
.stringn "姫と同じようなものだったからな。\n"
.stringn "\x0711アイク様が？\n"
.stringn "\x0703ああ。\n"
.stringn "だが俺は親父から、いかなる環境でも\n"
.stringn "生き抜く術と、剣の扱いを\n"
.stringn "何より先に叩き込まれたからな。\n"
.stringn "姫とは根本が違うのかも知れんが。\n"
.stringn "\x0711そうなのですか……\n"
.stringn "\x0703だから姫、背伸びはしなくてもいい。\n"
.stringn "あんたは俺たち生まれながらの\n"
.stringn "傭兵とは違うんだ。\n"
.stringn "慣れないところで無理をすると…\n"
.stringn "戦場で死を招くぞ。\n"
.stringn "\x0711わ、わかりました……\n"
.stringn "\x0703……とにかく、必要以上に\n"
.stringn "思い詰めないようにしてくれ。\n"
.stringn "できないことを自覚して、\n"
.stringn "他人に助けを求めることは…\n"
.stringn "恥でもなんでもないんだからな。\n"
.stringn "\x0711はい……\n"
.stringn "\x0703…………"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_C

//0x112B8
Text_11298:
.stringn "\x05FL|MARCIA|GATRIE||\x070-\x0703あ、ガトリーさん。\n"
.stringn "\x0711…………\n"
.stringn "\x0703あれ、どうしたんですか？\n"
.stringn "元気ないですね。\n"
.stringn "\x0711……おれみたいな負け犬に\n"
.stringn "もう話しかけない方がいいよ。\n"
.stringn "おれなんて、\n"
.stringn "そこらの石ころでも見るような目で\n"
.stringn "眺めてくれればそれでいいのさ……\n"
.stringn "\x0703は、はあ……\n"
.stringn "あ、もしかしてガトリーさん\n"
.stringn "こないだのこと気にしてるんですか？\n"
.stringn "訓練でアイクさんに完敗……\n"
.stringn "\x0711も、もうあのことは\n"
.stringn "思い出させないでくれ～！\n"
.stringn "さんざん大口叩いたくせに\n"
.stringn "あんなに無様な負けっぷりを\n"
.stringn "よりによって君に見られるなんて…\n"
.stringn "おれはもうだめさ。\n"
.stringn "世界一だめな男さ……\n"
.stringn "\x0703そんなことないですよ。\n"
.stringn "確かにあの時は\n"
.stringn "アイクさんの勝ちでしたけど……\n"
.stringn "でも、ガトリーさんの\n"
.stringn "一生懸命な姿、格好良かったです。\n"
.stringn "\x0711ほ、本当に！？\n"
.stringn "\x0703はい、２人ともすごく強かったです。\n"
.stringn "私も負けていられません。\n"
.stringn "今度一緒に訓練、付き合ってくださいね。\n"
.stringn "アイクさんにもガトリーさんにも\n"
.stringn "色々教えて欲しいです。\n"
.stringn "\x0711も、もちろん！\n"
.stringn "\x0703よかった。\n"
.stringn "楽しみにしてます！\n"
.stringn "それじゃ！\n"
.stringn "\x0711……　……　……\n"
.stringn "アイク、おれちょっぴり\n"
.stringn "おまえのこと恨んでたけど……\n"
.stringn "今はありがとうの気持ちで\n"
.stringn "胸がいっぱいだ！\n"
.stringn "またな、マーシャちゃーん！"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_A

//0x10F74
Text_10F54:
.stringn "\x05FL|MARCIA|GATRIE||\x0C01\x071-\x0C13\x0701どうしたんですか、ガトリーさん？\n"
.stringn "私になにかご用ですか？\n"
.stringn "\x0713やあ、よく来てくれたねマーシャちゃん。\n"
.stringn "実はこれからおれ、アイクの奴と\n"
.stringn "実戦訓練することになってるんだ。\n"
.stringn "\x0701ええ！？\n"
.stringn "ガトリーさん、\n"
.stringn "アイクさんと戦うんですか？\n"
.stringn "\x0713もちろん！　だから君を呼んだんだ。\n"
.stringn "おれがふだん隠してる本当の強さを\n"
.stringn "君だけに見せてあげようと思って。\n"
.stringn "アイクは団長だけあって強いけど、\n"
.stringn "おれの真の実力は\n"
.stringn "さらにその上を行くからね。\n"
.stringn "\x0701そうなんですか……\n"
.stringn "ガトリーさんてすごく強いんですね。\n"
.stringn "尊敬しちゃいます。\n"
.stringn "\x0713いや～　ははははは！\n"
.stringn "ま、そこでおれの強さを\n"
.stringn "よく見ててくれよマーシャちゃん。\n"
.stringn "\x0716お、アイク！\n"
.stringn "準備はいいな？　行くぞ！\n"
.stringn "\x0C01\x0718マーシャちゃん、\n"
.stringn "きみへの愛で、おれは勝つ！\n"
.stringn "うおおおおおおーーー！！\n"
.stringn "……ぐはっ！？\n"
.stringn "\x0701あ～……\n"
.stringn "今の痛そう。\n"
.stringn "\x0718……ま、待ってくれアイク！\n"
.stringn "もう少し手加減……ぎええ！？\n"
.stringn "\x0701ガトリーさん、大丈夫かな……？"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_B

//0x10BE8
Text_10BC8:
.stringn "\x05FL|MARCIA|GATRIE||\x0C01\x071-\x0713やあマーシャちゃん！\n"
.stringn "\x0701え？　どうして私の名前を？\n"
.stringn "\x0713君みたいな可愛い子、\n"
.stringn "名前を知ってて当然じゃないか！\n"
.stringn "しっかし、おれが昔いた頃は\n"
.stringn "一緒に戦う女性といえば\n"
.stringn "ティアマトさんだけだったのに……\n"
.stringn "しばらく離れてる間に\n"
.stringn "いい団体になったなあ、\n"
.stringn "うんうん。\n"
.stringn "\x0701もしかして…\n"
.stringn "以前、グレイル傭兵団にいた人ですか？\n"
.stringn "\x0713うん。\n"
.stringn "おれ、あのアイクの\n"
.stringn "大先輩ってやつなんだ。\n"
.stringn "\x0701あ～やっぱり！\n"
.stringn "私が海賊に襲われているのを\n"
.stringn "助けてくださった時、\n"
.stringn "いらっしゃいましたよね？\n"
.stringn "\x0713え…！？\n"
.stringn "\x0701私、あの時のこと、\n"
.stringn "本っ当に感謝してて…\n"
.stringn "受けたご恩返しのために\n"
.stringn "がんばってます！\n"
.stringn "\x0713あ、ああ。うん！\n"
.stringn "君のような優秀な天馬騎士が\n"
.stringn "入ってくれただけで充分だって！\n"
.stringn "現におれは……君がこの団に\n"
.stringn "いてくれるだけで…もう何もいらない！\n"
.stringn "\x0701そ、そんなに期待されてるなんて\n"
.stringn "ちょっと緊張…………\n"
.stringn "と、とにかく、これからも\n"
.stringn "がんばりますのでよろしくお願いしますね！\n"
.stringn "\x0713ああ、なんてかわいい子なんだろ。\n"
.stringn "やっぱりさ、これって……\n"
.stringn "運命だよな？　な？"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_C

//0x12034
Text_12014:
.stringn "\x05FL|GATRIE|STELLA||\x070-\x0C01\x071-\x0713ガトリーさん、\n"
.stringn "今日もよろしくお願いいたします。\n"
.stringn "\x0701ええ！\n"
.stringn "えーとじゃあ、前回の話ですけど…\n"
.stringn "ステラさん、『臨機応変』って\n"
.stringn "なんて意味かわかります？\n"
.stringn "\x0713はい、わかります。\n"
.stringn "\x0701え！？\n"
.stringn "わかるんですか？\n"
.stringn "\x0713その時々の状況や変化に応じて\n"
.stringn "適切に対処すること……でしょうか？\n"
.stringn "\x0701あ、なるほど！\n"
.stringn "なんだ、そういう意味か。\n"
.stringn "前回の答えはそれです、はい！\n"
.stringn "さすがステラさんは賢いっすね！\n"
.stringn "いや、おれももちろん知ってましたよ？\n"
.stringn "知ってたんですけど、ちょっと\n"
.stringn "生徒を試してみようかなと思っただけで。\n"
.stringn "いやもう合格！　合格ですよ！\n"
.stringn "\x0713はい、そんなふうに\n"
.stringn "ほめていただけて嬉しいです。\n"
.stringn "\x0701ま、そんな感じで先生と生徒の間柄も\n"
.stringn "深くなったことですし…\n"
.stringn "あの、ス、ステラさんって……\n"
.stringn "恋人とかいます？　いませんよね？\n"
.stringn "\x0713恋人……ですか？\n"
.stringn "\x0701ええ！\n"
.stringn "あ、ちなみにおれは恋人いません！\n"
.stringn "安心してください！\n"
.stringn "\x0713恋人はいません。\n"
.stringn "ですが、許婚なら……\n"
.stringn "\x0701え？\n"
.stringn "い、許婚？\n"
.stringn "\x0713はい。\n"
.stringn "\x0701そ、そうなんですか！\n"
.stringn "いや、そりゃめでたいっすね！\n"
.stringn "\x0713あの……なぜ涙を？\n"
.stringn "\x0701いや、おれのことは気にしないで…\n"
.stringn "いいんです！\n"
.stringn "ステラさんが幸せなら、それでっ！\n"
.stringn "\x0713あ、ガトリーさんどちらへ……\n"
.stringn "\x0705はあ……またふられちまった。\n"
.stringn "今回こそはと思ったのになあ。\n"
.stringn "……ん、けど待てよ？\n"
.stringn "ステラさん、\n"
.stringn "婚約者がいるって言ってたよな？\n"
.stringn "そんなことわざわざ言うってことは\n"
.stringn "これって遠まわしに……私をさらって\n"
.stringn "逃げて欲しいってことじゃないのか？\n"
.stringn "なんだ！　そうならそうと言ってくれれば！\n"
.stringn "待ってて下さいステラさん～！\n"
.stringn ""
db 0
.align 4
//MYELL_8_GATRIE_STELLA_A

//0x11AAC
Text_11A8C:
.stringn "\x05FL|STELLA|GATRIE||\x070-\x0C01\x071-\x0C13\x0701ガトリーさん。\n"
.stringn "お話を伺いに参りました。\n"
.stringn "よろしいでしょうか？\n"
.stringn "\x0713ええ、もちろんっすよ！\n"
.stringn "むしろおれの方が探してたくらいで！\n"
.stringn "えー、ごほん\n"
.stringn "じゃあ、説明します！\n"
.stringn "\x0701はい。\n"
.stringn "\x0713えーまず！\n"
.stringn "傭兵団の戦いってのはですね！\n"
.stringn "役割分担が大切なんです！\n"
.stringn "仲間同士が協力しあえば、\n"
.stringn "たった３人でも１０人分の働きができるらし…\n"
.stringn "できるんですよ！\n"
.stringn "\x0701なるほど……役割分担ですね。\n"
.stringn "はい、わかります。\n"
.stringn "\x0713グレイル傭兵団でのおれの役割は、\n"
.stringn "敵を防ぐ盾です。\n"
.stringn "とにかく、おれが勇敢に前に出て\n"
.stringn "敵の攻撃を全部防ぐ！\n"
.stringn "その隙に他のみんなが攻撃っス！\n"
.stringn "弓はおれの後ろから、\n"
.stringn "騎馬は一撃当てたらすぐ下がる！\n"
.stringn "とまあ、こんな感じらしい……\n"
.stringn "こんな感じです！\n"
.stringn "\x0701とてもよくわかりました。\n"
.stringn "では私は……\n"
.stringn "\x0713ステラさんはもちろんおれの後ろに！\n"
.stringn "あまり離れると危険ですから、\n"
.stringn "くっつきすぎだろっていうくらい\n"
.stringn "おれにくっついてください！　ええもう！\n"
.stringn "\x0701はい、できる限り努力します。\n"
.stringn "あ、それと\n"
.stringn "１つ質問をよろしいでしょうか？\n"
.stringn "\x0713ええ、何でも！\n"
.stringn "\x0701私は騎馬で、ガトリーさんは歩兵ですから、\n"
.stringn "行軍の足並みが合わない気がいたします。\n"
.stringn "この場合はどうすればいいのでしょう？\n"
.stringn "\x0713えーと、その場合はですね……\n"
.stringn "あれ？\n"
.stringn "ティアマトさんなんて言ってたっけ？\n"
.stringn "\x0701？\n"
.stringn "\x0713あーいえ、今の独り言っす！\n"
.stringn "じゃあ、その件は\n"
.stringn "また今度ってことで！\n"
.stringn "次に話すときはばっちり教えますからね！\n"
.stringn "\x0701はい、今日は大変勉強になりました。\n"
.stringn "またぜひお教え下さいね。\n"
.stringn "では、失礼いたします。\n"
.stringn "\x0713『また教えて下さい』、か～……\n"
.stringn "これって、遠まわしに結婚して欲しいって\n"
.stringn "意味だよなあ……\n"
.stringn "ああ、まいったなあ～…"
db 0
.align 4
//MYELL_8_GATRIE_STELLA_B

//0x116B4
Text_11694:
.stringn "\x05FL|STELLA|GATRIE||\x070-\x0C01\x071-\x0713いやあ、ステラさん！\n"
.stringn "あなたとこうして一緒に戦えるなんて\n"
.stringn "大感激っすよ！\n"
.stringn "\x0701はい、これからも\n"
.stringn "よろしくお願いいたします。\n"
.stringn "ガトリーさんは、以前にも\n"
.stringn "アイクさんの傭兵団に\n"
.stringn "おられたと聞きましたが……\n"
.stringn "\x0713もちろん！\n"
.stringn "おれはずっと前から\n"
.stringn "ここでやってた古参ですからね！\n"
.stringn "わかんないことがあったら\n"
.stringn "何でも聞いてください！　何でも！\n"
.stringn "\x0701ありがとうございます。\n"
.stringn "では……私に\n"
.stringn "傭兵としての戦い方を\n"
.stringn "教えていただけませんか？\n"
.stringn "\x0713傭兵団の戦い方……っていうと？\n"
.stringn "\x0701私には戦いの経験が\n"
.stringn "あまりありません。\n"
.stringn "ですから、みなさんに\n"
.stringn "ご迷惑をおかけしないように\n"
.stringn "学んでおきたいと思って……\n"
.stringn "\x0713な、なるほど！\n"
.stringn "さすがステラさん！\n"
.stringn "……あー、けど\n"
.stringn "今はちょっとまずいっすね。\n"
.stringn "ティアマトさんもいないし、\n"
.stringn "今度会うときまでにこっそり聞い……\n"
.stringn "\x0701？\n"
.stringn "\x0713いえ、何でもないっす！\n"
.stringn "どうせなら\n"
.stringn "ばっちり用意してからにしたいんで！\n"
.stringn "日をおいてまた来てください！\n"
.stringn "\x0701はい。では、次の機会に。\n"
.stringn "よろしくお願いいたします。\n"
.stringn "\x0713ああ、可愛いなあ……\n"
.stringn "おれに戦い方を\n"
.stringn "教えて欲しいってことは……\n"
.stringn "やっぱ、彼女ってば\n"
.stringn "おれに気があるんだよなあ……\n"
.stringn "まいったなあ……"
db 0
.align 4
//MYELL_8_GATRIE_STELLA_C

//0x12A34
Text_12A14:
.stringn "\x05FL|JILL|HAAR||\x0703ハールさん。\n"
.stringn "\x071-\x0711ここだ。\n"
.stringn "\x0703やっと１回で返事をしてくれましたね。\n"
.stringn "\x0711そのほうが、おまえの小言に\n"
.stringn "付き合う時間が減るかもしれんからな。\n"
.stringn "\x0703もう…\n"
.stringn "いいですけど、別に。\n"
.stringn "\x0711…ジル、おまえ\n"
.stringn "この戦いが済んだらどうするんだ？\n"
.stringn "\x0703……デインに戻りたいです。\n"
.stringn "ダルレカの…父の墓の近くで暮らしたい。\n"
.stringn "\x0711そうか。\n"
.stringn "\x0703ハールさんは？\n"
.stringn "\x0711俺は…　アシュナードの野郎と\n"
.stringn "やりあっても生き残れたんなら……\n"
.stringn "………どうするかな。\n"
.stringn "シハラム殿の墓守役は\n"
.stringn "先に言われちまったからなあ。\n"
.stringn "\x0703わ、私と一緒は…\n"
.stringn "不満だということですか！？\n"
.stringn "\x0711…おまえが俺と一緒だと\n"
.stringn "嫌がると思って遠慮しただけだ。\n"
.stringn "\x0703……嫌なわけ、ありません。\n"
.stringn "\x0711じゃあ、もし２人とも生き残れたら\n"
.stringn "ダルレカで飛竜を使った\n"
.stringn "荷運びでもやって暮らすか。\n"
.stringn "\x0703はい。\n"
.stringn "もし…生き残れたなら。"
db 0
.align 4
//MYELL_8_HAAR_JILL_A

//0x12784
Text_12764:
.stringn "\x05FL|JILL|HAAR||\x0703ハールさん！\n"
.stringn "ハールさん…どこですか！？\n"
.stringn "ハールさ…\n"
.stringn "\x071-\x0711ここだ。\n"
.stringn "\x0703聞こえてるなら、最初の１回で\n"
.stringn "返事をして下さい！\n"
.stringn "『隊長』って言わなかったら\n"
.stringn "ちゃんと返事をするって\n"
.stringn "約束したはずですよ。\n"
.stringn "\x0711…面倒くせえなあ。\n"
.stringn "\x0703……ずっと思ってましたけど。\n"
.stringn "ハールさんが軍人らしく\n"
.stringn "真面目な態度だったのって…\n"
.stringn "父上の前でだけでしたよね。\n"
.stringn "\x0711おまえだって、\n"
.stringn "そのつり上がった眉が下がるの、\n"
.stringn "シハラム殿の前だけだったな。\n"
.stringn "\x0703そ、それは…\n"
.stringn "仕方ないでしょう？\n"
.stringn "父上は特別なんですから。\n"
.stringn "\x0711俺もだ。\n"
.stringn "シハラム殿は特別な存在だった。\n"
.stringn "だからあの人の前でだけは、\n"
.stringn "この不精でどうしようもない\n"
.stringn "姿を見せないよう神経を尖らせてた。\n"
.stringn "\x0703…ハールさん。\n"
.stringn "\x0711ふぁぁ…　眠いな。\n"
.stringn "話は終わりだ。今日はもう邪魔するなよ。"
db 0
.align 4
//MYELL_8_HAAR_JILL_B

//0x12574
Text_12554:
.stringn "\x05FL|JILL|HAAR||\x0703ハール隊長！\n"
.stringn "ハール隊長…どこですか！？\n"
.stringn "ハール隊ちょ…\n"
.stringn "\x071-\x0711ここだ。\n"
.stringn "おまえな、人の名前を\n"
.stringn "市の野菜売りみたいに連呼するな。\n"
.stringn "\x0703だったら、最初の１回で\n"
.stringn "返事をして下さい！\n"
.stringn "\x0711おまえが俺のことを『隊長』って\n"
.stringn "呼ばなくなったらな。\n"
.stringn "\x0703だって…\n"
.stringn "じゃあ、なんて呼べばいいんですか？\n"
.stringn "\x0711おまえの好きにしろ。\n"
.stringn "\x0703ハール殿…？\n"
.stringn "\x0711普通だな。\n"
.stringn "\x0703ハールさん。\n"
.stringn "\x0711いまいちぴんとこねえなあ。\n"
.stringn "\x0703ハール！\n"
.stringn "\x0711おぉ。それでいいぜ。\n"
.stringn "\x0703嫌ですよ。\n"
.stringn "元の上官を呼び捨てにするなんて。\n"
.stringn "やっぱり、ハールさんにします。\n"
.stringn "\x0711まぁ…いいけどな。"
db 0
.align 4
//MYELL_8_HAAR_JILL_C

//0x130EC
Text_130CC:
.stringn "\x05FL|HAAR|MAKAROV||\x070-\x0C03\x0711あ、いたいた。\n"
.stringn "ハールの兄さん！\n"
.stringn "\x0703………\n"
.stringn "\x0711兄さ～ん。\n"
.stringn "起きてくださいよお。\n"
.stringn "あっ！　アイク将軍が来たぞーっ！！\n"
.stringn "………\n"
.stringn "\x0703………\n"
.stringn "\x0711あれ～　起きないなあ。\n"
.stringn "しっかし、この状態で寝てられるってのは\n"
.stringn "すごい神経だよ。尊敬しちゃうね。\n"
.stringn "おれも早くこの域まで達さないと～。\n"
.stringn "借金取りも泣いて逃げ出すような、\n"
.stringn "この迫力を身に付けられれば、\n"
.stringn "踏み倒し放題だもんな。\n"
.stringn "よし！　特訓あるのみだ。\n"
.stringn "まずはどこでも寝れるようになるぞ。\n"
.stringn "……………\n"
.stringn "ぐー…　ぐががががが\n"
.stringn "\x0703……うるせえな。\n"
.stringn "ったく、誰が兄さんだよ…\n"
.stringn "\x0711すやすや　ん～…\n"
.stringn "マーシャぁ…　兄ちゃんが悪かった……\n"
.stringn "\x0703………\n"
.stringn "\x0711…金、貸してくれ……　むにゃむにゃ\n"
.stringn "\x0703……この有様で、ここまで\n"
.stringn "生き残ってきたっていうのが\n"
.stringn "ある意味、奇跡だな。\n"
.stringn "よっぽど運がいいのかね。\n"
.stringn "せっかくだから、このまま最後まで\n"
.stringn "是非、生き残ってもらいたいもんだ。"
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_A

//0x12E00
Text_12DE0:
.stringn "\x05FL|HAAR|MAKAROV||\x0701ん…？　おまえは……\n"
.stringn "\x0713ひええ！？\n"
.stringn "\x0701この間の男だな。\n"
.stringn "\x0C13\x0C01こら、逃げるな。\n"
.stringn "\x0714か、かんべんしてください～！\n"
.stringn "きちんとお返ししますから～！\n"
.stringn "\x0701…なんの話だ？\n"
.stringn "\x0714い、いえ、あの時はちょうど\n"
.stringn "持ち合わせが無くて……\n"
.stringn "かといって今あるかと言えば\n"
.stringn "ないんですけど……\n"
.stringn "どうか、もうしばらく\n"
.stringn "返済の方はお待ちを……\n"
.stringn "\x0701返済…\n"
.stringn "なんのことだ？\n"
.stringn "\x0714あれ……？\n"
.stringn "もしかして…\n"
.stringn "借金取りの方じゃないんですか？\n"
.stringn "\x0701……俺が借金取りか。\n"
.stringn "\x0714ち、違うんですか？\n"
.stringn "\x0701なった覚えはないな。\n"
.stringn "\x0714なんだ、ビビって損した～。\n"
.stringn "そんな、いかにもって顔してるから、\n"
.stringn "もうてっきりそうだとばっかり。\n"
.stringn "\x0701…ほぅ　俺はいかにも\n"
.stringn "借金取りしそうな顔なのか。\n"
.stringn "\x0714あ、いやいや！\n"
.stringn "それは言葉のあやですって。\n"
.stringn "ほんと、かんちがいしちゃって\n"
.stringn "失礼しました～。\n"
.stringn "\x0701………\n"
.stringn "さて、ひと寝入りするか。"
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_B

//0x12D08
Text_12CE8:
.stringn "\x05FL|HAAR|MAKAROV||\x070-\x0703………\n"
.stringn "\x0711！！\n"
.stringn "\x0703……ん？\n"
.stringn "\x0711あ、あわわわ……\n"
.stringn "\x0703なんだ、おまえは？\n"
.stringn "\x0711おっ　お、お…\n"
.stringn "\x0703おい、どうした……\n"
.stringn "\x0711ひ～っ！\n"
.stringn "おた、おたすけ～っ！！\n"
.stringn "\x0703………\n"
.stringn "俺をデイン兵と間違えたか？\n"
.stringn "…ま、どうでもいいが……\n"
.stringn "ふぁぁ　…………"
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_C

//0x13E5C
Text_13E3C:
.stringn "\x05FL|LAY|IKE||\x070-\x0701！\n"
.stringn "\x0713…ライ、どうした？\n"
.stringn "\x0701アイクか…\n"
.stringn "おどかすなよ。\n"
.stringn "\x0713……ここんとこ\n"
.stringn "やけに張り詰めてるな？\n"
.stringn "\x0701王都が近づいてきて…\n"
.stringn "デイン王の……\n"
.stringn "いや、奴自身というよりは\n"
.stringn "メダリオンのか？\n"
.stringn "とにかくそれが発する\n"
.stringn "【負】の気にあてられて…\n"
.stringn "全身の毛が逆立ってる。\n"
.stringn "\x0713ラグズは敏感だな。\n"
.stringn "\x0701…これに反応しない\n"
.stringn "ベオクが空恐ろしいよ。\n"
.stringn "どうして平気でいられるんだか…\n"
.stringn "この…威圧感は……\n"
.stringn "ちょっと尋常じゃない。\n"
.stringn "\x0713俺は、傍にいないほうがいいか？\n"
.stringn "\x0701そうだな…\n"
.stringn "……いや、やっぱり居てくれ。\n"
.stringn "すぐに落ち着くから……\n"
.stringn "……………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………ふぅ\n"
.stringn "…悪かったな。時間とらせて。\n"
.stringn "\x0713大丈夫か？\n"
.stringn "\x0701ああ。もう平気だ。\n"
.stringn "オレともあろうものが、\n"
.stringn "ベオクにこんな弱みを\n"
.stringn "見せちまうなんて…世も末だ。\n"
.stringn "\x0713俺を、信用できないのか？\n"
.stringn "\x0701してるさ。\n"
.stringn "…でも、全部じゃない。\n"
.stringn "オレのほとんどの部分は\n"
.stringn "おまえを認めてるが……\n"
.stringn "まだ獣牙の同胞のように\n"
.stringn "手放しってわけには…なかなかね。\n"
.stringn "\x0713俺は信用してるぞ。\n"
.stringn "\x0701……真顔でさらっと\n"
.stringn "言ってくれるね～。\n"
.stringn "ほんっと、おまえって…\n"
.stringn "\x0713俺って？\n"
.stringn "\x0701バカだな。\n"
.stringn "\x0713なんだと？\n"
.stringn "\x0701そうやって、だれかれかまわず\n"
.stringn "信用してたら…\n"
.stringn "いつか絶対に\n"
.stringn "足元をすくわれるからな！\n"
.stringn "覚えとけよ！！\n"
.stringn "\x0713こら、待てよ！　ライ！\n"
.stringn "…ったく、気安いのか\n"
.stringn "気難しいのかわからん奴だな。"
db 0
.align 4
//MYELL_8_IKE_LAY_A

//0x139C8
Text_139A8:
.stringn "\x05FL|IKE|LAY||\x0701ライ。\n"
.stringn "\x071-\x0713ん？　なんか用かい？\n"
.stringn "\x0701……もしかして訓練中か？\n"
.stringn "\x0713お、するどい！\n"
.stringn "努力家のアイク将軍殿に\n"
.stringn "置いてけぼりくわされないように、\n"
.stringn "ちょいとばかりね。\n"
.stringn "\x0701いい心構えだな。\n"
.stringn "\x0713あ～…　やだね。\n"
.stringn "嫌味も通じないのかよ、おまえ。\n"
.stringn "訓練てなあ、嘘だ。\n"
.stringn "こっちの姿でやっても意味がない。\n"
.stringn "\x0701じゃあ、なにをやってたんだ？\n"
.stringn "筋を伸ばしてたように見えたけど。\n"
.stringn "\x0713そのとおり。体を伸ばして\n"
.stringn "緊張をほぐしてただけだ。\n"
.stringn "\x0701なんだ。獣牙族の特別な\n"
.stringn "訓練術かと思って期待したのに。\n"
.stringn "\x0713期待に背いて申し訳ないが、\n"
.stringn "化身してなければ、\n"
.stringn "オレもおまえもそう変わらないんだって。\n"
.stringn "見たまんまな。\n"
.stringn "\x0701なるほど。\n"
.stringn "俺に尻尾が足りないぐらいか。\n"
.stringn "\x0713尻尾はいいぜ～。\n"
.stringn "急に身体の向きを変える時とか\n"
.stringn "高い場所を渡る時、\n"
.stringn "バランスとるのにすっげえ重宝する。\n"
.stringn "尻尾なしの人生なんて\n"
.stringn "考えられないぜ。\n"
.stringn "\x0701寝る時には邪魔そうだけどな。\n"
.stringn "\x0713ところがどっこい。\n"
.stringn "うまい方法があんのさ。\n"
.stringn "\x0701どんな？\n"
.stringn "\x0713それはだなあ……\n"
.stringn "…おっと、危ない危ない。\n"
.stringn "危うく誘導尋問に\n"
.stringn "ひっかかるところだったぜ。\n"
.stringn "\x0701尋問って、普通に聞いただけだろ。\n"
.stringn "\x0713いいか、アイク。\n"
.stringn "これはラグズの種族全体に関わる\n"
.stringn "秘密だからな。\n"
.stringn "おいそれとベオクのおまえに\n"
.stringn "ばらすわけにはいかないんだ。\n"
.stringn "\x0701そうか。\n"
.stringn "じゃあ、別にいいか。\n"
.stringn "\x0713お～い。\n"
.stringn "そこはもっと食い下がるところだぞ？"
db 0
.align 4
//MYELL_8_IKE_LAY_B

//0x13400
Text_133E0:
.stringn "\x05FL|LAY|IKE||\x070-\x0C01\x0C13\x0701よう、アイク。\n"
.stringn "この期に及んで、まだ訓練か？\n"
.stringn "\x0713俺は…　剣の鍛錬を欠かしたことはない。\n"
.stringn "どんなにわずかな時間だけでも、\n"
.stringn "必ず剣を振るうようにしている。\n"
.stringn "こうしてると、精神集中できて\n"
.stringn "落ち着くっていうのもあるしな。\n"
.stringn "\x0701なるほど。\n"
.stringn "おまえの強さには…\n"
.stringn "親父さんから受け継いだ\n"
.stringn "とびきりの才能だけじゃなく、\n"
.stringn "たゆまぬ努力の裏づけってのがあるんだな。\n"
.stringn "どうりで、見るたびに成長してるわけだ。\n"
.stringn "結構けっこう………\n"
.stringn "\x0713…………\n"
.stringn "\x0701あ、オレ…　もしかして邪魔してる？\n"
.stringn "そんじゃ……\n"
.stringn "\x0713待て。\n"
.stringn "何か用があって来たんじゃないのか？\n"
.stringn "\x0701……ちょっとばかし\n"
.stringn "余計な心配をしてるだけだ。\n"
.stringn "おまえさ、どんなに休めっていっても\n"
.stringn "休もうとしないし。\n"
.stringn "…今も、話しかければ\n"
.stringn "手を止めるかと思ったけど……\n"
.stringn "見事失敗のようだから退散するよ。\n"
.stringn "\x0713……なんだ。俺は\n"
.stringn "そんなに危なっかしいか？\n"
.stringn "\x0701それを聞くか！？\n"
.stringn "おまえみたいな強引で直線な将軍、\n"
.stringn "どこ探したって居ないって。\n"
.stringn "『めんどくさい！　突っ走る！』って\n"
.stringn "どこが作戦だよそれって、呆れるばっかりだ。\n"
.stringn "\x0713別に…　俺は俺だ。\n"
.stringn "他の誰かと同じでなくても構わんだろう。\n"
.stringn "\x0701……で、これだよ。\n"
.stringn "なに？　その脈絡のない自信は。\n"
.stringn "ベオクって、人と同じことをして\n"
.stringn "安心感を得る種族だから…\n"
.stringn "なんかぷか～って浮いてるぜ、おまえ。\n"
.stringn "\x0713悪かったな。\n"
.stringn "\x0701そいでもって、ベオクのことをこんなに\n"
.stringn "気にしちまうオレは…\n"
.stringn "ラグズじゃあ、やっぱり浮いてるわけよ。\n"
.stringn "ぷかぷか　ぷかぷか　オレは魚かっての。\n"
.stringn "\x0713……ぶっ\n"
.stringn "猫のくせに自分を魚に例えるなよ。\n"
.stringn "\x0701おっ！　笑ったな。\n"
.stringn "よ～しよし。その調子で肩の力抜いてろよ。\n"
.stringn "\x0713わかった。休憩する。\n"
.stringn "ついでに茶でも飲めばいいのか？\n"
.stringn "\x0701おう。飯と仮眠付きだと、文句なしだ。"
db 0
.align 4
//MYELL_8_IKE_LAY_C

//0x14910
Text_148F0:
.stringn "\x05FL|RETHE|IKE||\x070-\x0703来たぞ、アイク。\n"
.stringn "\x071-\x0711ああ、今日もやるか？\n"
.stringn "\x0703おまえはこのところ\n"
.stringn "めざましい成長を見せているからな。\n"
.stringn "私も負けてはおれん。\n"
.stringn "\x0711そうか？\n"
.stringn "……あんたに褒められるのは\n"
.stringn "嬉しいもんだな。\n"
.stringn "\x0703なんだ。ひょっとして……\n"
.stringn "最初に会った時のことを\n"
.stringn "根に持ってるのか？\n"
.stringn "\x0711そういうわけじゃない。\n"
.stringn "あんたは強いからな。\n"
.stringn "強いやつに褒められるのは\n"
.stringn "単純に嬉しいだけだ。\n"
.stringn "\x0703ふん……\n"
.stringn "えらく買いかぶられたものだ。\n"
.stringn "…………\n"
.stringn "なあ、アイク。\n"
.stringn "\x0711何だ？\n"
.stringn "\x0703この戦いが終わって……\n"
.stringn "すべてが終わったら……\n"
.stringn "ガリアに来ないか？\n"
.stringn "\x0711ガリアに？\n"
.stringn "\x0703ああ。ガリアで鍛錬すれば、\n"
.stringn "おまえはもっと強くなれるはずだ。\n"
.stringn "ガリアの環境は、ベオクにとっては\n"
.stringn "生きていくのも厳しい地だと聞いた。\n"
.stringn "しかし、だからこそその地で\n"
.stringn "おまえはおまえの父から受け継いだという\n"
.stringn "その剣技を……\n"
.stringn "更なる極みへ導くことができると思うんだ。\n"
.stringn "\x0711…鍛錬の相手は、当然\n"
.stringn "レテがやってくれるんだよな？\n"
.stringn "\x0703お、おまえが…\n"
.stringn "それでいいなら…私に異論はない。\n"
.stringn "\x0711なら、ガリア暮らしも悪くない。\n"
.stringn "\x0703よし、じゃあ約束だ。\n"
.stringn "いつでもおまえの気の向いたときで構わない。\n"
.stringn "私はその時を楽しみに待っているからな。\n"
.stringn "\x0711わかった。約束しよう。"
db 0
.align 4
//MYELL_8_IKE_LETHE_A

//0x145DC
Text_145BC:
.stringn "\x05FL|RETHE|IKE||\x0703おい。\n"
.stringn "\x0711レテか。\n"
.stringn "どうした？\n"
.stringn "\x0703先の戦い、なかなかのものだった。\n"
.stringn "思っていたよりはやるようだな。\n"
.stringn "\x0711俺のことか？\n"
.stringn "\x0703そうだ。他に誰がいる？\n"
.stringn "\x0711……意外だな。\n"
.stringn "俺はあんたたちの驚異的な力に\n"
.stringn "いつも驚いているんだが。\n"
.stringn "\x0703お互い、まったく\n"
.stringn "違う戦い方をするからな。\n"
.stringn "動きや考えが読めないのも\n"
.stringn "あるだろうが…\n"
.stringn "おまえたちは意外と素早く、\n"
.stringn "細やかに反応する。\n"
.stringn "自分の身体とは別の刃を\n"
.stringn "よくあそこまでうまく操るものだ。\n"
.stringn "鍛錬の賜物なのだろうな。\n"
.stringn "\x0711ああ。\n"
.stringn "俺たちはあんたたちのような爪も牙も\n"
.stringn "持ち合わせていないからな。\n"
.stringn "いかにして武器を\n"
.stringn "自分の身体の一部にするか……\n"
.stringn "そのためには\n"
.stringn "日々訓練を欠かす訳にはいかん。\n"
.stringn "\x0703ふん……なるほどな。\n"
.stringn "では私もおまえたちを見習って\n"
.stringn "鍛錬に励まねばならん。\n"
.stringn "この間の約束を覚えているか？\n"
.stringn "\x0711もちろん。\n"
.stringn "頼めるか？\n"
.stringn "\x0703こちらこそ頼もう。\n"
.stringn "お互い、手を抜くのは無しだ。\n"
.stringn "いいな？\n"
.stringn "\x0711わかった。\n"
.stringn "……行くぞ！"
db 0
.align 4
//MYELL_8_IKE_LETHE_B

//0x142D8
Text_142B8:
.stringn "\x05FL|IKE|RETHE||\x0701よし……このくらいか……\n"
.stringn "……ん？\n"
.stringn "\x0713熱心に鍛えているようだな。\n"
.stringn "\x0701レテか。見てたのか？\n"
.stringn "\x0713ああ、興味があった。\n"
.stringn "今後ベオクの戦い方を\n"
.stringn "どれだけ知っているかが\n"
.stringn "勝敗を分けるだろうからな。\n"
.stringn "貴様らに遅れを取るわけにはいかん。\n"
.stringn "\x0701それで、俺を研究か？\n"
.stringn "\x0713安心しろ、戦いに紛れて\n"
.stringn "おまえの寝首を掻こうとは思っていない。\n"
.stringn "そんなことには何の意味もないし、\n"
.stringn "そんな姑息で卑怯な手段を使うのは\n"
.stringn "ベオクくらいのものだ。\n"
.stringn "\x0701そうか。\n"
.stringn "ラグズは正々堂々と正面から\n"
.stringn "戦うのが普通なのか？\n"
.stringn "\x0713……大抵はな。\n"
.stringn "すべてがそうとは言い切れないが。\n"
.stringn "まあ、どんな小細工をしようと\n"
.stringn "我々には匂いでわかる。\n"
.stringn "闇に潜もうとも無駄な話だ。\n"
.stringn "……鼻を潰されれば話は別だがな。\n"
.stringn "\x0701レテ。\n"
.stringn "また次の機会でいい、\n"
.stringn "獣牙族の戦い方を教えてくれないか？\n"
.stringn "\x0713そういうことなら請け負おう。\n"
.stringn "全力で相手してやる。\n"
.stringn "\x0701ああ、頼む。"
db 0
.align 4
//MYELL_8_IKE_LETHE_C

//0x15530
Text_15510:
.stringn "\x05FL|OSCAR|IKE||\x0701アイク。\n"
.stringn "\x0713オスカー？\n"
.stringn "……どうした？\n"
.stringn "\x0701…………\n"
.stringn "大丈夫かい？\n"
.stringn "\x0713ああ……問題ないつもりだが。\n"
.stringn "不安にさせたか？\n"
.stringn "\x0701いや、違うんだ。\n"
.stringn "その…どんどん戦いが激しくなって…\n"
.stringn "少し前まではこんな大きな出来事に\n"
.stringn "私たちが巻き込まれることになるとは\n"
.stringn "思ってもいなかったから。\n"
.stringn "\x0713そうだな……\n"
.stringn "親父が死んでからこっち……\n"
.stringn "怒涛の展開って感じだ。\n"
.stringn "正直、息つく暇もない。\n"
.stringn "\x0701だから……平気かい？\n"
.stringn "いや、平気な訳ないんだろうが……\n"
.stringn "私に……何かできることはないか？\n"
.stringn "\x0713……ありがとう。\n"
.stringn "あんたにはずっと面倒や\n"
.stringn "苦労ばかりかけてる気がする。\n"
.stringn "こんな頼りない団長に\n"
.stringn "今まで付いてきてくれただけで\n"
.stringn "もう充分だ。\n"
.stringn "\x0701アイク……\n"
.stringn "\x0713これからも付いてきてくれるか？\n"
.stringn "\x0701ああ、もちろんだよ。\n"
.stringn "私は、グレイル団長も言ってたように\n"
.stringn "君のことを家族だと思ってる。\n"
.stringn "傭兵団は、私の帰る家だから。\n"
.stringn "\x0713オスカー……\n"
.stringn "そうだ、あんたの飯が食いたいな。\n"
.stringn "またミストと一緒に作ってくれるか？\n"
.stringn "\x0701よし、わかった。\n"
.stringn "今日は腕をふるうよ。期待しててくれ。"
db 0
.align 4
//MYELL_8_IKE_OSCAR_A

//0x15190
Text_15170:
.stringn "\x05FL|OSCAR|IKE||\x070-\x0703アイク。\n"
.stringn "調子はどうだい？\n"
.stringn "\x0711オスカーか。\n"
.stringn "ああ、ちょっと戦う上で\n"
.stringn "悩んでるところがあってな……\n"
.stringn "\x0703私でよければ相手になろうか。\n"
.stringn "\x0711いや、獣牙族や鳥翼族相手には\n"
.stringn "どう戦えばいいのかって\n"
.stringn "考えてたんだ。\n"
.stringn "\x0703なるほど……\n"
.stringn "それは私も思っていたよ。\n"
.stringn "本来の姿になった彼らは\n"
.stringn "我々が想定している戦いの範疇を\n"
.stringn "遥かに超える。\n"
.stringn "\x0711そうだ。\n"
.stringn "獣牙族はその爪の一撃で\n"
.stringn "岩を叩き割ることも\n"
.stringn "大地をえぐりとることも可能だ。\n"
.stringn "鳥翼族には俺たちの死角を\n"
.stringn "見つけることなどた易いだろう。\n"
.stringn "それに、空に逃げられてしまえば\n"
.stringn "俺の剣技など何の意味も成さない…\n"
.stringn "\x0703……やはり、１番いいのは\n"
.stringn "彼らに手合わせしてもらうことだろうね。\n"
.stringn "難しいことだけど……\n"
.stringn "\x0711……難しい？\n"
.stringn "そうか？\n"
.stringn "\x0703あ……\n"
.stringn "いや、うん。\n"
.stringn "……アイクは……すごいな。\n"
.stringn "\x0711？　オスカーにすごいとか\n"
.stringn "言われたくはないな。\n"
.stringn "あんたは何でもできるし、\n"
.stringn "たいがいのことは知ってる。\n"
.stringn "\x0703私のできることは、努力すれば\n"
.stringn "どうにかなるようなものだよ。\n"
.stringn "……君はやっぱり、団長の子だ。\n"
.stringn "見習いたいと、私は思うよ。\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_IKE_OSCAR_B

//0x14D24
Text_14D04:
.stringn "\x05FL|IKE|OSCAR||\x0703オスカー、\n"
.stringn "ちょっと訓練に付き合って……\n"
.stringn "？\n"
.stringn "どこかへ行くのか？\n"
.stringn "\x0711悪いね、アイク。\n"
.stringn "今日は私が食事係なんだ。\n"
.stringn "\x0703ミストは？\n"
.stringn "\x0711洗濯物がまだ終わらないらしくてね。\n"
.stringn "料理はひさしぶりにやるから、\n"
.stringn "腕が鈍ってないといいけど。\n"
.stringn "\x0703オスカーの料理は久しぶりだな。\n"
.stringn "楽しみだ。\n"
.stringn "\x0711…本当に？\n"
.stringn "\x0703ああ。なんでだ？\n"
.stringn "あんたの料理はいつも美味かった。\n"
.stringn "\x0711私の印象では…\n"
.stringn "いつも無反応なセネリオと、\n"
.stringn "元々、私の料理を食べ慣れていた\n"
.stringn "弟２人は除外するとして…\n"
.stringn "団長、ティアマト副長、アイク、\n"
.stringn "ガトリーは何を出しても完食だけど…\n"
.stringn "なんでもいいって感じだったな。\n"
.stringn "毎回、細かな味の差に気づいて\n"
.stringn "感想をくれたのは…\n"
.stringn "ミストとシノン、それから\n"
.stringn "キルロイだけだったな。\n"
.stringn "\x0703特に口にだしてなかっただけで、\n"
.stringn "ちゃんと味わってたぞ？　一応。\n"
.stringn "食事作りの担当がオスカーから\n"
.stringn "ミストに交代した日の夕食は…\n"
.stringn "今思い出しても胸が悪くなる。\n"
.stringn "さすがの親父も脂汗だしながら\n"
.stringn "食ってた気がするし。\n"
.stringn "そういや最近やっと、\n"
.stringn "ミストの料理もまともになってきたよな。\n"
.stringn "\x0711ああ、君が剣の腕を磨くように\n"
.stringn "影で一生懸命特訓してるんだよ。\n"
.stringn "おいしい、って言ってもらえることが\n"
.stringn "作ってる側には１番励みになるから\n"
.stringn "そのためにもね。\n"
.stringn "\x0703そうか……\n"
.stringn "これからはちゃんと\n"
.stringn "旨いと言うようにしよう。\n"
.stringn "\x0711はは　ありがとう。"
db 0
.align 4
//MYELL_8_IKE_OSCAR_C

//0x16288
Text_16268:
.stringn "\x05FL|IKE|RIEUSION||\x0703リュシオン。\n"
.stringn "\x0711……アイク…わかっている。\n"
.stringn "自分のことだ。\n"
.stringn "誰よりもわかっている。\n"
.stringn "………だが、どうか…\n"
.stringn "最後までは…やらせてくれ。\n"
.stringn "\x0703…………\n"
.stringn "全てが終わった途端、\n"
.stringn "命まで尽きるってのじゃなければ…\n"
.stringn "\x0711……\n"
.stringn "メダリオンの気が落ち着けば…\n"
.stringn "私の身体も元に戻るはずだ。\n"
.stringn "大丈夫、私の精神力はまだ…\n"
.stringn "少しも挫かれてはいない。\n"
.stringn "アシュナードに対峙し…\n"
.stringn "事の真相を確かめなくてはならない。\n"
.stringn "\x0703リュシオン。\n"
.stringn "俺があんたを助けよう。\n"
.stringn "\x0711私を特別扱いするなと…\n"
.stringn "\x0703だから、あんたも俺を助けてくれ。\n"
.stringn "\x0711！\n"
.stringn "\x0703俺たちがそれぞれ備える力は、\n"
.stringn "質のまったく違うものだ。\n"
.stringn "互いに助け合えば…\n"
.stringn "これからの戦いでも勝ちを掴めるだろう。\n"
.stringn "\x0711……そうだ…な。\n"
.stringn "わかった。よろしく頼む。\n"
.stringn "\x0703こっちこそ、最後まで頼むな。"
db 0
.align 4
//MYELL_8_IKE_RIEUSION_A

//0x15EA0
Text_15E80:
.stringn "\x05FL|IKE|RIEUSION||\x0703リュシオン！\n"
.stringn "\x0717ここだ、アイク。\n"
.stringn "\x0711戦いの話か？\n"
.stringn "\x0703ああ。次の作戦では\n"
.stringn "あんたの力が勝敗の要になるだろうって\n"
.stringn "話になった。体調はどうだ？\n"
.stringn "\x0711…そうだな。\n"
.stringn "空の高みまで上がれば、\n"
.stringn "多少は【負】の気から逃れられるようだ。\n"
.stringn "今も風をあびて、少し楽になった。\n"
.stringn "次の一戦ぐらいはもつだろう。\n"
.stringn "\x0703……あんたのその様子を見てると、\n"
.stringn "どうしても戦わせたくなかった\n"
.stringn "フェニキス王の気持ちがわかるな。\n"
.stringn "本当に、無理をさせてすまない。\n"
.stringn "\x0711自ら望んでここにいる私に…\n"
.stringn "それを言うのは侮辱だぞ？\n"
.stringn "\x0703……そうだったな。すまん。\n"
.stringn "あんたがこの類の気遣いを嫌がるって\n"
.stringn "ことはわかってるつもりなんだが……\n"
.stringn "\x0711…おまえでなければ、\n"
.stringn "とっくに殴って黙らせているところだ。\n"
.stringn "\x0703……サギの民は、まったく攻撃\n"
.stringn "できないんじゃなかったのか？\n"
.stringn "\x0711…………\n"
.stringn "殴るぐらいはできる。ただ…\n"
.stringn "\x0703ただ？\n"
.stringn "\x0711殴られた相手より、\n"
.stringn "殴った私の拳のほうがダメージが大きい。\n"
.stringn "\x0703具体的に言うと？\n"
.stringn "\x0711…以前、タナス公の顔面を\n"
.stringn "殴りつけた時は……\n"
.stringn "奴は鼻血をだしただけだったが、\n"
.stringn "私は手の甲の骨にひびがはいった…\n"
.stringn "\x0703…………\n"
.stringn "\x0711…………\n"
.stringn "\x0703漢だな。\n"
.stringn "\x0711ああ、まあな。"
db 0
.align 4
//MYELL_8_IKE_RIEUSION_B

//0x158B4
Text_15894:
.stringn "\x05FL|IKE|RIEUSION||\x0701リュシオン。\n"
.stringn "\x071-\x0713アイクか。どうかしたのか？\n"
.stringn "\x0701様子を見に来ただけだ。\n"
.stringn "調子はどうだ？\n"
.stringn "\x0713大丈夫だ。何も問題ない。\n"
.stringn "\x0701…問題ないっていうには\n"
.stringn "説得力のない顔色だけどな。\n"
.stringn "\x0713……私たちサギの民は【正】に近い存在。\n"
.stringn "【負】の気に満ちる戦いの場では…\n"
.stringn "体調万全というわけにはいかない。\n"
.stringn "だが、倒れる前に自ら休むよう\n"
.stringn "心がけているから…どうか最後まで\n"
.stringn "共に戦わせて欲しい。頼む。\n"
.stringn "\x0701自分で気をつけているなら、\n"
.stringn "俺に文句はないが…\n"
.stringn "精のつく食べ物とか、\n"
.stringn "少しでも助けになるものがあれば、\n"
.stringn "なんとか用意するぞ？\n"
.stringn "\x0713…その気持ちだけで十分だ。\n"
.stringn "実は私も…昔はこの軟弱な身体を\n"
.stringn "うとましく思っていて……\n"
.stringn "試したことがあるんだ。\n"
.stringn "肉、魚、酒…　ティバーンの好物を\n"
.stringn "並べて端から口に入れてみた。\n"
.stringn "\x0701…どうだった？\n"
.stringn "\x0713１０日ほど生死の境をさまよった。\n"
.stringn "どうやら私たちサギの民は\n"
.stringn "新鮮な木の実以外はうけつけない\n"
.stringn "体質らしい。\n"
.stringn "\x0701…捨て身な行為だな。\n"
.stringn "\x0713ティバーンのようになりたかった。\n"
.stringn "大きく逞しい身体、翼…\n"
.stringn "私がそれらを持っていれば、\n"
.stringn "自らベグニオンに乗り込んで\n"
.stringn "ニンゲンたちに復讐してやれるのに…\n"
.stringn "毎夜、女神に祈り…力を乞うた。\n"
.stringn "でも………叶わなかった。\n"
.stringn "\x0701…あんたの気持ちは、なんとなく\n"
.stringn "わかる気がするが……\n"
.stringn "かえって良かったんじゃないか？\n"
.stringn "\x0713どうしてだ？\n"
.stringn "\x0701戦いの気だけで体調を崩すあんたが、\n"
.stringn "直接、相手を傷つけるような\n"
.stringn "真似をしたら…ただじゃすまんだろう。\n"
.stringn "\x0713……そうだな。\n"
.stringn "絶望に心を支配されていた時には\n"
.stringn "命と引き換えにしても構わないと\n"
.stringn "真剣に考えていた。\n"
.stringn "だが…今は生きていて良かったと思える。\n"
.stringn "生きていたからこそ、リアーネに会えた。\n"
.stringn "\x0701リュシオン…あんたは、\n"
.stringn "思った以上に男らしいな。\n"
.stringn "\x0713精神力だけなら、\n"
.stringn "他にひけはとらないつもりだ。"
db 0
.align 4
//MYELL_8_IKE_RIEUSION_C

//0x170E0
Text_170C0:
.stringn "\x05FL|SENERIO|IKE||\x070-\x0C05\x0713……\n"
.stringn "\x0705……\n"
.stringn "\x0713…この間の話を聞いてから、\n"
.stringn "俺なりにない知恵を絞って考えた。\n"
.stringn "けど、わからん。\n"
.stringn "おまえが自分の存在について\n"
.stringn "何か不安をもっているんだろうって\n"
.stringn "それ以外は何もな。\n"
.stringn "だから、やっぱり話を聞くしかない。\n"
.stringn "\x0C05\x0701……どうして、\n"
.stringn "放っておいてくれないんですか？\n"
.stringn "僕には…あなたしか\n"
.stringn "頼る相手がいないのに……\n"
.stringn "あなたに嫌われたら……\n"
.stringn "もはや生きてはいけないのに……\n"
.stringn "\x0713だからだ。\n"
.stringn "おまえは俺以外の誰にも\n"
.stringn "心を開こうとしない。\n"
.stringn "だったら、俺がなんとかしてやらんと\n"
.stringn "おまえはいつまでも\n"
.stringn "苦しみを抱えたままだろうが。\n"
.stringn "\x0701………アイク…\n"
.stringn "僕は…　僕は……\n"
.stringn "\x0713俺を信じろ。\n"
.stringn "おまえがたとえ何者でも、\n"
.stringn "俺がおまえを認めてやる。\n"
.stringn "\x0701………ぅ……\n"
.stringn "………………………\n"
.stringn "…………はい……\n"
.stringn "………………\n"
.stringn "…僕は…おそらく……\n"
.stringn "【印付き】なんです。\n"
.stringn "\x0713【印付き】…\n"
.stringn "なんだ、それは？\n"
.stringn "\x0701ベオクとラグズの…混血です……\n"
.stringn "女神の定めし理を犯したために…\n"
.stringn "どちらの種族からも…\n"
.stringn "忌み嫌われる不浄の存在……\n"
.stringn "\x0713……よくわからんが、\n"
.stringn "とにかく、おまえは\n"
.stringn "ラグズの血をひいてるってことだな？\n"
.stringn "\x0701…はい。\n"
.stringn "僕の額にある模様は、その証…\n"
.stringn "ベグニオンの大神殿マナイルで……\n"
.stringn "古い書物を調べていて…知りました。\n"
.stringn "それまでは…\n"
.stringn "魔道士が、より強い魔力を得るために\n"
.stringn "行なう【精霊の護符】なのだとばかり……\n"
.stringn "賢者は、それに目をつけたと\n"
.stringn "話していましたので………\n"
.stringn "\x0713それで？\n"
.stringn "\x0701え…　それで、とは？\n"
.stringn "\x0713おまえが、ラグズの血が混じった\n"
.stringn "印なんとか…なのはわかった。\n"
.stringn "それで、それがどうしたんだ？\n"
.stringn "\x0701それがどうしたって…\n"
.stringn "不快じゃないんですか！？\n"
.stringn "自分の傍らに…こんな\n"
.stringn "何にも属さない存在がいて…！\n"
.stringn "\x0713………いや。\n"
.stringn "特になにも変わらん。\n"
.stringn "セネリオはセネリオだろう。\n"
.stringn "俺の団の有能な参謀だ。\n"
.stringn "おまえがいないと、\n"
.stringn "団はたちまち立ち行かなくなる。\n"
.stringn "\x0701…………アイク…\n"
.stringn "僕は…　だからあなたが……\n"
.stringn "\x0713ん？\n"
.stringn "\x0701ガリアです…\n"
.stringn "僕が賢者と暮らしていたのは…\n"
.stringn "ガリアにある小さな村でした。\n"
.stringn "そこには、何人かのベオクが\n"
.stringn "集まって暮らしていて……\n"
.stringn "\x0713…ガリア？\n"
.stringn "おまえ、それって…\n"
.stringn "\x0701賢者が死に……口のきけない僕は\n"
.stringn "飢えて死にかけていた……\n"
.stringn "そんな僕に\n"
.stringn "あなただけが、手を差し伸べてくれた。\n"
.stringn "だから……\n"
.stringn "あなただけが、僕にとって\n"
.stringn "特別になったんです……"
db 0
.align 4
//MYELL_8_IKE_SENERIO_A

//0x1679C
Text_1677C:
.stringn "\x05FL|SENERIO|IKE||\x0703………\n"
.stringn "\x0711セネリオ、ちょっといいか？\n"
.stringn "\x0703は、はい。\n"
.stringn "どうかしましたか、アイク？\n"
.stringn "\x0711…いいかげん、話してみないか？\n"
.stringn "どうしてそんなに\n"
.stringn "ふさぎこんでいるのか。\n"
.stringn "\x0703あ…　………\n"
.stringn "\x0711………\n"
.stringn "\x0703……あの……\n"
.stringn "……………………\n"
.stringn "…アイクは、自分が何者であるか…\n"
.stringn "悩んだことはありませんよね？\n"
.stringn "\x0711自分が何者か…？\n"
.stringn "…そうだな、特にない。\n"
.stringn "親父と母さんの子で、それに\n"
.stringn "不満を持ったこともないし。\n"
.stringn "\x0703……ご両親の存在は、大きいでしょうね。\n"
.stringn "周囲に自分の幼い頃を知る者が\n"
.stringn "存在するかどうか…\n"
.stringn "それは幼子が自我を形成していく過程では、\n"
.stringn "必要なものなんだろうと思います。\n"
.stringn "何も知らない生き物が、確固たる\n"
.stringn "１人になるには…それを肯定して\n"
.stringn "後押ししてくれる大人がいないと……\n"
.stringn "幼子は進む道がわからなくなり…\n"
.stringn "自分がいったい何であるかすら\n"
.stringn "わからなくなってしまう。\n"
.stringn "\x0711セネリオには、親の記憶がないのか？\n"
.stringn "\x0703ええ。僕を育てた女は、\n"
.stringn "少なくとも僕を生んだわけではない。\n"
.stringn "あの女の口癖は…\n"
.stringn "『どうして私が？』\n"
.stringn "『世の中は不公平だ』\n"
.stringn "『近寄らないで』…でした。\n"
.stringn "一片の愛情もなく、\n"
.stringn "なんらかの義務によって\n"
.stringn "僕の面倒をみているだけのようでした。\n"
.stringn "\x0711……\n"
.stringn "\x0703それから…４つぐらいの時、\n"
.stringn "付近に住んでいた賢者が……\n"
.stringn "僕を引き取りたいと申し出ました。\n"
.stringn "その子供には…類稀なる\n"
.stringn "魔道の才があるからと言って…\n"
.stringn "女は大喜びで賢者に僕を譲りました。\n"
.stringn "よく覚えています。\n"
.stringn "僕があの女の笑った顔を見たのは\n"
.stringn "あの時だけでした。\n"
.stringn "心の底から嬉しそうでしたよ。\n"
.stringn "やっかい払いだけでなく\n"
.stringn "僅かばかりでしたが礼金まで\n"
.stringn "手にすることができたのですから。\n"
.stringn "\x0711……\n"
.stringn "\x0703賢者は死期が近く、\n"
.stringn "自分の知識を受け継ぐ者を求めていました。\n"
.stringn "時間がないと言って、\n"
.stringn "寝食の時間をも惜しんで魔道の修行に\n"
.stringn "明け暮れさせられました。\n"
.stringn "でも…僕にとっては、\n"
.stringn "女との生活よりはるかにましでした。\n"
.stringn "自分が何者であるかを\n"
.stringn "振り返る余裕もなかったので。\n"
.stringn "２年後、賢者が死んだ時には……\n"
.stringn "僕は一通りの魔道を身につけていました。\n"
.stringn "賢者の館に食べる物がなくなったので、\n"
.stringn "外に出て町に行きました。\n"
.stringn "そして……\n"
.stringn "僕は…初めて気付きました。\n"
.stringn "自分が一言も口がきけないことに。\n"
.stringn "\x0711…セネリオ……\n"
.stringn "\x0703読み書きはできました。\n"
.stringn "相手の言葉も理解できます。\n"
.stringn "だけど…自分では何も話せない。\n"
.stringn "仕方なかったんです。\n"
.stringn "女も賢者も、僕に一方的に\n"
.stringn "言葉を投げつけはしたものの\n"
.stringn "返事を必要としなかったので……\n"
.stringn "\x0711…セネリオ！！\n"
.stringn "\x0703！\n"
.stringn "…あ…\n"
.stringn "す、すみません……\n"
.stringn "こんなくだらない話を…\n"
.stringn "\x0711くだらなくない。\n"
.stringn "それが理由でおまえは…\n"
.stringn "ふさいでいたのか？\n"
.stringn "もしかして、幼い頃、\n"
.stringn "おまえが暮らしていたのは\n"
.stringn "ベグニオンだったのか？\n"
.stringn "\x0703…違います。\n"
.stringn "……僕が言いたかったのは…\n"
.stringn "………………\n"
.stringn "いえ、もういいんです。\n"
.stringn "すみません、失礼します。\n"
.stringn "\x0711待て、セネリオ…！\n"
.stringn "…………"
db 0
.align 4
//MYELL_8_IKE_SENERIO_B

//0x1653C
Text_1651C:
.stringn "\x05FL|SENERIO|IKE||\x0C01\x0C13\x0701それで、今回の支出は…\n"
.stringn "物資も不足しがちで……\n"
.stringn "………アイク？\n"
.stringn "ちゃんと聞いていますか？\n"
.stringn "\x0713ん？\n"
.stringn "ああ、聞いてなかった。\n"
.stringn "すまん。\n"
.stringn "\x0701………\n"
.stringn "\x0713悪いが、もう１度\n"
.stringn "最初から報告してくれ。\n"
.stringn "\x0701少し、休まれてはどうですか？\n"
.stringn "ひどくお疲れのようですよ。\n"
.stringn "\x0713…わかるのか？\n"
.stringn "\x0701はい。\n"
.stringn "調子の悪い時のアイクは\n"
.stringn "眉間の皺が深くなりますから。\n"
.stringn "\x0713…妙な判断だな。\n"
.stringn "\x0701とにかく、休んで下さい。\n"
.stringn "その間のことは\n"
.stringn "僕がうまくやっておきますから。\n"
.stringn "\x0713じゃあ、そうさせてもらうか。\n"
.stringn "\x0701はい。\n"
.stringn "\x0713……他の奴にも\n"
.stringn "それぐらい愛想がよければ\n"
.stringn "いいんだが……\n"
.stringn "\x0701え、なんですか？\n"
.stringn "\x0713なんでもない。\n"
.stringn "じゃあ、頼むな。\n"
.stringn "\x0701…はい。"
db 0
.align 4
//MYELL_8_IKE_SENERIO_C

//0x17FF4
Text_17FD4:
.stringn "\x05FL|IKE|TIAMAT||\x0C01\x0C13\x0701なあ、ティアマト……\n"
.stringn "ありがとう。\n"
.stringn "\x0713な……なあに？　アイク。\n"
.stringn "あらたまって……\n"
.stringn "\x0701明日があるという保障はないからな。\n"
.stringn "思ったときに伝えておきたい。\n"
.stringn "……聞いてくれるか？\n"
.stringn "\x0713え、ええ……いいけど……\n"
.stringn "いきなりどうしたの？\n"
.stringn "私、あなたに感謝されるようなこと\n"
.stringn "したかしら……？\n"
.stringn "\x0701ああ。\n"
.stringn "あんたは……ガリアで母さんを失い、\n"
.stringn "幼い俺とミストを抱えた親父を\n"
.stringn "助け、傭兵団を築いてくれた。\n"
.stringn "そのことに……礼を言いたい。\n"
.stringn "\x0713…………\n"
.stringn "\x0701今まで、何も知らずに来てすまん。\n"
.stringn "あんたが守ってくれたからこそ\n"
.stringn "存在するものを、当たり前のように\n"
.stringn "享受していた。\n"
.stringn "\x0713……違うわ、アイク。\n"
.stringn "私は私自身のために……\n"
.stringn "\x0701わかってる。\n"
.stringn "親父を……愛してたんだろう？\n"
.stringn "\x0713……！！\n"
.stringn "\x0701もしも、そうじゃなくて\n"
.stringn "もっと違った思惑があったとしても\n"
.stringn "今、こうして俺は生きてるんだ。\n"
.stringn "その事実に\n"
.stringn "感謝する気持ちに変わりはない。\n"
.stringn "親父だって、あんたの手がなければ\n"
.stringn "ひょっとしたら俺たちと一緒に\n"
.stringn "死んでいたかも知れん。\n"
.stringn "その命を、あの時、あそこで\n"
.stringn "漆黒の騎士に倒されるまで……\n"
.stringn "支えてくれたんだ。\n"
.stringn "………本当に、ありがとう。\n"
.stringn "\x0713……　……　……\n"
.stringn "う、う………っ…\n"
.stringn "\x0701親父と違って、俺にはまだ経験も力も\n"
.stringn "ないが……よければこれからも\n"
.stringn "俺たちを導き、支えてくれ。\n"
.stringn "……頼む。\n"
.stringn "\x0713ええ……\n"
.stringn "ええ、もちろんよ……アイク……"
db 0
.align 4
//MYELL_8_IKE_TIAMAT_A

//0x17B5C
Text_17B3C:
.stringn "\x05FL|IKE|TIAMAT||\x0703ティアマト。いいか？\n"
.stringn "\x0711アイク？\n"
.stringn "何か私に用かしら。\n"
.stringn "\x0703忘れたのか？\n"
.stringn "この間、話してただろう。\n"
.stringn "あんたと親父は\n"
.stringn "いつから知り合ったんだって。\n"
.stringn "\x0711あ、ああ……\n"
.stringn "そういえば、そうだったわね……\n"
.stringn "\x0703……嫌そうだな。\n"
.stringn "なら無理強いはしないが……\n"
.stringn "\x0711嫌、というか……\n"
.stringn "自分の過去を話すのが苦手なだけよ。\n"
.stringn "……でも……\n"
.stringn "あの人のこと、少しでもたくさん\n"
.stringn "あなたに知っていて欲しいものね……\n"
.stringn "わかったわ。\n"
.stringn "\x0703ああ、頼む。\n"
.stringn "\x0711私がまだクリミア騎士だった頃……\n"
.stringn "クリミアとガリアの交換武官に志願し、\n"
.stringn "そのガリアでの滞在中に出会ったわ。\n"
.stringn "王宮で開かれた合同闘技で\n"
.stringn "あの人の強さを目の当たりにしたの。\n"
.stringn "襲い来る幾人もの強豪を、まるで\n"
.stringn "小さな子供をあしらうかのように倒していった。\n"
.stringn "相手は一体どうして自分が倒されているのかも\n"
.stringn "分からないほど……鮮やかな剣技だった。\n"
.stringn "一騎当千とはこのことを言うのかと……\n"
.stringn "身体が震えたわ。\n"
.stringn "\x0703…………\n"
.stringn "\x0711私も剣を交えたのだけれど……\n"
.stringn "到底敵うことはできなくて。\n"
.stringn "けれど、その後も時間の許す限り\n"
.stringn "相手してもらったわ。\n"
.stringn "それで、親しくなって……\n"
.stringn "あの人の家に招かれたとき、\n"
.stringn "あなたは居たわね。\n"
.stringn "\x0703俺が？\n"
.stringn "\x0711ええ。微笑んだエルナに抱かれて\n"
.stringn "眠っていたけど……かわいかったわ。\n"
.stringn "あの人もあなたを見るときの目は\n"
.stringn "とても優しくて……\n"
.stringn "剣を構えている時の彼とは別人だった。\n"
.stringn "\x0703…………そうか……"
db 0
.align 4
//MYELL_8_IKE_TIAMAT_B

//0x1787C
Text_1785C:
.stringn "\x05FL|TIAMAT|IKE||\x070-\x0701あら、アイク。\n"
.stringn "あなたも訓練？\n"
.stringn "\x0713ティアマトもか。\n"
.stringn "なら、相手を頼めるか？\n"
.stringn "あんた相手だと学ぶことが多くていい。\n"
.stringn "\x0701そう？　よかった。\n"
.stringn "もうあなたに私の指導は\n"
.stringn "必要ないかと思ってたから。\n"
.stringn "\x0713何言ってるんだ。\n"
.stringn "親父から受け継いだ剣技が\n"
.stringn "本物になるように仕上げてくれたのは\n"
.stringn "あんただと俺は思ってる。\n"
.stringn "\x0701ふふ　そう言ってもらえると光栄だわ。\n"
.stringn "……ねえ、アイク。\n"
.stringn "\x0713何だ？\n"
.stringn "\x0701あなたがグレイル団長から\n"
.stringn "継いだ剣技は……\n"
.stringn "この世で唯一のものよ。\n"
.stringn "大事にしてちょうだい。\n"
.stringn "\x0713…………\n"
.stringn "なあ、ティアマト。\n"
.stringn "ふと思ったんだが……\n"
.stringn "あんたはいつから親父と一緒だったんだ？\n"
.stringn "クリミア騎士だったんだよな、ティアマトは。\n"
.stringn "\x0701……そうよ。\n"
.stringn "でもその話はまた次の機会に話すわね。\n"
.stringn "構えてちょうだい。\n"
.stringn "今は次の戦いのことだけに専念しましょう。\n"
.stringn "\x0713……わかった。"
db 0
.align 4
//MYELL_8_IKE_TIAMAT_C

//0x18C40
Text_18C20:
.stringn "\x05FL|JANAFF|LUCHINO||\x0C01\x071-\x0713ベオクであろうと\n"
.stringn "ラグズであろうと区別のない、\n"
.stringn "国や種族を超えた友好……\n"
.stringn "我々クリミアの理想は、\n"
.stringn "すべての人々の平和なのです。\n"
.stringn "\x0701種族を越えた……か。\n"
.stringn "クリミアってのは変わった国だよな。\n"
.stringn "ラグズを自分たちの国の中に\n"
.stringn "住まわせたりしてるんだろ？\n"
.stringn "\x0713ええ、カイネギス王との\n"
.stringn "同盟によるものです。\n"
.stringn "エリンシア姫は、いずれは\n"
.stringn "ガリアだけではなく、他の\n"
.stringn "ラグズの国々ともそういった関係を…\n"
.stringn "\x0701……いい話だと思うぜ。\n"
.stringn "けど、種族や国を\n"
.stringn "越えた友好なんて、\n"
.stringn "そううまくいくもんかな？\n"
.stringn "\x0713……と仰られますと？\n"
.stringn "\x0701たとえば、だ。\n"
.stringn "おれたちフェニキスと\n"
.stringn "ベグニオンが対立してたのは\n"
.stringn "もちろん知ってるよな？\n"
.stringn "\x0713ええ……\n"
.stringn "\x0701神使からセリノスへの詫びは受け取ったが\n"
.stringn "だからといってその事実は\n"
.stringn "国全体にはなかなか浸透しないだろう。\n"
.stringn "いつ、何のはずみで再び対立し、\n"
.stringn "戦が起こるとも限らない。\n"
.stringn "そうなったら、あんたはどっちにつく？\n"
.stringn "\x0713それは……\n"
.stringn "\x0701ベグニオンだ。違うか？\n"
.stringn "おれたちフェニキスからみれば、\n"
.stringn "クリミアはベグニオンの属国、\n"
.stringn "ベグニオンの手下ってところだ。\n"
.stringn "となれば、おれはあんたを相手に\n"
.stringn "戦うことになる。\n"
.stringn "\x0713……エリンシア姫は決して\n"
.stringn "そのようなことは望まれません。\n"
.stringn "あらゆる手を尽くして\n"
.stringn "戦争を回避しようとなさるでしょう。\n"
.stringn "……ですが、私はエリンシア姫の臣。\n"
.stringn "万一戦わねばならないとしたら……\n"
.stringn "その時は、迷いません。\n"
.stringn "\x0701おれも同じだ。\n"
.stringn "王の味方はおれの味方。\n"
.stringn "王の敵はおれの敵だ。\n"
.stringn "けどできれば、\n"
.stringn "あんたとは戦いたくないもんだよ。\n"
.stringn "あんたみたいないい女とは、戦うより\n"
.stringn "呑みながら話し合いたいもんだ。\n"
.stringn "\x0713ええ……私も同感です。\n"
.stringn "この戦いが終わり、\n"
.stringn "クリミアが再興を果たした後……\n"
.stringn "またお会いしましょう。\n"
.stringn "敵ではなく、友として。\n"
.stringn "\x0701その頃にはあんたも酒が呑めるように\n"
.stringn "なっててくれよ。頼むぜ？\n"
.stringn "\x0713は……はあ……\n"
.stringn "…………？"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_A

//0x187F4
Text_187D4:
.stringn "\x05FL|JANAFF|LUCHINO||\x070-\x0C01\x071-\x0C13\x0701おれたちのフェニキスは南海にある。\n"
.stringn "あったかくて住みやすいところだ。\n"
.stringn "人口は少ないけど\n"
.stringn "おれたちは同族で争い合ったりはしない。\n"
.stringn "おれはこの目でいろんな国を見てきたが、\n"
.stringn "間違いなく世界一の国だぜ。\n"
.stringn "\x0713他国との国交は\n"
.stringn "もっておられたのですか？\n"
.stringn "\x0701いや、おれたちは他と交わらない。\n"
.stringn "親交をもってたセリノスは\n"
.stringn "ベオクどもに滅ぼされちまったし……\n"
.stringn "あのネサラ王のいるキルヴァスは\n"
.stringn "信用ならねえからな。\n"
.stringn "\x0713ベオクの国々とはどうだったのですか？\n"
.stringn "\x0701それこそ、ありえない話だ。\n"
.stringn "セリノスの虐殺で、おれたちにとって\n"
.stringn "ベオクは敵だったからな。\n"
.stringn "\x0713そうですか……\n"
.stringn "しかし前にも言いましたが、我々クリミアは\n"
.stringn "あなた方との国交を望んでいます。\n"
.stringn "亡き陛下はラグズとの友好を唱えられ、\n"
.stringn "ガリアのカイネギス王とも\n"
.stringn "親密な関係にありました。\n"
.stringn "\x0701ああ、らしいな。\n"
.stringn "おれたちフェニキスは\n"
.stringn "よそと手を組まなくたってやってけるが…\n"
.stringn "けど、おれたちの王が\n"
.stringn "そう決断なされば、\n"
.stringn "クリミアとの友好もありうるだろう。\n"
.stringn "\x0713あなた自身はどうお考えですか？\n"
.stringn "\x0701おれは……そうだな。\n"
.stringn "前はベオクってだけで\n"
.stringn "嫌いだったもんだが……\n"
.stringn "今は友好ってのも悪くないと思ってる。\n"
.stringn "それもこれも……\n"
.stringn "あんたと出会ったおかげさ……\n"
.stringn "\x0713は……はぁ……\n"
.stringn "恐縮です…………"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_B

//0x18478
Text_18458:
.stringn "\x05FL|JANAFF|LUCHINO||\x0C01\x0713フェニキスの騎士殿ですね。\n"
.stringn "\x0701ん？\n"
.stringn "\x0713初めてお目にかかります。\n"
.stringn "私はクリミア王国のルキノ、\n"
.stringn "エリンシア姫の臣です。\n"
.stringn "この度の貴国のご助力、\n"
.stringn "心より感謝いたします。\n"
.stringn "\x0701へえ……\n"
.stringn "\x0713？\n"
.stringn "\x0701いやいや、ご丁寧にどーも。\n"
.stringn "おれはヤナフ。\n"
.stringn "我らの王の命令でここにいる。\n"
.stringn "だから感謝なら\n"
.stringn "おれじゃなくて王にしてくれよ。\n"
.stringn "\x0713ええ。\n"
.stringn "できることなら直接お目通りの上\n"
.stringn "お伝えしたいと思いますが……\n"
.stringn "この状況下では叶いませんので。\n"
.stringn "ティバーン王には\n"
.stringn "どうかよろしくお伝えください。\n"
.stringn "\x0701……ふーん。\n"
.stringn "\x0713な、何か？\n"
.stringn "\x0701いやさ、あんたとは今後も\n"
.stringn "この軍で一緒に戦うんだよな？\n"
.stringn "なあ、友好の意味を兼ねて\n"
.stringn "１度、酒でも飲まないか？\n"
.stringn "\x0713いえ、それはいけません。\n"
.stringn "あなた方の習慣はわかりませんが……\n"
.stringn "我々の国では、まだお酒に興味を\n"
.stringn "もっていい年ではありませんので……\n"
.stringn "\x0701ふーん……\n"
.stringn "ま、そういうことなら仕方ないか。\n"
.stringn "しかしあんた、見た目はいい女なのに\n"
.stringn "年はまだ子供なのか？\n"
.stringn "ベオクの年ってのはわからないもんだな。\n"
.stringn "\x0713……？"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_C

//0x1973C
Text_1971C:
.stringn "\x05FL|OSCAR|JANAFF||\x0703あの……\n"
.stringn "\x0711ん？\n"
.stringn "…ふん、またおまえか。\n"
.stringn "\x0703先日は本当に\n"
.stringn "申し訳ありませんでした。\n"
.stringn "あなた方鳥翼族に対する\n"
.stringn "私の不勉強をどうかお許しください。\n"
.stringn "\x0711……ほう。\n"
.stringn "まあ……わかればいいんだ。\n"
.stringn "ところで、おまえはいくつなんだ？\n"
.stringn "ベオクの年はよくわからん。\n"
.stringn "\x0703私は２４になります。\n"
.stringn "\x0711２４！？\n"
.stringn "２４って……おいおい、\n"
.stringn "まだ羽根も生えそろわない\n"
.stringn "子供じゃないか！\n"
.stringn "ベオクは赤子も戦場に出すのか！？\n"
.stringn "まったく…血も涙もない奴らだ。\n"
.stringn "\x0703は…はあ……\n"
.stringn "\x0711……小僧、おまえの名は？\n"
.stringn "\x0703オ、オスカーです。\n"
.stringn "\x0711おれはヤナフだ。\n"
.stringn "……ったく、道理で失礼なことを\n"
.stringn "抜かすと思ったぜ……\n"
.stringn "子供ならそれも仕方ないか。\n"
.stringn "\x0703………………\n"
.stringn "\x0711ま、物を知らん子供が\n"
.stringn "飛べるようになるまで導いてやるのが\n"
.stringn "年長者の義務というもんだ。\n"
.stringn "これまでの無礼は許してやるよ。\n"
.stringn "何かあればおれを頼れ。\n"
.stringn "わかったな？\n"
.stringn "\x0703は……はい。\n"
.stringn "ありがとうございます。"
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_A

//0x19404
Text_193E4:
.stringn "\x05FL|OSCAR|JANAFF||\x070-\x0703やあ、君。\n"
.stringn "\x0711ん？\n"
.stringn "\x0703また会ったな。\n"
.stringn "この間は、すまなかった。\n"
.stringn "私は君たちと話した経験が\n"
.stringn "あまりなかったものだから……\n"
.stringn "そうだ。何かこの軍の中で\n"
.stringn "わからないことはあるかい？\n"
.stringn "\x0711いや、特にない。\n"
.stringn "なんだいきなり？\n"
.stringn "\x0703私にもちょうど君くらいの弟がいるんだ。\n"
.stringn "だから、なんだか放っておけなくてね。\n"
.stringn "しかし、君たちラグズはすごいな。\n"
.stringn "君のように、まだ幼い子供まで\n"
.stringn "優れた戦士で……\n"
.stringn "\x0711おい、ちょっと待て……\n"
.stringn "子供……子供だと！？\n"
.stringn "\x0703ど、どうかしたのか？\n"
.stringn "\x0711いいか、よく聞け！\n"
.stringn "おれは断じてガキじゃない！\n"
.stringn "もう１００年以上は生きてる！\n"
.stringn "\x0703え？\n"
.stringn "１００年……？\n"
.stringn "\x0711おまえがいくつかは知らんが\n"
.stringn "このおれの顔を見て\n"
.stringn "子供呼ばわりされるのは我慢ならん！\n"
.stringn "２度と間違えるな！\n"
.stringn "わかったな！\n"
.stringn "\x0703あ、君……！\n"
.stringn "\x0C11\x0C03しまった……\n"
.stringn "ひどく怒らせてしまったようだ……\n"
.stringn "見た目で判断してはいけないということか。\n"
.stringn "また日を改めて詫びに行かなくてはな……"
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_B

//0x19270
Text_19250:
.stringn "\x05FL|OSCAR|JANAFF||\x0701君は……\n"
.stringn "\x0713ん？\n"
.stringn "\x0701やあ。\n"
.stringn "………………\n"
.stringn "\x0713？\n"
.stringn "おれに何か用か？\n"
.stringn "\x0701いや、特に用があるわけでは\n"
.stringn "ないんだが……\n"
.stringn "\x0713なんだ？　妙な奴だな。\n"
.stringn "用はないんだな？\n"
.stringn "じゃあ、行くぞ。\n"
.stringn "……ベオクはよくわからんな。\n"
.stringn "\x0701まいったな……\n"
.stringn "どう接すればいいんだろう……\n"
.stringn "これまで鳥翼族と関わったことなど\n"
.stringn "なかったからな……\n"
.stringn "だが、仲間同士、\n"
.stringn "交流をもたないのは不自然だし…\n"
.stringn "次はもう少し、ちゃんと話をしよう……"
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_C

//0x1A79C
Text_1A77C:
.stringn "\x05FL|RETHE|JILL||\x0701……\n"
.stringn "\x0713！　レテ…\n"
.stringn "\x0701……なぜだ？\n"
.stringn "ダルレカで戦った竜騎士は……\n"
.stringn "おまえの父親だったそうだな。\n"
.stringn "…どうして、そこまでして\n"
.stringn "こちら側に残る決意をしたんだ？\n"
.stringn "\x0713………\n"
.stringn "運命というのは、不思議なものだ。\n"
.stringn "もし、この軍を…\n"
.stringn "アイク殿や傭兵団…\n"
.stringn "そして何より……\n"
.stringn "レテたちラグズを知らなければ……\n"
.stringn "私は今もきっとデイン軍にいた。\n"
.stringn "デイン王国軍人としての誇りに燃え、\n"
.stringn "アシュナードのために\n"
.stringn "喜んで命を捧げたことだろう。\n"
.stringn "おまえたちを倒すことに\n"
.stringn "ためらいはしなかったろう。\n"
.stringn "……でも、知ってしまった。\n"
.stringn "\x0701……\n"
.stringn "\x0713手柄を得るため、港町トハから\n"
.stringn "おまえたちの船を追った時とは違う。\n"
.stringn "私は初めて…自分で考え行動した。\n"
.stringn "私にとって…\n"
.stringn "より正しいと思う道を選ぶために。\n"
.stringn "それがたとえ…実の父と\n"
.stringn "相対するものだったとしても。\n"
.stringn "もう、知らなかった頃には戻れない。\n"
.stringn "だから…私はここにいる。\n"
.stringn "\x0701………ジル。\n"
.stringn "私の手を取ってくれるか？\n"
.stringn "\x0713え…？\n"
.stringn "\x0701友愛の気持ちを示す時…\n"
.stringn "互いの手を取り合うのが\n"
.stringn "ベオクの慣わしだと聞いた。\n"
.stringn "私は、おまえの強さ…\n"
.stringn "おまえの生き方に共感する。\n"
.stringn "\x0713レテ…\n"
.stringn "あ……　うん。…もちろん。\n"
.stringn "\x0701…ベオクとラグズは\n"
.stringn "分かり合える。\n"
.stringn "互いを理解するきっかけと…\n"
.stringn "歩み寄る気持ちがあれば、きっと。"
db 0
.align 4
//MYELL_8_JILL_LETHE_A

//0x19D6C
Text_19D4C:
.stringn "\x05FL|JILL|RETHE||\x0701れ…　レテ？\n"
.stringn "\x0713…誰かと思えば、またおまえか。\n"
.stringn "\x0701私はジルだ。\n"
.stringn "おまえじゃ…ない。\n"
.stringn "\x0713では、ジル。\n"
.stringn "今日は何の用だ？\n"
.stringn "また、くだらない質問か？\n"
.stringn "\x0701…ずっと、わからなくて。\n"
.stringn "デインでは…\n"
.stringn "おまえたちは猛獣同様、\n"
.stringn "人間を無差別に襲う敵だと…\n"
.stringn "教えられてきた。\n"
.stringn "\x0713ハッ　我らがベオクを\n"
.stringn "無差別に襲う？\n"
.stringn "たとえ頼まれたとしても\n"
.stringn "関わりたくもないというのにか？\n"
.stringn "\x0701……だが、デインでは\n"
.stringn "周囲の誰もがそうだと信じていた。\n"
.stringn "だから…そうなのだろうと\n"
.stringn "疑うこともせず生きてきた……\n"
.stringn "しかし…南の海で……\n"
.stringn "アイクたち人間と共に戦う\n"
.stringn "レテの姿に…違和感を感じた。\n"
.stringn "どうして、こんなに\n"
.stringn "想像していたのと違うんだろう。\n"
.stringn "幼い頃から聞かされていた\n"
.stringn "化物のような獣ではなかった。\n"
.stringn "そして化身を解いたおまえは……\n"
.stringn "獣ではなく…むしろ、私たちに近い。\n"
.stringn "\x0713………\n"
.stringn "\x0701そもそも…\n"
.stringn "ベオクとラグズが争い始めたのは\n"
.stringn "いつだったのだろう？\n"
.stringn "何かきっかけがあったのだろうか？\n"
.stringn "\x0713…それは分からん。\n"
.stringn "元々…女神がそのように\n"
.stringn "創られたからなのか、\n"
.stringn "根本的に相容れぬものなのか。\n"
.stringn "ただ…　ゴルドアを除く\n"
.stringn "ガリア、フェニキス、キルヴァス…\n"
.stringn "これらに限って言えば\n"
.stringn "ベオクを憎む理由は明確にある。\n"
.stringn "\x0701ど、どんな理由なんだ？\n"
.stringn "\x0713……その様子では、\n"
.stringn "ベオクは子に…正確な歴史を\n"
.stringn "伝えずにいるようだな。\n"
.stringn "………ふぅ…\n"
.stringn "…いいか。ベグニオンがまだ\n"
.stringn "帝国ではなく、王国だった頃…\n"
.stringn "テリウスにはベグニオンと\n"
.stringn "ゴルドアの２国だけが存在した。\n"
.stringn "ゴルドアは今と変わらず、\n"
.stringn "竜鱗族だけの閉鎖的な国で…\n"
.stringn "他のラグズ…獣牙族、鳥翼族は\n"
.stringn "ベグニオンにおいて\n"
.stringn "ベオクと共に暮らしていたのだ。\n"
.stringn "\x0701かつてベグニオンで…\n"
.stringn "人間とラグズが共存していた…？\n"
.stringn "そ、そんな話…\n"
.stringn "聞いたこともない。\n"
.stringn "\x0713国の王には…初代こそ、\n"
.stringn "ベオクが選ばれたらしいが\n"
.stringn "その後は…力に優れるラグズが\n"
.stringn "王位に就くことが多かったという。\n"
.stringn "だが、それを不服とした元老院は\n"
.stringn "【神使】の名の下に、\n"
.stringn "ベオクこそがベグニオンの\n"
.stringn "支配者たらんと内乱を起こした。\n"
.stringn "所詮は烏合の衆と高をくくった\n"
.stringn "ラグズの王たちは…\n"
.stringn "改良を加えられ進化を果たした\n"
.stringn "武器と魔道の前に敗北を喫した。\n"
.stringn "………………\n"
.stringn "…そして…長い長い……\n"
.stringn "ラグズの奴隷時代が始まった。\n"
.stringn "\x0701……\n"
.stringn "\x0713２００年に及ぶ時を経て、\n"
.stringn "ベオクからの隷属を逃れるため\n"
.stringn "ベグニオン脱出に成功したラグズたちがいた。\n"
.stringn "獣牙族は険しい山岳を命がけで踏破し\n"
.stringn "未開の大森林地帯へ…\n"
.stringn "鳥翼族は南の島々へそれぞれ逃れた。\n"
.stringn "それが私たちラグズの王国の始まりだ。\n"
.stringn "そこから、正式に国と認められるまでには\n"
.stringn "８０年の時を要し、多くの\n"
.stringn "同胞の血が流されたのだ。\n"
.stringn "戦いの理由はある。\n"
.stringn "ベオクたちは、１度は従えさせた\n"
.stringn "奴隷が国を持ち自分達と並ぶことを許さない。\n"
.stringn "ラグズたちは、過去の屈辱を抱え\n"
.stringn "今なお、自由を求め勝ち取ろうとしている。\n"
.stringn "これがおまえたちベオクが後世に伝えず\n"
.stringn "闇に葬ろうとしている歴史の真実だ。\n"
.stringn "\x0701…………\n"
.stringn "\x0713フン　言葉もないか。\n"
.stringn "よく…考えろ。\n"
.stringn "自分のその目で見たものを…\n"
.stringn "その耳で聞いたものを考えてみろ。\n"
.stringn "それすらもできぬなら、\n"
.stringn "２度と私の前にその姿を現すな。\n"
.stringn "\x0701………………"
db 0
.align 4
//MYELL_8_JILL_LETHE_B

//0x19A5C
Text_19A3C:
.stringn "\x05FL|RETHE|JILL||\x0C01\x0713あ…\n"
.stringn "\x0701？\n"
.stringn "私になにか用か？\n"
.stringn "\x0713し、質問があるのだが\n"
.stringn "かまわないか？\n"
.stringn "\x0701…内容によるな。\n"
.stringn "\x0713…………その…\n"
.stringn "なぜ、半じゅ…いや\n"
.stringn "ラグズ…は、\n"
.stringn "戦闘に武器を使わないのか？\n"
.stringn "\x0701………\n"
.stringn "ラグズには、生来、\n"
.stringn "戦う術は体に備わっている。\n"
.stringn "武器とは、力を持たない\n"
.stringn "おまえたちベオクが…\n"
.stringn "私たちの爪や牙に対抗して\n"
.stringn "作り出したもの。\n"
.stringn "使う必要などない。\n"
.stringn "\x0713そ、そうか…\n"
.stringn "\x0701それだけか？\n"
.stringn "\x0713え…　あ、いや。\n"
.stringn "まだある。\n"
.stringn "おまえたちはどうして\n"
.stringn "私たち…その、人間を\n"
.stringn "憎むのだろうか？\n"
.stringn "\x0701……その質問なら\n"
.stringn "むしろこちらが先に\n"
.stringn "おまえの返事を聞きたい。\n"
.stringn "なぜ、ベオクはラグズを憎むのだ？\n"
.stringn "私は…それが知りたい。\n"
.stringn "\x0713それは…\n"
.stringn "半じゅ…ラグズが敵だからだ。\n"
.stringn "\x0701敵か…\n"
.stringn "だとすれば、こちらも\n"
.stringn "敵だからベオクを憎むのだとしか\n"
.stringn "答えようがないな。\n"
.stringn "……じゃあ、もう行くぞ。\n"
.stringn "これ以上、時間を無駄にしたくない。\n"
.stringn "\x0713………"
db 0
.align 4
//MYELL_8_JILL_LETHE_C

//0x1AF64
Text_1AF44:
.stringn "\x05FL|JILL|MIST||\x0C01\x0C13\x0701ミスト、少しいいかな？\n"
.stringn "\x0713あ、ジル。\n"
.stringn "\x0701…別に何か用が\n"
.stringn "あるわけじゃないんだけど…\n"
.stringn "ミストと一緒にいたいなって。\n"
.stringn "邪魔だったら言って？\n"
.stringn "\x0713ううん。\n"
.stringn "わたしもちょうど、ジルに\n"
.stringn "会いたいなって思ってたから。\n"
.stringn "来てくれてうれしい。\n"
.stringn "\x0701よかった。\n"
.stringn "\x0713へへ\n"
.stringn "\x0701………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………\n"
.stringn "\x0713……すごかったね。\n"
.stringn "\x0701…？\n"
.stringn "\x0713セリノスの森。\n"
.stringn "リュシオンさんたちの歌声が…\n"
.stringn "まばゆい光にかわって……\n"
.stringn "森が…森が息を吹き返した。\n"
.stringn "\x0701……そ…だね。\n"
.stringn "…………\n"
.stringn "\x0713ジル？\n"
.stringn "…どうして泣いてるの？\n"
.stringn "\x0701あれを見て…理解した……\n"
.stringn "ラグズは…悪なんかじゃない。\n"
.stringn "間違っていたのは…私……\n"
.stringn "……私の信じてきた…もの……\n"
.stringn "\x0713………ジル……\n"
.stringn "\x0701…父上は…なぜ…\n"
.stringn "私に偽りを……？\n"
.stringn "こんな苦しい思いをするなら…\n"
.stringn "最初から真実を知っていたかった……\n"
.stringn "まさか…　デインに都合のいい軍人に\n"
.stringn "仕立て上げるために……？\n"
.stringn "\x0713そんなことあるわけない！\n"
.stringn "\x0701！？\n"
.stringn "\x0713お父さんは、絶対…\n"
.stringn "自分の子供のこと……\n"
.stringn "そんな…道具みたいに考えないよ！\n"
.stringn "もし…嘘をついてたんなら、\n"
.stringn "きっとそれが子供のために\n"
.stringn "なると思って…それで……\n"
.stringn "\x0701ミスト…\n"
.stringn "\x0713ジルのバカっ！\n"
.stringn "いくら落ち込んでるからって\n"
.stringn "お父さんの愛情まで疑うなんて…\n"
.stringn "そんなのすっごくバカなんだから！\n"
.stringn "だって、お父さんは…\n"
.stringn "お父さんは………\n"
.stringn "\x0701ミスト…っ！\n"
.stringn "わかった…　もうわかったから…\n"
.stringn "\x0713お父さん…\n"
.stringn "お…とうさ……\n"
.stringn "………………\n"
.stringn "\x0701……………………\n"
.stringn "……ミスト…\n"
.stringn "泣かないで…………\n"
.stringn "………ミスト…？\n"
.stringn "\x0713……ん…　ごめ…ん…\n"
.stringn "\x0701……ミスト、ありがとう。\n"
.stringn "私の父のことを…\n"
.stringn "そんな風に言ってくれて\n"
.stringn "ありがとう……\n"
.stringn "\x0713…ジル…\n"
.stringn "\x0701私…本当に馬鹿だね。\n"
.stringn "あんなに…私のことを\n"
.stringn "大切に育ててくれた人を\n"
.stringn "一瞬でも疑うなんて……\n"
.stringn "どうかしてる……\n"
.stringn "……私、決めた。\n"
.stringn "自分の信じる道を選ぶ。\n"
.stringn "父上は…きっとわかってくれる。\n"
.stringn "\x0713ジル…　うん。\n"
.stringn "……うん！"
db 0
.align 4
//MYELL_8_JILL_MIST_A_a

