.stringn "来てくれてうれしい。\n"
.stringn "\x0701よかった。\n"
.stringn "\x0713へへ\n"
.stringn "\x0701………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………\n"
.stringn "\x0713……すごかったね。\n"
.stringn "\x0701…？\n"
.stringn "\x0713セリノスの森。\n"
.stringn "リュシオンさんたちの歌声が…\n"
.stringn "まばゆい光にかわって……\n"
.stringn "森が…森が息を吹き返した。\n"
.stringn "\x0701……そ…だね。\n"
.stringn "…………\n"
.stringn "\x0713ジル？\n"
.stringn "…どうして泣いてるの？\n"
.stringn "\x0701あれを見て…理解した……\n"
.stringn "ラグズは…悪なんかじゃない。\n"
.stringn "間違っていたのは…私……\n"
.stringn "……私の信じてきた…もの……\n"
.stringn "\x0713………ジル……\n"
.stringn "それが…わかったから、\n"
.stringn "ジルはここに残ってくれたんだよね。\n"
.stringn "お父さんのいるデイン軍に戻らずに…\n"
.stringn "\x0701知ってしまったら…\n"
.stringn "戻れるわけが…ない……\n"
.stringn "父上は…私に失望しただろうな……\n"
.stringn "出来の悪い…裏切り者だと……\n"
.stringn "\x0713そんなことない！\n"
.stringn "\x0701！？\n"
.stringn "\x0713お父さんは、絶対…\n"
.stringn "自分の子供のこと……\n"
.stringn "そんな風に言ったりしない！\n"
.stringn "どんなに失敗しても…\n"
.stringn "最後には笑いながら\n"
.stringn "仕方のない奴だって…許してくれる。\n"
.stringn "まして…　子供が、\n"
.stringn "自分の信じる道を選んだなら\n"
.stringn "きっと喜んでくれたよ。\n"
.stringn "だって、お父さんは…\n"
.stringn "お父さんは………\n"
.stringn "\x0701ミスト…っ！\n"
.stringn "わかった…　もうわかったから…\n"
.stringn "\x0713お父さん…\n"
.stringn "お…とうさ……\n"
.stringn "………………\n"
.stringn "\x0701……………………\n"
.stringn "……ミスト…\n"
.stringn "泣かないで…………\n"
.stringn "………ミスト…？\n"
.stringn "\x0713……ん…　ごめ…ん…\n"
.stringn "\x0701……ミスト。\n"
.stringn "私は…ミストの傍にいると……\n"
.stringn "…心が少し軽くなるよ。\n"
.stringn "\x0713ジル…\n"
.stringn "\x0701生きるのは辛いけど…\n"
.stringn "それでも、生きつづけたいって\n"
.stringn "そう思えるよ。ありがとう。\n"
.stringn "\x0713ジルぅ…　…\n"
.stringn "\x0701泣かないでってば…\n"
.stringn "もう…　しかたないなあ……"
