//0x1AD44
Text_1AD24:
.stringn "\x05FL|MIST|JILL||\x0C01\x0C13\x0701ジル、それ…\n"
.stringn "まずい？\n"
.stringn "\x0713…そんなことないけど。\n"
.stringn "どうして？\n"
.stringn "\x0701よかった。\n"
.stringn "それ、わたしが作ったの。\n"
.stringn "\x0713ミストが？\n"
.stringn "\x0701うん。それはね、\n"
.stringn "本当は病気の時に食べる\n"
.stringn "滋養のつくスープなんだ。\n"
.stringn "ジル、元気ないし食も細いから…\n"
.stringn "これならいいかなって。\n"
.stringn "\x0713…私は、ミストに気を使わせてるね。\n"
.stringn "どうしてそんなに\n"
.stringn "よくしてくれるのかな…？\n"
.stringn "私はデインの…\n"
.stringn "\x0701もう、やめようよ…それ。\n"
.stringn "\x0713え…\n"
.stringn "\x0701デイン兵だから、\n"
.stringn "いっしょにいるのが\n"
.stringn "嫌で当然…って言われても困るの。\n"
.stringn "目の前にいるジルは\n"
.stringn "全然、嫌な子じゃないし。\n"
.stringn "わたし…仲良くなりたいよ？\n"
.stringn "\x0713ミスト…"
db 0
.align 4
//MYELL_8_JILL_MIST_B

//0x1ABC8
Text_1ABA8:
.stringn "\x05FL|JILL|MIST||\x0C01\x071-\x0713あ、いた。\n"
.stringn "\x0701……ミスト、また来たのか。\n"
.stringn "\x0713うん。だってジルが、\n"
.stringn "また食事しに来ないんだもん。\n"
.stringn "\x0701デインの者が、みなと同じ場所に\n"
.stringn "行くわけにはいかないだろう。\n"
.stringn "せっかくの食事がまずくなる。\n"
.stringn "\x0713お兄ちゃんはかまわないって\n"
.stringn "言ってるけど。\n"
.stringn "\x0701……\n"
.stringn "\x0713わたしも、同じ年頃の\n"
.stringn "女の子がいてくれると嬉しいよ？\n"
.stringn "\x0701……\n"
.stringn "すまない。\n"
.stringn "\x0713そっか。じゃあしかたないね。\n"
.stringn "\x0701………"
db 0
.align 4
//MYELL_8_JILL_MIST_C

//0x1C2E4
Text_1C2C4:
.stringn "\x05FL|KILROY|KEVIN||\x0703ケビンさん。\n"
.stringn "……また訓練中ですか？\n"
.stringn "\x071-\x0711おお、キルロイ！\n"
.stringn "この前は助かったぞ。\n"
.stringn "自分の斧が垂直に頭へと落ちた時は\n"
.stringn "さすがにどうなるかと思った。\n"
.stringn "\x0703だったらもう少し……\n"
.stringn "自分の身の安全を考えては\n"
.stringn "もらえないでしょうか……？\n"
.stringn "\x0711安全に？　はっはっは！\n"
.stringn "オレはそんな臆病者じゃないぞ！\n"
.stringn "騎士は何事も恐れん！　決してだ！\n"
.stringn "\x0703だ、だけど……\n"
.stringn "もし万が一のことがあったら、\n"
.stringn "ケビンさんの名誉にかかわりますよ？\n"
.stringn "\x0711オレの名誉？\n"
.stringn "\x0703例えば……\n"
.stringn "『騎士ケビン、訓練中に何故か大出血。\n"
.stringn "　謎の戦死を遂げる』……\n"
.stringn "そう後世の記録に載ったりしますよ。\n"
.stringn "いいんですか？\n"
.stringn "\x0711ぐう！\n"
.stringn "そ、それは確かに\n"
.stringn "いやかもしれん……\n"
.stringn "\x0703だったら約束してください。\n"
.stringn "もう危ない訓練はしないって。\n"
.stringn "\x0711くう！　仕方ないのか！？\n"
.stringn "戦場に出る前に１人で勝手に死んだとなれば\n"
.stringn "末代までの恥になってしまう。\n"
.stringn "し、しかし……\n"
.stringn "\x0703…………\n"
.stringn "ケ、ケビンさん、あなたを失ったら\n"
.stringn "僕たちが困ってしまいます！\n"
.stringn "えーと……そう、我々の軍で\n"
.stringn "最も頼りになるケビンさんがいなくては\n"
.stringn "勝利はありませんし……\n"
.stringn "\x0711……そうか…そうだな！\n"
.stringn "そのとおりだ！\n"
.stringn "我が軍の一大戦力であるオレが\n"
.stringn "無茶をするわけにはいかんな！\n"
.stringn "わかった。\n"
.stringn "今１つ動き足りんが自重しよう！\n"
.stringn "\x0703ふぅ……わかってもらえたようで\n"
.stringn "助かりました……\n"
.stringn "これからも時々見に来ますから。\n"
.stringn "くれぐれも無茶はしないでくださいよ？\n"
.stringn "\x0711ようし、わかった！"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_A

//0x1BF8C
Text_1BF6C:
.stringn "\x05FL|KILROY|KEVIN||\x070-\x0701ケビンさん、\n"
.stringn "ここにいたんですね。\n"
.stringn "\x071-\x0713おお、キルロイか！\n"
.stringn "どうかしたのか？\n"
.stringn "\x0701ケビンさんの訓練風景を\n"
.stringn "見学させてもらっていいですか？\n"
.stringn "また先日のような事故が\n"
.stringn "起こった時にも、杖を使える者が\n"
.stringn "傍についていた方がいいと思って。\n"
.stringn "\x0713ははは　心配性だなキルロイは。\n"
.stringn "だが、人に見られるというのはいい！\n"
.stringn "いつもより一層訓練にも\n"
.stringn "熱が入ろうというものだ！\n"
.stringn "むん！　せい！\n"
.stringn "\x0701あの、どうか\n"
.stringn "僕のことは気にしないで……\n"
.stringn "\x0713よし、１つ立ち回りを披露しよう。\n"
.stringn "……見ろ！　どうだオレの斧さばきは！\n"
.stringn "おまえの傭兵団の者たちには\n"
.stringn "到底真似などできんだろう！！\n"
.stringn "\x0701いえ、あの、\n"
.stringn "僕は怪我をしないようにと\n"
.stringn "見ているだけなんで……\n"
.stringn "極力張り切らないでもらう方が……\n"
.stringn "\x0713見よ、これこそ\n"
.stringn "クリミア騎士ケビンの奥義、\n"
.stringn "その名も――\n"
.stringn "……ぐお！　しまったぁ！\n"
.stringn "\x0701ちょっ……ケビンさんっ！？\n"
.stringn "……ああ……逆効果だったか……\n"
.stringn "ケビンさん、どうかそのままで。\n"
.stringn "今治しますので……\n"
.stringn "\x0718すまん……"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_B

//0x1BB8C
Text_1BB6C:
.stringn "\x05FL|KEVIN|KILROY||\x070-\x0701よお、キルロイ！\n"
.stringn "\x071-\x0713これはケビンさ……\n"
.stringn "！？\n"
.stringn "ど、どうしたんですか一体？\n"
.stringn "\x0701何がだ？\n"
.stringn "\x0713ち、血が……\n"
.stringn "側頭部から血が流れてますよ！？\n"
.stringn "\x0701ん？\n"
.stringn "おおそうか！　忘れていた。\n"
.stringn "\x0713わ、忘れて……？\n"
.stringn "と、とにかく\n"
.stringn "その場を動かないでください。\n"
.stringn "今、ライブの杖を使いますから……\n"
.stringn "\x0701平気だ、\n"
.stringn "このくらい放っておけば治る！\n"
.stringn "\x0713な、治りませんよ！\n"
.stringn "安静にしててください……\n"
.stringn "…………ふう……\n"
.stringn "これでひとまず大丈夫かな。\n"
.stringn "しかし……どうして怪我を？\n"
.stringn "\x0701いや、訓練をしていたら\n"
.stringn "つい熱が入っただけだ。\n"
.stringn "\x0713訓練？　誰かと手合わせを\n"
.stringn "していたんですか？\n"
.stringn "\x0701いや、ただの素振りだ。\n"
.stringn "\x0713い、いったいどうやったら\n"
.stringn "素振りで流血を……？\n"
.stringn "\x0701オレはクリミア騎士だからな！\n"
.stringn "よくあることだ、\n"
.stringn "気にしなくていいぞ！\n"
.stringn "\x0C13\x0C01……ん、どうしたキルロイ？\n"
.stringn "\x0713す、すみません……\n"
.stringn "ちょっと立ちくらみが……\n"
.stringn "い、いつもそんなに\n"
.stringn "過酷な訓練をしてるんですか？\n"
.stringn "\x0701もちろんだ。\n"
.stringn "オレはクリミア騎士だからな！\n"
.stringn "たとえ訓練でも、\n"
.stringn "やるからには手は抜かん！\n"
.stringn "いついかなる場所であろうとも\n"
.stringn "全力を尽くし、鍛えるのみだ！\n"
.stringn "\x0713その心意気は\n"
.stringn "大変立派だと思うんですが……\n"
.stringn "……不安だなあ……"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_C

//0x1D024
Text_1D004:
.stringn "\x05FL|MARCIA|KEVIN||\x070-\x0701ケビンさん！\n"
.stringn "\x071-\x0713む、マーシャ殿か！\n"
.stringn "\x0701ケビンさんのお馬さん、\n"
.stringn "元気になったみたいですね。\n"
.stringn "よかった。\n"
.stringn "\x0713ああ、マーシャ殿のおかげだ。\n"
.stringn "あらためて礼を……\n"
.stringn "\x0701その話はもういいですってば。\n"
.stringn "それより、これから\n"
.stringn "お出かけですか？\n"
.stringn "\x0713いや、久しぶりに\n"
.stringn "馬の身体を洗ってやろうと思ってな。\n"
.stringn "いつも苦労をかけているから\n"
.stringn "戦の合間には\n"
.stringn "できるだけいたわってやりたいのだ。\n"
.stringn "\x0701……素敵ですね。\n"
.stringn "\x0713なにがだ？\n"
.stringn "\x0701この前も思ったんですけど、\n"
.stringn "ケビンさん、馬の事にはとっても\n"
.stringn "気をつかってるように思えるから……\n"
.stringn "\x0713無論！　オレにとっては、\n"
.stringn "大事な戦友だからな。\n"
.stringn "騎士仲間には『所詮は乗り物』って\n"
.stringn "ヤツもいたが、オレはそうは思わん。\n"
.stringn "馬だけじゃない、\n"
.stringn "鎧も斧も、共に戦うものは全て\n"
.stringn "オレにとっては大切な戦友なのだ！\n"
.stringn "\x0701ご立派です。\n"
.stringn "\x0713立派か？\n"
.stringn "当たり前の話をしてるだけだがな。\n"
.stringn "\x0701当たり前なんかじゃないですよ。\n"
.stringn "他のことはしょっちゅう忘れたり\n"
.stringn "うっかりしたりしてるのに……\n"
.stringn "うふふ\n"
.stringn "\x0713そうか？\n"
.stringn "今ひとつ、ふに落ちないんだが…\n"
.stringn "\x0701ふふ"
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_A

//0x1CBCC
Text_1CBAC:
.stringn "\x05FL|KEVIN|MARCIA||\x0701マーシャ殿！\n"
.stringn "\x071-\x0713あ、ケビンさん。\n"
.stringn "…お馬の様子は、どうですか？\n"
.stringn "\x0701ああ、ずいぶん良くなった！\n"
.stringn "マーシャ殿のおかげだ。\n"
.stringn "最初、様子がおかしい時は\n"
.stringn "どうしようかと思ったが……\n"
.stringn "マーシャ殿の応急処置のおかげだ！\n"
.stringn "\x0713行軍での疲労がたまったんですよ。\n"
.stringn "これだけ長い間、転戦しているんですから\n"
.stringn "仕方がないですね。\n"
.stringn "土地の変化に慣れるまで\n"
.stringn "しばらく休ませればまた元気になりますよ。\n"
.stringn "\x0701オレはクリミア国内でしか\n"
.stringn "戦った事がなかったから\n"
.stringn "そういう知識はなかったのだ。\n"
.stringn "本当に、心底礼を言う！\n"
.stringn "\x0713やだ、やめてくださいよ！\n"
.stringn "私は傭兵になってから\n"
.stringn "あちこち飛び回ってたんで\n"
.stringn "たまたま知ってただけです。\n"
.stringn "\x0701この恩は、どんなことがあっても…\n"
.stringn "\x0713だから、やめてくださいってば。\n"
.stringn "これからの戦いでは、\n"
.stringn "ケビンさんが知っていて\n"
.stringn "私が知らない事も一杯あると思います。\n"
.stringn "その時に力になっていただければ\n"
.stringn "それで十分です。\n"
.stringn "\x0701分かった！\n"
.stringn "その時は、オレの命にかえて…\n"
.stringn "\x0713かえなくていいです！\n"
.stringn "……そういえばケビンさん、\n"
.stringn "この前私に何か用があったんじゃ\n"
.stringn "なかったんですか？\n"
.stringn "\x0701それが……相棒の不調もあったりで\n"
.stringn "すっかり忘れてしまってな……\n"
.stringn "いつか必ず思い出すとこの斧に誓いを…\n"
.stringn "\x0713誓わなくていいですってー！\n"
.stringn "もう、どうして\n"
.stringn "そういうノリになっちゃうのかな～。"
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_B

//0x1C7A0
Text_1C780:
.stringn "\x05FL|KEVIN|MARCIA||\x0703うーむ、能力向上のため\n"
.stringn "１度天馬騎士と\n"
.stringn "手合わせを願いたいのだが……\n"
.stringn "お、いたいた、マーシャ殿！\n"
.stringn "\x0711はい？\n"
.stringn "\x0703コホン、えー、１度貴公と…\n"
.stringn "と、その前に名乗らねばな。\n"
.stringn "オレの名前は……\n"
.stringn "\x0711知っています。\n"
.stringn "クリミア王国王宮騎士、\n"
.stringn "５番小隊隊長ケビンさんでしょう？\n"
.stringn "\x0703むっ、なぜオレの名を？\n"
.stringn "しかも所属まで…\n"
.stringn "実は、オレが先の戦いで\n"
.stringn "ひそかに手柄を立てていたとか？\n"
.stringn "…だが、思い当たる節はないな。\n"
.stringn "\x0711……あのー。\n"
.stringn "\x0703ひょっとして、ありえんと思うが\n"
.stringn "このオレがとてつもない失敗をした？\n"
.stringn "いや、そんな覚えもないぞ。\n"
.stringn "\x0711あのー……\n"
.stringn "\x0703それとも、オレの武勇が\n"
.stringn "他国にも響き渡った？\n"
.stringn "…いやいや、いくらなんでもそれは。\n"
.stringn "だが、ありえない話ではないな。\n"
.stringn "他の可能性としては…\n"
.stringn "\x0711あのーっ！！\n"
.stringn "\x0703な、なんだ。\n"
.stringn "驚くじゃないか！\n"
.stringn "\x0711ケビンさんの名前ならみんな知ってますよ。\n"
.stringn "だって、戦う前に、\n"
.stringn "いつも名乗ってるじゃないですか。\n"
.stringn "『われこそは、クリミア王国王宮騎士、\n"
.stringn "　５番小隊隊長ケビンなり』って。\n"
.stringn "\x0703なるほど、そういうことか！\n"
.stringn "\x0711で、ご用はなんです？\n"
.stringn "\x0703え？\n"
.stringn "\x0711私にご用が\n"
.stringn "あったんじゃないんですか？\n"
.stringn "\x0703ああ、そうだ。\n"
.stringn "ええと…　ん？　なんだったかな？\n"
.stringn "\x0711……思い出したら言ってくださいね。"
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_C

//0x1DA94
Text_1DA74:
.stringn "\x05FL|KEVIN|OSCAR||\x0701オスカー！！\n"
.stringn "\x071-\x0713やあ、また騎士団に戻れって話か？\n"
.stringn "\x0701その通り！\n"
.stringn "オレはクリミア騎士だ。\n"
.stringn "それを強く誇りに思っている！\n"
.stringn "戦場で華々しく戦功を上げ、\n"
.stringn "人々の賞賛を得て凱旋を果たし、\n"
.stringn "そして主君にお褒めの言葉を賜る。\n"
.stringn "騎士として名をあげれば\n"
.stringn "皆に広くその名を知られ、\n"
.stringn "やがては領地を賜ることもできる。\n"
.stringn "なにより、愛すべきクリミアとその民を\n"
.stringn "この手で守ることができるのだ！！\n"
.stringn "\x0713そうだな。\n"
.stringn "\x0701無法者たちの群れに紛れ、\n"
.stringn "明日をも知れぬ戦いに身を投じる\n"
.stringn "傭兵などよりずっと良いはずだ。\n"
.stringn "なのになぜだ？\n"
.stringn "オレにはどうしても解せん！\n"
.stringn "\x0713…………\n"
.stringn "\x0701貴様の実力は\n"
.stringn "オレが一番よく知っている。\n"
.stringn "何しろ永遠の好敵手だからな。\n"
.stringn "貴様が戻ると言うなら、\n"
.stringn "オレは騎士団に戻れるように\n"
.stringn "全力で推薦するぞ！\n"
.stringn "\x0713ありがとう。\n"
.stringn "でも、戻る気は本当にないんだ。\n"
.stringn "……傭兵団に入り、\n"
.stringn "いろいろな仕事をするうちに……\n"
.stringn "私は民の悲しみを目の当たりにした。\n"
.stringn "誰にも知られることなく死んでいく人々がいる。\n"
.stringn "国には救いきれない人々がいる。\n"
.stringn "だったら、それを助けるのは\n"
.stringn "自分たち野の人間だと思う。\n"
.stringn "それに、名誉などは私には不要だ。\n"
.stringn "傭兵団という私の家族が守れれば、\n"
.stringn "それで充分なんだ。\n"
.stringn "\x0701く……くそう！\n"
.stringn "貴様、なんだかまぶしいぞ！\n"
.stringn "なぜだ……またもや\n"
.stringn "貴様に負けた気がする……！\n"
.stringn "\x0713そんなことはないだろう。\n"
.stringn "きみのような騎士の身でなければ、\n"
.stringn "成し得ないことも沢山ある。\n"
.stringn "だから、お互いがんばろう。\n"
.stringn "立場は違っても、\n"
.stringn "目指す理想に変わりはないはずだ。\n"
.stringn "\x0701…………そうか。\n"
.stringn "ならば、もう言わん！！\n"
.stringn "クリミア再興が成った暁には、\n"
.stringn "オレは必ず大陸中に\n"
.stringn "鳴り響くような活躍をするぞ！\n"
.stringn "貴様がどこにいようとも、\n"
.stringn "オレの活躍が伝わるようにな！\n"
.stringn "\x0713ああ、君ならきっとできる。\n"
.stringn "この大陸のどこかで、\n"
.stringn "武運を祈ってるよ。"
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_A

//0x1D6A4
Text_1D684:
.stringn "\x05FL|KEVIN|OSCAR||\x0701オスカー！！\n"
.stringn "\x071-\x0713やあ、相変わらず元気だな。\n"
.stringn "\x0701クリミア騎士に戻れ！\n"
.stringn "\x0713そしていきなりだな。\n"
.stringn "\x0701元クリミア騎士として、\n"
.stringn "主君への忠誠心を持ったらどうだ！\n"
.stringn "今は祖国の危機なのだぞ！\n"
.stringn "クリミア騎士であった者は\n"
.stringn "すぐさまこの危機に駆けつけるべきだ！\n"
.stringn "\x0713そうだな。\n"
.stringn "今は傭兵という立場でだが、\n"
.stringn "祖国再興の役に立てて嬉しいよ。\n"
.stringn "\x0701嬉しいよ、ではない！\n"
.stringn "オレは貴様に騎士に戻れと言ってるんだ！\n"
.stringn "傭兵では、祖国への\n"
.stringn "忠誠を果たせていない！\n"
.stringn "それでいいのか！\n"
.stringn "\x0713ああ、構わない。\n"
.stringn "私はグレイル傭兵団の団員として\n"
.stringn "いつまでもアイク達と一緒に\n"
.stringn "ありたいと思ってる。\n"
.stringn "\x0701くっ……何故だ！\n"
.stringn "何が貴様をそこまで惹きつけるというのだ…\n"
.stringn "素晴らしき祖国クリミアへの\n"
.stringn "忠誠と引き換えにできるほどの\n"
.stringn "傭兵団とはいったい……！？\n"
.stringn "は！　さては高給なのか！？\n"
.stringn "そうだろう！　貴様は家族のために\n"
.stringn "金が必要だともらしていたからな！\n"
.stringn "\x0713お金だけの問題なら、そのまま\n"
.stringn "クリミア騎士団に残ったよ。\n"
.stringn "今の報酬は、あの頃の半分以下だし。\n"
.stringn "\x0701なんだと！？\n"
.stringn "目を覚ませ！\n"
.stringn "貴様、謀られているぞ！！\n"
.stringn "\x0713ないない。\n"
.stringn "\x0701ええい…！\n"
.stringn "どこまでも頑固な奴だ！\n"
.stringn "\x0713……君がな。"
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_B

//0x1D3B8
Text_1D398:
.stringn "\x05FL|OSCAR|KEVIN||\x070-\x0701やあ、ケビン。\n"
.stringn "調子はどうだ？\n"
.stringn "\x0713貴様、オスカー！\n"
.stringn "ふぬけた挨拶をするなっ！\n"
.stringn "\x0701…今日は私の何に\n"
.stringn "腹を立てているんだ？\n"
.stringn "\x0713忘れもしない、入隊２年目の時だ。\n"
.stringn "オレたちは馬術を競い合った！\n"
.stringn "オレと愛馬は素晴らしく健闘したが\n"
.stringn "ほんのわずかな差で\n"
.stringn "貴様に敗北を喫したのだ……っ！\n"
.stringn "\x0701んー…　ああ、あれか。\n"
.stringn "私の記憶の中では\n"
.stringn "それぞれの馬の距離は僅差ではなく、\n"
.stringn "３馬身は離れてるけど。\n"
.stringn "\x0713あの瞬間から\n"
.stringn "貴様とオレは永遠の好敵手と\n"
.stringn "定められたんだぞ！？\n"
.stringn "\x0701……知らなかったよ。\n"
.stringn "\x0713その貴様がなぜ！\n"
.stringn "このオレにひと言の断りも無く！\n"
.stringn "騎士団を辞めたりした！？\n"
.stringn "オレは、雪辱を果たすため\n"
.stringn "愛馬と共に訓練に没頭した…\n"
.stringn "……あまりに没頭しすぎたせいで、\n"
.stringn "貴様がいないことに気づいたのは\n"
.stringn "半年後のことだったんだぞ！\n"
.stringn "\x0701ちょっと待て、ケビン…\n"
.stringn "それは…私のせいなのか？"
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_C

//0x1E944
Text_1E924:
.stringn "\x05FL|LOFA|KILROY||\x0701キルロイさん？\n"
.stringn "\x071-\x0713ヨファ？　どうかした？\n"
.stringn "\x0701あ……\n"
.stringn "今日は具合いいみたいだね。\n"
.stringn "よかった。\n"
.stringn "\x0713……ごめんよ。\n"
.stringn "いつもヨファには心配ばかりかけて…\n"
.stringn "こんなことなら、僕は傭兵団を\n"
.stringn "出て行った方がいいのかも知れないね…\n"
.stringn "\x0701！？　ちがうよ！\n"
.stringn "そんなつもりで言ったんじゃない！\n"
.stringn "\x0713うん、わかってるよ。\n"
.stringn "でも……僕が辛いんだ。\n"
.stringn "戦うことだけでも大変なのに、\n"
.stringn "余計な心配までさせて……\n"
.stringn "アイクやティアマトさんにも迷惑かけてる。\n"
.stringn "だから…みんなとは離れたくないけど……\n"
.stringn "\x0701いやだっ！！\n"
.stringn "キルロイさんが居なくなるなんて\n"
.stringn "いやだよ！\n"
.stringn "ごめん、ぼく……\n"
.stringn "キルロイさんを責めてたんじゃない……\n"
.stringn "だって、病気はキルロイさんの\n"
.stringn "せいじゃないもん……\n"
.stringn "\x0713…………ヨファ……\n"
.stringn "\x0701……ちがうんだ。ぼくは、もっとちゃんと\n"
.stringn "ぼくのこと、頼りにしてほしかっただけなんだ。\n"
.stringn "\x0713え？\n"
.stringn "\x0701戦うのって……人を、倒す…のって\n"
.stringn "本当にこわいし、震えるんだ……\n"
.stringn "でも、ぼく、傭兵団の誰にも死んでほしくない。\n"
.stringn "前はなにもできなくて祈るしかなかったけど…\n"
.stringn "今は、戦ってみんなを守ることができる。\n"
.stringn "だから、よかった、って。\n"
.stringn "こうやってみんなと一緒にいれて、戦うように\n"
.stringn "なったのはよかったことだって……\n"
.stringn "思うようにしてて……\n"
.stringn "\x0713…………\n"
.stringn "\x0701だから、ちゃんと守りたいんだ。\n"
.stringn "キルロイさんのこと。\n"
.stringn "守るために戦ってるって思えば、\n"
.stringn "震えなくてすむんだ。\n"
.stringn "ぼく、がんばるから…強くなるから……\n"
.stringn "だから、出て行くなんて言わないでよ……\n"
.stringn "\x0713ヨファ……君は…………\n"
.stringn "……………………\n"
.stringn "強くなったね、ヨファ……\n"
.stringn "これからはなんでもちゃんと\n"
.stringn "言うようにするよ。\n"
.stringn "そして、頼りにさせてもらうから……\n"
.stringn "…………ありがとう。\n"
.stringn "\x0701……うん！"
db 0
.align 4
//MYELL_8_KILROY_LOFA_A

//0x1E570
Text_1E550:
.stringn "\x05FL|LOFA|KILROY||\x070-\x0703あ、キルロイさん！\n"
.stringn "\x071-\x0711……ん？\n"
.stringn "ヨファ、どうかしたかい？\n"
.stringn "\x0703あ……今日は具合悪いの？\n"
.stringn "\x0711そんなことないよ。\n"
.stringn "どうして？\n"
.stringn "\x0703ウソついたってだめだよ！\n"
.stringn "ぼくにはわかるもん！\n"
.stringn "キルロイさん、辛いときは\n"
.stringn "顔も手も真っ青になるじゃないか！\n"
.stringn "……手、貸して！\n"
.stringn "\x0C02\x0711あ……\n"
.stringn "\x0702ほら、すごく冷たい！\n"
.stringn "……辛いときはちゃんと言ってね、って\n"
.stringn "ぼく言ったのに……\n"
.stringn "\x0711ごめんよ、ヨファ。\n"
.stringn "でもちゃんと戦場に立てるくらいは\n"
.stringn "元気だし、大丈夫だから……\n"
.stringn "\x0C02\x0703大丈夫じゃない！\n"
.stringn "ここは戦場なんだよ？\n"
.stringn "砦の中じゃないんだ！\n"
.stringn "具合が悪いことを隠すなんて……\n"
.stringn "そんなことしてたら……\n"
.stringn "キルロイさんがいつか死んじゃうよ…\n"
.stringn "\x0711……ヨファ…………\n"
.stringn "ご、ごめん……\n"
.stringn "\x0703……………………\n"
.stringn "\x0711……本当にごめん、ヨファ。\n"
.stringn "ヨファの方が……僕よりずっと\n"
.stringn "しっかりしてるね……\n"
.stringn "\x0703…………杖で病気も……\n"
.stringn "治せたらいいのにね……\n"
.stringn "\x0711……そうだね。\n"
.stringn "治ったら……こんな心配、かけなくて\n"
.stringn "済むのにね……　……\n"
.stringn "\x0C03\x0C11\x0C03\x0704アイクさんに、お願いしてみるね。\n"
.stringn "ぼくとキルロイさんを\n"
.stringn "一緒に戦わせてくださいって。\n"
.stringn "\x0711ありがとう、ヨファ……"
db 0
.align 4
//MYELL_8_KILROY_LOFA_B

//0x1E08C
Text_1E06C:
.stringn "\x05FL|LOFA|KILROY||\x070-\x0701キルロイさん！\n"
.stringn "\x071-\x0713やあ、ヨファ。\n"
.stringn "そんなに走って…どうかした？\n"
.stringn "\x0701ううん、キルロイさんが見えたから\n"
.stringn "走ってきただけだよ。\n"
.stringn "ねえねえ、体の具合は平気？\n"
.stringn "\x0713ありがとう。今日は大丈夫だよ。\n"
.stringn "朝も軽く運動したし、\n"
.stringn "食事もちゃんとみんなと食べたしね。\n"
.stringn "\x0701そっか、よかった！\n"
.stringn "辛いときはちゃんとぼくに言ってね！\n"
.stringn "キルロイさん、傭兵団のみんなで\n"
.stringn "砦に居たときは、よく具合が\n"
.stringn "悪くなっちゃって寝込んでたのに……\n"
.stringn "ずっと戦うことになっちゃったね。\n"
.stringn "\x0713うん……でも、みんなと一緒に\n"
.stringn "いられるのはうれしいよ。\n"
.stringn "\x0701ぼくも！\n"
.stringn "ミストちゃんとキルロイさんとぼくは\n"
.stringn "留守番ばっかりしてたもん。\n"
.stringn "置いてけぼりはさみしかったし、\n"
.stringn "すごくこわかったよね……\n"
.stringn "\x0713そうだったね……\n"
.stringn "次は危険な任務だ、って\n"
.stringn "作戦室の前を\n"
.stringn "偶然通りがかった時に聞いちゃって…\n"
.stringn "３人で一生懸命\n"
.stringn "無事を祈ったこともあったね。\n"
.stringn "たった２日のことだったのに……\n"
.stringn "すごく長くて……\n"
.stringn "\x0701だから、戦うのがこわい時もあるけど…\n"
.stringn "いつも一緒にいて戦えるようになったのは\n"
.stringn "よかったのかもしれないって思うんだ。\n"
.stringn "\x0713…………難しいけど……\n"
.stringn "いいことを思うのは正しいと僕も思うよ。\n"
.stringn "悪いことの方を考えても仕方ないし。\n"
.stringn "僕もいいことばかり思うようにしてるからね。\n"
.stringn "\x0701そうだよね！\n"
.stringn "いいことを考えなくちゃ。\n"
.stringn "じゃないと、ぼく……\n"
.stringn "\x0713……ヨファ？\n"
.stringn "\x0701なんでもない！\n"
.stringn "ぼく、ミストちゃんにも用があるから……\n"
.stringn "また後でね、キルロイさん！\n"
.stringn "\x0713………………"
db 0
.align 4
//MYELL_8_KILROY_LOFA_C

//0x1FA88
Text_1FA68:
.stringn "\x05FL|KILROY|TIAMAT||\x070-\x0701ティアマトさん。\n"
.stringn "今日も少しだけですが、\n"
.stringn "訓練にお付き合いさせてもらえますか？\n"
.stringn "\x071-\x0713ええ、もちろん。\n"
.stringn "結構体力がついてきたんじゃない？\n"
.stringn "以前より心なしか顔色もいいようだし。\n"
.stringn "\x0701ええ、\n"
.stringn "ティアマトさんのおかげです。\n"
.stringn "\x0713ふふ……ならよかったわ。\n"
.stringn "……ねえ、キルロイ。\n"
.stringn "あなたはアイクのことをどう思う？\n"
.stringn "\x0701アイクですか？\n"
.stringn "戦いの技能などについては\n"
.stringn "僕にはわかりませんけど……\n"
.stringn "アイクはああ見えて\n"
.stringn "細かい心遣いができる人ですし、\n"
.stringn "何よりも揺るぎのない意思の強さと\n"
.stringn "理想を現実に導くだけの力も持っています。\n"
.stringn "グレイル傭兵団の団長として\n"
.stringn "ふさわしい人物だと思いますよ。\n"
.stringn "\x0713そうね。私もそう思うわ。\n"
.stringn "でも……彼はまだ若い。\n"
.stringn "これから体験する出来事が、\n"
.stringn "彼をどちら側へ導くか……\n"
.stringn "少し心配なの。\n"
.stringn "\x0701どうしてですか？\n"
.stringn "\x0713これから先、傭兵団が大きくなるにつれて\n"
.stringn "いろんな誘惑が増えると思うわ。\n"
.stringn "お金は儲かるけれども、どこかで誰かが\n"
.stringn "傷つき、涙を流すような……\n"
.stringn "そんな依頼も来るでしょうね。\n"
.stringn "けど、団員を養い、団を存続させるためには\n"
.stringn "儲かる仕事を選んだ方が楽に生きられる。\n"
.stringn "\x0701でも、\n"
.stringn "グレイル団長は違いましたね。\n"
.stringn "\x0713ええ……\n"
.stringn "私たちグレイル傭兵団は、\n"
.stringn "傭兵団らしくないことで有名だった。\n"
.stringn "時には無償で仕事を請けて……\n"
.stringn "人々を大勢救ってきた。\n"
.stringn "\x0701アイクも、同じですよ。\n"
.stringn "きっと、グレイル団長と\n"
.stringn "同じ理想を持っていると思います。\n"
.stringn "\x0713……そうよね、きっと……\n"
.stringn "私なんかが何も言わなくても、\n"
.stringn "私たちの戦う理由を、生きていく意味を…\n"
.stringn "アイクならきっと正しい道を選び取ってくれる。\n"
.stringn "私たちは、ただアイクを信じて\n"
.stringn "ついていけばいい……\n"
.stringn "\x0701……はい。"
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_A

//0x1F478
Text_1F458:
.stringn "\x05FL|KILROY|TIAMAT||\x070-\x0701ティアマトさん、\n"
.stringn "今日も訓練ですか？\n"
.stringn "\x071-\x0713ええ、体を動かしていないと\n"
.stringn "なんだか落ち着かなくて。\n"
.stringn "\x0701少し、ご一緒させてもらっても\n"
.stringn "いいですか？\n"
.stringn "\x0713ええ、もちろん構わないけれど。\n"
.stringn "どうしたの急に？\n"
.stringn "\x0701せめて、身を守るために\n"
.stringn "何かできることがあればな、と……\n"
.stringn "みんなの足手まといに\n"
.stringn "なるのは嫌ですから……\n"
.stringn "\x0713でも、それは仕方ないでしょ？\n"
.stringn "だってキルロイは、ここへ来るまで\n"
.stringn "戦いの経験なんてなかったろうし。\n"
.stringn "それが今では傭兵団の一員……\n"
.stringn "…………\n"
.stringn "\x0701ティアマトさん？\n"
.stringn "\x0713……本当は、私を助けない方が\n"
.stringn "キルロイは幸せだったかもしれない。\n"
.stringn "ご両親と過ごす穏やかな暮らしこそ\n"
.stringn "キルロイには似合っているのにね。\n"
.stringn "\x0701でも、両親の稼ぎだけでは\n"
.stringn "ろくに食べていけませんでしたから。\n"
.stringn "僕みたいに身体の弱い人間を\n"
.stringn "雇ってくれるような仕事なんて\n"
.stringn "あの小さな村では何もなかったんです。\n"
.stringn "両親も身体が弱いのを心配して\n"
.stringn "僕に村へ留まるよう言っていましたが……\n"
.stringn "ティアマトさんのような人のいる傭兵団なら\n"
.stringn "安心だろうと、見送ってくれたんですから。\n"
.stringn "\x0713……でも、きっと他にもっと\n"
.stringn "安全な仕事はあるかもしれないのに……\n"
.stringn "\x0701ティアマトさん。\n"
.stringn "僕はずっと、あこがれていたんですよ。\n"
.stringn "小さい頃は床に伏せることが多くて……\n"
.stringn "仲良く外で遊ぶ子供たちの声を\n"
.stringn "うらやましく聞いていました。\n"
.stringn "そんな僕をかわいがってくれた叔父が\n"
.stringn "傭兵で……いろんな土地の、いろんな話を\n"
.stringn "よく聞かせてくれました。\n"
.stringn "だから、僕はきっといつか、\n"
.stringn "傭兵になってみせるって思ってて。\n"
.stringn "\x0713そうだったの？　意外だわ。\n"
.stringn "\x0701そうなんですよ。\n"
.stringn "だから、今こうして転戦していることは…\n"
.stringn "不謹慎ですが、夢が叶ったようで\n"
.stringn "うれしいと、思うこともあるんです。\n"
.stringn "\x0713……そう。\n"
.stringn "私たちにとって、あなたの存在は本当に\n"
.stringn "大きいから……そう思ってくれてるなら\n"
.stringn "うれしいわ……"
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_B

//0x1EEE4
Text_1EEC4:
.stringn "\x05FL|TIAMAT|KILROY||\x070-\x0701キルロイ、体の具合はどう？\n"
.stringn "\x071-\x0713はい。\n"
.stringn "今日は熱もないし、\n"
.stringn "気分もいいです。\n"
.stringn "いつも気にかけてくださって\n"
.stringn "ありがとうございます。\n"
.stringn "\x0701そういえば……\n"
.stringn "あれからもう１年になるのね。\n"
.stringn "あなたとはじめて出会ったのは……\n"
.stringn "\x0713そうですね。\n"
.stringn "\x0701といっても、\n"
.stringn "私は何日も意識がなくて\n"
.stringn "よく憶えていないのだけれど。\n"
.stringn "私が任務で重傷を負って……\n"
.stringn "その頃は杖の使い手もいなくて。\n"
.stringn "その時、治療を申し出てくれたのが\n"
.stringn "偶然そこに居合わせたあなただったわね。\n"
.stringn "\x0713ちょうど薬草を摘みに出ていたから\n"
.stringn "気づきましたが……あんな林の中で\n"
.stringn "本当に危険でしたね……\n"
.stringn "\x0701ええ。相手はかなり以前から\n"
.stringn "あなたの住んでいた村近くを\n"
.stringn "縄張りにしていた山賊団で。\n"
.stringn "思った以上に手こずってしまった。\n"
.stringn "逃した１人が林に逃げ込んで……\n"
.stringn "それを私が追いかけたのが敗因だったわ。\n"
.stringn "林の中では馬の自由がきかなくて…\n"
.stringn "シノンが駆けつけてくれなかったら\n"
.stringn "どうなっていたか。\n"
.stringn "\x0713ガトリーさんもシノンさんも、僕の家に\n"
.stringn "ティアマトさんを運ぶ間、本当に\n"
.stringn "心配そうでしたよ。\n"
.stringn "\x0701あら、そうだったの？　…ふふ\n"
.stringn "それで…私の傷が癒えるまで\n"
.stringn "看病を続けてくれて……\n"
.stringn "あの時あなたが助けてくれなかったら、\n"
.stringn "私はもう２度と斧を振るうことは\n"
.stringn "できなくなっていた。\n"
.stringn "感謝しているわ、本当に。\n"
.stringn "\x0713いいえ、僕の方こそ。\n"
.stringn "こうして今、傭兵団に\n"
.stringn "雇ってもらっているおかげで\n"
.stringn "故郷の両親に仕送りができるんですから。\n"
.stringn "２人とも足腰が悪くて、僕しか\n"
.stringn "まともな働き手がいませんからね。\n"
.stringn "\x0701そうね……あの時はご両親にも\n"
.stringn "本当にお世話になったわ。\n"
.stringn "そのご恩に報いるためにも\n"
.stringn "あなたのことは私が必ず守るから。\n"
.stringn "\x0713ありがとうございます、ティアマトさん。"
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_C

//0x20648
Text_20628:
.stringn "\x05FL|VULCI|KILROY||\x0C01\x071-\x0713ウルキさん！\n"
.stringn "次の戦いが楽しみになってしまいました！\n"
.stringn "いえその、戦うことは恐ろしいし、\n"
.stringn "避けたいと思うんですけど……\n"
.stringn "ああでも、うん！\n"
.stringn "すごく役に立てると思います！\n"
.stringn "\x0701…………それは、何よりだ。\n"
.stringn "\x0713でも、ウルキさんの背中から\n"
.stringn "落ちないように気をつけないと……\n"
.stringn "あ、もう１度練習させてもらっても\n"
.stringn "いいですか？\n"
.stringn "\x0701……いや…………\n"
.stringn "戦いの前にこれ以上は\n"
.stringn "消耗できん……\n"
.stringn "\x0713そ、そうですか……\n"
.stringn "すみません……\n"
.stringn "…………ひょっとして……\n"
.stringn "化身することは\n"
.stringn "消耗するんですか……？\n"
.stringn "\x0701………………ああ。\n"
.stringn "\x0713ええ！？　そうなんですか！？\n"
.stringn "なのに何日も、しかも何度も\n"
.stringn "練習させてくださったんですか！？\n"
.stringn "\x0701………………いや。\n"
.stringn "黙っていた私も悪かった。\n"
.stringn "あんまりにもおまえが嬉しそうにするから\n"
.stringn "つい……言うきっかけを失ってな。\n"
.stringn "\x0713……ひょっとしなくても……\n"
.stringn "顔色、悪いですか？\n"
.stringn "……………………\n"
.stringn "すみません……\n"
.stringn "この話はなかったことにしましょう……\n"
.stringn "\x0701……それが、好ましいな。\n"
.stringn "今の消耗した状態で戦場に出るのは\n"
.stringn "危険かも知れん。\n"
.stringn "\x0713………………はい……\n"
.stringn "\x0701…………だが……\n"
.stringn "また、時間ができれば……\n"
.stringn "戦場でない場所で\n"
.stringn "乗せてやろう……\n"
.stringn "\x0713！！\n"
.stringn "は、はい！\n"
.stringn "ありがとうございます、ウルキさん！！"
db 0
.align 4
//MYELL_8_KILROY_VULCI_A

//0x2032C
Text_2030C:
.stringn "\x05FL|KILROY|VULCI||\x070-\x0701ウルキさん！\n"
.stringn "\x0713……キルロイか。\n"
.stringn "\x0701あの、先日ウルキさんの戦い方を\n"
.stringn "拝見していたんですけど……\n"
.stringn "くるっと空中で１回転しましたよね？\n"
.stringn "\x0713そう……だったか？\n"
.stringn "\x0701そのあとも何度も回って\n"
.stringn "素早く右へ左へ……\n"
.stringn "ホントにすごいです！\n"
.stringn "\x0713……いや…………\n"
.stringn "\x0701ああ……僕もあんなふうに\n"
.stringn "空を飛べたらなあ……\n"
.stringn "\x0713…………\n"
.stringn "\x0701天気のいい日には大空へ出かけて\n"
.stringn "高い山の上に降り立って……\n"
.stringn "下に見える町や村を眺める……\n"
.stringn "ああ……考えただけでも楽しいなあ……\n"
.stringn "\x0713……………………\n"
.stringn "おまえが……飛べたなら……\n"
.stringn "怪我人も…素早く治せるかもな…\n"
.stringn "\x0701あ、それってすごいですよね！\n"
.stringn "どんな遠くで怪我をした人でも\n"
.stringn "治療しに行けますし！\n"
.stringn "できるのならやってみたいです、それ！\n"
.stringn "\x0713……………………\n"
.stringn "…………………………\n"
.stringn "………やって……みるか？\n"
.stringn "\x0701え！？\n"
.stringn "ど、どうやって！？\n"
.stringn "僕には翼なんてありませんけど……\n"
.stringn "\x0713……………………"
db 0
.align 4
//MYELL_8_KILROY_VULCI_B

//0x20004
Text_1FFE4:
.stringn "\x05FL|VULCI|KILROY||\x0C01\x0713こ……こんにちは。\n"
.stringn "\x0701……\n"
.stringn "\x0713あ、あの……す、すみません。\n"
.stringn "怒らせるつもりはなかったんです。\n"
.stringn "ただ僕はあなたとお話を……\n"
.stringn "\x0701いや。怒ってはいない。\n"
.stringn "何か用だろうか。\n"
.stringn "\x0713そ、そうですか……よかった。\n"
.stringn "僕はキルロイです！\n"
.stringn "よ、よろしくおねがいします！\n"
.stringn "\x0701……ああ。\n"
.stringn "私はウルキ。よろしく。\n"
.stringn "\x0713あの、えっと……ウルキさんは\n"
.stringn "その翼で空を飛べるんですもんね。\n"
.stringn "タカの姿になったところも見ましたけど……\n"
.stringn "いいなあ……すごいです……\n"
.stringn "\x0701？\n"
.stringn "\x0713あ、すみません……\n"
.stringn "僕は幼い頃から病弱で、\n"
.stringn "ベッドで１日を送ることが多くって。\n"
.stringn "だから……よく窓の外を眺めて\n"
.stringn "空を飛ぶ小鳥を見ていました。\n"
.stringn "自由にどこへでも飛んでいけたら…\n"
.stringn "さぞ素晴らしいでしょうね……\n"
.stringn "\x0701……\n"
.stringn "素晴らしい……か。\n"
.stringn "そんなふうには\n"
.stringn "考えたこともなかったな。\n"
.stringn "\x0713それは、そうでしょうね。\n"
.stringn "産まれたときから飛べるんですから。\n"
.stringn "でも……いいなあ……\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_KILROY_VULCI_C

//0x211DC
Text_211BC:
.stringn "\x05FL|WAYU|KILROY||\x0701うーん……\n"
.stringn "ほんっとゴメン。\n"
.stringn "無理させちゃったみたいだね……\n"
.stringn "\x071-\x0713いや……僕も剣士には\n"
.stringn "憧れてたところがあったからね……\n"
.stringn "でも、ちょっと楽しかったよ。\n"
.stringn "\x0701でも、ここんとこずっと\n"
.stringn "微熱出てるでしょ？\n"
.stringn "そんなんで戦場に出て大丈夫なの？\n"
.stringn "\x0713慣れっこといえば慣れっこだからね。\n"
.stringn "無理はしてないつもりだし、\n"
.stringn "後衛にいるのが基本だから平気だよ。\n"
.stringn "それに、ワユさんも傍にいてくれるしね。\n"
.stringn "\x0701そりゃもう、あたし責任感じてるからさ…\n"
.stringn "いっつも『大丈夫かな～、どうかな～』って\n"
.stringn "気になっちゃって。\n"
.stringn "最近キルロイさんのことしか考えてないし。\n"
.stringn "はぁ～……\n"
.stringn "これからは占いなんて信じるのやめるよ。\n"
.stringn "\x0713いや……信じるとかでなくて\n"
.stringn "途中から意味がすりかわってた\n"
.stringn "だけのような……？\n"
.stringn "\x0701細かいことは気にしない！\n"
.stringn "……いや、でも待てよ。\n"
.stringn "白馬に乗ってやってくる\n"
.stringn "宿命のライバル……\n"
.stringn "………ひょっとして、剣士とかでなくて\n"
.stringn "騎馬兵なのかな………\n"
.stringn "\x0713……え？\n"
.stringn "\x0701キルロイさんが向いてる職業。\n"
.stringn "そっか、そうかも！\n"
.stringn "馬に乗れば行軍も楽だし、\n"
.stringn "体にもいいんじゃない？\n"
.stringn "\x0713ええ！？　う、馬！？\n"
.stringn "\x0701そうだよ！　馬に乗ったキルロイさん！\n"
.stringn "服も白いし、かなりカッコよくない！？\n"
.stringn "馬の上から杖使ったりしてさ、\n"
.stringn "そんであたしがその傍で華麗に戦うの！\n"
.stringn "\x0713ちょ、ちょっとワユさん……\n"
.stringn "\x0701ようし、それだ！\n"
.stringn "次はそれでいってみよう！\n"
.stringn "\x0713ちょっと待ってよ、ワユさん。\n"
.stringn "そもそも僕がどうとかっていうんじゃなくて\n"
.stringn "他の人が君の……\n"
.stringn "\x0701それは嫌。\n"
.stringn "\x0713嫌？\n"
.stringn "\x0701うん。もうキルロイさん以外に\n"
.stringn "考えられないのよね、あたしの運命の人！\n"
.stringn "\x0713う、運命……！？　宿命のライバルじゃ……\n"
.stringn "\x0701細かいことは気にしなーい！\n"
.stringn "じゃ、これからもよろしくね、キルロイさん！"
db 0
.align 4
//MYELL_8_KILROY_WAYU_A

//0x20DD4
Text_20DB4:
.stringn "\x05FL|KILROY|WAYU||\x070-\x0C01\x0C13\x0701ワユさん。\n"
.stringn "また訓練中かい？\n"
.stringn "\x0713あれ、キルロイさん？\n"
.stringn "また『誰か来い～』って念じてから\n"
.stringn "最初に出会っちゃったよ……\n"
.stringn "\x0701あ、例の占いか。\n"
.stringn "ごめん、すっかり忘れてて。\n"
.stringn "邪魔するつもりはなかったんだけど……\n"
.stringn "\x0713ううん。やっぱり占いなんて\n"
.stringn "当たらないのかもね～。\n"
.stringn "すんごく当たるって評判の占い師\n"
.stringn "だったのに……\n"
.stringn "…………いや、ひょっとして……\n"
.stringn "\x0701？\n"
.stringn "\x0713キルロイさん、あたしと特訓しない？\n"
.stringn "\x0701ええ！？\n"
.stringn "\x0713あーなんで気が付かなかったんだろ。\n"
.stringn "キルロイさんは剣士とか戦士の素質が\n"
.stringn "あるんだよ！\n"
.stringn "今はまだ気づいてないだけで、\n"
.stringn "キルロイさんにはすごい素質が眠ってる。\n"
.stringn "それで剣士として目覚めた後は\n"
.stringn "あたしと宿命の対決とか\n"
.stringn "しちゃうんだよ、きっと！\n"
.stringn "\x0701そ、それは無茶だよ、ワユさん。\n"
.stringn "そりゃ、僕だって小さい頃は\n"
.stringn "身体が弱かったから……\n"
.stringn "強い傭兵になりたいなって\n"
.stringn "思ったこともあったけど……\n"
.stringn "\x0713ほら！　やっぱり！\n"
.stringn "身体が弱いからって諦めちゃったから\n"
.stringn "いけないんだよ～もったいない！\n"
.stringn "ほらほら、１回だまされたと思って\n"
.stringn "やってみてよ。\n"
.stringn "ちゃんと基本から教えてあげるしさ！\n"
.stringn "\x0701そ、そうなのかなあ……？\n"
.stringn "\x0713細かいことは気にしない！\n"
.stringn "んじゃ、やってみよ～う！"
db 0
.align 4
//MYELL_8_KILROY_WAYU_B

//0x20A78
Text_20A58:
.stringn "\x05FL|WAYU|KILROY||\x070-\x0C01\x0C13\x0701あ……キルロイさん！\n"
.stringn "はい、これ！\n"
.stringn "\x0713これは……剣？\n"
.stringn "\x0701そう！　しかしまさか\n"
.stringn "キルロイさんだったとはね～。\n"
.stringn "ってわけで、いざ勝負！\n"
.stringn "\x0713ど、どういうことか\n"
.stringn "よくわからないんだけど……\n"
.stringn "それに、僕は武器が扱えなくって。\n"
.stringn "\x0701ええ！？\n"
.stringn "けど、ちょっとくらい\n"
.stringn "できるでしょ？\n"
.stringn "\x0713いや、今まで握ったこともなかったし…\n"
.stringn "これを構えて立っているだけでいいなら\n"
.stringn "そうするけど。\n"
.stringn "\x0701なんだ、がっかり。\n"
.stringn "この前、占いで見てもらったらね、\n"
.stringn "もうじきあたし、\n"
.stringn "運命の相手に出会うって言われたの。\n"
.stringn "白馬に乗ってやってくる\n"
.stringn "あたしの宿命のライバル……\n"
.stringn "期待してたのになあ。\n"
.stringn "\x0713それは悪かったね。\n"
.stringn "ごめんごめん。\n"
.stringn "\x0701いや、キルロイさんは\n"
.stringn "べつに悪くないんだけど。\n"
.stringn "でもちょうど『誰か来い～』って\n"
.stringn "思ってたところに来たからさ、\n"
.stringn "ひょっとして、って思ったんだけど。\n"
.stringn "\x0713じゃあ……持ってるだけだけど\n"
.stringn "相手しようか？\n"
.stringn "\x0701いいよいいよ、怪我させちゃいそうだし。\n"
.stringn "今日はあきらめるか……あーあ。"
db 0
.align 4
//MYELL_8_KILROY_WAYU_C

//0x21DA0
Text_21D80:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0703おお、ムワリム！\n"
.stringn "こないだは楽しかったぜ！\n"
.stringn "\x071-\x0711ああ、私もだ。\n"
.stringn "\x0703みんなの荷物、どんだけ持てるか\n"
.stringn "力比べしようとしてたら、\n"
.stringn "みんな面白がっていろんなもの乗せて\n"
.stringn "きやがるんだもんなあ。\n"
.stringn "\x0711ああ。物だけでなく、\n"
.stringn "人まで上に\n"
.stringn "乗ってくるのにはまいった。\n"
.stringn "\x0703ああ、最後まで結局あれだ、\n"
.stringn "ほとんど同じくらいだったよなあ。\n"
.stringn "いちばん最後に乗っけたのが、\n"
.stringn "おれがでかい鉄釜１つ、\n"
.stringn "あんたがあの小さい女の子……\n"
.stringn "なんつったか。\n"
.stringn "\x0711ミストだろう。\n"
.stringn "\x0703そう、その子だ。\n"
.stringn "あの子と鉄釜、\n"
.stringn "どっちが重いかわかりゃ\n"
.stringn "決着がついたんだがなあ。\n"
.stringn "\x0711……おまえは、すごいな。\n"
.stringn "\x0703ん？　なにがだ？\n"
.stringn "おまえだってすごかったじゃねえか。\n"
.stringn "\x0711そうじゃない。\n"
.stringn "張り詰めた行軍の雰囲気を\n"
.stringn "逆に飲み込んで、あっという間に\n"
.stringn "引き込んでしまった。\n"
.stringn "いい息抜きができた、笑ったと\n"
.stringn "みんなが感謝していた。\n"
.stringn "\x0703ま、おれが単純にピリピリしたのが\n"
.stringn "いやってだけなんだよなぁ。\n"
.stringn "ガチガチ固まってると全力で戦えねえだろ？\n"
.stringn "\x0711それに、おまえは私に対しても\n"
.stringn "誰に対しても変わらない。\n"
.stringn "それが、すごいと私は思う。\n"
.stringn "\x0703わははは！　なんか知らねえけど\n"
.stringn "そんなにホメんなよ！\n"
.stringn "まあまあ、細かいこたぁいいじゃねえか。\n"
.stringn "勝負は引き分けだったんだ、次は……\n"
.stringn "そうだ、腕相撲なんてどうだよ！\n"
.stringn "おれぁ腕相撲には自信があるんだよな！\n"
.stringn "\x0711…………ああ、いいだろう。\n"
.stringn "次の機会を楽しみにしている。"
db 0
.align 4
//MYELL_8_LARGO_MWARIM_A

//0x219EC
Text_219CC:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0C01\x0C13\x0701おお、ムワリムじゃねえか。\n"
.stringn "調子はどうだ？\n"
.stringn "\x0713……ああ、ラルゴか。\n"
.stringn "この間は……助かった。\n"
.stringn "\x0701わはははは！　いいってことよ！\n"
.stringn "けどあんた、大したもんだぜ。\n"
.stringn "いろんなところ旅してきたけど、\n"
.stringn "おれくらい力持ちな男ってなあ\n"
.stringn "見たことなかったからなあ。\n"
.stringn "さすがのおれもあんたには\n"
.stringn "負けちまうかもしれねえな。\n"
.stringn "なあ、おれとあんた、\n"
.stringn "どっちが力持ちだろうな？\n"
.stringn "\x0713……どうだろうな。\n"
.stringn "\x0701おれぁ……そうだな。\n"
.stringn "一番重いものはあれだ。\n"
.stringn "昔、樹齢何百年とかいう\n"
.stringn "おれの身長の３倍はある直径の大木を\n"
.stringn "かついで運んだことがあったなあ。\n"
.stringn "あんたはどうだい？\n"
.stringn "\x0713……そうだな。\n"
.stringn "城壁の修復に使う岩を\n"
.stringn "岩山から切り出し、\n"
.stringn "積み上げたことがある。\n"
.stringn "\x0701ほう、どのくらいの岩だ？\n"
.stringn "\x0713私の身長の３倍、か。\n"
.stringn "\x0701おお、やっぱりあんたすげえや！\n"
.stringn "なんだかうれしいぜ！\n"
.stringn "どうだ、今度力比べをしてみねえか？\n"
.stringn "おれとあんたなら、\n"
.stringn "いい勝負になりそうだ！\n"
.stringn "\x0713いや、私は……\n"
.stringn "\x0701ケチケチすんなって！\n"
.stringn "へるもんじゃねえんだ、いいだろ？\n"
.stringn "\x0713………………ふぅ……\n"
.stringn "仕方ないな……\n"
.stringn "わかった。１度だけな。"
db 0
.align 4
//MYELL_8_LARGO_MWARIM_B

//0x21790
Text_21770:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0703お？\n"
.stringn "あんた、なかなかいい体してるなぁ。\n"
.stringn "ちょっと腕見せてくれねえか。\n"
.stringn "\x0711……？\n"
.stringn "\x0703おお、大したもんだ。\n"
.stringn "おれは腕の太さには自信があったんだが、\n"
.stringn "あんた大したもんだよ。\n"
.stringn "\x0711…………おまえもな。\n"
.stringn "\x0703わはははは！　おれぁ\n"
.stringn "この馬鹿力だけがとりえだからなぁ！\n"
.stringn "ところでそれ、どっかへ運ぶのか？\n"
.stringn "\x0711ああ。\n"
.stringn "この水がめに水を汲んでくる。\n"
.stringn "\x0703そんなでっかいやつに水を？\n"
.stringn "そいつぁ大変だろう。\n"
.stringn "ひいふうみい、\n"
.stringn "数も結構あるなあ。\n"
.stringn "よし、おれも手伝うぜ。\n"
.stringn "\x0711いや、そんなことはしなくていい。\n"
.stringn "\x0703お、余裕だぜこりゃ！　軽いもんだ！\n"
.stringn "おれぁ腕っぷしぐらいしか\n"
.stringn "能がねえからなあ！　ほら、行くぜ！\n"
.stringn "\x0711………………"
db 0
.align 4
//MYELL_8_LARGO_MWARIM_C

//0x229EC
Text_229CC:
.stringn "\x05FL|LARGO|TAURONEO||\x070-\x0701う～ん……\n"
.stringn "う～～ん……\n"
.stringn "\x0713また店のことで\n"
.stringn "悩んでおるのか？\n"
.stringn "\x0701ああ、あんたかい。\n"
.stringn "またなんかいい智恵貸してくれるか？\n"
.stringn "\x0713うむ。\n"
.stringn "\x0701おれぁ店の名前考えてるんだ。\n"
.stringn "いろいろ頭ぁひねっちゃみたんだけどなあ。\n"
.stringn "\x0713ほう。たとえばどんな名前だ？\n"
.stringn "\x0701『おれの店』ってのはどうだい？\n"
.stringn "\x0713ふむ。いささか安直だな。\n"
.stringn "\x0701じゃあなあ……もうちょいひねるか。\n"
.stringn "おれぁベオクでもラグズでも誰でも\n"
.stringn "気軽に入れて、いっぱい飲んで話でもして、\n"
.stringn "幸せになれるような酒場にしてえんだ。\n"
.stringn "だから『ベオクでもラグズでも誰でも\n"
.stringn "　気軽に入れて、いっぱい飲んで\n"
.stringn "　話でもして幸せな店』！\n"
.stringn "\x0713ふむ。いささか長いな。\n"
.stringn "\x0701ああ、やっぱだめかよ。\n"
.stringn "まいったぜおい、\n"
.stringn "おれぁこういうの考えるの\n"
.stringn "からきし苦手だからなあ。\n"
.stringn "\x0713何も難しく考える必要はあるまい。\n"
.stringn "一番大事に思うものの名ではどうだ？\n"
.stringn "\x0701じゃ、カリルだ。\n"
.stringn "おれぁいつだってカリルが一番なんだ…\n"
.stringn "\x0713惚れた女の名か。\n"
.stringn "ならばそれがよかろう。\n"
.stringn "店を開いたら、\n"
.stringn "わしも立ち寄らせてもらおうか。\n"
.stringn "\x0701ああ、あんたには\n"
.stringn "さんざっぱら世話になったからな。\n"
.stringn "あんたの好きな酒は……\n"
.stringn "確かどっかに書いたぞ……どこだ？\n"
.stringn "おお、あった。強い酒だな？\n"
.stringn "\x0713うむ。\n"
.stringn "\x0701わはははは！　任しといてくれよ！\n"
.stringn "火ぃ吹くような\n"
.stringn "強い酒用意してまってるからな！"
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_A

//0x22590
Text_22570:
.stringn "\x05FL|LARGO|TAURONEO||\x0C05\x0C13\x0705う～～ん。\n"
.stringn "\x0713……\n"
.stringn "\x0705う～～ん。\n"
.stringn "\x0713……またどうかしたのか？\n"
.stringn "\x0C05\x0701ん？\n"
.stringn "おお、あんたかい。\n"
.stringn "\x0713先ほどから唸ってばかりのようだな。\n"
.stringn "上の空、といった感じだ。\n"
.stringn "自陣内といえど、気を緩めていては\n"
.stringn "命に関わるぞ。\n"
.stringn "\x0701ああ、確かにそうだ。\n"
.stringn "いけねえいけねえ。\n"
.stringn "おれぁ頭悪いから２つのこと\n"
.stringn "いっぺんに考えられねえんだよ。\n"
.stringn "\x0713何か悩み事か？\n"
.stringn "\x0701おう、聞いてくれるかい？\n"
.stringn "おれ、いつか店開こうって思ってんだ。\n"
.stringn "ここでたくさん金貯めてさ、\n"
.stringn "酒屋なんかいいだろうなあって。\n"
.stringn "\x0713ほう。\n"
.stringn "\x0701おれはお客さんを大切にしたいんだ。\n"
.stringn "来てくれるお客さんには、\n"
.stringn "みんな幸せになってもらいてえのさ。\n"
.stringn "だからいろんな人間の集まるここで\n"
.stringn "いろいろ勉強してんだ。\n"
.stringn "人の数だけ好みはあるもんなあ。\n"
.stringn "\x0713それは素晴らしい理想だな。\n"
.stringn "ところで、その店はどこに出すのだ？\n"
.stringn "\x0701う～～～ん……\n"
.stringn "おれぁこう見えても\n"
.stringn "ベグニオン生まれだからなぁ、\n"
.stringn "やっぱ故郷のベグニオンってところかな。\n"
.stringn "けど人の話聞いてっと、\n"
.stringn "クリミアもデインもいいとか思うしなあ…\n"
.stringn "ああ、こりゃ大変だぜおい。\n"
.stringn "おれぁ頭悪いからなあ……\n"
.stringn "\x0713………………\n"
.stringn "わしで良ければ相談に乗るが？\n"
.stringn "\x0701おお、そいつぁありがてえや。\n"
.stringn "２人なら、２つのこと考えれるもんな。\n"
.stringn "あと店のメニューと、\n"
.stringn "ええと……なんだっけか……"
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_B

//0x22250
Text_22230:
.stringn "\x05FL|LARGO|TAURONEO||\x0701う～～ん……う～～ん……\n"
.stringn "\x0716……\n"
.stringn "\x0701お？\n"
.stringn "なあ、そこのあんた。\n"
.stringn "\x0C16\x0713む？\n"
.stringn "\x0701この軍、結構変わったとこだと\n"
.stringn "思わないか？\n"
.stringn "こんだけ色んな国の連中が\n"
.stringn "混ざってんのは珍しいや。\n"
.stringn "おれぁあちこち旅してきたが、\n"
.stringn "こんだけごちゃごちゃ\n"
.stringn "してるのは初めてさ。\n"
.stringn "\x0713……そうかもしれぬな。\n"
.stringn "なにしろ敵側の元デイン兵も\n"
.stringn "混じっておるほどだ。\n"
.stringn "国の多様さには事欠くまい。\n"
.stringn "\x0701だろう、それで色んな人種が\n"
.stringn "いるだけあって\n"
.stringn "珍しい料理も出てくるしなあ。\n"
.stringn "\x0713……その手にあるものは何だ？\n"
.stringn "\x0701ん？　ああ、考え事してる時ぁ\n"
.stringn "忘れないように書いとくのさ。\n"
.stringn "おれぁ頭悪いからすぐ忘れちまうんだな。\n"
.stringn "ラグズは濃い味つけが好きみたいだし、\n"
.stringn "それにおれたちと一緒で酒も飲む！\n"
.stringn "よかったよかった！\n"
.stringn "なあ、あんたはどんな酒が好きだい？\n"
.stringn "\x0713……酒か。\n"
.stringn "強い酒を所望する。\n"
.stringn "\x0701味は？\n"
.stringn "\x0713味は問わぬ。\n"
.stringn "\x0701わははは！　いいねえ漢じゃねえか！\n"
.stringn "よし、そいつも忘れねえように書いとくぜ。"
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_C

//0x23554
Text_23534:
.stringn "\x05FL|WAYU|LARGO||\x0C03\x0C11\x0703手加減した？\n"
.stringn "\x0711いいや。\n"
.stringn "\x0703……本当に？\n"
.stringn "\x0711本当だ。\n"
.stringn "\x0703本当に本当？\n"
.stringn "\x0711本当に本当だ。\n"
.stringn "見事に一本取られちまったよ。\n"
.stringn "負けだ負けだ。\n"
.stringn "あんたの成長はたいしたもんだぜ。\n"
.stringn "\x0703…………\n"
.stringn "は～～～……疲れたぁ。\n"
.stringn "じゃ、今日こそはあたしの勝ちだからね！\n"
.stringn "それじゃちょっと一寝入りしてこよっと……\n"
.stringn "\x0711ああ、あんた。\n"
.stringn "疲れてるとこすまんが……\n"
.stringn "１ついいかい？\n"
.stringn "\x0703ん？\n"
.stringn "\x0711あんた、\n"
.stringn "なぜそこまで意地を張るんだ？\n"
.stringn "おれが前に言ったこと……\n"
.stringn "あんたはおれ以上に\n"
.stringn "身にしみてわかってるはずだろ。\n"
.stringn "なのになんで、\n"
.stringn "そこまで頑張れるんだい？\n"
.stringn "\x0703負けらんないの、あたしは。\n"
.stringn "女だから、女には向いてない。\n"
.stringn "今までに何度もそう言われたから。\n"
.stringn "だから、負けらんないの。\n"
.stringn "\x0711……\n"
.stringn "\x0703弱いから負けるんなら、納得できるよ。\n"
.stringn "技が足りないなら、磨けばいい。\n"
.stringn "経験が足りないなら、戦えばいい。\n"
.stringn "だけど女だから負けるっていうのだけは\n"
.stringn "自分が許せない。\n"
.stringn "おじさんに負けたのは、\n"
.stringn "自分が女だからじゃない。\n"
.stringn "そんな理由に逃げたくない。\n"
.stringn "あたしが未熟だから負けたんだ。\n"
.stringn "だったら修行する。\n"
.stringn "剣の腕を磨いて磨いて、そしていつか勝つ。\n"
.stringn "\x0711……そうか。\n"
.stringn "まいったな。\n"
.stringn "こりゃおれがやられちまうのも当然だ。\n"
.stringn "おれも負けちゃいられねえな、\n"
.stringn "あんたのその意気を見習わねえとな。\n"
.stringn "\x0703じゃあ、いつやる？\n"
.stringn "\x0711うん？\n"
.stringn "\x0703次の勝負の約束。\n"
.stringn "おじさんだって、\n"
.stringn "負けたまんまじゃ終わりたくないでしょ？\n"
.stringn "\x0711わはははは！　さすがだぜあんた。\n"
.stringn "もちろんだ。\n"
.stringn "勝つまで何度でもおれはやるぞ！\n"
.stringn "\x0703望むところよ！"
db 0
.align 4
//MYELL_8_LARGO_WAYU_A

//0x230E4
Text_230C4:
.stringn "\x05FL|WAYU|LARGO||\x0C03\x0C11\x0703おじさん！\n"
.stringn "\x0711おお、あんたかよ。\n"
.stringn "こないだはその、なんだ。\n"
.stringn "悪かったな。\n"
.stringn "\x0703あんなの平気に決まってんじゃない。\n"
.stringn "それよりおじさん、\n"
.stringn "わかってるわよね！\n"
.stringn "\x0711へ？\n"
.stringn "なんだ？\n"
.stringn "\x0703こないだの借りを返しに来たに\n"
.stringn "決まってんじゃない！\n"
.stringn "あの時はね、確かに負けたけどね！\n"
.stringn "けど今のあたしを前と同じだと\n"
.stringn "思わないでよね！\n"
.stringn "\x0711またやんのかい？\n"
.stringn "気持ちはわかるが……\n"
.stringn "やめといた方がいいぜ、\n"
.stringn "女の子の力じゃ、\n"
.stringn "おれにゃ勝てねえだろう。\n"
.stringn "\x0703！\n"
.stringn "また女だって馬鹿にしてる！\n"
.stringn "\x0711まいっちまったなぁ……\n"
.stringn "なあ、あんた。\n"
.stringn "これはあんたを\n"
.stringn "馬鹿にして言ってるわけじゃねえんだ。\n"
.stringn "男と女では骨も肉のつき方も違う。\n"
.stringn "戦いではどうしたって\n"
.stringn "不利になっちまうんだ。\n"
.stringn "\x0703そんなことわかってる！\n"
.stringn "けどあたしは負けないの。\n"
.stringn "負けられないの、絶対に。\n"
.stringn "今日負けたら修行して、明日勝つ。\n"
.stringn "明日も負けたら修行して、明後日……\n"
.stringn "\x0711お、おいおい……\n"
.stringn "あんたよく見りゃ\n"
.stringn "ふらふらじゃねえか。\n"
.stringn "そんな状態で戦おうなんざ\n"
.stringn "どだい無理な話ってもんだ。\n"
.stringn "今日はとにかく休んで……\n"
.stringn "\x0703気づかいは無用！\n"
.stringn "ちょっとふらついてんのはね、\n"
.stringn "今日おじさんに勝つために\n"
.stringn "訓練してきたから。\n"
.stringn "だから今日\n"
.stringn "おじさんと戦えなきゃ意味ないの。\n"
.stringn "\x0711……\n"
.stringn "わかった。\n"
.stringn "あんたがそこまで言うんなら……\n"
.stringn "おれも男だ。受けて立つぜ。\n"
.stringn "\x0703行くよ！"
db 0
.align 4
//MYELL_8_LARGO_WAYU_B

//0x22E50
Text_22E30:
.stringn "\x05FL|WAYU|LARGO||\x070-\x0C03\x0C11\x0703へえ。\n"
.stringn "おじさん、いい身体してるね。\n"
.stringn "\x0711ん？　なんだ、あんた。\n"
.stringn "\x0703あたしはワユ！\n"
.stringn "修行中の剣士よ。\n"
.stringn "いっちょ、勝負してくれない？\n"
.stringn "\x0711勝負だって？\n"
.stringn "う～ん……弱っちまったな。\n"
.stringn "\x0703なんで？\n"
.stringn "\x0711あんたは女だろう。\n"
.stringn "女の子相手に勝負ってのは\n"
.stringn "ちょっとなあ……\n"
.stringn "\x0703！\n"
.stringn "\x0711あんたもなんだ、\n"
.stringn "剣を持って戦うより……\n"
.stringn "もっとこう、うまくいえねえが\n"
.stringn "家庭的なことをした方が良くねえか？\n"
.stringn "たとえば、よくわかんねえが\n"
.stringn "編み物とか料理とか……\n"
.stringn "せめて魔道使いになるとか……\n"
.stringn "\x0703何それ！\n"
.stringn "女だから戦えないっての？\n"
.stringn "\x0711う～ん……\n"
.stringn "そりゃあすまねえ。\n"
.stringn "\x0703わかったら\n"
.stringn "早く早く！　構える！\n"
.stringn "\x0711う～ん……まいっちまったな。\n"
.stringn "なあ、どうだ？\n"
.stringn "ここは１つ編み物で勝負……\n"
.stringn "\x0703問答無用！"
db 0
.align 4
//MYELL_8_LARGO_WAYU_C

//0x242A8
Text_24288:
.stringn "\x05FL|RETHE|LAY||\x0C01\x0713レテ、こないだの話だけどな。\n"
.stringn "部隊長クラスの志願者を何人か、\n"
.stringn "派遣先からガリアに戻すかって話がある。\n"
.stringn "まだ本決まりじゃないんだが……\n"
.stringn "もしそうなったらおまえ、どうする？\n"
.stringn "ガリアに戻りたいってことならそう伝えるけど。\n"
.stringn "\x0701私は……\n"
.stringn "ここに残る。\n"
.stringn "\x0713え？\n"
.stringn "いいのか？\n"
.stringn "\x0701……私がいなくなったとたん\n"
.stringn "アイクたちが何かあっては困るからな。\n"
.stringn "だから、ここに残る。\n"
.stringn "\x0713へえ……\n"
.stringn "\x0701な、なんだ\n"
.stringn "その意味ありげな笑みは。\n"
.stringn "\x0713いや、なーんでも。\n"
.stringn "『ニンゲンどもが！』って吐き捨ててた\n"
.stringn "おまえがな、って……\n"
.stringn "\x0701べ、別に私は……\n"
.stringn "\x0713おまえの動揺は尻尾に出るからな、\n"
.stringn "すぐわかる。\n"
.stringn "そうかそうか、やっぱりな。\n"
.stringn "\x0701……鍛錬の途中だ。\n"
.stringn "話がそれだけなら行くぞ。\n"
.stringn "\x0713あ、悪い。\n"
.stringn "ちょっとからかい過ぎたか。\n"
.stringn "\x0700…………\n"
.stringn "ライ。\n"
.stringn "\x0713ん？\n"
.stringn "\x0700……私の気持ちが\n"
.stringn "以前と変わったことは認めよう。\n"
.stringn "\x0713……そっか。\n"
.stringn "\x0700ずっと……おまえの考えには\n"
.stringn "賛同できなかったが……\n"
.stringn "今はおまえの気持ちがわかる。\n"
.stringn "共に戦う彼らは大切な仲間だ。\n"
.stringn "呪われた【負】の気が渦巻く地へ向かう\n"
.stringn "仲間たちを見送ることはできん。\n"
.stringn "だから、私はアイクと共に行く。\n"
.stringn "\x0713そうか……\n"
.stringn "よし、勝ったらアイクたちと\n"
.stringn "みんなでぱーっと盛り上がろうぜ。\n"
.stringn "\x0700今はまだ気を緩める時ではないぞ。\n"
.stringn "だが……そうだな。\n"
.stringn "いつか……そうできるといいな。"
db 0
.align 4
//MYELL_8_LAY_LETHE_A

//0x23E4C
Text_23E2C:
.stringn "\x05FL|LAY|RETHE||\x070-\x0C01\x0713ライ、ガリアに残してきた\n"
.stringn "私の部下たちは鍛錬を続けているか？\n"
.stringn "\x0701ああ、もちろんだ。\n"
.stringn "あいつらだってガリアの戦士だ。\n"
.stringn "国の守りは\n"
.stringn "あいつらに任せとけば大丈夫さ。\n"
.stringn "\x0713だが、どうにも心配だ。\n"
.stringn "熱心に鍛錬するのはいいのだが、\n"
.stringn "手合わせの最中に本気になり、\n"
.stringn "頭に血が昇ってケンカになることがよくあった。\n"
.stringn "\x0701ま、血の気の多いやつが\n"
.stringn "わんさかいるからなあ……\n"
.stringn "でも、なんとかなるって。\n"
.stringn "\x0713おまえはそんな呑気なことで……\n"
.stringn "\x0701おまえはさ、\n"
.stringn "そう四六時中ピリピリしてないで、\n"
.stringn "たまにはちょっと息抜きでもしたらどうだ。\n"
.stringn "だからっておまえの妹みたいに\n"
.stringn "戦場でも隙あらば毛づくろいしたり、\n"
.stringn "爪磨いたりしてるのはいただけないが。\n"
.stringn "\x0713…リィレは今、おまえの部隊に？\n"
.stringn "\x0701ああ。キサと合わせて手を焼かされてる。\n"
.stringn "\x0713キサもでかい図体して\n"
.stringn "おまえに懐いてるからな。\n"
.stringn "大変だろうが…よろしく頼む。\n"
.stringn "\x0701リィレには長いこと会ってないんだってな？\n"
.stringn "\x0713……\n"
.stringn "\x0701話したくないか。ま、別にいいけどな。\n"
.stringn "さっさと仲直りしろよ。\n"
.stringn "２人っきりの姉妹なんだし。\n"
.stringn "\x0713おまえには関係ない。\n"
.stringn "\x0701はいはい。\n"
.stringn "\x0713妹のことはともかく……\n"
.stringn "本国の部隊が心配なのは確かだ。\n"
.stringn "おまえや私たちがここへ派遣され、\n"
.stringn "国の守りは薄くなっている。\n"
.stringn "\x0701そうだな……\n"
.stringn "オレもちょっと上と相談してみるか。"
db 0
.align 4
//MYELL_8_LAY_LETHE_B

//0x23A74
Text_23A54:
.stringn "\x05FL|LAY|RETHE||\x070-\x0C03\x0C11\x0703よう、レテ。\n"
.stringn "\x0711ライか。やっと参戦とはな。\n"
.stringn "\x0703ああ、ようやく\n"
.stringn "風向きが変わってくれたからな。\n"
.stringn "それより調子はどうだ、レテ？\n"
.stringn "今まで、おまえやモゥディだけに\n"
.stringn "任せきりだったからな。\n"
.stringn "本当はオレもいるはずだったのに\n"
.stringn "悪かったな。\n"
.stringn "\x0711謝罪などに意味はない。\n"
.stringn "行動で返してくれ。\n"
.stringn "\x0703相変わらず固いね～おまえは。\n"
.stringn "ところで、どうだ？\n"
.stringn "傭兵団の連中とはすっかり馴染んだか？\n"
.stringn "\x0711…………それなりには、な。\n"
.stringn "しかし、不満は相変わらずある。\n"
.stringn "無理とは分かっているが、あの鎧だ。\n"
.stringn "味方が鉄の匂いをまとっていては、\n"
.stringn "私が敵を感知することもできない。\n"
.stringn "\x0703まあ、そればっかりはなあ～…\n"
.stringn "まさかアイクたちに全員生身で\n"
.stringn "戦ってくれって言うわけにもいかないし。\n"
.stringn "\x0711あと、ベオクの目は何とかならんものか。\n"
.stringn "暗闇で目が見えないのは致命的だ。\n"
.stringn "鳥翼族なら不可能なんだと思えるが、\n"
.stringn "多少見えているんなら気合で何とか……\n"
.stringn "\x0703いや無茶だろ、それは……\n"
.stringn "\x0711だが……\n"
.stringn "思った以上にやるとは思っている。\n"
.stringn "\x0703そうか、良かった。\n"
.stringn "最初アイクたちと一緒に行くってことに\n"
.stringn "なった時のおまえの悲壮な顔って言ったら……\n"
.stringn "\x0711う、うるさい！"
db 0
.align 4
//MYELL_8_LAY_LETHE_C

//0x24DD0
Text_24DB0:
.stringn "\x05FL|LAY|MORDY||\x0C03\x0711スまん、ライ。\n"
.stringn "\x0703どうした、モゥディ？\n"
.stringn "\x0711ライに言われてカら、考えてイた。\n"
.stringn "デも、ドうしてもモゥディは\n"
.stringn "戦いが苦手だ。\n"
.stringn "\x0703ああ…　それは\n"
.stringn "わかってるって言ったろ？\n"
.stringn "\x0711モゥディは戦士ダから、戦う。\n"
.stringn "仲間を守りたいカら、戦う。\n"
.stringn "ナのに……モゥディは、\n"
.stringn "今のマまの戦い方しか、デきない。\n"
.stringn "\x0703……モゥディ。\n"
.stringn "そうだな……おまえは\n"
.stringn "昔からそうだったもんな。\n"
.stringn "森でリスと昼寝してるのが好きな…\n"
.stringn "陽気で、おおらかな奴だ。\n"
.stringn "\x0711ウぅ……スまん。\n"
.stringn "\x0703いや、だから気にすんなって。\n"
.stringn "\x0711……ヒょっとしたら\n"
.stringn "モゥディは…大好きなアイクたちニも\n"
.stringn "迷惑をカけてイるのかもシれない……\n"
.stringn "ソう思うとトても辛い………\n"
.stringn "\x0703じゃ、とっとと戦を終わらることだ。\n"
.stringn "そうすりゃああだこうだと悩まなくて済むだろ？\n"
.stringn "\x0711ソうか！　ソうなればイいな！\n"
.stringn "\x0703じゃあ、いつもより多めに気合をいれとくか。\n"
.stringn "ちょっと付き合えよ。\n"
.stringn "次に備えて、身体動かしとこうぜ。\n"
.stringn "\x0711オぉ！！"
db 0
.align 4
//MYELL_8_LAY_MORDY_A

//0x24A30
Text_24A10:
.stringn "\x05FL|MORDY|LAY||\x0707グぅ……グぅ……\n"
.stringn "\x071-\x0713おーいモゥディ。\n"
.stringn "なんだ？　寝てるのか？\n"
.stringn "\x0C07\x0701ンんンんん……　ライ？\n"
.stringn "\x0713お！　起きたか。\n"
.stringn "よくそんな場所で寝ていられるな。\n"
.stringn "おまえも、神経の図太さじゃ\n"
.stringn "アイクといい勝負かもな？\n"
.stringn "\x0701モゥディは、アイクたちのコとを\n"
.stringn "信頼シてイるカらな。\n"
.stringn "ミんながイると思うと、安心デきるぞ。\n"
.stringn "\x0713はは　そうか。\n"
.stringn "……そういえばモゥディ。\n"
.stringn "以前、おまえの戦い方を見てて\n"
.stringn "気づいたんだがな。\n"
.stringn "おまえ、敵を攻撃するとき\n"
.stringn "時々目をつぶってないか？\n"
.stringn "\x0701……ソうだ。\n"
.stringn "ライはよく見てイる。\n"
.stringn "\x0713どうしてそんなことを？\n"
.stringn "\x0701痛がる敵を見てイると、モゥディも痛い。\n"
.stringn "デも、戦いだ。\n"
.stringn "戦いデは情けはダめだ。\n"
.stringn "ガんばって戦わナいとイけない。\n"
.stringn "ダから、少しダけ目をツぶる。\n"
.stringn "\x0713時々、不自然に\n"
.stringn "動きが鈍るのもそのせいか…\n"
.stringn "\x0701アあ…　ライはヨく見てイるな。\n"
.stringn "\x0713まあな…\n"
.stringn "しっかし、惜しいな。\n"
.stringn "その優しい心がなけりゃ\n"
.stringn "おまえは、もっと強い戦士になるものを。\n"
.stringn "\x0701ウぅ……スまない……\n"
.stringn "\x0713別に謝ることじゃないさ。\n"
.stringn "おまえの気性は、理解してるつもりだ。\n"
.stringn "\x0701ウぅ……"
db 0
.align 4
//MYELL_8_LAY_MORDY_B

//0x24720
Text_24700:
.stringn "\x05FL|MORDY|LAY||\x070-\x0C01\x071-\x0713よう、モゥディ。\n"
.stringn "\x0701ライ。\n"
.stringn "コうして話すノは久しぶりだ。\n"
.stringn "\x0713ああ、今までご苦労だったな。\n"
.stringn "聞いたぜ、傭兵団の中に混じって\n"
.stringn "大活躍してたって？\n"
.stringn "\x0701ソうなのか？\n"
.stringn "役に立てて良かった。\n"
.stringn "アイクは良いベオクだから\n"
.stringn "モゥディはガんばった。\n"
.stringn "\x0713傭兵団の仲間たちとも\n"
.stringn "もう打ち解けたか？\n"
.stringn "\x0701ドうだろう？\n"
.stringn "タぶん、上手くイってイる。\n"
.stringn "トころでライ、\n"
.stringn "モゥディの言葉は、変か？\n"
.stringn "\x0713いや、全然おかしくないぜ。\n"
.stringn "ちょっとなまってるけどな。\n"
.stringn "\x0701言葉は難しい。\n"
.stringn "モゥディたちは化身すれば、\n"
.stringn "難しい言葉はイらない。\n"
.stringn "森の仲間たちトも一声で\n"
.stringn "意志を交わすコとがデきる。\n"
.stringn "\x0713まあな。\n"
.stringn "けどオレたちが吠えても\n"
.stringn "ベオクにはわからないんだよなあ。\n"
.stringn "でかい声で吠えまくって\n"
.stringn "みんなを怯えさせちまってもまずい。\n"
.stringn "\x0701ソうだな。ライは正しい。\n"
.stringn "コこにイるのは\n"
.stringn "良いベオクたちバかりダからな。\n"
.stringn "怖がらせるノはイけないコとだ。"
db 0
.align 4
//MYELL_8_LAY_MORDY_C

//0x25844
Text_25824:
.stringn "\x05FL|MWARIM|RETHE||\x0C01\x0C13\x0701レテ。\n"
.stringn "\x0713……何か用か？\n"
.stringn "\x0701不快な思いをさせてすまなかった。\n"
.stringn "諦めているくせに……\n"
.stringn "私はおまえのことを\n"
.stringn "うらやましいと思っていたようだ。\n"
.stringn "\x0713そうか……\n"
.stringn "\x0701ベオクにひるむことなく\n"
.stringn "対等に接することができる。\n"
.stringn "おまえから見れば当然のことだろうが、\n"
.stringn "私はそんな事を考えたこともなかった。\n"
.stringn "\x0713…………ならば……\n"
.stringn "考えさえすれば、できるように\n"
.stringn "なれるんじゃないのか？\n"
.stringn "\x0701……ああ、そうかも知れない。\n"
.stringn "いや……そうしなくてはいけないのか。\n"
.stringn "\x0713義務じゃないと思うが……\n"
.stringn "しかし、そうした方がきっとおまえが\n"
.stringn "楽になれると思うのだ。\n"
.stringn "おまえが穏やかな顔でいるときを\n"
.stringn "私は見たことがない。\n"
.stringn "それが気になって……辛い。\n"
.stringn "\x0701…………そうか……\n"
.stringn "\x0713……なあ、辛いかもしれんが……\n"
.stringn "おまえがどんな風に暮らしてきたのか\n"
.stringn "聞かせてくれないか？\n"
.stringn "……少しでも、おまえの考えてることが\n"
.stringn "わかるようになるかも知れん。\n"
.stringn "\x0701…………レテ……"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_A

//0x2544C
Text_2542C:
.stringn "\x05FL|MWARIM|RETHE||\x0C01\x0713ムワリム。\n"
.stringn "……調子はどうだ？\n"
.stringn "\x0701ああ、ずいぶんこの軍にも\n"
.stringn "馴染んできた。\n"
.stringn "他のラグズの目にさらされるのにも…\n"
.stringn "ずいぶん慣れたつもりだ。\n"
.stringn "\x0713？　ラグズの……？\n"
.stringn "しかし、おまえ……また荷物運びか？\n"
.stringn "そんな物資を運ぶことなど\n"
.stringn "他の兵にやらせておけばいいだろう。\n"
.stringn "\x0701目に付いてしまうからな。\n"
.stringn "そのまま見過ごして去るのには\n"
.stringn "恐怖すら感じる。\n"
.stringn "\x0713恐怖……？\n"
.stringn "\x0701産まれたときからそういう環境で育てば\n"
.stringn "骨の髄まで染み込んでしまうものだな。\n"
.stringn "\x0713…………そうか。\n"
.stringn "\x0701おまえは、罵らないのか？\n"
.stringn "ラグズとしての誇りはどうしたのかと。\n"
.stringn "\x0713…………いや……\n"
.stringn "昔の私であれば、言ったかもしれない。\n"
.stringn "しかし今は……アイクの元に身を寄せて\n"
.stringn "戦うようになってからは……\n"
.stringn "ラグズとベオクの関係について\n"
.stringn "いろいろと考えることもあってな……\n"
.stringn "\x0701…………\n"
.stringn "\x0713なによりも、とっくに諦めているおまえに\n"
.stringn "何も言うことはない。\n"
.stringn "\x0701！\n"
.stringn "\x0713それが悪いとは言わない。\n"
.stringn "私には理解できないような人生を……\n"
.stringn "おまえは歩んできたのだろう？\n"
.stringn "だが……ひとつだけ。\n"
.stringn "おまえが全てを受け入れ、諦めたのなら\n"
.stringn "そんな卑屈な態度を取らないでくれ。\n"
.stringn "……気になって、仕方がない。\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_B

//0x25100
Text_250E0:
.stringn "\x05FL|RETHE|MWARIM||\x0C01\x0C13\x0701ムワリム。\n"
.stringn "\x0713……レテか。\n"
.stringn "\x0701調子はどうだ？\n"
.stringn "こんな風に軍隊で戦うのは初めてだろう。\n"
.stringn "\x0713ああ、そうだな。\n"
.stringn "分からぬことが多くて戸惑うこともある。\n"
.stringn "\x0701何でも聞くがいい。\n"
.stringn "私はガリアで部隊を率いていたからな。\n"
.stringn "戦の知識なら豊富に持っている。\n"
.stringn "\x0713……女の身でか。\n"
.stringn "レテは優秀なのだな。\n"
.stringn "\x0701………………\n"
.stringn "そうか……おまえはベグニオンで\n"
.stringn "生まれ育ったと言っていたな……\n"
.stringn "ガリアでは男も女も関係ない。\n"
.stringn "より優秀な戦士であればいいのだ。\n"
.stringn "身体の造りの問題で、男より\n"
.stringn "女の方がどうしても劣る部分はあるが…\n"
.stringn "しかし、努力で補えばどうとでもなる。\n"
.stringn "\x0713素晴らしいな。\n"
.stringn "\x0701……おまえ、そんな他人事のように\n"
.stringn "聞き流すなよ。\n"
.stringn "ベグニオンでの奴隷だったというが……\n"
.stringn "ベオクなど、おまえが本気になれば…\n"
.stringn "\x0713……わからない話だろうな。\n"
.stringn "産まれたときから偉大なるガリア王に守られ、\n"
.stringn "ラグズであることの誇りを胸に生きてきた。\n"
.stringn "そんなおまえには理解できんことだ。\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_C

//0x26228
Text_26208:
.stringn "\x05FL|LOFA|MARCIA||\x0C01\x071-\x0713すごーい！\n"
.stringn "ヨファ、全部的中しちゃったね。\n"
.stringn "\x0701うん。\n"
.stringn "でももっとがんばらなくちゃ。\n"
.stringn "それに、当てるだけじゃだめなんだよ。\n"
.stringn "ぼくに弓を教えてくれた人は\n"
.stringn "鎧のすきまだけを確実に狙うんだって。\n"
.stringn "\x0713すごいね……\n"
.stringn "ヨファもそうなるのかな……\n"
.stringn "…………あれ？\n"
.stringn "ちょ、ちょっとヨファ、\n"
.stringn "手見せて！\n"
.stringn "\x0701手……？\n"
.stringn "\x0713やっぱり……\n"
.stringn "マメがつぶれて血が出てるじゃない。\n"
.stringn "もう、だめでしょ！\n"
.stringn "なんでこんなになるまでほっといたの！？\n"
.stringn "\x0701ほんとだね……\n"
.stringn "痛いな、と思ってたんだけど……\n"
.stringn "途中からわからなくなってきたから\n"
.stringn "そのまま続けてたんだ。\n"
.stringn "\x0713ヨファ……\n"
.stringn "ヨファは本当に強いね……\n"
.stringn "ちょっと待って、きずぐすりは……\n"
.stringn "あ、あった。\n"
.stringn "じっとしててね。ちょっとしみるけど。\n"
.stringn "\x0701……ありがとう。\n"
.stringn "\x0713ヨファは体が大きくなったら\n"
.stringn "きっともっと強くなるね。\n"
.stringn "今もこんなに強いんだもの……\n"
.stringn "\x0701そうかな？\n"
.stringn "\x0713うん。腕前もそうだけど、心がね。\n"
.stringn "痛いのを忘れちゃうくらい\n"
.stringn "集中できてるんだもん。\n"
.stringn "そうそうできることじゃないよ。\n"
.stringn "\x0701じゃあ……ちゃんとみんなのこと、\n"
.stringn "ぼくは守れるのかな？\n"
.stringn "危ない時に、ちゃんと役に立てるかな？\n"
.stringn "\x0713もっちろんだよ！\n"
.stringn "ヨファが大事な人みーんな、きっと守れるよ。\n"
.stringn "私が勝手に保証してあげるわ！\n"
.stringn "\x0701……ありがとう、マーシャさん。\n"
.stringn "ちゃんと、マーシャさんのことも守るからね。\n"
.stringn "いつも傍にいてくれて、ありがとう。\n"
.stringn "\x0713ヨファ…………\n"
.stringn "…………私も…私も、ヨファを守るね。\n"
.stringn "ヨファはまだ小さいのに……\n"
.stringn "どうして、大人にならなきゃ\n"
.stringn "なんなかったんだろうね…………"
db 0
.align 4
//MYELL_8_LOFA_MARCIA_A

//0x25EDC
Text_25EBC:
.stringn "\x05FL|LOFA|MARCIA||\x0C03\x071-\x0714あ、すごい！\n"
.stringn "２３回連続で的に当てたじゃない！\n"
.stringn "\x0703うーん……ほんとは３０回連続で\n"
.stringn "当てたかったんだけどなあ……\n"
.stringn "\x0C14\x0C14\x0711でも、その半分以上は当ててるわけだよね？\n"
.stringn "うまいよ、ヨファ！\n"
.stringn "\x0703でも、戦場じゃ全部的中させなきゃな、って\n"
.stringn "ぼくに弓を教えてくれた人が言ってた。\n"
.stringn "２３回で満足してちゃだめだよ。\n"
.stringn "訓練用だから距離も短いんだし。\n"
.stringn "\x0711そっか……えらいね、ヨファは。\n"
.stringn "自分に厳しいんだ。\n"
.stringn "\x0703マーシャさんは自分にやさしいの？\n"
.stringn "\x0711ん？　そんなつもりはないわよ。\n"
.stringn "自分に厳しく、他人にも厳しく！\n"
.stringn "っていうのが、昔所属してた軍の\n"
.stringn "副長だった人に言われた言葉だったし。\n"
.stringn "でも、ヨファはまだ……\n"
.stringn "\x0703子供じゃないよ。\n"
.stringn "……ぼくだって、敵を倒してる。\n"
.stringn "\x0711……うん、そうだね。\n"
.stringn "\x0703マーシャさんは、ぼくが子供だから\n"
.stringn "いろいろ心配してくれてるの？\n"
.stringn "\x0711うん……\n"
.stringn "\x0703じゃあ、もう心配してくれなくていいよ。\n"
.stringn "ぼく、そんなに弱くないから。\n"
.stringn "\x0711そっか……　ごめんね。"
db 0
.align 4
//MYELL_8_LOFA_MARCIA_B

//0x25B6C
Text_25B4C:
.stringn "\x05FL|LOFA|MARCIA||\x0703よいしょ……っと。\n"
.stringn "\x0711あれ？　君……\n"
.stringn "確か、ヨファ君だったよね。\n"
.stringn "１人で何してるの？\n"
.stringn "\x0703弓の訓練だよ。\n"
.stringn "ここにこうやって木を立てて、\n"
.stringn "的中の場所を自分で決めてから\n"
.stringn "そこを狙うんだ。\n"
.stringn "他のところに当たると危ないから\n"
.stringn "矢の先には布をつけてる。\n"
.stringn "それに、的との距離も短く取ってるから\n"
.stringn "ちゃんとした訓練にはならないんだけど。\n"
.stringn "\x0711へえ、えらいね。\n"
.stringn "小さいのにがんばってるんだ。\n"
.stringn "\x0703小さいって言わないでよ。\n"
.stringn "ぼく、れっきとした傭兵だよ？\n"
.stringn "\x0711わかってるわかってる。\n"
.stringn "じゃあ私が\n"
.stringn "訓練に付き合ってあげようか？\n"
.stringn "\x0703え……いいよ。\n"
.stringn "１人でできるから。\n"
.stringn "\x0711遠慮しないの。\n"
.stringn "私はね、世界一大きい国の\n"
.stringn "騎士だったんだから。\n"
.stringn "しかも、弓兵の知識は豊富なのよ？\n"
.stringn "天馬騎士にとって、弓兵は大敵だからね。\n"
.stringn "\x0703ぼく、騎士じゃないもん。\n"
.stringn "関係ないよ。\n"
.stringn "\x0711あ、まってヨファ。\n"
.stringn "こういうところで弓を射る時は、\n"
.stringn "まわりに人がいないか\n"
.stringn "気をつけないとだめなんだよ。\n"
.stringn "\x0703もう、そんなことわかってるよ。\n"
.stringn "\x0711そっか、ごめんごめん！"
db 0
.align 4
//MYELL_8_LOFA_MARCIA_C

//0x26E98
Text_26E78:
.stringn "\x05FL|MIST|LOFA||\x0C01\x0C13\x0701ねえ、ヨファ。\n"
.stringn "\x0713……\n"
.stringn "\x0701無視しないで。\n"
.stringn "ちゃんと話、しよ？\n"
.stringn "\x0713………\n"
.stringn "\x0701ヨファを責める気はないの。\n"
.stringn "ただ、傭兵団の時みたいに\n"
.stringn "山賊退治とか…そんなふうに\n"
.stringn "相手がぜったいに悪者じゃない…\n"
.stringn "それを知ってほしかったの。\n"
.stringn "\x0713…ぼくが何も考えてないって\n"
.stringn "そう思った？\n"
.stringn "\x0701…え？\n"
.stringn "\x0713相手は的じゃない…\n"
.stringn "的は動かないし、悲鳴もあげない…\n"
.stringn "血も流さない……\n"
.stringn "わかってるよ、そんなこと\n"
.stringn "最初の敵を倒した…時から……\n"
.stringn "敵だって…\n"
.stringn "ぼくたちみたいに仲間や家族を\n"
.stringn "守るために戦う、人間なんだって…\n"
.stringn "\x0701ヨファ…\n"
.stringn "\x0713でも、悪者だよ。\n"
.stringn "ぼくにとっては…\n"
.stringn "大切な人たちを傷つけるなら\n"
.stringn "敵で、悪者なんだ。\n"
.stringn "だから倒す。\n"
.stringn "だって、そいつを生かしてたら\n"
.stringn "次は味方の誰かが殺される！\n"
.stringn "ぼくは…それが怖いよ。\n"
.stringn "戦争が終わらなきゃ\n"
.stringn "いつまでだって…続くんだ！\n"
.stringn "だから…\n"
.stringn "はやく戦いを終わらせたいから…\n"
.stringn "\x0C01\x0701ヨファ…！\n"
.stringn "\x0713ミストちゃんが…\n"
.stringn "死んだら、いやだよ。\n"
.stringn "ぼく、もう…\n"
.stringn "誰も…亡くしたくな……\n"
.stringn "…　…　…\n"
.stringn "\x0701ヨファ、ごめん！\n"
.stringn "ごめんね…\n"
.stringn "\x0713…っ　…　…\n"
.stringn "\x0701ヨファが…かわったと思ったの。\n"
.stringn "優しい子だったのに、\n"
.stringn "人の死が…わからない…そんな\n"
.stringn "戦いかたをしてるのかと……\n"
.stringn "ごめんね…　わたし\n"
.stringn "ヨファの気持ち…\n"
.stringn "わかってあげられなくて…ごめんね…\n"
.stringn "戦うために必死だったんだね…\n"
.stringn "いっしょうけんめいだったんだね……\n"
.stringn "\x0713……ぼく…戦うよ…\n"
.stringn "もう１度…みんないっしょに\n"
.stringn "平和に暮らすために…\n"
.stringn "………戦う……\n"
.stringn "\x0701うん…\n"
.stringn "わたしも…\n"
.stringn "２人で…いっしょに……\n"
.stringn "がんばろ…ね？"
db 0
.align 4
//MYELL_8_LOFA_MIST_A

//0x26A60
Text_26A40:
.stringn "\x05FL|LOFA|MIST||\x0703……よ、と。\n"
.stringn "\x0714…ヨファ、ちょっといいかな？\n"
.stringn "\x0703あ、うん。\n"
.stringn "待ってて、弦のたるみを\n"
.stringn "なおしちゃわないと。\n"
.stringn "いざって時、困るからね。\n"
.stringn "\x0714……\n"
.stringn "\x0C03\x0C03\x0701おまたせ！\n"
.stringn "なに？　ミストちゃん。\n"
.stringn "\x0714ヨファ、もう\n"
.stringn "戦場に行くの、よそう？\n"
.stringn "やっぱり、わたしたちみたいな\n"
.stringn "子供が戦うの…よくないよ。\n"
.stringn "\x0701…え…\n"
.stringn "どうして急にそんなこというの？\n"
.stringn "\x0714どうしても！\n"
.stringn "お兄ちゃんにはわたしが言うから…\n"
.stringn "だから、前みたいに\n"
.stringn "２人でみんなの世話を…\n"
.stringn "\x0701…そうだね、\n"
.stringn "ミストちゃんは戦うの怖いって\n"
.stringn "言ってたし…\n"
.stringn "うん、戦場にでないほうがいいよ。\n"
.stringn "心配しなくても大丈夫！\n"
.stringn "ミストちゃんの分まで、ぼくが戦うよ。\n"
.stringn "\x0714ちがう！\n"
.stringn "ヨファがやめなきゃ、意味がないよ！！\n"
.stringn "\x0701そんなの無理だよ！\n"
.stringn "ぼくは男だから…\n"
.stringn "敵を倒して、みんなを守らないと…\n"
.stringn "\x0714倒すって…そんなに簡単に言わないで！\n"
.stringn "敵も人間なんだよ？\n"
.stringn "\x0701！！\n"
.stringn "\x0714ヨファ、それをわかってる？\n"
.stringn "敵も…わたしたちと同じ人間…\n"
.stringn "練習用の的なんかじゃない……\n"
.stringn "\x0701………………知らない…\n"
.stringn "\x0714ヨファ！\n"
.stringn "\x0701知らない！　…そんなの\n"
.stringn "ぼく知らないもん！！\n"
.stringn "敵はぼくらを傷つける悪者じゃないか！\n"
.stringn "ぼく、それを倒してるだけだ！\n"
.stringn "みんなを守ってるだけだ！！\n"
.stringn "\x0714待って、ヨファ！\n"
.stringn "……だめだよ…このままじゃ……"
db 0
.align 4
//MYELL_8_LOFA_MIST_B

//0x26750
Text_26730:
.stringn "\x05FL|MIST|LOFA||\x070-\x0C01\x0C13\x0701ヨファ！\n"
.stringn "ここにいたんだ？\n"
.stringn "\x0713ミストちゃん、\n"
.stringn "どうしたの？\n"
.stringn "ぼくをさがしてたの？\n"
.stringn "\x0701うん。\n"
.stringn "ヨファと話したいなって思って。\n"
.stringn "あれから…\n"
.stringn "はじめて戦った時から、\n"
.stringn "ヨファと話す機会、なかったから。\n"
.stringn "\x0713…無事でよかったね。\n"
.stringn "二人とも……生きてたね。\n"
.stringn "\x0701うん……本当によかった…\n"
.stringn "\x0713ぼくね、すごく胸がどきどきして\n"
.stringn "手がふるえちゃった。\n"
.stringn "\x0701わたしも……\n"
.stringn "まわりですごい声がして、\n"
.stringn "目の前がぐるぐる回って……\n"
.stringn "……すごく……怖かった。\n"
.stringn "\x0713ミストちゃんは\n"
.stringn "やっぱり女の子だね。\n"
.stringn "ぼくは全然、怖くなんかなかった。\n"
.stringn "緊張して…はじめは\n"
.stringn "うまく射れなかったけど、\n"
.stringn "最後のほうはちゃんと的に当てたよ！\n"
.stringn "\x0701え…？\n"
.stringn "\x0713次の戦いが待ち遠しいな。\n"
.stringn "今度はもっと上手く戦えるよ。\n"
.stringn "もっとたくさん\n"
.stringn "敵を倒してみせるからね！\n"
.stringn "さ、もっともっと練習しないと。\n"
.stringn "じゃあね、ミストちゃん。\n"
.stringn "\x0701あ、ヨファ！\n"
.stringn "………ヨファ…"
db 0
.align 4
//MYELL_8_LOFA_MIST_C

//0x27BBC
Text_27B9C:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713……やはり、わしは……\n"
.stringn "間違っておったのだろうな。\n"
.stringn "できることなら家族に……\n"
.stringn "一言詫びたかった。\n"
.stringn "\x0701……ねえ、おじさん。\n"
.stringn "おじさんの家族って\n"
.stringn "本当にどこにいるかわからないの？\n"
.stringn "何かちょっとでも、手がかりないの？\n"
.stringn "\x0713…………\n"
.stringn "……妻はデインを逃れ、\n"
.stringn "クリミアの親類を頼ったそうだ。\n"
.stringn "おそらくクリミアの地で\n"
.stringn "暮らしているのだろう……\n"
.stringn "\x0701そうなんだ！　だったら\n"
.stringn "会いにいけば……\n"
.stringn "\x0713……それはできぬ。\n"
.stringn "わしが今さら……どの顔を下げて\n"
.stringn "子供たちに会いにいけるというのか。\n"
.stringn "今さらわしが姿を見せたところで……\n"
.stringn "妻や子供らに迷惑をかけるだけだ。\n"
.stringn "\x0701そんなことないよ！\n"
.stringn "だって、ぼく……\n"
.stringn "ぼく、お父さんに会いたいもん！\n"
.stringn "\x0713……ヨファ。\n"
.stringn "\x0701お兄ちゃんたちには……\n"
.stringn "ぼく平気だよ、さびしくなんかないよって\n"
.stringn "いつも言ってた。\n"
.stringn "でも本当は、お父さんに会いたかった。\n"
.stringn "会っていろいろ話したかった……\n"
.stringn "\x0713……\n"
.stringn "\x0701でもぼくのお父さんは\n"
.stringn "死んじゃったから……もう会えない。\n"
.stringn "でもおじさんは、まだ生きてるんだよ？\n"
.stringn "\x0713そう……だな。\n"
.stringn "だが、もう遅い……\n"
.stringn "\x0701遅くなんかないよ……\n"
.stringn "だって、おじさんは生きてるんだもん。\n"
.stringn "その子たちはまだ、お父さんに\n"
.stringn "会えるんだから……\n"
.stringn "だから、会いに行ってあげてよ。\n"
.stringn "きっと、きっと待ってるはずだから……\n"
.stringn "\x0713……\n"
.stringn "………ヨファ……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_A

//0x276F4
Text_276D4:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713わしの家は代々デインにおいて\n"
.stringn "武門として名をなしていた。\n"
.stringn "父もわしも、デイン軍の将軍として\n"
.stringn "デイン王家に仕えてきた。\n"
.stringn "それが我が一族の誇りであった。\n"
.stringn "\x0701じゃあ、ジョシュさんも……？\n"
.stringn "\x0713わしは当然のように息子のジョシュを\n"
.stringn "デイン軍へやるつもりで育てた。\n"
.stringn "そしてジョシュもわしの期待に\n"
.stringn "応えようとしてくれた……と、そう思う。\n"
.stringn "最年少で騎士叙勲に任ぜられ、\n"
.stringn "親衛隊に配属されたのだ。\n"
.stringn "だが……\n"
.stringn "\x0701……どうしたの？\n"
.stringn "\x0713アシュナードの側近として出陣し……\n"
.stringn "息子は瀕死の重傷を\n"
.stringn "負って帰還してきた。\n"
.stringn "一命はとりとめたが……\n"
.stringn "……２度と歩くことのできぬ身となった。\n"
.stringn "\x0701…………そんな……\n"
.stringn "\x0713妻は気も狂わんばかりに嘆いた。\n"
.stringn "こんなことは２度とあっては生きていけぬと\n"
.stringn "わしに軍を退いて欲しい、\n"
.stringn "平和な暮らしがしたいと懇願した。\n"
.stringn "だがわしは、承服できなかった。\n"
.stringn "我が家は代々将軍として\n"
.stringn "名を上げてきたのだ。\n"
.stringn "このまま軍を捨てて逃げるなど、\n"
.stringn "今まで続いてきた我が家の\n"
.stringn "武門としての名が許さなかった。\n"
.stringn "わしはまだ年端のいかぬ次男を鍛え、\n"
.stringn "デイン軍の将として後を継がせることで\n"
.stringn "体面を保とうとした。\n"
.stringn "\x0701だめだよ、そんなこと……\n"
.stringn "\x0713そうだな……\n"
.stringn "だがあの時のわしは愚かだった。\n"
.stringn "そんなこともわからぬほどに。\n"
.stringn "……気がつけば、\n"
.stringn "妻と子供たちは我が家を去っていた。\n"
.stringn "それからわしは……\n"
.stringn "無数の勲章が飾られた屋敷で、\n"
.stringn "ただ１人暮らしてきた。\n"
.stringn "…………もう、何年も……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_B

//0x273B0
Text_27390:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713！\n"
.stringn "ジョシュ……？\n"
.stringn "\x0701え……？\n"
.stringn "\x0713……いや、そんなはずはない。\n"
.stringn "すまぬな、人違いだ。\n"
.stringn "……少年、きみの名は？\n"
.stringn "\x0701ヨファです。\n"
.stringn "\x0713ヨファ、きみのような子供が\n"
.stringn "なぜこんなところにいる？\n"
.stringn "戦場は幼子のいるべき場所ではない。\n"
.stringn "きみのご両親はなぜ\n"
.stringn "こんなことを許しているのだ？\n"
.stringn "\x0701ぼく……親はいません。\n"
.stringn "おかあさんは家から出て行って、\n"
.stringn "おとうさんは死んじゃったから……\n"
.stringn "\x0713そう……だったか。\n"
.stringn "すまぬな。\n"
.stringn "辛いことを思い出させた。\n"
.stringn "\x0701いいです。\n"
.stringn "今は、みんなと一緒だから。\n"
.stringn "……おじさん、\n"
.stringn "ぼくって誰かに似てるの？\n"
.stringn "\x0713わしの……息子だよ。\n"
.stringn "ジョシュは長男の名だ。\n"
.stringn "だがジョシュはもう成人を迎えている。\n"
.stringn "きみのような少年であったのは、\n"
.stringn "もう何年も前の話だ……\n"
.stringn "それを見間違えるとは……\n"
.stringn "わしももうろくしたものよ。\n"
.stringn "\x0701そのジョシュさん、\n"
.stringn "今はどこにいるの？\n"
.stringn "\x0713……わからぬ。\n"
.stringn "\x0701え？\n"
.stringn "\x0713わしは妻子と離縁した。\n"
.stringn "それ以来、\n"
.stringn "もう何年も会っていない……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_C

//0x28548
Text_28528:
.stringn "\x05FL|ULYSSES|LUCHINO||\x070-\x0C01\x0C13\x0701ルキノ殿、今日こそは\n"
.stringn "色好いお返事を\n"
.stringn "聞かせていただきますぞ。\n"
.stringn "\x0713ユリシーズ伯…\n"
.stringn "私は、あなたのその\n"
.stringn "ふざけた態度は表面だけだと知っている。\n"
.stringn "クリミアの忠臣として…\n"
.stringn "頼りにもしている。\n"
.stringn "そうね…悔しいけど、認めるわ。\n"
.stringn "私はあなたのことを好ましく思っている。\n"
.stringn "\x0701では、我輩の想いを\n"
.stringn "受け入れていただけるのですな？\n"
.stringn "\x0713…そうね。\n"
.stringn "この戦いが終わり……\n"
.stringn "無事、クリミアが再興したら\n"
.stringn "考えてみてもいいわ。\n"
.stringn "\x0701おお、ルキノ！\n"
.stringn "我が最愛の君よ！！\n"
.stringn "\x0713ユリシーズ…\n"
.stringn "まったく憎めない人ね。\n"
.stringn "あ、いけない。\n"
.stringn "エリンシア様のお支度を\n"
.stringn "手伝いに行く時間だわ。\n"
.stringn "\x0701ま、待ちたまえ。ルキノ！\n"
.stringn "今宵の予定は？\n"
.stringn "よければ我輩と共に…\n"
.stringn "\x0713ごめんなさい。\n"
.stringn "エリンシア様の御用があるの。\n"
.stringn "当分、時間は作れないわ。\n"
.stringn "\x0701やれ…　まだまだ\n"
.stringn "前途多難でありますな。"
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_A

//0x282B8
Text_28298:
.stringn "\x05FL|LUCHINO|ULYSSES||\x0701ユリシーズ伯！\n"
.stringn "ど、どこにいるの！？\n"
.stringn "\x071-\x0713これは、ルキノ殿…\n"
.stringn "あなたらしくもない、\n"
.stringn "何をそのように慌てて…\n"
.stringn "\x0701け、怪我は？\n"
.stringn "大丈夫なの！？\n"
.stringn "\x0713はて、我輩の体には\n"
.stringn "特に不自由なところは\n"
.stringn "ありはせぬようですが？\n"
.stringn "\x0701……そうなの…\n"
.stringn "いかれた格好をした\n"
.stringn "ちょび髭の道化師が\n"
.stringn "大怪我をしたって聞いたから…\n"
.stringn "てっきり、あなたのことだと…\n"
.stringn "違ったのね……\n"
.stringn "\x0713…ルキノ殿、\n"
.stringn "我輩を心配するあまり…\n"
.stringn "そのように慌てていらしたのか。\n"
.stringn "なんと可愛らしい方だ。\n"
.stringn "\x0701え！？\n"
.stringn "ち、違…\n"
.stringn "\x0713もう隠しても無駄ですぞ。\n"
.stringn "貴女のお気持ち、\n"
.stringn "しかと受け止めましたからな。\n"
.stringn "\x0701違うと言ってるでしょう！？\n"
.stringn "\x0713誤魔化せば誤魔化すほど\n"
.stringn "表に出るのが恋心なれば。\n"
.stringn "\x0701もう！　人の話を聞きなさい！！"
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_B

//0x28020
Text_28000:
.stringn "\x05FL|ULYSSES|LUCHINO||\x070-\x0C01\x071-\x0713あらユリシーズ伯。\n"
.stringn "ごきげんよう。\n"
.stringn "\x0701おお…　ルキノ殿。\n"
.stringn "その麗しき御手をしばし拝借し、\n"
.stringn "ご挨拶をさせていただく\n"
.stringn "栄誉を与えていただけるでしょうか？\n"
.stringn "\x0713ごめんなさい。\n"
.stringn "さっきまで剣の手入れをしていたから\n"
.stringn "指先が油まみれだわ。\n"
.stringn "\x0701我輩はいっこうに構いませんが？\n"
.stringn "\x0713私が構うの。\n"
.stringn "悪いけど遠慮してちょうだい。\n"
.stringn "\x0701ふぅ　素気無くされれば\n"
.stringn "尚のこと心惹かれ…\n"
.stringn "逃げる素振りをなされば\n"
.stringn "追いたくなるのが人の常。\n"
.stringn "いつまでこの哀れなる\n"
.stringn "恋の下僕を虜となすおつもりですかな。\n"
.stringn "我が心の主、ルキノ殿。\n"
.stringn "\x0713私を…他の貴婦人と同じく\n"
.stringn "その手管にひっかかるものだと\n"
.stringn "思わないことだわ。\n"
.stringn "いい加減、諦めたらいかが？\n"
.stringn "しつこい殿方は嫌われてよ。\n"
.stringn "\x0701いやはやこれは手厳しい。"
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_C

//0x292AC
Text_2928C:
.stringn "\x05FL|STELLA|?|MAKAROV||\x0705……\n"
.stringn "\x0718お～い。\n"
.stringn "ステラさん！\n"
.stringn "\x0705！\n"
.stringn "\x0C23\x0C05\x0C05\x0701ごきげんよう。\n"
.stringn "マカロフ様。\n"
.stringn "\x0723これ、返すよ。\n"
.stringn "\x0701…このペンダントに\n"
.stringn "なにか問題がありましたか？\n"
.stringn "\x0723いや、すっごい\n"
.stringn "いい品だったよ。\n"
.stringn "最低でも５０００ゴールドは\n"
.stringn "ふっかけられそうだったのに…\n"
.stringn "\x0701では、なぜ…\n"
.stringn "\x0723古物屋に持ち込んだところで、\n"
.stringn "妹にばったり出くわしちゃってさ。\n"
.stringn "どこで手に入れたんだ、とか、\n"
.stringn "盗んだんじゃないのか、とか…\n"
.stringn "色々と問い詰められて…\n"
.stringn "\x0701これは…私が\n"
.stringn "マカロフ様に差し上げたものですわ。\n"
.stringn "\x0723もちろんそう言ったさ。でも…\n"
.stringn "女の人にたかるなんて最低！\n"
.stringn "っとか、泣き出しちゃって…\n"
.stringn "だからまあ、諦めようかなって。\n"
.stringn "\x0701そうですか…\n"
.stringn "わかりました。\n"
.stringn "\x0723それにしても、\n"
.stringn "あんたは恵まれてるよなあ。\n"
.stringn "そんな高価なペンダントを\n"
.stringn "ポンと惜しげもなく人にくれてやれるんだ。\n"
.stringn "うちの妹なんか、安物の１つだって\n"
.stringn "持ってやしないってのにさ。\n"
.stringn "あ～あ。女神様は不公平だよ。\n"
.stringn "貴族ばっかりひいきしてさ。\n"
.stringn "\x0701…す…すみません……\n"
.stringn "\x0723いや、別に\n"
.stringn "あんたに謝ってもらいたいわけじゃ…\n"
.stringn "\x0701このペンダントは…\n"
.stringn "そんなに高価なものだったのですね？\n"
.stringn "…私…これは…大好きなおばあさまの\n"
.stringn "形見だったから身に着けていただけで……\n"
.stringn "何も…知らなくて……\n"
.stringn "\x0723げ！　形見っ！？\n"
.stringn "ど、どうしてそんな大事なもんを\n"
.stringn "おれなんかに…\n"
.stringn "\x0701このペンダントを手放しても…\n"
.stringn "おばあさまの想い出は…\n"
.stringn "私の胸の中に残っています。\n"
.stringn "ですから…　困っている方の\n"
.stringn "お役に立てるほうがよいと考えました。\n"
.stringn "\x0723あ…あんたって人は……\n"
.stringn "すまんっ！　本っ当にすまなかった！！\n"
.stringn "おれは賭け事のために\n"
.stringn "あんたに金をたかった悪人なのに…\n"
.stringn "心の底から反省してる。\n"
.stringn "すいません！　許してください！！\n"
.stringn "\x0701そんな…\n"
.stringn "マカロフ様、私\n"
.stringn "なにも気にしていませんわ。\n"
.stringn "\x0723ステラさん…　あんた\n"
.stringn "女神様より優しい女だなあ。\n"
.stringn "\x0701………そ…\n"
.stringn "そんなことありませんわ。\n"
.stringn "\x0723いやあ。もう真剣に\n"
.stringn "目の前が眩しいから。\n"
.stringn "\x0701からかわないで下さい。\n"
.stringn "マカロフ様のような\n"
.stringn "素敵な男性に…\n"
.stringn "そんな風に見つめられては…\n"
.stringn "…私……はずかしいです…\n"
.stringn "\x0723へ？\n"
.stringn "ステキって…おれが？\n"
.stringn "\x0701や、やだ…\n"
.stringn "…私ったら…はしたない…！\n"
.stringn "し、失礼しますっ！！\n"
.stringn "\x0723…………………\n"
.stringn "……ああいう育ち方すると、\n"
.stringn "男を見る目も育たないんだろうなあ。\n"
.stringn "かわいそうに……"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_A_a

