//0x28E88
Text_28E68:
.stringn "\x05FL|MAKAROV|STELLA||\x0C01\x071-\x0713ご、ごきげんよう。\n"
.stringn "マカロフ様。\n"
.stringn "\x0701やあ、ステラさん。\n"
.stringn "あんたとは、よく会うなあ。\n"
.stringn "よっぽど縁があるのかもねえ～。\n"
.stringn "\x0713そ、そうでしょうか。\n"
.stringn "だとすれば…光栄です。\n"
.stringn "\x0701縁といえばさ、\n"
.stringn "ちょっと頼みがあるんだけど。\n"
.stringn "\x0713なんですか？\n"
.stringn "私にできることでしたら、なんでも。\n"
.stringn "\x0701金貸してもらえないかなあ？\n"
.stringn "\x0713お金…ですか？\n"
.stringn "\x0701そう、ほんのちょっとでいいんだけど。\n"
.stringn "なんとかならないか？\n"
.stringn "\x0713……どうしましょう。\n"
.stringn "私、お金は１ゴールドも\n"
.stringn "持っていませんわ。\n"
.stringn "\x0701たったの１ゴールドも？\n"
.stringn "この軍でもらった給料、\n"
.stringn "なんに使ったんだい。\n"
.stringn "\x0713町にでた時に…\n"
.stringn "とても困っている方がいらしたので…\n"
.stringn "差し上げてしまいました。\n"
.stringn "\x0701うわっ　信じられねえよ。\n"
.stringn "同じ施すなら、外じゃなくて\n"
.stringn "身内にやってくれればいいのに。\n"
.stringn "まったく…\n"
.stringn "\x0713す、すみません。\n"
.stringn "マカロフ様がお困りだとは\n"
.stringn "存じ上げなかったものですから…\n"
.stringn "\x0701う～…　わかったよ。\n"
.stringn "じゃあ他を当たるかあ。\n"
.stringn "\x0713ま、待ってください。\n"
.stringn "\x0701あ～？\n"
.stringn "\x0713これでは、だめでしょうか。\n"
.stringn "\x0701お！　なんだよ\n"
.stringn "見るからに高そうなペンダントだ！\n"
.stringn "これ、もらっていいのかい？\n"
.stringn "\x0713はい。\n"
.stringn "\x0701く～　ありがとよ！\n"
.stringn "あんたいい女だねえ。\n"
.stringn "じゃあな！　またな！！\n"
.stringn "\x0713………"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_B

//0x28828
Text_28808:
.stringn "\x05FL|STELLA|MAKAROV||\x070-\x0C01\x0C13\x0701ごきげんよう、騎士様。\n"
.stringn "\x0713へ？　あ、ああ…\n"
.stringn "おれに挨拶してんのかい？\n"
.stringn "\x0701はい。\n"
.stringn "私、ステラと申します。\n"
.stringn "騎士様のお名前は？\n"
.stringn "\x0713騎士様ってほどのもんじゃないけど…\n"
.stringn "おれはマカロフ。\n"
.stringn "よろしく頼むよ、ステラさん。\n"
.stringn "\x0701こちらこそ。\n"
.stringn "それで…　マカロフ様。\n"
.stringn "これを落とされましたわ。\n"
.stringn "\x0713あれ、いつの間に…\n"
.stringn "\x0701きれいなお花ですね。\n"
.stringn "\x0713だろ。その辺に咲いてたにしては、\n"
.stringn "結構見れるよな？\n"
.stringn "\x0701まあ、ご自分で摘まれたのですか？\n"
.stringn "マカロフ様はとても風雅な\n"
.stringn "ご趣味をお持ちなのですね。\n"
.stringn "\x0713いや、なんつーか。\n"
.stringn "妹のご機嫌取りにね、ちょっとだけ。\n"
.stringn "\x0701優しいお兄様なんですね。\n"
.stringn "いけない、このお花が枯れる前に\n"
.stringn "持ち主のお手にお返ししなくては。\n"
.stringn "どうぞ。\n"
.stringn "\x0713ああ、いいよ別に１本ぐらい。\n"
.stringn "\x0701…え。\n"
.stringn "\x0713拾ってもらったお礼。\n"
.stringn "あんたによく似合ってるし。\n"
.stringn "んじゃあ、失礼するよ～。\n"
.stringn "\x0701あ、ありがとうございます！\n"
.stringn "…………マカロフ様。"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_C_a

//0x28B58
Text_28B38:
.stringn "\x05FL|STELLA|MAKAROV||\x070-\x0C01\x0C13\x0701ごきげんよう、騎士様。\n"
.stringn "\x0713へ？　あ、ああ…\n"
.stringn "おれに挨拶してんのかい？\n"
.stringn "\x0701はい。\n"
.stringn "私、ステラと申します。\n"
.stringn "騎士様のお名前は？\n"
.stringn "\x0713騎士様ってほどのもんじゃないけど…\n"
.stringn "おれはマカロフ。\n"
.stringn "よろしく頼むよ、ステラさん。\n"
.stringn "\x0701こちらこそ。\n"
.stringn "それで…　マカロフ様。\n"
.stringn "これを落とされましたわ。\n"
.stringn "\x0713あれ、いつの間に…\n"
.stringn "\x0701きれいなお花ですね。\n"
.stringn "\x0713だろ。その辺に咲いてたにしては、\n"
.stringn "結構見れるよな？\n"
.stringn "\x0701まあ、ご自分で摘まれたのですか？\n"
.stringn "マカロフ様はとても風雅な\n"
.stringn "ご趣味をお持ちなのですね。\n"
.stringn "\x0713いや、なんつーか。\n"
.stringn "死んだ妹のためにね、ちょっとだけ。\n"
.stringn "\x0701優しいお兄様なんですね。\n"
.stringn "いけない、このお花が枯れる前に\n"
.stringn "持ち主のお手にお返ししなくては。\n"
.stringn "どうぞ。\n"
.stringn "\x0713ああ、いいよ別に１本ぐらい。\n"
.stringn "\x0701…え。\n"
.stringn "\x0713拾ってもらったお礼。\n"
.stringn "あんたによく似合ってるし。\n"
.stringn "んじゃあ、失礼するよ～。\n"
.stringn "\x0701あ、ありがとうございます！\n"
.stringn "…………マカロフ様。"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_C_b

//0x2AD9C
Text_2AD7C:
.stringn "\x05FL|MAKAROV|ULYSSES||\x0C01\x071-\x0713どうしたのだ、マカロフ？\n"
.stringn "\x0701………\n"
.stringn "\x0713君の情熱と根気に負け、\n"
.stringn "こうして共に足を運び、遊び\n"
.stringn "賭場を後にした今…\n"
.stringn "何が君にそのような\n"
.stringn "渋面を作らせているのかな？\n"
.stringn "\x0701ユリシーズ…\n"
.stringn "あんた、おれに嘘ついてたろう？\n"
.stringn "\x0713はて？\n"
.stringn "我輩が君に嘘をつく理由など\n"
.stringn "ありはしないと思うのだが。\n"
.stringn "\x0701賭場に行ったことないって\n"
.stringn "言ってたよな。\n"
.stringn "けど、あんたメチャクチャ\n"
.stringn "慣れてて…しかも強かった。\n"
.stringn "おれはボロ負けだったのに、\n"
.stringn "あんたは大儲け。\n"
.stringn "くさるなってほうがむりだよ。\n"
.stringn "\x0713嘘はついておらぬさ。\n"
.stringn "賭場に足を踏み入れたのは\n"
.stringn "我が生涯において\n"
.stringn "これが最初なのだから。\n"
.stringn "ただ…　貴族の遊戯にも\n"
.stringn "同じような賭け事があり、\n"
.stringn "我輩はそれに通じていた。\n"
.stringn "それだけのからくりなのだよ。\n"
.stringn "\x0701くそぉ　金持ちが\n"
.stringn "もっと金儲けるなんて\n"
.stringn "世の中、間違ってるっ！\n"
.stringn "\x0713我輩にとって…手にした\n"
.stringn "ゴールドにはあまり意味がない。\n"
.stringn "君が今回の戦の運試しだというので\n"
.stringn "付き合ったまで。\n"
.stringn "しかして、勝負には圧勝した。\n"
.stringn "素晴らしい結果を得られることができ\n"
.stringn "我輩は至極満足だよ。\n"
.stringn "\x0701じゃあ、金はいらないのか？\n"
.stringn "だったらおれがもらって…\n"
.stringn "\x0713そうはいかぬよ。\n"
.stringn "戦はとにかく金のかかるもの。\n"
.stringn "貯えは多いに越したことはない。\n"
.stringn "\x0701…心配しなくても、\n"
.stringn "今回の戦はクリミアの勝ちだよ。\n"
.stringn "\x0713ほう？　なぜそう思うのか\n"
.stringn "聞かせてもらえるかね？\n"
.stringn "\x0701あんたみたいな強運の男が\n"
.stringn "ついてるんだ。\n"
.stringn "２回も続けて負けるわけがないよ。\n"
.stringn "\x0713なるほど。\n"
.stringn "君には先見の明があるようだ。\n"
.stringn "\x0701だからさ、金はおれに…\n"
.stringn "\x0713クリミアがこの戦に勝利すれば\n"
.stringn "我輩がいくらでも\n"
.stringn "君の懐を潤してやろうではないか。\n"
.stringn "\x0701ほ、ほんとうか！？\n"
.stringn "\x0713我輩はできぬ約束はしない。\n"
.stringn "嘘もつく必要もない。\n"
.stringn "稼ぐ手段はいくらでも\n"
.stringn "持ち合わせているのだからな。\n"
.stringn "\x0701よ、よ～し！\n"
.stringn "一世一代の大博打だとおもって\n"
.stringn "がんばってみるかなあ。"
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_A

//0x2A910
Text_2A8F0:
.stringn "\x05FL|MAKAROV|ULYSSES||\x070-\x0C01\x071-\x0C13\x0701なあ、ユリシーズ殿。\n"
.stringn "おれとあんたは、もう友達だよなあ？\n"
.stringn "\x0713無論だ。\n"
.stringn "何度も酒を酌み交わし…\n"
.stringn "互いの氏素性も語り合った。\n"
.stringn "我輩と君が友好を築くのに、\n"
.stringn "もはや何の障害もあるまい。\n"
.stringn "\x0701じゃあさ、今からいっしょに\n"
.stringn "面白い遊びをしに行こうぜ。\n"
.stringn "ユリシーズが知らないような、\n"
.stringn "庶民の遊びなんだけど。\n"
.stringn "これが結構はまるんだよ。\n"
.stringn "\x0713ほほう。庶民の遊戯…\n"
.stringn "して、それは\n"
.stringn "どのようなものであろうか？\n"
.stringn "\x0701単純なもんさ。\n"
.stringn "金を賭けて、伏せられた木の札に\n"
.stringn "描かれている模様を当てる。\n"
.stringn "正解すれば配当金がもらえるし、\n"
.stringn "はずれれば金を失う。それだけだ。\n"
.stringn "\x0713なるほど。\n"
.stringn "マカロフは、我輩を\n"
.stringn "賭場に誘おうという魂胆であるか。\n"
.stringn "\x0701ぎくっ　な、なんだよ…\n"
.stringn "あんたもしかして\n"
.stringn "賭場に行ったことあんのか？\n"
.stringn "\x0713いや、知識として持っておるだけで\n"
.stringn "実際に足を踏み入れたことは\n"
.stringn "ついぞないが。\n"
.stringn "ふむ、興味がないではないな。\n"
.stringn "\x0701じゃあ、おれが案内するから\n"
.stringn "行ってみようぜ。\n"
.stringn "あんたぐらい金持ちなら\n"
.stringn "たっぷり遊んでもお釣りがくるから\n"
.stringn "初めてでも心配いらないし。\n"
.stringn "\x0713…いや、我輩は遠慮しておこう。\n"
.stringn "\x0701ええっ！？　どうして？\n"
.stringn "\x0713祖国の大事に、賭け事に\n"
.stringn "うつつをぬかすわけには参らぬさ。\n"
.stringn "さて、そろそろ失礼しよう。\n"
.stringn "君もあまり羽目をはずさぬよう\n"
.stringn "自戒の念を忘れぬことだ。\n"
.stringn "\x0701ああ！　…行っちまった。\n"
.stringn "おれの財布……"
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_B

//0x2A1FC
Text_2A1DC:
.stringn "\x05FL|ULYSSES|MAKAROV|?|CRIMEA1||\x0C05\x071-\x0713へえ～　この軍って、\n"
.stringn "大道芸人を呼べるぐらいの余裕\n"
.stringn "あったんだねえ。\n"
.stringn "あのデインを相手にまわして戦ってるんだ。\n"
.stringn "もっと殺伐としてるかと思ってたよ。\n"
.stringn "\x0705…ふむ。\n"
.stringn "\x0701今の言動は、もしや我輩に向かって\n"
.stringn "発せられたものであろうかな？\n"
.stringn "ベグニオンの傭兵騎士マカロフ殿。\n"
.stringn "\x0713おわっ！？\n"
.stringn "な、なんで大道芸人が\n"
.stringn "おれの名前を…って\n"
.stringn "ああそうか。\n"
.stringn "あんた、そういう芸なんだ？\n"
.stringn "当てものが売りなんだろ？\n"
.stringn "だとしたら、中々いい腕してるなあ。\n"
.stringn "今の正解だからさ。\n"
.stringn "\x0701我輩を大道芸人と評されるか。\n"
.stringn "さもありなん。\n"
.stringn "仮初めの姿なれど、一時は\n"
.stringn "それを生業としていたのだ。\n"
.stringn "嗚呼、その月日を思えば\n"
.stringn "この後待受ける苦難もなんのその。\n"
.stringn "祖国解放の夜明けまで、\n"
.stringn "我輩はこの身を\n"
.stringn "如何様にも変化させん…\n"
.stringn "\x0713はは　あんた\n"
.stringn "面白いやつだなあ。\n"
.stringn "今夜にでも、おれの天幕に\n"
.stringn "飲みにこないか？\n"
.stringn "\x0701魅力的な申し出ながら、\n"
.stringn "今宵は先約があるのだ。\n"
.stringn "別の機会に、こちらから\n"
.stringn "お誘い申し上げようと思うのだが。\n"
.stringn "それでいかがかな？\n"
.stringn "\x0713そっちがいいなら、\n"
.stringn "おれはそれでも構わないよ。\n"
.stringn "\x0701意見の一致をみましたな。\n"
.stringn "では、失礼。\n"
.stringn "\x0713は～　これまで\n"
.stringn "見たことないような男だなあ。\n"
.stringn "次に会うのが楽しみだ。\n"
.stringn "\x0728こら！　貴様っ！！\n"
.stringn "\x0713ん～？\n"
.stringn "\x0C11\x0C34\x0711おれになんか用かい、\n"
.stringn "クリミアの兵隊さん。\n"
.stringn "\x0734気の抜けた返事をするな！\n"
.stringn "貴様も、今はクリミア軍に\n"
.stringn "所属しているだろうがっ！？\n"
.stringn "\x0711あ、そっか。\n"
.stringn "アイクさんがクリミア軍の\n"
.stringn "総大将になったから、\n"
.stringn "おれも自動的にクリミア兵かあ。\n"
.stringn "はは　あんたのお仲間だ。\n"
.stringn "\x0734ふざけた男だ…\n"
.stringn "アイク将軍お抱えの\n"
.stringn "傭兵団の一員であるから\n"
.stringn "ここは見逃すが……\n"
.stringn "１つだけ忠告しておくぞ。\n"
.stringn "貴様が、先ほど話していた相手は\n"
.stringn "フェール伯爵であるぞ！\n"
.stringn "\x0711へ？\n"
.stringn "\x0734フェール伯ユリシーズ殿は、\n"
.stringn "亡き王弟殿下の筆頭文官を\n"
.stringn "勤められるほどの、\n"
.stringn "クリミア王宮の重鎮なのだ。\n"
.stringn "貴様ごときが、気安く\n"
.stringn "口をきいてよい相手ではない。\n"
.stringn "わかったら、今後、\n"
.stringn "態度をあらためるようにしろ。\n"
.stringn "よいな！？\n"
.stringn "\x0711あの大道芸人が…\n"
.stringn "クリミアの貴族？\n"
.stringn "………だとすれば、\n"
.stringn "いい金づるになるかもしれないなあ。\n"
.stringn "付き合って損なしだ。"
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_C

//0x2BCB4
Text_2BC94:
.stringn "\x05FL|TANIS|MARCIA||\x0C01\x0713ですからその……\n"
.stringn "懲罰はできることなら\n"
.stringn "勘弁していただきたいと……\n"
.stringn "\x0701脱走には最も重い懲罰を与えるのが鉄則だ。\n"
.stringn "おまえにだけ特例、というわけにはいかん。\n"
.stringn "\x0713はぁ……\n"
.stringn "副長のいじわる……\n"
.stringn "\x0701なぜ私が意地悪なのだ！\n"
.stringn "私はおまえが脱走したから……\n"
.stringn "\x0713だって、副長は\n"
.stringn "いつもそうじゃないですか。\n"
.stringn "シグルーン隊長と違って、\n"
.stringn "私たちのこと褒めてくれたことなんて\n"
.stringn "１度もなかったし……\n"
.stringn "こっちの事情も察してくれてるようで\n"
.stringn "そうでないし……\n"
.stringn "\x0701まったく、わからん奴だな。\n"
.stringn "なぜ私がおまえに\n"
.stringn "ここまで言うと思っている！\n"
.stringn "\x0713え？\n"
.stringn "\x0701他の団員ならばここまでのことはしない。\n"
.stringn "マーシャ、私は\n"
.stringn "おまえに期待していたのだ。\n"
.stringn "おまえならば将来隊長や私の後を継いで、\n"
.stringn "騎士団をまとめてくれると思っていた。\n"
.stringn "\x0713ええ！？\n"
.stringn "な、なんで急に\n"
.stringn "そんなこと言い出すんですか？\n"
.stringn "ベグニオンにいた頃は\n"
.stringn "そんなこと一言も……\n"
.stringn "\x0701当たり前だ！\n"
.stringn "私の口からそんなことが言えるものか。\n"
.stringn "だがやむをえん。\n"
.stringn "私から隊長に進言して、\n"
.stringn "騎士団に復帰できるようとりはからってもらう。\n"
.stringn "脱走は不問に付す。だから戻って来い。\n"
.stringn "\x0713副長……\n"
.stringn "あ……ありがとうございます！"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_A

//0x2B884
Text_2B864:
.stringn "\x05FL|TANIS|MARCIA||\x0701マーシャ！\n"
.stringn "\x0713ひぃっ！？\n"
.stringn "ふ、副長……！\n"
.stringn "\x0701みっともない悲鳴をあげるな。\n"
.stringn "かつての上官相手に。\n"
.stringn "\x0713だ、だって副長……\n"
.stringn "まだ怒ってますか？\n"
.stringn "\x0701もちろんだ。\n"
.stringn "マーシャ、おまえが騎士団を\n"
.stringn "離れた理由は何だ？\n"
.stringn "おまえは任務の厳しさに耐えかねて\n"
.stringn "逃げ出すような軟弱者ではなかった。\n"
.stringn "異性との色恋沙汰に\n"
.stringn "うつつをぬかすような女でもない。\n"
.stringn "なぜ私に一言の相談もなく団を離れたのだ？\n"
.stringn "\x0713実はその～……\n"
.stringn "兄が、借金をたくさん作って……\n"
.stringn "行方不明になってしまったんです。\n"
.stringn "\x0701借金……？\n"
.stringn "\x0713それで、代わりに私に対して\n"
.stringn "兵舎に取立てが来るようになったから\n"
.stringn "兄の行方を捜そうと思って。\n"
.stringn "その途中でアイクさんたちと出会って、\n"
.stringn "海賊から助けてもらったのを縁に\n"
.stringn "ご一緒させてもらうようになりました。\n"
.stringn "でも兄はやっぱり見つからなくって……\n"
.stringn "\x0701……\n"
.stringn "\x0713それで、アイクさんについて行って\n"
.stringn "あちこち旅をすれば、\n"
.stringn "兄の行方がわかるかもしれないと思って。\n"
.stringn "今に至るわけです……\n"
.stringn "\x0701……なるほど。話はわかった。\n"
.stringn "まさか借金苦で夜逃げだったとは……\n"
.stringn "かつての上官として、\n"
.stringn "多少なりと同情を禁じえん。\n"
.stringn "\x0713じゃ、じゃあ……\n"
.stringn "\x0701だが脱走は脱走だ。\n"
.stringn "ここでの任務が終われば、おまえを\n"
.stringn "罰することにかわりはない。\n"
.stringn "\x0713そ、そんなあ……"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_B

//0x2B3BC
Text_2B39C:
.stringn "\x05FL|TANIS|MARCIA||\x0C01\x0713あ……あれ？\n"
.stringn "\x0701……ひさしぶりだな、マーシャ。\n"
.stringn "\x0713タ、タニス副長！？\n"
.stringn "ど……どうしてここに？\n"
.stringn "\x0701それは私の台詞だ。\n"
.stringn "私は親衛騎士団の副長として\n"
.stringn "勅命を受けてこの任についている。\n"
.stringn "まさかその先で\n"
.stringn "かつての部下に会おうとはな。\n"
.stringn "\x0713そ、そうだったんですね！\n"
.stringn "副長がデインに入ってから一緒だったなんて\n"
.stringn "全然気づきませんでした！\n"
.stringn "すごい偶然ですね、はい！\n"
.stringn "\x0701ああ。可愛い部下に\n"
.stringn "ようやく出会えて嬉しいぞ。\n"
.stringn "私は長い間、\n"
.stringn "おまえの行方を追っていたからな……\n"
.stringn "\x0713ふ、副長、\n"
.stringn "目が笑ってません……けど……\n"
.stringn "もしかして……怒ってます？\n"
.stringn "\x0701ああ、おまえは正しい。\n"
.stringn "私はとても怒っているとも。\n"
.stringn "無断でベグニオン天馬騎士団を離れた\n"
.stringn "脱走兵マーシャにどんな罰を\n"
.stringn "下すべきか考えているところだ。\n"
.stringn "\x0713だ、脱走じゃないですよっ！\n"
.stringn "ちゃんと『やめます』って\n"
.stringn "手紙に書き残して……\n"
.stringn "\x0701おまえは子供か！\n"
.stringn "あんな走り書き１つで\n"
.stringn "除隊が認められると思っているのか！\n"
.stringn "ベグニオン騎士団員の重みを知れ！\n"
.stringn "\x0713す、す……すみません！\n"
.stringn "でもあの、あの時は急いでたから……\n"
.stringn "\x0701……シグルーン隊長は優しい方だ。\n"
.stringn "おまえが隊を離れた件については\n"
.stringn "不問に付そうと仰っておられる。\n"
.stringn "\x0713ほっ……\n"
.stringn "\x0701だが私が反対した。\n"
.stringn "なんとしてでも私が連れ戻し、\n"
.stringn "しかるべき罰を受けさせると報告してある。\n"
.stringn "覚悟しておけ。\n"
.stringn "\x0713あ！　私、急用思い出しました！\n"
.stringn "……失礼します！\n"
.stringn "\x0701こら、\n"
.stringn "また逃げるのかマーシャ！"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_C

//0x2C61C
Text_2C5FC:
.stringn "\x05FL|MORDY|MIST||\x0C01\x071-\x0713あれ、モゥディさん。\n"
.stringn "どうかした？\n"
.stringn "\x0701ミスト。\n"
.stringn "アイクはどこだろう？\n"
.stringn "\x0713あ、お兄ちゃんなら\n"
.stringn "ティアマトさんたちと一緒かな？\n"
.stringn "でもそのうちここにも来ると思うよ。\n"
.stringn "\x0701ワかった。\n"
.stringn "……ミストとアイクは仲がイいのか？\n"
.stringn "\x0713えーっと、どうかな。\n"
.stringn "普通だと思うよ？\n"
.stringn "\x0701アイクは良いベオクだ。\n"
.stringn "会ったバかりのモゥディと、\n"
.stringn "スぐに打ち解けた。\n"
.stringn "ベオクなのに、\n"
.stringn "マるで獣牙族の同胞のヨうだ。\n"
.stringn "アイクはスごいと思う。\n"
.stringn "\x0713あはは　そうかな？\n"
.stringn "お兄ちゃんはちょっと変だから。\n"
.stringn "\x0701ソうなのか？　デもモゥディは\n"
.stringn "アイクのコとが好きだぞ。\n"
.stringn "……ミスト。\n"
.stringn "今ダからモゥディはミストに言う。\n"
.stringn "笑わナいで欲しい。\n"
.stringn "\x0713え？　何？\n"
.stringn "\x0701最初、ミストに洗濯物を渡す時、\n"
.stringn "本当はモゥディも怖かった。\n"
.stringn "\x0713怖かった……？\n"
.stringn "モゥディさんが？\n"
.stringn "\x0701ソうだ。ミストに拒絶されるノが怖かった。\n"
.stringn "怯えサせてシまうのデはナいかと怖かった。\n"
.stringn "ドキドキして、トても緊張してイた。\n"
.stringn "\x0713なんだ……そうだったんだ。\n"
.stringn "ふふ　なんだかおかしいな。\n"
.stringn "おんなじだね、わたしと。\n"
.stringn "\x0701アあ、オんなじだ。"
db 0
.align 4
//MYELL_8_MIST_MORDY_A

//0x2C2F4
Text_2C2D4:
.stringn "\x05FL|MORDY|MIST||\x070-\x0C01\x071-\x0713モゥディさん！　こんにちは！\n"
.stringn "\x0701ミスト、元気がイいな。\n"
.stringn "\x0713うん、わたし\n"
.stringn "元気いっぱいだよ！\n"
.stringn "\x0701イいコとだ。\n"
.stringn "\x0713あのね、わたし、\n"
.stringn "わたしって、性格は明るい方だと思うの！\n"
.stringn "趣味は洗濯とか掃除とか、\n"
.stringn "でもちょっとお裁縫は苦手で、それから…\n"
.stringn "\x0701アあ。\n"
.stringn "\x0713それでそれで……\n"
.stringn "あとなんだっけ？\n"
.stringn "え、えっと、\n"
.stringn "えっと…………\n"
.stringn "\x0701ミスト。\n"
.stringn "ユっくりで、イい。\n"
.stringn "\x0713え……\n"
.stringn "\x0701ミストはラグズと話した経験が少ない。\n"
.stringn "ダから、怖いノは分かる。\n"
.stringn "ダが気持ちはモう、伝わった。\n"
.stringn "ミストは心から、モゥディたちと\n"
.stringn "親しくナろうとシてクれてイる……\n"
.stringn "ヨく分かった。\n"
.stringn "\x0713…………\n"
.stringn "\x0701ダから、無理しなくてイい。\n"
.stringn "お互いに、\n"
.stringn "少しズつ慣れてイけばイい。\n"
.stringn "モゥディも、ミストと同じ気持ちで\n"
.stringn "イるのダから。\n"
.stringn "\x0713モゥディさん……\n"
.stringn "うん……ありがとう。\n"
.stringn "なんか、すごく楽になったよ。\n"
.stringn "そうだよね、無理しないで\n"
.stringn "自然にするのが１番だよね。\n"
.stringn "\x0701アあ。"
db 0
.align 4
//MYELL_8_MIST_MORDY_B

//0x2C098
Text_2C078:
.stringn "\x05FL|MIST|MORDY||\x0708まってー\n"
.stringn "まってってばー！\n"
.stringn "\x0703あれ？　あれれ？\n"
.stringn "どこに行ったんだろう……\n"
.stringn "確かこのへんに……\n"
.stringn "\x0711コれか？\n"
.stringn "\x0703わ！\n"
.stringn "モ、モゥディさん……\n"
.stringn "びっくりしたぁ。\n"
.stringn "\x0711スまない。驚かセた。\n"
.stringn "ソこで拾った。\n"
.stringn "コれはミストの探し物か？\n"
.stringn "\x0703あ……う、うん、\n"
.stringn "取り込んだ洗濯物が\n"
.stringn "飛んで逃げちゃって……\n"
.stringn "ありがと、モゥディさん。\n"
.stringn "\x0711ドうイたしまして。\n"
.stringn "\x0703あ……あの、モゥディさん。\n"
.stringn "\x0711ナんだ？\n"
.stringn "\x0703え……っとその……ええと。\n"
.stringn "……ごめん、何でもない。\n"
.stringn "\x0711ワかった。\n"
.stringn "ジゃあ、モゥディはモう行く。\n"
.stringn "\x0703はぁ……\n"
.stringn "あたしってだめだなぁ、もう……\n"
.stringn "なんでお兄ちゃんみたいに\n"
.stringn "ふつうにできないかな……\n"
.stringn "もっと、がんばらなくっちゃ。"
db 0
.align 4
//MYELL_8_MIST_MORDY_C

//0x2D48C
Text_2D46C:
.stringn "\x05FL|MIST|TIAMAT||\x070-\x0C03\x071-\x0711ミスト、ちょっとこっちへ来て。\n"
.stringn "\x0703なになに？\n"
.stringn "\x0711はい、私からの贈り物。\n"
.stringn "\x0703これって、この前の服！\n"
.stringn "あたしが１番いいなって思ってた……！\n"
.stringn "\x0711やっぱり。\n"
.stringn "一緒に行ったかいがあったわ。\n"
.stringn "\x0703ありがとう、ティアマトさん。\n"
.stringn "\x0711ふふふ……\n"
.stringn "ミストの嬉しそうな顔が\n"
.stringn "見られて良かったわ。\n"
.stringn "本当を言うとね、\n"
.stringn "少しミストのことが心配だったの。\n"
.stringn "急に戦場に出るようになって\n"
.stringn "その重荷にいつか\n"
.stringn "押しつぶされてしまわないかって。\n"
.stringn "だから、私にできることは\n"
.stringn "何でもしてあげたかったのよ。\n"
.stringn "\x0703ティアマトさん……\n"
.stringn "\x0711ねえ、ミスト。\n"
.stringn "これからもし何かつらいことがあって、\n"
.stringn "でもアイクには話しづらいことなら…\n"
.stringn "私を頼って欲しいわ。\n"
.stringn "エルナのようには\n"
.stringn "なれないかもしれないけど、\n"
.stringn "あなたを思う気持ちは変わらないつもりよ。\n"
.stringn "\x0703うん……うん……ありがとう……\n"
.stringn "あたし……すごく嬉しいよ\n"
.stringn "ティアマトさん。\n"
.stringn "えへへ…なんかもうこの服、\n"
.stringn "もったいなくて着られないよ……"
db 0
.align 4
//MYELL_8_MIST_TIAMAT_A

//0x2D204
Text_2D1E4:
.stringn "\x05FL|MIST|TIAMAT||\x0C03\x0C11\x0703あ、こないだはごめんなさい、\n"
.stringn "ティアマトさん。\n"
.stringn "せっかく一緒に買い物に\n"
.stringn "行ってくれたのに……\n"
.stringn "\x0711いいのよ、そんなこと。\n"
.stringn "でもせっかくだから思い切って\n"
.stringn "買ってしまえば良かったのに。\n"
.stringn "\x0703うーん、でもいざとなると\n"
.stringn "あれこれ悩んじゃって……\n"
.stringn "\x0711ミストは食料品の買い置きとか、\n"
.stringn "みんなのための買い物は上手なのにね。\n"
.stringn "そんなところは、\n"
.stringn "だんだんエルナに似てきたわ。\n"
.stringn "\x0703お母さん？\n"
.stringn "\x0711ええ。\n"
.stringn "あなたがしっかり者なのも\n"
.stringn "エルナ譲りね。\n"
.stringn "でもミスト、あなたはもう少し\n"
.stringn "誰かに甘えてもいいと思うわ。\n"
.stringn "そばにいるのが私では\n"
.stringn "頼りないかもしれないけど……\n"
.stringn "\x0703そんなことないよ。\n"
.stringn "あたし、ティアマトさんのこと\n"
.stringn "お姉ちゃんだと思ってるもん。\n"
.stringn "\x0711ありがとう、ミスト。"
db 0
.align 4
//MYELL_8_MIST_TIAMAT_B

//0x2C9B4
Text_2C994:
.stringn "\x05FL|MIST|TIAMAT||\x070-\x0C03\x071-\x0711あらミスト、洗濯？\n"
.stringn "私も手伝うわ。\n"
.stringn "\x0703え？　いいよぉ！\n"
.stringn "ティアマトさんは\n"
.stringn "戦闘で疲れてるんだから。\n"
.stringn "\x0711それはあなただって同じでしょう？\n"
.stringn "いいから、手伝わせて。\n"
.stringn "それにしても、すごい量ね。\n"
.stringn "\x0703うん。ついでだから\n"
.stringn "他のみんなの分も、やらせてもらってるの。\n"
.stringn "いつもお兄ちゃんを助けてもらってる\n"
.stringn "お礼なんだけどね。\n"
.stringn "\x0711ふふ　律儀なのもいいけど、\n"
.stringn "疲れすぎない範囲にしないとだめよ。\n"
.stringn "…あら、これ、破けてるわ。\n"
.stringn "\x0703あ、お兄ちゃんのだ。\n"
.stringn "……ずっと戦い続きだから、\n"
.stringn "結構古くなってきたかなあ。\n"
.stringn "今度、町で新しいの買っとかなきゃ。\n"
.stringn "団長がボロの服着てたら\n"
.stringn "格好つかないもんね。\n"
.stringn "\x0711そういうミストも…\n"
.stringn "ほら、ちょっと見せて。\n"
.stringn "あなたの服も\n"
.stringn "そでのところ、ほつれてるじゃない。\n"
.stringn "\x0703あ。\n"
.stringn "本当だ。\n"
.stringn "\x0711ほんと、仕方がないわねえ。\n"
.stringn "そうだわ。今度一緒に町へ行かない？\n"
.stringn "新しい服を見ましょう。\n"
.stringn "\x0703え、でも、いいのかな。\n"
.stringn "色々物入りなのに。\n"
.stringn "\x0711ミストも年頃なんだから\n"
.stringn "そういうことを気にしなさいって\n"
.stringn "いつも言っているでしょう？\n"
.stringn "\x0703うん。\n"
.stringn "わたしなりには、気をつけている\n"
.stringn "つもりなんだけど…\n"
.stringn "\x0711口で言っているだけではダメよ。\n"
.stringn "実行に移さないと。\n"
.stringn "じゃあ、今度、誘うからね。\n"
.stringn "\x0703はーい。"
db 0
.align 4
//MYELL_8_MIST_TIAMAT_C_a

