.stringn "格好つかないもんね。\n"
.stringn "\x0711そういうミストも…\n"
.stringn "ほら、ちょっと見せて。\n"
.stringn "あなたの服も\n"
.stringn "そでのところ、ほつれてるじゃない。\n"
.stringn "\x0703あ。\n"
.stringn "本当だ。\n"
.stringn "\x0711ほんと、仕方がないわねえ。\n"
.stringn "そうだわ。今度一緒に町へ行かない？\n"
.stringn "新しい服を見ましょう。\n"
.stringn "\x0703え、でも、いいのかな。\n"
.stringn "色々物入りなのに。\n"
.stringn "\x0711ミストも年頃なんだから\n"
.stringn "そういうことを気にしなさいって\n"
.stringn "いつも言っているでしょう？\n"
.stringn "\x0703うん。\n"
.stringn "わたしなりには、気をつけている\n"
.stringn "つもりなんだけど…\n"
.stringn "\x0711口で言っているだけではダメよ。\n"
.stringn "実行に移さないと。\n"
.stringn "じゃあ、今度、誘うからね。\n"
.stringn "\x0703はーい。"
