//MYELL_8_MIST_TIAMAT_C_b

//0x2DBB4
Text_2DB94:
.stringn "\x05FL|MORDY|SOANEVALCKE||\x0C01\x071-\x0C13\x0701…ソーン。\n"
.stringn "\x0713……答えは見つかったか？\n"
.stringn "\x0701………【印付き】…\n"
.stringn "ベオクは……\n"
.stringn "ラグズとの…混血の子をソう呼ぶ。\n"
.stringn "ソーンは、ラグズの血を\n"
.stringn "ヒいてイるのか？\n"
.stringn "\x0713そのようだ。\n"
.stringn "…証となる印が、左のこめかみに\n"
.stringn "現れているからな。\n"
.stringn "\x0701…………\n"
.stringn "\x0713無理をしなくていいぞ。\n"
.stringn "私と話したくないだろう？\n"
.stringn "\x0701…モゥディには…ヨくワからない。\n"
.stringn "ガリアの言い伝えデは…\n"
.stringn "【親無し】は不吉だと…サれてイる。\n"
.stringn "【親無し】が生まれると……\n"
.stringn "大地の破滅が１００年近ヅくのダと…\n"
.stringn "\x0713そうだ。私は…ラグズの間では\n"
.stringn "【親無し】と呼ばれる者。\n"
.stringn "決して生まれるはずがない子供。\n"
.stringn "だから【親無し】…うまく言ったものだ。\n"
.stringn "ラグズは…　そうやって、\n"
.stringn "私たち混血の印を持つ者を……\n"
.stringn "最初から存在しないものとして扱う。\n"
.stringn "ベオクも【印付き】として\n"
.stringn "私たちを迫害するが……\n"
.stringn "存在の否定まではせぬ。\n"
.stringn "だから、私たちは…\n"
.stringn "ベオク以上にラグズを嫌悪する。\n"
.stringn "\x0701ドうしてナのだ？\n"
.stringn "ナぜ、【親無し】は生まれるノだ？\n"
.stringn "異なる種族同士デは、子供は生まれナいハずだ。\n"
.stringn "ソれは、コの世界を創られた\n"
.stringn "女神アスタルテの決め事ナのダから。\n"
.stringn "\x0713私の知る限り…\n"
.stringn "獣・鳥・竜…どのまとまりであっても、\n"
.stringn "確かに、己の種族内でしか子は成せぬ。\n"
.stringn "だが…ベオクと他の種族では\n"
.stringn "ごく稀にだが……生まれることがある。\n"
.stringn "忌まわしいことに、混血の印は…\n"
.stringn "１度でもそれを取り入れた血族に……\n"
.stringn "密かに受け継がれてゆくのだ。\n"
.stringn "女神の決め事を犯したのは、私か？\n"
.stringn "違う。私の祖先の誰かがやったことだ。\n"
.stringn "両親も祖父母も一族見渡す限り\n"
.stringn "みなベオクなんだぞ？\n"
.stringn "ずっと昔に…誰かが、ラグズの血を持ち込んだ。\n"
.stringn "その咎が…何代もの時を経て今、\n"
.stringn "私に現れた。私はただ生まれてきただけなのに。\n"
.stringn "最初から『不浄』の烙印を押されていた。\n"
.stringn "\x0701……\n"
.stringn "\x0713ラグズの血は、私に\n"
.stringn "常人ならざる力を与えた。\n"
.stringn "この力を使い…安穏と生きる奴らを\n"
.stringn "滅ぼしてやろうかとも考えたが…やめた。\n"
.stringn "私にも仲間がいたからな。\n"
.stringn "同じように混血の印を持つため…\n"
.stringn "表の世界から追われた者たちが……\n"
.stringn "\x0701ソーンは、ナぜ\n"
.stringn "モゥディに近づいたノだ？\n"
.stringn "ガリアに興味が…アると\n"
.stringn "言ったのはナぜだ？\n"
.stringn "\x0713ガリアの獣牙族に興味があった。\n"
.stringn "ベグニオンにいる奴らとは\n"
.stringn "毛色が変わって見えたのでな。\n"
.stringn "私の仲間には…\n"
.stringn "ベオクと手を組もうとするほど\n"
.stringn "開放的な国であれば、\n"
.stringn "私たちのような者に対しても\n"
.stringn "寛容なのではないかと主張する者がいた。\n"
.stringn "ガリアとクリミア…\n"
.stringn "そのどちらかには、\n"
.stringn "自分達を受け入れてくれる\n"
.stringn "場所があるのではないかと……\n"
.stringn "……無論、そんな\n"
.stringn "都合の良いことはなかったようだが。\n"
.stringn "\x0701ソーン…\n"
.stringn "\x0713さて、おまえとの付き合いも\n"
.stringn "これまでだな。\n"
.stringn "今しばらく…この戦いが終わるまでは\n"
.stringn "おまえの目の前をうろつくだろうが\n"
.stringn "それぐらいは辛抱してやってくれ。\n"
.stringn "２度と声はかけぬから…\n"
.stringn "\x0701イやだ！\n"
.stringn "目の前にいるソーンを\n"
.stringn "見えないヨうに振舞うことはできナい。\n"
.stringn "\x0713モゥディ…\n"
.stringn "女神の決め事はいいのか？\n"
.stringn "ベオクよりも自然に近いラグズは…\n"
.stringn "その理を大事にする存在だろう？\n"
.stringn "\x0701モゥディは女神に会ったコとがない。\n"
.stringn "モし…会えたら文句を言ってヤる。\n"
.stringn "ソーンを苦しめるナと。\n"
.stringn "モゥディの大切な友達ナのだと。\n"
.stringn "\x0713ふっ　女神に文句をか…\n"
.stringn "私の方は逆に、生まれて初めて\n"
.stringn "彼女に感謝したい気持ちだというのに。\n"
.stringn "\x0701ナぜだ？\n"
.stringn "\x0713モゥディのような男に出会えた。\n"
.stringn "こんな運命であれば悪くない。"
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_A

//0x2D9C0
Text_2D9A0:
.stringn "\x05FL|SOANEVALCKE|MORDY||\x070-\x0C01\x0713ソーン！！\n"
.stringn "\x0701どうした、モゥディ。\n"
.stringn "そんなに息を切らせて。\n"
.stringn "\x0713嫌悪は『トても嫌い』、\n"
.stringn "無知は『頭が悪い』だ。\n"
.stringn "ドうして、ソーンは\n"
.stringn "自分の国を嫌う？\n"
.stringn "モゥディをバカにスる？\n"
.stringn "\x0701…調べたのか。\n"
.stringn "思ったより頭は回るようだ。\n"
.stringn "では“無知”は取り消そう。\n"
.stringn "\x0713ソーン！\n"
.stringn "モゥディの質問に答えるノだ。\n"
.stringn "\x0701……せっかくだから\n"
.stringn "もっと調べてみるといい。\n"
.stringn "私は【印付き】だ。\n"
.stringn "だから国を嫌悪し、\n"
.stringn "無知なラグズを憎んでいる。\n"
.stringn "\x0713…ラグズを…憎む？\n"
.stringn "『シるしツき』ダから…？\n"
.stringn "……ソーンは…何者ナのだ？"
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_B

//0x2D7CC
Text_2D7AC:
.stringn "\x05FL|SOANEVALCKE|MORDY||\x070-\x0C01\x071-\x0713ソーン！\n"
.stringn "コこにイたのか。\n"
.stringn "\x0701…うむ。\n"
.stringn "\x0713ガリアの話は、モうイいのか？\n"
.stringn "モゥディはマだマだ\n"
.stringn "話しタいコとが、沢山アるぞ。\n"
.stringn "\x0701……モゥディは、\n"
.stringn "自分の国が好きか。\n"
.stringn "\x0713オお。ガリアはイい国だ。\n"
.stringn "モゥディにトっては、\n"
.stringn "世界イち、素晴らしい国だ。\n"
.stringn "\x0701そうか。\n"
.stringn "\x0713ソーンはドうだ？\n"
.stringn "ベグニオンが好きか？\n"
.stringn "\x0701…嫌悪している。\n"
.stringn "\x0713『ケんお』？\n"
.stringn "ドういう意味だ？\n"
.stringn "\x0701おまえは知らなくていい。\n"
.stringn "無知のままでいるほうが幸せだ。\n"
.stringn "\x0713『ムち』……\n"
.stringn "……ムぅ…モゥディには\n"
.stringn "現代語はヨくワからナい……"
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_C

//0x2ECC4
Text_2ECA4:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x071-\x0713ウルキ、イいコとを思いツいたぞ。\n"
.stringn "\x0701どうした？\n"
.stringn "\x0713モゥディが目にナる。\n"
.stringn "見えるものをオまえに伝えるぞ。\n"
.stringn "ダから、モゥディを乗せて\n"
.stringn "イっしょに夜の森に行けばイい！\n"
.stringn "\x0701………………\n"
.stringn "いや……それは無理な話だ…\n"
.stringn "おまえは重すぎる。\n"
.stringn "私の力ではおまえを運べない。\n"
.stringn "\x0713ムゥ……ソうか。スまん。\n"
.stringn "モゥディは夜でも見える、\n"
.stringn "オまえは空が飛べる、\n"
.stringn "イい思いつきダと思ったが……\n"
.stringn "\x0701…………\n"
.stringn "\x0713モゥディ、ガんばって考えたが……\n"
.stringn "……スまん、ウルキ。\n"
.stringn "\x0701いや……\n"
.stringn "……まあ、例えばの話だが。\n"
.stringn "私がもっと力をつけて、\n"
.stringn "おまえがもっと軽くなったなら……\n"
.stringn "それも可能だったろうな。\n"
.stringn "\x0713ナるほど！　ソうすればウルキのイる\n"
.stringn "フェニキスにも連れて行ってモらえるな！\n"
.stringn "モゥディ、ガんばるぞ！\n"
.stringn "ソうか…モゥディは軽くなる役ダな。\n"
.stringn "……ムゥ……ヨく考えると難しい……\n"
.stringn "ヨし、明日から食い物を減らしてミるぞ！\n"
.stringn "\x0701いや……例えばの話だと…………\n"
.stringn "……………………\n"
.stringn "………………………………\n"
.stringn "………ほどほどに、な……"
db 0
.align 4
//MYELL_8_MORDY_VULCI_A

//0x2E964
Text_2E944:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x0C13\x0701……モゥディ。\n"
.stringn "\x0713ドうかシたのか、ウルキ？\n"
.stringn "\x0701おまえに聞きたいことがある。\n"
.stringn "\x0713ン？　ナんだ？\n"
.stringn "\x0701おまえたち獣牙族は夜でも\n"
.stringn "物がよく見えるそうだな。\n"
.stringn "……私たちは夜目がきかない。\n"
.stringn "暗闇では、目を開けていても\n"
.stringn "見えるのは闇だけだ。\n"
.stringn "\x0713ムゥ、ソれは不便だ。\n"
.stringn "暗闇はタしかに見え辛いコともアるが、\n"
.stringn "少しの明かりがアれば見える。\n"
.stringn "オまえもモゥディたちのヨうに、\n"
.stringn "月の光で見ればイい。\n"
.stringn "\x0701……そうできればいいがな。\n"
.stringn "鳥翼族にはどうしたって無理だ。\n"
.stringn "\x0713ソうなのか。\n"
.stringn "\x0701……私は夜の景色を見た事が無い。\n"
.stringn "同胞の誰も夜の世界を知らないのだ。\n"
.stringn "私は１度、夜の森を見てみたいのだ。\n"
.stringn "夜になると森の木々はどのように見えるのか？\n"
.stringn "雨が降らなくても朝になると\n"
.stringn "なぜ葉に雫がついているのだ？\n"
.stringn "夜の森は、わからないことばかりだ。\n"
.stringn "一体、どんな感じなのだ？\n"
.stringn "\x0713夜の森は静かダが、\n"
.stringn "昼は生き物の息吹がアって、生きてイるな。\n"
.stringn "夜とは全然違う森がアる。\n"
.stringn "\x0701……そうか。\n"
.stringn "１度、見てみたいものだ。"
db 0
.align 4
//MYELL_8_MORDY_VULCI_B

//0x2E6AC
Text_2E68C:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x0713ウルキ、話してもイいか？\n"
.stringn "\x0701……ああ。\n"
.stringn "なんだ？\n"
.stringn "\x0713鳥翼族は空を飛ぶ。\n"
.stringn "空を飛ぶノはドんな気分ダ？\n"
.stringn "\x0701……\n"
.stringn "……特に考えたことはない。\n"
.stringn "\x0713ムゥ……ソうか。\n"
.stringn "ソうイうモのか。\n"
.stringn "モゥディはマだ、\n"
.stringn "空を飛んだコとがナいカらな。\n"
.stringn "聞いてミたかった。\n"
.stringn "\x0701……ああ、だろうな。\n"
.stringn "\x0713ウルキの住んでイるフェニキスは\n"
.stringn "ドんなトころだ？\n"
.stringn "ヤはり、飛ばないと行けナいノか？\n"
.stringn "\x0701そうだな……\n"
.stringn "船でやって来たところで\n"
.stringn "フェニキスには港がない。必要ないからな。\n"
.stringn "我々の助けがなくては上陸は難しいだろう。\n"
.stringn "\x0713ソうか……\n"
.stringn "残念だ……\n"
.stringn "\x0701……おまえはフェニキスに来たいのか？\n"
.stringn "\x0713オぉ！　行ってミたいぞ！\n"
.stringn "コの戦でイろんなベオクやラグズに出会った！\n"
.stringn "ミんなが住んでイるトころに\n"
.stringn "モゥディは行ってミたいのだ！\n"
.stringn "\x0701……そうか。"
db 0
.align 4
//MYELL_8_MORDY_VULCI_C

//0x2F694
Text_2F674:
.stringn "\x05FL|MWARIM|ZIHARK||\x0C01\x071-\x0713ムワリム。\n"
.stringn "\x0701なんだ、ツイハーク。\n"
.stringn "\x0713君に、これを採ってきた。\n"
.stringn "\x0701……これは？\n"
.stringn "\x0713獣牙族は、この草の香りが\n"
.stringn "大好きなんだろう？\n"
.stringn "滅多に生えないらしいが、\n"
.stringn "香りを嗅いだだけで、\n"
.stringn "落ち着いた気分になれると聞いた。\n"
.stringn "\x0701……\n"
.stringn "\x0713もしかして、\n"
.stringn "草を間違えてるか？\n"
.stringn "\x0701……いや。\n"
.stringn "だが、その草を好むのは\n"
.stringn "獣牙族の中でも猫たちだけだ。\n"
.stringn "私たち虎には…\n"
.stringn "そのような習慣はない。\n"
.stringn "\x0713なんだ…そうなのか。\n"
.stringn "すまない。昔、\n"
.stringn "恋人がそうだったから…\n"
.stringn "てっきりみんなそうなんだと\n"
.stringn "勘違いしていたようだ。\n"
.stringn "\x0701……恋人？\n"
.stringn "おまえの恋人は、\n"
.stringn "獣牙族だったのか？\n"
.stringn "\x0713ああ。\n"
.stringn "\x0701……そうか。\n"
.stringn "ベオクと結ばれるラグズもいると…\n"
.stringn "話に聞いたことがあったが……\n"
.stringn "その…大変だっただろう？\n"
.stringn "\x0713そうだな…\n"
.stringn "結局、添い遂げることは\n"
.stringn "できなかったが……\n"
.stringn "俺は今でも…\n"
.stringn "彼女以外の女性を愛したことはない。\n"
.stringn "\x0701……その草を、\n"
.stringn "もらえるだろうか。\n"
.stringn "\x0713え？　だが……\n"
.stringn "\x0701構わない。\n"
.stringn "これを採ってきてくれた\n"
.stringn "おまえの気持ちを受け取りたい。\n"
.stringn "\x0713そうか…\n"
.stringn "ありがとう。\n"
.stringn "あんたは優しいラグズなんだな。"
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_A

//0x2F2EC
Text_2F2CC:
.stringn "\x05FL|MWARIM|ZIHARK||\x0C01\x0C13\x0701……ツイハーク。\n"
.stringn "\x0713やあ、ムワリム。\n"
.stringn "また会ったな。\n"
.stringn "\x0701……打ち粉は見つかったか？\n"
.stringn "\x0713いや、あいにく。\n"
.stringn "誰かにまた譲ってもらうのも悪いし、\n"
.stringn "これから新しいものを\n"
.stringn "買いにいこうと思っているところだ。\n"
.stringn "\x0701……これは使えるか？\n"
.stringn "\x0713え？　これは…\n"
.stringn "ずいぶん良質な打ち粉だな。\n"
.stringn "ラグズの君が、\n"
.stringn "どうしてこんな物を？\n"
.stringn "\x0701……昔のくせだな。\n"
.stringn "\x0713昔…？\n"
.stringn "\x0701貴族の奴隷だった頃……\n"
.stringn "よく、主の剣を磨かされた。\n"
.stringn "いつも、いきなり持ってくるんだが、\n"
.stringn "その場で磨いてみせられないと、\n"
.stringn "手ひどく鞭で打たれたんだ。\n"
.stringn "それで…な。\n"
.stringn "\x0713……すまない。\n"
.stringn "嫌なことを\n"
.stringn "思い出させてしまったな。\n"
.stringn "\x0701構わない。\n"
.stringn "よかったら、\n"
.stringn "その剣も磨いてやろうか？\n"
.stringn "\x0713いや、真の剣使いであれば、\n"
.stringn "己の剣は自分で手入れするものだ。\n"
.stringn "気持ちだけで嬉しいよ。\n"
.stringn "\x0701じゃあ、この粉だけでも\n"
.stringn "使ってくれ。\n"
.stringn "私にはもう必要のないものだからな。\n"
.stringn "\x0713ムワリム…\n"
.stringn "ありがとう、助かった。\n"
.stringn "礼の代わりといってはなんだが…\n"
.stringn "いっしょに食事でもどうだ？\n"
.stringn "\x0701…そうだな。おまえとなら…\n"
.stringn "楽しい食事ができそうだ。"
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_B

//0x2F034
Text_2F014:
.stringn "\x05FL|ZIHARK|MWARIM||\x0703おかしいな。\n"
.stringn "さっきまであったのに\n"
.stringn "いったいどこへやって……\n"
.stringn "\x0711…どうかしたのか？\n"
.stringn "\x0703やあ、ムワリム。\n"
.stringn "剣の“打ち粉”が見当たらなくてね。\n"
.stringn "\x0711打ち粉？\n"
.stringn "\x0703剣の手入れに使う道具だ。\n"
.stringn "剣は放っておくとすぐに錆びるから。\n"
.stringn "油をぬぐったり、打ち粉を打ったり……\n"
.stringn "\x0711……細かい石粒を入れた袋のことか？\n"
.stringn "\x0703ああ、それだ。\n"
.stringn "もしかして拾ってくれたのか？\n"
.stringn "\x0711……いや。\n"
.stringn "昔、見たことがあるだけだ。\n"
.stringn "打ち粉と呼ばれる物だとは知らなかったが。\n"
.stringn "\x0703近くで落とした様子はないし、\n"
.stringn "行軍の最中に\n"
.stringn "無くしてしまったかな……\n"
.stringn "仕方ない、アイク団長に\n"
.stringn "少し譲ってもらおう。\n"
.stringn "\x0711……ベオクとは不便なものだな。\n"
.stringn "\x0703まったくだ。\n"
.stringn "俺たちは武器がないと何もできない。\n"
.stringn "こういう時はいつも、\n"
.stringn "ラグズがうらやましいよ。\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_C

//0x30318
Text_302F8:
.stringn "\x05FL|OSCAR|TANIS||\x070-\x0C01\x0713オスカー。\n"
.stringn "？　どこかへ行くのか？\n"
.stringn "\x0701はい、今から食事の準備に……\n"
.stringn "何か御用でしたか？\n"
.stringn "\x0713いや、大した用ではないのだが……\n"
.stringn "君に礼を言っておこうと思ってな。\n"
.stringn "君の補佐のおかげで、\n"
.stringn "私は十二分に力を発揮できている。\n"
.stringn "こんなに楽に戦えたことはなかった。\n"
.stringn "できることなら、君を\n"
.stringn "ベグニオンに連れ帰りたいほどだ。\n"
.stringn "\x0701ありがとうございます。\n"
.stringn "\x0713ところで……\n"
.stringn "オスカーが料理をするのか？\n"
.stringn "\x0701はい。傭兵団のみで行動している時はよく。\n"
.stringn "今は時折こうして手伝いにうかがいます。\n"
.stringn "\x0713ほう、器用なのだな。\n"
.stringn "\x0701そうですか？\n"
.stringn "\x0713なさけない話だが、\n"
.stringn "私は玉子の殻１つまともに割ることができん。\n"
.stringn "野営地で、１度だけ私が料理したんだが…\n"
.stringn "玉子を食べさせたいのか、殻を食べさせたいのか、\n"
.stringn "どっちかと聞かれた。\n"
.stringn "\x0701……それは、また…\n"
.stringn "\x0713あきれるだろう？\n"
.stringn "\x0701いいえ。あれだけ器用に\n"
.stringn "剣を使われるので意外だと思ったまでです。\n"
.stringn "もし、失礼でなければですが……\n"
.stringn "私でよければお教えしましょうか？\n"
.stringn "\x0713君が料理をか？\n"
.stringn "\x0701お嫌でなければ。\n"
.stringn "\x0713ふむ、君なら教え方も上手いだろう。\n"
.stringn "よし、ご教授願おうか。"
db 0
.align 4
//MYELL_8_OSCAR_TANIS_A

//0x2FD18
Text_2FCF8:
.stringn "\x05FL|OSCAR|TANIS||\x070-\x0C01\x0C13\x0701タニス殿。先日の勇敢な突撃……\n"
.stringn "素晴らしいものでした。\n"
.stringn "\x0713無論だ。我らはベグニオン騎士。\n"
.stringn "祖国と神使様の名において、\n"
.stringn "不名誉な戦いは許されない。\n"
.stringn "\x0701タニス殿の武勇は\n"
.stringn "私も噂で耳にしたことがあります。\n"
.stringn "最速にして最大、\n"
.stringn "光の奔流にも例えられる\n"
.stringn "天馬騎士隊の総突撃……\n"
.stringn "\x0713ほう、知っているのか。\n"
.stringn "\x0701しかしタニス殿。\n"
.stringn "失礼を承知で申し上げますが、\n"
.stringn "その戦術は数で勝ってこそ成り立つ\n"
.stringn "ものではないでしょうか？\n"
.stringn "\x0713む……\n"
.stringn "確かにそれは認めよう。\n"
.stringn "今回の戦ではベグニオン軍の戦術を\n"
.stringn "そのまま用いるわけにはいくまい。\n"
.stringn "\x0701ええ。\n"
.stringn "我々の軍は常に寡兵、\n"
.stringn "装備も十分にそろわないこともままあります。\n"
.stringn "ベグニオンのような潤沢な資金と兵力は\n"
.stringn "とても望めないのが現状です。\n"
.stringn "\x0713ふむ。\n"
.stringn "ならばどうする？\n"
.stringn "君の意見を聞こう。\n"
.stringn "\x0701私たちが続けてきたのは、\n"
.stringn "個を生かす戦いでした。\n"
.stringn "このような連戦では、まず負けないことを\n"
.stringn "第一に考える必要があります。\n"
.stringn "たとえ戦いに勝っても、犠牲が大きければ\n"
.stringn "次の戦いを乗り越えられませんから。\n"
.stringn "たとえ不名誉の謗りを受けようと、\n"
.stringn "負傷した時にはすぐに離脱し、\n"
.stringn "他の仲間に任せる……\n"
.stringn "\x0713なるほど……\n"
.stringn "個人的にはいささか不満だが\n"
.stringn "有効であることは認めざるをえない。\n"
.stringn "\x0701できればタニス殿にも\n"
.stringn "常に味方と連携して戦うよう\n"
.stringn "お願いしたいのですが。\n"
.stringn "\x0713だが、私と連携をとれる\n"
.stringn "天馬騎士はこの軍に多くはいまい。\n"
.stringn "誰が私を補佐する？\n"
.stringn "\x0701では、私がその役をつとめます。\n"
.stringn "\x0713君が？\n"
.stringn "\x0701ええ、まだ未熟ではありますが。\n"
.stringn "\x0713……いや、君がいい。\n"
.stringn "君のことは多少なりと知っている。\n"
.stringn "他の得体の知れぬ傭兵と違って\n"
.stringn "信用できそうだ。\n"
.stringn "\x0701光栄です。\n"
.stringn "\x0713だが、私は君の馬を待つつもりなどないぞ。\n"
.stringn "私を補佐するというのなら、\n"
.stringn "私についてこられる者でなくてはな。\n"
.stringn "\x0701はっ、努力します。"
db 0
.align 4
//MYELL_8_OSCAR_TANIS_B

//0x2FA40
Text_2FA20:
.stringn "\x05FL|TANIS|OSCAR||\x0703ん？　ちょっと待ってくれ。\n"
.stringn "\x0711はい？\n"
.stringn "\x0703今この布を落としたのは\n"
.stringn "君か？\n"
.stringn "\x0711これは……申し訳ありません。\n"
.stringn "タニス殿に\n"
.stringn "手ずから拾っていただくとは。\n"
.stringn "\x0703君の名は？\n"
.stringn "\x0711はっ、申し遅れました。\n"
.stringn "お初にお目にかかります。\n"
.stringn "私はグレイル傭兵団の\n"
.stringn "オスカーと申します。\n"
.stringn "\x0703ふむ、君も\n"
.stringn "アイク将軍が抱える傭兵団の者だな。\n"
.stringn "承知した。\n"
.stringn "私の部下たちは最小限しか随行させていないが\n"
.stringn "我らベグニオン騎士はたとえ単騎でも\n"
.stringn "他に劣る者ではない。戦場でそれを示そう。\n"
.stringn "\x0711高名なベグニオン天馬騎士の力は\n"
.stringn "よく存じています。\n"
.stringn "これからよろしくお願い申し上げます。\n"
.stringn "\x0703うむ。\n"
.stringn "\x0711では、失礼します。\n"
.stringn "本当にありがとうございました。\n"
.stringn "\x0703ふむ……\n"
.stringn "なかなか礼儀正しい青年だ。\n"
.stringn "傭兵など野卑で低俗で下劣な男ばかりと\n"
.stringn "決めつけていたが……\n"
.stringn "さすがアイク将軍の部下だな。"
db 0
.align 4
//MYELL_8_OSCAR_TANIS_C

//0x30D14
Text_30CF4:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x0713リュシオン王子。\n"
.stringn "先日は…危ないところを\n"
.stringn "ありがとうございました。\n"
.stringn "\x0701…とりあえず、\n"
.stringn "事なきを得てよかったな。\n"
.stringn "いつもは俊敏に動くおまえの騎が…\n"
.stringn "敵を目前にして、\n"
.stringn "突然…動きを止めたから驚いた。\n"
.stringn "\x0713自分でも気づかぬうちに…\n"
.stringn "疲れを溜めてしまっていたようです。\n"
.stringn "あの時、リュシオン王子が\n"
.stringn "【呪歌】を歌って下さらなければ…\n"
.stringn "かなり危うい状況に陥ったことでしょう。\n"
.stringn "重ねてお礼申し上げます。\n"
.stringn "\x0701……これでも、私は\n"
.stringn "戦場で役に立たない存在だと思うか？\n"
.stringn "\x0713いえ、全て私の思い上がりでした。\n"
.stringn "お守りすると申し出ておいて、\n"
.stringn "逆に守られてしまうとは…\n"
.stringn "これほどなさけない話もございません。\n"
.stringn "\x0701わかってくれたなら、\n"
.stringn "それでいい。\n"
.stringn "\x0713しかし…こうなった以上、\n"
.stringn "この軍にいてもご迷惑となるばかり……\n"
.stringn "この足でベグニオンに戻り、\n"
.stringn "神使様のお叱りを受ける覚悟です。\n"
.stringn "\x0701ま、待て！\n"
.stringn "たった１度の失敗で…\n"
.stringn "何もそこまでしなくてもいいだろう。\n"
.stringn "\x0713いえ…　任務をことごとく\n"
.stringn "失敗した私には……\n"
.stringn "もはや除隊の道しか残されておりません。\n"
.stringn "\x0701だったら…！\n"
.stringn "私の護衛に任じよう。\n"
.stringn "そうすれば、\n"
.stringn "神使の任務を１つ果たせる。\n"
.stringn "\x0713そんな…私などが護衛では、\n"
.stringn "王子の足手まといとなります。\n"
.stringn "\x0701私がおまえを守ってやろう。\n"
.stringn "名ばかりの護衛でいいから、\n"
.stringn "ここに残って役目を果たすんだ。\n"
.stringn "\x0713リュシオン王子…\n"
.stringn "それでは、謹んで護衛の任務を賜ります。\n"
.stringn "不束者ですが、以後\n"
.stringn "よろしくお引立て下さいませ。"
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_A

//0x30A4C
Text_30A2C:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x071-\x0713リュシオン王子。\n"
.stringn "\x0701…おまえか。\n"
.stringn "\x0713お見受けしたところ…\n"
.stringn "先日の怪我も順調に回復されたようで、\n"
.stringn "なによりです。\n"
.stringn "\x0701……\n"
.stringn "\x0713無礼を承知で申し上げます。\n"
.stringn "やはり、あなたのようなお方が\n"
.stringn "戦場に出られるのは\n"
.stringn "無謀ではないでしょうか？\n"
.stringn "あなたをお守りするために、\n"
.stringn "何人もの兵の手を割かなくてはいけません。\n"
.stringn "せめて私を、専属の護衛に\n"
.stringn "任じていただければ…\n"
.stringn "少しはましな状態に……\n"
.stringn "\x0701…アイクが、\n"
.stringn "私の力を不要だと言わない限り…\n"
.stringn "戦場には出る。\n"
.stringn "それ以外は、誰の指図も受けない。\n"
.stringn "\x0713リュシオン王子！\n"
.stringn "\x0701…先の戦で……おまえが、\n"
.stringn "助けてくれたことには感謝している。\n"
.stringn "だが、何度も言うが…護衛は必要ない。\n"
.stringn "私に付きまとうのはやめてくれ。\n"
.stringn "\x0713…ふむ。勅命でなければ\n"
.stringn "私も無理強いはしたくないのだがな…\n"
.stringn "さて…困ったな。"
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_B

//0x306D8
Text_306B8:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x0713リュシオン王子。\n"
.stringn "少し、よろしいでしょうか。\n"
.stringn "\x0701おまえは確か……\n"
.stringn "神使の…？\n"
.stringn "\x0713はい。\n"
.stringn "神使親衛隊副隊長を務めます\n"
.stringn "タニスと申します。\n"
.stringn "\x0701…私に何の用だ？\n"
.stringn "\x0713神使様より、でき得る限り、\n"
.stringn "王子をお守りするよう命じられました。\n"
.stringn "以後、お見知りおき下さい。\n"
.stringn "\x0701２０年前の償い…というわけか。\n"
.stringn "あいにくだが、必要ない。\n"
.stringn "自分の身は自分で守れる。\n"
.stringn "\x0713ですが、王子。\n"
.stringn "サギの民が、戦う術を一切\n"
.stringn "持たぬというのは…\n"
.stringn "ベグニオンにおいては\n"
.stringn "幼子でも知っている事実です。\n"
.stringn "戦場において…戦わずして、\n"
.stringn "どうやってご自身をお守りになる\n"
.stringn "おつもりでしょうか？\n"
.stringn "\x0701そんなことは、\n"
.stringn "おまえに関係ないだろう。\n"
.stringn "\x0713…私は勅命を受けております。\n"
.stringn "確かな理由も聞かせていただけぬまま、\n"
.stringn "命令を放棄するわけには参りません。\n"
.stringn "\x0701ベオクの仕来たりのために、\n"
.stringn "私がそれをのむいわれはない。\n"
.stringn "…話は以上だ。失礼する。\n"
.stringn "\x0713……やれやれ、見かけによらず\n"
.stringn "気の強い王子だ。\n"
.stringn "簡単に守らせてはくれなさそうだな。\n"
.stringn "さて、どうしたものか…"
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_C

//0x3184C
Text_3182C:
.stringn "\x05FL|TOPUCK|RIEUSION||\x0C01\x0C13\x0701なあなあ…　どうしてだ？\n"
.stringn "\x0713………\n"
.stringn "\x0701本当はできるんだろ？\n"
.stringn "頼むから、やってくれよ。\n"
.stringn "別に今すぐじゃなくていいから。\n"
.stringn "\x0713…無理だ。\n"
.stringn "\x0701…おいらたちが\n"
.stringn "何ももってないからか？\n"
.stringn "だから助けてくれないのか？\n"
.stringn "\x0713私が、見返りを求めて\n"
.stringn "動いているとでも言うつもりか！？\n"
.stringn "\x0701だ、だって…！\n"
.stringn "神使を許した時には…\n"
.stringn "あんなにすごいことできたのに！！\n"
.stringn "\x0713あれは…\n"
.stringn "あの条件下だからできたことだ。\n"
.stringn "\x0701？　…よくわかんねえ。\n"
.stringn "\x0713…まず、あれはセリノスの森だった。\n"
.stringn "聖なる祭壇の上で、\n"
.stringn "一族の正式な儀式として行なった。\n"
.stringn "そして何よりも…\n"
.stringn "あの時はリアーネがいた。\n"
.stringn "【再生】の呪歌は、\n"
.stringn "１人で謡っても大した効力を発揮しないんだ。\n"
.stringn "\x0701………じゃあ、\n"
.stringn "あのお姫さんもいればいいのか？\n"
.stringn "\x0713飲み込みの悪い…\n"
.stringn "たとえリアーネと私が\n"
.stringn "倒れるまで謡ったとしても、\n"
.stringn "砂を土に変えることなどできない。\n"
.stringn "あの砂漠が、太古の昔\n"
.stringn "豊かな土だったとしても…\n"
.stringn "何百年も前の状態に戻すほどの力はない。\n"
.stringn "わかったか？\n"
.stringn "\x0701………ちぇっ\n"
.stringn "\x0713どうして、そんなことが必要なんだ？\n"
.stringn "アイクから…\n"
.stringn "おまえたちのことは\n"
.stringn "神使の預かりになったと聞いたぞ。\n"
.stringn "\x0701神使は…ラグズ奴隷のこと\n"
.stringn "なんとかしてくれるって言ったけど…\n"
.stringn "もし、それが\n"
.stringn "ベオクと同じ町に住めって話なら…\n"
.stringn "困るなって思ったんだ。\n"
.stringn "だってそうだろ？\n"
.stringn "いくら神使が許しても、\n"
.stringn "他のベオクたちは…やっぱり\n"
.stringn "ラグズが嫌いだし……\n"
.stringn "おいら…仲間が辛いめにあうの\n"
.stringn "やっぱり、やだし……\n"
.stringn "\x0713それは…確かに\n"
.stringn "無理な話だな。\n"
.stringn "\x0701だから…\n"
.stringn "砂漠をなんとかできないかなって。\n"
.stringn "ラグズだけで暮らせる村が\n"
.stringn "作れないかなって、思ったんだ。\n"
.stringn "\x0713………まだ先の話だろうが、\n"
.stringn "もし、セリノスの森が\n"
.stringn "私たちの手に戻ったら…共に暮らすか？\n"
.stringn "\x0701い、いいのか！？\n"
.stringn "\x0713もちろん。\n"
.stringn "\x0701すっげえ！\n"
.stringn "みんな喜ぶぜ！！\n"
.stringn "\x0713ただし、森の動物を捕食することは\n"
.stringn "禁じるがな。\n"
.stringn "\x0701え～…　じゃあ、どうやって\n"
.stringn "飯を食うんだよ？\n"
.stringn "\x0713水と木の実が豊富にある。\n"
.stringn "\x0701おいらの仲間は\n"
.stringn "獣牙族が多くて、\n"
.stringn "あいつら肉食なんだよ！\n"
.stringn "\x0713慣れろ。\n"
.stringn "\x0701……一応、みんなで相談してみる。\n"
.stringn "けど、みんな…\n"
.stringn "肉が全然食えないんなら\n"
.stringn "砂漠でいいって言いそうだけど…"
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_A

//0x31604
Text_315E4:
.stringn "\x05FL|TOPUCK|RIEUSION||\x070-\x0C01\x0C13\x0701サギの民の王子！\n"
.stringn "\x0713…リュシオンだ。\n"
.stringn "\x0701んじゃ、リュシオン王子！\n"
.stringn "いま時間、いいか？\n"
.stringn "\x0713まあ…構わない。\n"
.stringn "この間言ってたラグズのために\n"
.stringn "呪歌を謡う話だろう？\n"
.stringn "\x0701そうだ。覚えててくれたんだ。\n"
.stringn "あんたいいやつだな。\n"
.stringn "\x0713……内容は？\n"
.stringn "\x0701あのな、あんたの歌で…\n"
.stringn "砂漠の砂を、\n"
.stringn "土に変えてもらいたいんだ。\n"
.stringn "\x0713砂を土に…だと？\n"
.stringn "\x0701うん。よく肥えた\n"
.stringn "作物がいっぱい育つ土。\n"
.stringn "そしたら、あそこに\n"
.stringn "おいらたちの村を作るんだ。\n"
.stringn "\x0713………無茶を言うな。\n"
.stringn "呪歌は、そんな万能なものではない！\n"
.stringn "\x0701あ、おい！\n"
.stringn "…行っちまった。\n"
.stringn "サギの民って怒りっぽいぜ。\n"
.stringn "あんな優しそうな見た目なのにな。"
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_B

//0x311E8
Text_311C8:
.stringn "\x05FL|RIEUSION|TOPUCK||\x0C01\x071-\x0713あ、サギの民の王子！\n"
.stringn "\x0701誰だ、おまえは？\n"
.stringn "\x0713おいらはトパック。\n"
.stringn "おいら、あんたに\n"
.stringn "聞きたいことがあってさ。\n"
.stringn "\x0701唐突な奴だな。\n"
.stringn "なんだ？\n"
.stringn "\x0713あの歌は、なんにでも効くのか？\n"
.stringn "\x0701呪歌のことか？\n"
.stringn "\x0713色のなかった森を\n"
.stringn "いっぺんに変えちまったやつ。\n"
.stringn "\x0701【再生】の呪歌だな。\n"
.stringn "………それが？\n"
.stringn "\x0713あのな、それさ…\n"
.stringn "おいらたちのためにも、\n"
.stringn "歌ってくれないかな。\n"
.stringn "\x0701おいらたち？\n"
.stringn "\x0713うん。おいらと\n"
.stringn "グラーヌ砂漠で待ってる…\n"
.stringn "ラグズの仲間たち。\n"
.stringn "\x0701では、おまえが…\n"
.stringn "ラグズ奴隷解放軍の首領…\n"
.stringn "こんな子供だったのか。\n"
.stringn "\x0713…子供じゃ悪いかよ。\n"
.stringn "\x0701そういうわけではないが…\n"
.stringn "あのベグニオンの中で、\n"
.stringn "ラグズを助けるために尽力する\n"
.stringn "ベオクがいると聞いてから\n"
.stringn "どんな者かと思っていたが…\n"
.stringn "ずいぶん想像と違った。\n"
.stringn "\x0713それより、なあ、\n"
.stringn "どうなんだよ。\n"
.stringn "助けてくれないか？\n"
.stringn "\x0701ラグズのために力を貸すことは\n"
.stringn "やぶさかではないが…\n"
.stringn "いったい、何をすればいい？\n"
.stringn "\x0713やった！　えっとな…\n"
.stringn "あ、でもどうしようかな。\n"
.stringn "\x0701？\n"
.stringn "\x0713おいらまだ、\n"
.stringn "戦いの準備すんでないんだよな。\n"
.stringn "ちゃんと話したいから\n"
.stringn "時間できてから来るよ。\n"
.stringn "じゃあ、またな！\n"
.stringn "\x0701…ベオクの子供というのは、\n"
.stringn "ずいぶん落ち着きのないものだ。"
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_C

//0x32238
Text_32218:
.stringn "\x05FL|SOANEVALCKE|SENERIO||\x070-\x0C01\x0C16\x0701間もなく戦いが終わるな。\n"
.stringn "おまえは…\n"
.stringn "これからもベオクたちの中で\n"
.stringn "己を偽りながら生きていくのか？\n"
.stringn "\x0716………僕は、\n"
.stringn "やはり…【印付き】なんでしょうか。\n"
.stringn "\x0701間違いない。\n"
.stringn "私たちには同族は分かる。\n"
.stringn "\x0716………\n"
.stringn "\x0701隠せている間はいい。\n"
.stringn "その印が【精霊の護符】ではないと\n"
.stringn "気付く者はほとんどいない。\n"
.stringn "だが…時間の問題だぞ。\n"
.stringn "\x0716………\n"
.stringn "\x0701うすうす感じているだろうが、\n"
.stringn "私たちは…年の取り方が\n"
.stringn "ベオクたちと異なる。\n"
.stringn "ひいているラグズの血にもよるが…\n"
.stringn "総じて成長が緩やかになる。\n"
.stringn "\x0716…３年ぐらい前までは\n"
.stringn "普通に年を経ていると……\n"
.stringn "……思っていたのに。\n"
.stringn "\x0701同じ場所には留まれないぞ。\n"
.stringn "ベオクにはいつか気付かれる。\n"
.stringn "\x0716それでも…\n"
.stringn "僕はアイクの傍にいたい。\n"
.stringn "\x0701………\n"
.stringn "どうしようもならなくなったら、\n"
.stringn "グラーヌ砂漠に来い。\n"
.stringn "そこに、おまえの仲間がいることを\n"
.stringn "……忘れるな。\n"
.stringn "\x0716……………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_A

//0x320AC
Text_3208C:
.stringn "\x05FL|SENERIO|SOANEVALCKE||\x0705………\n"
.stringn "\x071-\x0713ベオクの群れにいながら\n"
.stringn "上手く馴染めていないようだな。\n"
.stringn "\x0C05\x0701！！\n"
.stringn "また…あなたですか。\n"
.stringn "\x0713グラーヌ砂漠にある\n"
.stringn "隠れ里に来ないか？\n"
.stringn "おまえと同じ…印を持つ者が\n"
.stringn "身を寄せ合って生きている。\n"
.stringn "\x0701あなたは…何か思い違いを\n"
.stringn "しているようですが……\n"
.stringn "とにかく、大きなお世話です。\n"
.stringn "…僕の居場所は……\n"
.stringn "……ここにありますから。\n"
.stringn "\x0713そうか…\n"
.stringn "では、無理強いはすまい。\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_B

//0x31F80
Text_31F60:
.stringn "\x05FL|SENERIO|SOANEVALCKE||\x0C01\x0713………\n"
.stringn "\x0701……何かご用ですか？\n"
.stringn "\x0713そう警戒しなくていい。\n"
.stringn "私は…おまえの仲間だ。\n"
.stringn "\x0701！！\n"
.stringn "\x0713……その格好…自分を偽り\n"
.stringn "異邦の中で生きてきたのだな。\n"
.stringn "\x0701…………\n"
.stringn "ぼ、僕は……\n"
.stringn "\x0713いきなりでは\n"
.stringn "戸惑わせるばかりか。\n"
.stringn "ひとまず、退く。\n"
.stringn "…次はゆっくり話をしよう。\n"
.stringn "\x0701………………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_C

//0x32CF4
Text_32CD4:
.stringn "\x05FL|STELLA|SOTHE||\x0C01\x0C13\x0701あ……サザさん。\n"
.stringn "この間は、\n"
.stringn "本当にありがとうございました。\n"
.stringn "\x0713……別に、\n"
.stringn "何度も礼を言うようなことじゃない。\n"
.stringn "\x0701でも……\n"
.stringn "\x0713あんたたち貴族は、\n"
.stringn "簡単に礼なんか言わないと思ってたけど。\n"
.stringn "……あんたは違うんだな。\n"
.stringn "\x0701そうなのですか？\n"
.stringn "\x0713ああ。\n"
.stringn "貴族は、俺たち平民を踏みつけて\n"
.stringn "自分たちだけのうのうと豊かな生活をしてる。\n"
.stringn "生まれた時から、それが\n"
.stringn "当然だって思い込んでて…\n"
.stringn "死ぬまで、今日の食い物や寝る場所を\n"
.stringn "どうしようかって悩むこともない……\n"
.stringn "まったく、うらやましいご身分だよ。\n"
.stringn "\x0701でも、自由はありません……\n"
.stringn "私の兄たちは軍人として家の誇りとなり\n"
.stringn "輝かしい人生を送っています。\n"
.stringn "でも姉たちはみな、顔も見たこともない\n"
.stringn "相手の家に娶られていきます……\n"
.stringn "そこに愛はなく、泣き暮らしているという手紙を\n"
.stringn "数年に１度もらうだけ……\n"
.stringn "女は家の権力を繋ぐ道具でしかないのです。\n"
.stringn "\x0713…………\n"
.stringn "あんたも……\n"
.stringn "そうなるはずだった……\n"
.stringn "\x0701はい……でもそれが自分の運命だと、\n"
.stringn "諦めてしまいたくありませんでした。\n"
.stringn "ですから私は……この戦いが終わるまで\n"
.stringn "ここを去る気はありません。\n"
.stringn "\x0713……そうか。\n"
.stringn "あんたは俺が知ってる貴族とは全然違うな。\n"
.stringn "ここんとこずっと、あんたが努力してるの見て\n"
.stringn "そう思ったよ。\n"
.stringn "一生懸命がんばって生きようとしてるのは\n"
.stringn "俺たちと一緒だ。何も変わらない。\n"
.stringn "貴族の気まぐれだとか思って悪かったよ。\n"
.stringn "\x0701あ……ありがとうございます……\n"
.stringn "\x0713これからもがんばってくれよ。\n"
.stringn "自分で自分の命を勝ち取るためにな。\n"
.stringn "\x0701……はい！"
db 0
.align 4
//MYELL_8_SOTHE_STELLA_A

//0x32854
Text_32834:
.stringn "\x05FL|STELLA|SOTHE||\x070-\x0C01\x0C13\x0701あ……ここは……？\n"
.stringn "\x0713…………\n"
.stringn "\x0701私、どうしたんでしょうか……？\n"
.stringn "\x0713あんた、倒れてたんだよ。\n"
.stringn "ほっといても良かったけど……\n"
.stringn "後味が悪いからな。\n"
.stringn "\x0701すみません……\n"
.stringn "\x0713俺には関係ないけど……\n"
.stringn "あんた、無理しすぎじゃないのか？\n"
.stringn "行軍についていくのも苦しそうだし、\n"
.stringn "その様子じゃ参っちまうだろ。\n"
.stringn "\x0701すみません……\n"
.stringn "戦いとは……\n"
.stringn "こんなに過酷なのですね。\n"
.stringn "毎日厳しい行軍が続き……\n"
.stringn "敵の襲撃に怯えて\n"
.stringn "夜安心して眠ることもできません…\n"
.stringn "自分の弱さを身にしみて感じています…\n"
.stringn "\x0713……お嬢様が無理するからだ。\n"
.stringn "ここじゃ、あんたに\n"
.stringn "かしづいてくれる執事や侍女はいない。\n"
.stringn "家に戻れば今までどおり、\n"
.stringn "何不自由なく暮らせるだろ。\n"
.stringn "\x0701……何不自由なく、ですか。\n"
.stringn "でも屋敷に戻ったら……\n"
.stringn "私には自由はないのです。\n"
.stringn "\x0713……？\n"
.stringn "\x0701私には親に定められた許婚者がいます。\n"
.stringn "相手の方は私より３０も年上の……\n"
.stringn "私の父よりお年を召された方だそうです。\n"
.stringn "\x0713……\n"
.stringn "\x0701私は……自分の意思で生きたいと願って\n"
.stringn "ベグニオン騎士団に志願しました……\n"
.stringn "家族には激しく反対されましたが……\n"
.stringn "長続きするはずがないだろうと思われたようです。\n"
.stringn "困り果てて、家に\n"
.stringn "泣いて戻ってくるに違いないと……\n"
.stringn "ですから……まだ、帰るわけにはいきません。\n"
.stringn "\x0713…………\n"
.stringn "……俺には、関係ない。\n"
.stringn "だから、あんたの好きにすればいい。\n"
.stringn "\x0701はい……ありがとうございます。"
db 0
.align 4
//MYELL_8_SOTHE_STELLA_B

//0x32544
Text_32524:
.stringn "\x05FL|STELLA|SOTHE||\x070-\x0C01\x0C13\x0701サザさん。\n"
.stringn "武器のお手入れですか？\n"
.stringn "\x0713ああ、そうだけど。\n"
.stringn "\x0701あの……\n"
.stringn "少し、よろしいでしょうか。\n"
.stringn "\x0713？　何か俺に用か？\n"
.stringn "\x0701サザさんは短剣をお使いですよね。\n"
.stringn "確か……剣は斧に強い武器なのですよね。\n"
.stringn "ところで…斧は一体、どんな武器に対して\n"
.stringn "有効でしたでしょうか。\n"
.stringn "\x0713……そんなことも知らなくて\n"
.stringn "あんた傭兵やってたのか？\n"
.stringn "\x0701は、はい……すみません。\n"
.stringn "傭兵になってまだ日も浅くて……\n"
.stringn "私は弓を使うものですから……\n"
.stringn "\x0713ふーん……\n"
.stringn "あんた、傭兵になる前はなにを？\n"
.stringn "\x0701な、何も……していませんでした。\n"
.stringn "\x0713なにも？　何もしなくて\n"
.stringn "食っていけるわけないじゃないか。\n"
.stringn "…………ひょっとして……\n"
.stringn "あんた、貴族なのか？\n"
.stringn "その喋り方といい、無知さといい…\n"
.stringn "……お貴族様がなぜこんな戦いに？\n"
.stringn "\x0701………………\n"
.stringn "\x0713……ま、俺が聞くこっちゃないな。\n"
.stringn "別に……いいんじゃないかな。\n"
.stringn "貴族の趣味としてはね。"
db 0
.align 4
//MYELL_8_SOTHE_STELLA_C

//0x33520
Text_33500:
.stringn "\x05FL|TOPUCK|SOTHE||\x0C01\x0C13\x0701あ。\n"
.stringn "\x0713まだあきらめないのか？\n"
.stringn "しつこい…\n"
.stringn "\x0701そんなに嫌なら、\n"
.stringn "もう頼まねえからいい！\n"
.stringn "おまえなんか、あっち行けよ！！\n"
.stringn "\x0713……なんだよ。\n"
.stringn "どうしてそんなに\n"
.stringn "友達にこだわるんだ？\n"
.stringn "\x0701ムワリムが心配するんだ…\n"
.stringn "\x0713ムワリム？\n"
.stringn "ああ…　あの虎の。\n"
.stringn "\x0701おいらに…\n"
.stringn "ベオクの友達がいねえのを\n"
.stringn "自分のせいだって\n"
.stringn "辛そうな顔するから…\n"
.stringn "だから、おまえと友達になって\n"
.stringn "喜ばせたかった。\n"
.stringn "\x0713そういうことか。\n"
.stringn "だったら、最初からそう言えよ。\n"
.stringn "\x0701言ったら、なってくれたのか！？\n"
.stringn "\x0713ああ。\n"
.stringn "\x0701…なんでだよ？\n"
.stringn "\x0713育ての親なんだろ？\n"
.stringn "心配させたくない気持ちなら\n"
.stringn "すごく分かるからさ。\n"
.stringn "俺も…親代わりで\n"
.stringn "すごく大事な人がいるし……\n"
.stringn "\x0701そっか！\n"
.stringn "おまえもそうなんだ！？\n"
.stringn "へへ　なんか親近感かも。\n"
.stringn "\x0713協力はするけど、\n"
.stringn "本当の友達になるわけじゃないからな。\n"
.stringn "そこんとこ、はきちがえて\n"
.stringn "べたべたするなよ？\n"
.stringn "\x0701なんでだよ。\n"
.stringn "どーせなら、ちゃんとした\n"
.stringn "友達になろうぜ？\n"
.stringn "\x0713嫌だ。"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_A_a

//0x33868
Text_33848:
.stringn "\x05FL|TOPUCK|SOTHE||\x0C01\x0C13\x0701あ。\n"
.stringn "\x0713まだあきらめないのか？\n"
.stringn "しつこい…\n"
.stringn "\x0701そんなに嫌なら、\n"
.stringn "もう頼まねえからいい！\n"
.stringn "おまえなんか、あっち行けよ！！\n"
.stringn "\x0713……なんだよ。\n"
.stringn "どうしてそんなに\n"
.stringn "友達にこだわるんだ？\n"
.stringn "\x0701ムワリムが心配するんだ…\n"
.stringn "\x0713ムワリム？\n"
.stringn "ああ…　あの虎の。\n"
.stringn "\x0701まだ、生きてた時に……\n"
.stringn "おいらに…ベオクの友達がいねえのは\n"
.stringn "自分のせいだって、すごく心配してた。\n"
.stringn "だからもし、おまえと友達になれたら…\n"
.stringn "あいつも安心するかなって。\n"
.stringn "\x0713そういうことか。\n"
.stringn "だったら、最初からそう言えよ。\n"
.stringn "\x0701言ったら、なってくれたのか！？\n"
.stringn "\x0713ああ。\n"
.stringn "\x0701…なんでだよ？\n"
.stringn "\x0713育ての親なんだろ？\n"
.stringn "安心させてやりたい気持ちなら\n"
.stringn "すごく分かるからさ。\n"
.stringn "俺も…親代わりで\n"
.stringn "すごく大事な人がいるし……\n"
.stringn "\x0701そっか！\n"
.stringn "おまえもそうなんだ！？\n"
.stringn "へへ　なんか親近感かも。\n"
.stringn "\x0713協力はするけど、\n"
.stringn "本当の友達になるわけじゃないからな。\n"
.stringn "そこんとこ、はきちがえて\n"
.stringn "べたべたするなよ？\n"
.stringn "\x0701なんでだよ。\n"
.stringn "どーせなら、ちゃんとした\n"
.stringn "友達になろうぜ？\n"
.stringn "\x0713嫌だ。"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_A_b

//0x333FC
Text_333DC:
.stringn "\x05FL|SOTHE|TOPUCK||\x0C05\x0713なあなあ。\n"
.stringn "\x0705……\n"
.stringn "\x0713おいらたち、\n"
.stringn "年も近いんだしさー。\n"
.stringn "せっかくだし、仲良くしようぜ。\n"
.stringn "\x0705馴れ合いは好きじゃない。\n"
.stringn "\x0713おまえはそうでもさー\n"
.stringn "おいらは、おまえと\n"
.stringn "友達になりたいんだよお。\n"
.stringn "\x0705……俺には関係ない。\n"
.stringn "\x0713なんだよ！\n"
.stringn "いいじゃねえかよ、\n"
.stringn "減るもんじゃないのに！！"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_B

//0x33200
Text_331E0:
.stringn "\x05FL|SOTHE|TOPUCK||\x0C01\x071-\x0713あ、おまえ。\n"
.stringn "なあなあ、こないだ\n"
.stringn "おいらと一緒の任務だったろ？\n"
.stringn "\x0701……憶えてない。\n"
.stringn "\x0713なんだよ……\n"
.stringn "おいらは、覚えてるぜ。\n"
.stringn "あんな小さい武器で\n"
.stringn "敵とまともに戦ってたろ？\n"
.stringn "おいらと同じくらいの年なのに\n"
.stringn "すげーなあと思ってみてたんだ。\n"
.stringn "あ、おいらトパックな。\n"
.stringn "こう見えても\n"
.stringn "いっぱしの魔法使いなんだぜ。\n"
.stringn "\x0701……\n"
.stringn "\x0713おまえは？\n"
.stringn "\x0701……サザ。\n"
.stringn "\x0713サザか！　よろしく頼むな！\n"
.stringn "ところでさあ、サザは\n"
.stringn "なんでここで傭兵やってるんだ？\n"
.stringn "\x0701……言いたくない。\n"
.stringn "\x0713お、おい！\n"
.stringn "なんだよあいつ。\n"
.stringn "すっげえ感じ悪ぃ！！"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_C

//0x340C0
Text_340A0:
.stringn "\x05FL|ULYSSES|VOLKE||\x0C01\x0713どうした…\n"
.stringn "まだ俺に用があるのか？\n"
.stringn "\x0701アイク将軍との\n"
.stringn "契約が終了するのはいつになる？\n"
.stringn "\x0713なぜだ？\n"
.stringn "\x0701依頼したい仕事ができた。\n"
.stringn "…おまえにしかできぬ類のな。\n"
.stringn "\x0713あんたとは短くない付き合いだが…\n"
.stringn "そんな切羽詰ったような表情は…\n"
.stringn "初めて見る。\n"
.stringn "\x0701２０万だ。\n"
.stringn "\x0713？\n"
.stringn "\x0701２０万用意する。\n"
.stringn "すぐに仕事に入ってくれ。\n"
.stringn "\x0713あいにく…\n"
.stringn "俺は仕事のかけもちはせん。\n"
.stringn "もちろん、請けた仕事を\n"
.stringn "途中で放り出すこともな。\n"
.stringn "\x0701……\n"
.stringn "\x0713…あと少しだ。\n"
.stringn "この戦いにけりがつけば…\n"
.stringn "俺とアイクの契約は終わる。\n"
.stringn "どんな形であれ…な。\n"
.stringn "晴れて自由な身になったら…\n"
.stringn "その足で、あんたのところに\n"
.stringn "御用聞きに行ってやろう。\n"
.stringn "\x0701…どういう風の吹き回しだ。\n"
.stringn "\x0713フェール伯、\n"
.stringn "俺はあんたを気に入ってる。\n"
.stringn "あんたの仕事をやって\n"
.stringn "はずれたことは１度もない。\n"
.stringn "\x0701我輩は、優良な雇用主ということか。\n"
.stringn "お褒めに預かり光栄だ。\n"
.stringn "では、とにかくこの\n"
.stringn "戦いを終結させるほかあるまい。\n"
.stringn "おまえを待つ次の仕事も…\n"
.stringn "それは急を要するものだからな。"
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_A

//0x33E5C
Text_33E3C:
.stringn "\x05FL|VOLKE|ULYSSES||\x070-\x0C01\x071-\x0C13\x0701…早かったな。\n"
.stringn "\x0713色々と有益な情報を得られたよ。\n"
.stringn "そのほとんどは、先だって\n"
.stringn "アイク将軍の口から姫が\n"
.stringn "聞かされたという話と合致しているが…\n"
.stringn "あえて語られずにいた細かい事実も\n"
.stringn "どれをとっても実に…興味深い。\n"
.stringn "\x0701あんたなら…\n"
.stringn "飛びつくネタばかりか。\n"
.stringn "\x0713ともかく、これでおまえと\n"
.stringn "アイク将軍に対する疑念は…\n"
.stringn "ひとまず取り払われたと伝えておこう。\n"
.stringn "\x0701それはどうも、ご親切に。\n"
.stringn "\x0713話はそれだけだ。\n"
.stringn "\x0701…フェール伯。\n"
.stringn "\x0713なにかね？\n"
.stringn "\x0701どうやらあんたには…\n"
.stringn "表より裏の仕事のほうがよほど\n"
.stringn "お似合いのようだ。\n"
.stringn "この機会に、\n"
.stringn "転職してはどうだ？\n"
.stringn "\x0713我輩の忠誠と献身は\n"
.stringn "常にクリミア王家と共に在らん。\n"
.stringn "\x0701………"
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_B

//0x33BD8
Text_33BB8:
.stringn "\x05FL|VOLKE|ULYSSES||\x0701…………\n"
.stringn "そこに隠れている男。\n"
.stringn "５を数え終えるまでに出て来い。\n"
.stringn "５、４、３…\n"
.stringn "\x0713…物騒なことだ。\n"
.stringn "流石は【火消し】。\n"
.stringn "この距離で我輩に気づくとはな。\n"
.stringn "\x0701フェール伯…\n"
.stringn "あんたか。\n"
.stringn "\x0713こんなところで、\n"
.stringn "おまえの姿を目にするとは\n"
.stringn "思いもしなかった。\n"
.stringn "…誰の下で動いている？\n"
.stringn "\x0701あんたのことだ、\n"
.stringn "既に調査済みだろう。\n"
.stringn "それを信じればいい。\n"
.stringn "\x0713真実…アイク将軍下で\n"
.stringn "クリミアのために\n"
.stringn "働いているということか？\n"
.stringn "\x0701正確には、\n"
.stringn "アイク自身の下でだ。\n"
.stringn "\x0713何故だ？\n"
.stringn "\x0701１０万だな。\n"
.stringn "\x0713１０万？\n"
.stringn "\x0701答えの代価だ。\n"
.stringn "\x0713ふっ\n"
.stringn "その額をだした時点で、\n"
.stringn "答える気はないか。\n"
.stringn "\x0701……\n"
.stringn "\x0713アイク将軍…\n"
.stringn "あの男を影につかい\n"
.stringn "何を企んでおるのか……\n"
.stringn "至急、調べる必要があるな。"
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_C

